INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Loosand/next-forge/typescript-advanced-types', 'community', 'Loosand', 'next-forge', 'Loosand/next-forge', 'typescript-advanced-types', 0, 0, 33, '2026-03-08T01:57:15.340Z', '2026-03-08T02:03:27.733Z', '7acbd365ffdf56b876f532836cb328d6399bf06d917a2bcca034a27295e9ed1c', '{"id":"Loosand/next-forge/typescript-advanced-types","name":"typescript-advanced-types","description":{"en":"The typescript-advanced-types skill enables developers to build robust, type-safe applications using TypeScript''s advanced type system, including generics, conditional types, and more.","zh":"TypeScript 高级类型是用于构建健壮、类型安全的应用程序的指南，包括泛型、条件类型、映射类型等","ja":"TypeScript 高級タイプは、堅牢なタイプセーフなアプリケーションを構築するためのガイドで、ジェネリック、条件付きタイプ、マッピングタイプなどを含む","ko":"TypeScript 고급 타입은 강력한 타입 안전 애플리케이션을 구축하는 방법을介绍하는 가이드로, 泛型, 조건부 타입, 맵핑 타입 등을 포함","es":"Los tipos avanzados de TypeScript permiten crear aplicaciones robustas y seguras. Aprende a utilizar generics, tipos condicionales y más.","fr":"Les types avancés de TypeScript permettent de créer des applications robustes et sécurisées. Apprenez à utiliser les génériques, les types conditionnels et plus.","de":"Die erweiterten Typen von TypeScript ermöglichen die Erstellung robuster und sicherer Anwendungen. Erfahren Sie, wie Sie Generics, bedingte Typen und mehr verwenden.","pt":"O TypeScript oferece uma variedade de tipos avançados para ajudar a criar aplicações robustas e seguras. Aprenda a usar genéricos, tipos condicionais e mapeamento de tipos.","ru":"TypeScript предлагает множество расширенных типов для помощи в создании надежных и безопасных приложений. Узнайте, как использовать обобщенные, условные типы и типы отображения.","ar":"يقدم TypeScript مجموعة من الأنواع المتقدمة لمساعدتك في إنشاء تطبيقات قوية وأمنة. تعلم كيفية استخدام الأنواع العامة والأنواع المشروطة وتصميم النوع."},"seo":{"title":{"en":"typescript-advanced-types: Mastering TypeScript Type Syst...","zh":"TypeScript 高级类型Setup Guide","ja":"TypeScript 高級タイプのベストプラクティス","ko":"TypeScript 고급 타입 사용법","es":"Guía de configuración de tipos avanzados de TypeScript","fr":"Guide de mise en place des types avancés de TypeScript","de":"Einrichtungsleitfaden für erweiterte TypeScript-Typen","pt":"Guia de Configuração de Tipos Avançados do TypeScript","ru":"Руководство по настройке расширенных типов TypeScript","ar":"دليل إعداد أنواع متقدمة من TypeScript"},"description":{"en":"Unlock the full potential of TypeScript with advanced types. Learn how to create robust, type-safe applications with our expert guide. Get started now!","zh":"学习TypeScript高级类型，包括泛型、条件类型、映射类型等，构建健壮的类型安全应用程序，使用AIエージェント","ja":"TypeScriptの高級タイプをマスターし、ジェネリック、条件付きタイプ、マッピングタイプなどを使用して堅牢なタイプセーフなアプリケーションを構築する、AIエージェント","ko":"TypeScript 고급 타입을学习하고,泛型, 조건부 타입, 맵핑 타입 등을 사용하여 강력한 타입 안전 애플리케이션을 구축하는 방법, AI Tools","es":"Aprende a dominar los tipos avanzados de TypeScript para crear aplicaciones robustas y seguras. Descubre las mejores prácticas para tipos genéricos, condicio...","fr":"Maîtrisez les types avancés de TypeScript pour créer des applications robustes et sécurisées. Découvrez les meilleures pratiques pour les types génériques, c...","de":"Erfahren Sie, wie Sie die erweiterten Typen von TypeScript meistern, um robuste und sichere Anwendungen zu erstellen. Entdecken Sie die besten Praktiken für ...","pt":"Aprenda a usar tipos avançados do TypeScript, incluindo genéricos, tipos condicionais e mapeamento de tipos, para criar aplicações robustas e seguras.","ru":"Узнайте, как использовать расширенные типы TypeScript, включая обобщенные, условные типы и типы отображения, для создания надежных и безопасных приложений.","ar":"تعلم كيفية استخدام أنواع متقدمة من TypeScript، بما في ذلك الأنواع العامة والأنواع المشروطة وتصميم النوع، لإنشاء تطبيقات قوية وأمنة."},"definition":{"en":"typescript-advanced-types is a comprehensive guide to TypeScript''s advanced type system, covering topics such as generics, conditional types, and mapping types.","zh":"TypeScript 高级类型是TypeScript中的一个特性，用于创建可复用、类型灵活的组件","ja":"TypeScript 高級タイプは、TypeScriptの中の一个特性で、再利用可能でタイプフレキシブルなコンポーネントを作成するために使用","ko":"TypeScript 고급 타입은 TypeScript中的一个特性로, 재사용 가능하고 타입 플렉시블한 컴포넌트를 생성하는 데 사용","es":"Los tipos avanzados de TypeScript son características que permiten crear aplicaciones más seguras y robustas mediante el uso de generics, tipos condicionales y más.","fr":"Les types avancés de TypeScript sont des fonctionnalités qui permettent de créer des applications plus sécurisées et robustes grâce à l''utilisation de génériques, de types conditionnels et plus.","de":"Die erweiterten Typen von TypeScript sind Funktionen, die die Erstellung sicherer und robuster Anwendungen durch die Verwendung von Generics, bedingten Typen und mehr ermöglichen.","pt":"Tipos avançados do TypeScript são recursos que permitem criar aplicações mais seguras e robustas, incluindo genéricos, tipos condicionais e mapeamento de tipos.","ru":"Расширенные типы TypeScript - это функции, которые позволяют создавать более безопасные и надежные приложения, включая обобщенные, условные типы и типы отображения.","ar":"الأنواع المتقدمة من TypeScript هي ميزات تسمح بإنشاء تطبيقات أكثر أمانًا وقوة، بما في ذلك الأنواع العامة والأنواع المشروطة وتصميم النوع."},"features":{"en":["Creates reusable, type-safe components with generics","Implements complex type inference logic with conditional types","Designs type-safe API clients with mapping types","Builds robust form validation systems with template literal types","Enables type-safe state management with tool types","Migrates JavaScript codebases to TypeScript with advanced type checking"],"zh":["泛型","条件类型","映射类型","模板字面量类型","工具类型"],"ja":["ジェネリック","条件付きタイプ","マッピングタイプ","テンプレートリテラルタイプ","ツールタイプ"],"ko":["泛型","조건부 타입","맵핑 타입","템플릿 리터럴 타입","도구 타입"],"es":["Generics para crear componentes reutilizables","Tipos condicionales para inferir tipos complejos","Tipos de mapeo para transformar tipos","Tipos de literal de plantilla para crear tipos personalizados","Tipos de herramientas para simplificar la creación de tipos"],"fr":["Génériques pour créer des composants réutilisables","Types conditionnels pour inférer des types complexes","Types de mapeo pour transformer des types","Types de littéral de modèle pour créer des types personnalisés","Types d''outils pour simplifier la création de types"],"de":["Generics zum Erstellen wiederverwendbarer Komponenten","Bedingte Typen zum Inferenz komplexer Typen","Typen von Mapping zum Transformieren von Typen","Typen von Template-Literal zum Erstellen benutzerdefinierter Typen","Typen von Tools zum Vereinfachen der Typenerstellung"],"pt":["Genéricos para criar componentes reutilizáveis","Tipos condicionais para lógica de inferência de tipo complexa","Mapeamento de tipos para criação de APIs seguras","Tipos de literal de modelo para validação de formulários","Objetos de configuração fortes para gerenciamento de estado","Migração de código JavaScript para TypeScript"],"ru":["Обобщенные для создания многократно используемых компонентов","Условные типы для сложной логики вывода типа","Типы отображения для создания безопасных API","Типы шаблонных литералов для валидации форм","Сильные объекты конфигурации для управления состоянием","Миграция кода JavaScript на TypeScript"],"ar":["الأنواع العامة لإنشاء مكونات قابلة لإعادة الاستخدام","الأنواع المشروطة لمنطق استنتاج النوع المعقد","تصميم النوع لإنشاء واجهات برمجة تطبيقات آمنة","أنواع الحرفية القابلة للتحويل لتحقق صحة النماذج","كائنات التكوين القوية لإدارة الحالة","هجرة رمز JavaScript إلى TypeScript"]},"keywords":{"en":["how to use typescript-advanced-types","typescript-advanced-types tutorial","typescript generics","conditional types in typescript","typescript-advanced-types vs flow","typescript-advanced-types setup guide","typescript-advanced-types best practices","typescript type safety","advanced typescript types"],"zh":["TypeScript 高级类型","TypeScript 泛型","TypeScript 条件类型","TypeScript 映射类型","TypeScript 模板字面量类型","TypeScript 工具类型","AIエージェント","TypeScript Setup"],"ja":["TypeScript 高級タイプ","TypeScript ジェネリック","TypeScript 条件付きタイプ","TypeScript マッピングタイプ","TypeScript テンプレートリテラルタイプ","TypeScript ツールタイプ","AIエージェント","TypeScript ベストプラクティス"],"ko":["TypeScript 고급 타입","TypeScript 泛型","TypeScript 조건부 타입","TypeScript 맵핑 타입","TypeScript 템플릿 리터럴 타입","TypeScript 도구 타입","AI Tools","TypeScript 사용법"],"es":["tipos avanzados de TypeScript","generics en TypeScript","tipos condicionales en TypeScript","tipos de mapeo en TypeScript","tipos de literal de plantilla en TypeScript","tipos de herramientas en TypeScript","configuración de tipos avanzados de TypeScript","mejores prácticas para tipos avanzados de TypeScript"],"fr":["types avancés de TypeScript","génériques dans TypeScript","types conditionnels dans TypeScript","types de mapeo dans TypeScript","types de littéral de modèle dans TypeScript","types d''outils dans TypeScript","configuration des types avancés de TypeScript","meilleures pratiques pour les types avancés de TypeScript"],"de":["erweiterte Typen von TypeScript","Generics in TypeScript","bedingte Typen in TypeScript","Typen von Mapping in TypeScript","Typen von Template-Literal in TypeScript","Typen von Tools in TypeScript","Einrichtung erweiterter Typen von TypeScript","beste Praktiken für erweiterte Typen von TypeScript"],"pt":["tipos avançados do TypeScript","genéricos TypeScript","tipos condicionais TypeScript","mapeamento de tipos TypeScript","desenvolvimento de aplicações seguras","TypeScript para iniciantes","guia de configuração de TypeScript","melhores práticas de TypeScript","ferramentas de desenvolvimento de TypeScript"],"ru":["расширенные типы TypeScript","обобщенные типы TypeScript","условные типы TypeScript","типы отображения TypeScript","разработка безопасных приложений","TypeScript для начинающих","руководство по настройке TypeScript","лучшие практики TypeScript","инструменты разработки TypeScript"],"ar":["الأنواع المتقدمة من TypeScript","الأنواع العامة من TypeScript","الأنواع المشروطة من TypeScript","تصميم النوع من TypeScript","تطوير التطبيقات الآمنة","TypeScript لل مبتدئين","دليل إعداد TypeScript","أفضل الممارسات لبرمجة TypeScript","أدوات تطوير TypeScript"]}},"owner":"Loosand","repo":"next-forge","repoPath":"Loosand/next-forge","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.340Z","topics":[],"category":"community","skillMd":{"name":"typescript-advanced-types","description":"掌握 TypeScript 高级类型系统，包括泛型、条件类型、映射类型、模板字面量类型和工具类型，用于构建类型安全的应用程序。在实现复杂类型逻辑、创建可复用类型工具或确保 TypeScript 项目的编译时类型安全时使用。","bodyPreview":"# TypeScript 高级类型\n\n全面掌握 TypeScript 高级类型系统的指南，包括泛型、条件类型、映射类型、模板字面量类型和工具类型，用于构建健壮、类型安全的应用程序。\n\n## 何时使用此技能\n\n- 构建类型安全的库或框架\n- 创建可复用的泛型组件\n- 实现复杂的类型推断逻辑\n- 设计类型安全的 API 客户端\n- 构建表单验证系统\n- 创建强类型配置对象\n- 实现类型安全的状态管理\n- 将 JavaScript 代码库迁移到 TypeScript\n\n## 核心概念\n\n### 1. 泛型\n\n**目的：** 创建可复用、类型灵活的组件，同时保持类型安全。\n\n**基础泛型函数：**\n\n```typescript\nfunction identity<T>(value: T): T {\n  return value;\n}\n\nconst num = identity<number>(42); // 类型: number\nconst str = identity<string>(\"hello\"); // 类型: string\nconst auto = identity(true); /","body":"# TypeScript 高级类型\n\n全面掌握 TypeScript 高级类型系统的指南，包括泛型、条件类型、映射类型、模板字面量类型和工具类型，用于构建健壮、类型安全的应用程序。\n\n## 何时使用此技能\n\n- 构建类型安全的库或框架\n- 创建可复用的泛型组件\n- 实现复杂的类型推断逻辑\n- 设计类型安全的 API 客户端\n- 构建表单验证系统\n- 创建强类型配置对象\n- 实现类型安全的状态管理\n- 将 JavaScript 代码库迁移到 TypeScript\n\n## 核心概念\n\n### 1. 泛型\n\n**目的：** 创建可复用、类型灵活的组件，同时保持类型安全。\n\n**基础泛型函数：**\n\n```typescript\nfunction identity<T>(value: T): T {\n  return value;\n}\n\nconst num = identity<number>(42); // 类型: number\nconst str = identity<string>(\"hello\"); // 类型: string\nconst auto = identity(true); // 类型推断: boolean\n```\n\n**泛型约束：**\n\n```typescript\ntype HasLength = {\n  length: number;\n};\n\nfunction logLength<T extends HasLength>(item: T): T {\n  console.log(item.length);\n  return item;\n}\n\nlogLength(\"hello\"); // OK: string 有 length 属性\nlogLength([1, 2, 3]); // OK: 数组有 length 属性\nlogLength({ length: 10 }); // OK: 对象有 length 属性\n// logLength(42);             // 错误: number 没有 length 属性\n```\n\n**多个类型参数：**\n\n```typescript\nfunction merge<T, U>(obj1: T, obj2: U): T & U {\n  return { ...obj1, ...obj2 };\n}\n\nconst merged = merge({ name: \"John\" }, { age: 30 });\n// 类型: { name: string } & { age: number }\n```\n\n### 2. 条件类型\n\n**目的：** 创建依赖于条件的类型，实现复杂的类型逻辑。\n\n**基础条件类型：**\n\n```typescript\ntype IsString<T> = T extends string ? true : false;\n\ntype A = IsString<string>; // true\ntype B = IsString<number>; // false\n```\n\n**提取返回类型：**\n\n```typescript\ntype ReturnType<T> = T extends (...args: any[]) => infer R ? R : never;\n\nfunction getUser() {\n  return { id: 1, name: \"John\" };\n}\n\ntype User = ReturnType<typeof getUser>;\n// 类型: { id: number; name: string; }\n```\n\n**分布式条件类型：**\n\n```typescript\ntype ToArray<T> = T extends any ? T[] : never;\n\ntype StrOrNumArray = ToArray<string | number>;\n// 类型: string[] | number[]\n```\n\n**嵌套条件：**\n\n```typescript\ntype TypeName<T> = T extends string\n  ? \"string\"\n  : T extends number\n    ? \"number\"\n    : T extends boolean\n      ? \"boolean\"\n      : T extends undefined\n        ? \"undefined\"\n        : T extends Function\n          ? \"function\"\n          : \"object\";\n\ntype T1 = TypeName<string>; // \"string\"\ntype T2 = TypeName<() => void>; // \"function\"\n```\n\n### 3. 映射类型\n\n**目的：** 通过遍历现有类型的属性来转换类型。\n\n**基础映射类型：**\n\n```typescript\ntype Readonly<T> = {\n  readonly [P in keyof T]: T[P];\n};\n\ntype User = {\n  id: number;\n  name: string;\n};\n\ntype ReadonlyUser = Readonly<User>;\n// 类型: { readonly id: number; readonly name: string; }\n```\n\n**可选属性：**\n\n```typescript\ntype Partial<T> = {\n  [P in keyof T]?: T[P];\n};\n\ntype PartialUser = Partial<User>;\n// 类型: { id?: number; name?: string; }\n```\n\n**键重映射：**\n\n```typescript\ntype Getters<T> = {\n  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];\n};\n\ntype Person = {\n  name: string;\n  age: number;\n};\n\ntype PersonGetters = Getters<Person>;\n// 类型: { getName: () => string; getAge: () => number; }\n```\n\n**属性过滤：**\n\n```typescript\ntype PickByType<T, U> = {\n  [K in keyof T as T[K] extends U ? K : never]: T[K];\n};\n\ntype Mixed = {\n  id: number;\n  name: string;\n  age: number;\n  active: boolean;\n};\n\ntype OnlyNumbers = PickByType<Mixed, number>;\n// 类型: { id: number; age: number; }\n```\n\n### 4. 模板字面量类型\n\n**目的：** 创建具有模式匹配和转换功能的字符串类型。\n\n**基础模板字面量：**\n\n```typescript\ntype EventName = \"click\" | \"focus\" | \"blur\";\ntype EventHandler = `on${Capitalize<EventName>}`;\n// 类型: \"onClick\" | \"onFocus\" | \"onBlur\"\n```\n\n**字符串操作：**\n\n```typescript\ntype UppercaseGreeting = Uppercase<\"hello\">; // \"HELLO\"\ntype LowercaseGreeting = Lowercase<\"HELLO\">; // \"hello\"\ntype CapitalizedName = Capitalize<\"john\">; // \"John\"\ntype UncapitalizedName = Uncapitalize<\"John\">; // \"john\"\n```\n\n**路径构建：**\n\n```typescript\ntype Path<T> = T extends object\n  ? {\n      [K in keyof T]: K extends string ? `${K}` | `${K}.${Path<T[K]>}` : never;\n    }[keyof T]\n  : never;\n\ntype Config = {\n  server: {\n    host: string;\n    port: number;\n  };\n  database: {\n    url: string;\n  };\n};\n\ntype ConfigPath = Path<Config>;\n// 类型: \"server\" | \"database\" | \"server.host\" | \"server.port\" | \"database.url\"\n```\n\n### 5. 工具类型\n\n**内置工具类型：**\n\n```typescript\n// Partial<T> - 使所有属性可选\ntype PartialUser = Partial<User>;\n\n// Required<T> - 使所有属性必需\ntype RequiredUser = Required<PartialUser>;\n\n// Readonly<T> - 使所有属性只读\ntype ReadonlyUser = Readonly<User>;\n\n// Pick<T, K> - 选择特定属性\ntype UserName = Pick<User, \"name\" | \"email\">;\n\n// Omit<T, K> - 移除特定属性\ntype UserWithoutPassword = Omit<User, \"password\">;\n\n// Exclude<T, U> - 从联合类型中排除类型\ntype T1 = Exclude<\"a\" | \"b\" | \"c\", \"a\">; // \"b\" | \"c\"\n\n// Extract<T, U> - 从联合类型中提取类型\ntype T2 = Extract<\"a\" | \"b\" | \"c\", \"a\" | \"b\">; // \"a\" | \"b\"\n\n// NonNullable<T> - 排除 null 和 undefined\ntype T3 = NonNullable<string | null | undefined>; // string\n\n// Record<K, T> - 创建键为 K、值为 T 的对象类型\ntype PageInfo = Record<\"home\" | \"about\", { title: string }>;\n```\n\n## 高级模式\n\n### 模式 1：类型安全的事件发射器\n\n```typescript\ntype EventMap = {\n  \"user:created\": { id: string; name: string };\n  \"user:updated\": { id: string };\n  \"user:deleted\": { id: string };\n};\n\nclass TypedEventEmitter<T extends Record<string, any>> {\n  private listeners: {\n    [K in keyof T]?: Array<(data: T[K]) => void>;\n  } = {};\n\n  on<K extends keyof T>(event: K, callback: (data: T[K]) => void): void {\n    if (!this.listeners[event]) {\n      this.listeners[event] = [];\n    }\n    this.listeners[event]!.push(callback);\n  }\n\n  emit<K extends keyof T>(event: K, data: T[K]): void {\n    const callbacks = this.listeners[event];\n    if (callbacks) {\n      callbacks.forEach((callback) => callback(data));\n    }\n  }\n}\n\nconst emitter = new TypedEventEmitter<EventMap>();\n\nemitter.on(\"user:created\", (data) => {\n  console.log(data.id, data.name); // 类型安全！\n});\n\nemitter.emit(\"user:created\", { id: \"1\", name: \"John\" });\n// emitter.emit(\"user:created\", { id: \"1\" });  // 错误: 缺少 ''name''\n```\n\n### 模式 2：类型安全的 API 客户端\n\n```typescript\ntype HTTPMethod = \"GET\" | \"POST\" | \"PUT\" | \"DELETE\";\n\ntype EndpointConfig = {\n  \"/users\": {\n    GET: { response: User[] };\n    POST: { body: { name: string; email: string }; response: User };\n  };\n  \"/users/:id\": {\n    GET: { params: { id: string }; response: User };\n    PUT: { params: { id: string }; body: Partial<User>; response: User };\n    DELETE: { params: { id: string }; response: void };\n  };\n};\n\ntype ExtractParams<T> = T extends { params: infer P } ? P : never;\ntype ExtractBody<T> = T extends { body: infer B } ? B : never;\ntype ExtractResponse<T> = T extends { response: infer R } ? R : never;\n\nclass APIClient<Config extends Record<string, Record<HTTPMethod, any>>> {\n  async request<Path extends keyof Config, Method extends keyof Config[Path]>(\n    path: Path,\n    method: Method,\n    ...[options]: ExtractParams<Config[Path][Method]> extends never\n      ? ExtractBody<Config[Path][Method]> extends never\n        ? []\n        : [{ body: ExtractBody<Config[Path][Method]> }]\n      : [\n          {\n            params: ExtractParams<Config[Path][Method]>;\n            body?: ExtractBody<Config[Path][Method]>;\n          },\n        ]\n  ): Promise<ExtractResponse<Config[Path][Method]>> {\n    // 实现代码\n    return {} as any;\n  }\n}\n\nconst api = new APIClient<EndpointConfig>();\n\n// 类型安全的 API 调用\nconst users = await api.request(\"/users\", \"GET\");\n// 类型: User[]\n\nconst newUser = await api.request(\"/users\", \"POST\", {\n  body: { name: \"John\", email: \"john@example.com\" },\n});\n// 类型: User\n\nconst user = await api.request(\"/users/:id\", \"GET\", {\n  params: { id: \"123\" },\n});\n// 类型: User\n```\n\n### 模式 3：类型安全的建造者模式\n\n```typescript\ntype BuilderState<T> = {\n  [K in keyof T]: T[K] | undefined;\n};\n\ntype RequiredKeys<T> = {\n  [K in keyof T]-?: {} extends Pick<T, K> ? never : K;\n}[keyof T];\n\ntype OptionalKeys<T> = {\n  [K in keyof T]-?: {} extends Pick<T, K> ? K : never;\n}[keyof T];\n\ntype IsComplete<T, S> =\n  RequiredKeys<T> extends keyof S\n    ? S[RequiredKeys<T>] extends undefined\n      ? false\n      : true\n    : false;\n\nclass Builder<T, S extends BuilderState<T> = {}> {\n  private state: S = {} as S;\n\n  set<K extends keyof T>(key: K, value: T[K]): Builder<T, S & Record<K, T[K]>> {\n    this.state[key] = value;\n    return this as any;\n  }\n\n  build(this: IsComplete<T, S> extends true ? this : never): T {\n    return this.state as T;\n  }\n}\n\ntype User = {\n  id: string;\n  name: string;\n  email: string;\n  age?: number;\n};\n\nconst builder = new Builder<User>();\n\nconst user = builder\n  .set(\"id\", \"1\")\n  .set(\"name\", \"John\")\n  .set(\"email\", \"john@example.com\")\n  .build(); // OK: 所有必需字段已设置\n\n// const incomplete = builder\n//   .set(\"id\", \"1\")\n//   .build();  // 错误: 缺少必需字段\n```\n\n### 模式 4：深度只读/可选\n\n```typescript\ntype DeepReadonly<T> = {\n  readonly [P in keyof T]: T[P] extends object\n    ? T[P] extends Function\n      ? T[P]\n      : DeepReadonly<T[P]>\n    : T[P];\n};\n\ntype DeepPartial<T> = {\n  [P in keyof T]?: T[P] extends object\n    ? T[P] extends Array<infer U>\n      ? Array<DeepPartial<U>>\n      : DeepPartial<T[P]>\n    : T[P];\n};\n\ntype Config = {\n  server: {\n    host: string;\n    port: number;\n    ssl: {\n      enabled: boolean;\n      cert: string;\n    };\n  };\n  database: {\n    url: string;\n    pool: {\n      min: number;\n      max: number;\n    };\n  };\n};\n\ntype ReadonlyConfig = DeepReadonly<Config>;\n// 所有嵌套属性都是只读的\n\ntype PartialConfig = DeepPartial<Config>;\n// 所有嵌套属性都是可选的\n```\n\n### 模式 5：类型安全的表单验证\n\n```typescript\ntype ValidationRule<T> = {\n  validate: (value: T) => boolean;\n  message: string;\n};\n\ntype FieldValidation<T> = {\n  [K in keyof T]?: ValidationRule<T[K]>[];\n};\n\ntype ValidationErrors<T> = {\n  [K in keyof T]?: string[];\n};\n\nclass FormValidator<T extends Record<string, any>> {\n  constructor(private rules: FieldValidation<T>) {}\n\n  validate(data: T): ValidationErrors<T> | null {\n    const errors: ValidationErrors<T> = {};\n    let hasErrors = false;\n\n    for (const key in this.rules) {\n      const fieldRules = this.rules[key];\n      const value = data[key];\n\n      if (fieldRules) {\n        const fieldErrors: string[] = [];\n\n        for (const rule of fieldRules) {\n          if (!rule.validate(value)) {\n            fieldErrors.push(rule.message);\n          }\n        }\n\n        if (fieldErrors.length > 0) {\n          errors[key] = fieldErrors;\n          hasErrors = true;\n        }\n      }\n    }\n\n    return hasErrors ? errors : null;\n  }\n}\n\ntype LoginForm = {\n  email: string;\n  password: string;\n};\n\nconst validator = new FormValidator<LoginForm>({\n  email: [\n    {\n      validate: (v) => v.includes(\"@\"),\n      message: \"邮箱必须包含 @\",\n    },\n    {\n      validate: (v) => v.length > 0,\n      message: \"邮箱为必填项\",\n    },\n  ],\n  password: [\n    {\n      validate: (v) => v.length >= 8,\n      message: \"密码至少需要 8 个字符\",\n    },\n  ],\n});\n\nconst errors = validator.validate({\n  email: \"invalid\",\n  password: \"short\",\n});\n// 类型: { email?: string[]; password?: string[]; } | null\n```\n\n### 模式 6：可辨识联合\n\n```typescript\ntype Success<T> = {\n  status: \"success\";\n  data: T;\n};\n\ntype Error = {\n  status: \"error\";\n  error: string;\n};\n\ntype Loading = {\n  status: \"loading\";\n};\n\ntype AsyncState<T> = Success<T> | Error | Loading;\n\nfunction handleState<T>(state: AsyncState<T>): void {\n  switch (state.status) {\n    case \"success\":\n      console.log(state.data); // 类型: T\n      break;\n    case \"error\":\n      console.log(state.error); // 类型: string\n      break;\n    case \"loading\":\n      console.log(\"加载中...\");\n      break;\n  }\n}\n\n// 类型安全的状态机\ntype State =\n  | { type: \"idle\" }\n  | { type: \"fetching\"; requestId: string }\n  | { type: \"success\"; data: any }\n  | { type: \"error\"; error: Error };\n\ntype Event =\n  | { type: \"FETCH\"; requestId: string }\n  | { type: \"SUCCESS\"; data: any }\n  | { type: \"ERROR\"; error: Error }\n  | { type: \"RESET\" };\n\nfunction reducer(state: State, event: Event): State {\n  switch (state.type) {\n    case \"idle\":\n      return event.type === \"FETCH\"\n        ? { type: \"fetching\", requestId: event.requestId }\n        : state;\n    case \"fetching\":\n      if (event.type === \"SUCCESS\") {\n        return { type: \"success\", data: event.data };\n      }\n      if (event.type === \"ERROR\") {\n        return { type: \"error\", error: event.error };\n      }\n      return state;\n    case \"success\":\n    case \"error\":\n      return event.type === \"RESET\" ? { type: \"idle\" } : state;\n  }\n}\n```\n\n## 类型推断技术\n\n### 1. infer 关键字\n\n```typescript\n// 提取数组元素类型\ntype ElementType<T> = T extends (infer U)[] ? U : never;\n\ntype NumArray = number[];\ntype Num = ElementType<NumArray>; // number\n\n// 提取 Promise 类型\ntype PromiseType<T> = T extends Promise<infer U> ? U : never;\n\ntype AsyncNum = PromiseType<Promise<number>>; // number\n\n// 提取函数参数\ntype Parameters<T> = T extends (...args: infer P) => any ? P : never;\n\nfunction foo(a: string, b: number) {}\ntype FooParams = Parameters<typeof foo>; // [string, number]\n```\n\n### 2. 类型守卫\n\n```typescript\nfunction isString(value: unknown): value is string {\n  return typeof value === \"string\";\n}\n\nfunction isArrayOf<T>(\n  value: unknown,\n  guard: (item: unknown) => item is T,\n): value is T[] {\n  return Array.isArray(value) && value.every(guard);\n}\n\nconst data: unknown = [\"a\", \"b\", \"c\"];\n\nif (isArrayOf(data, isString)) {\n  data.forEach((s) => s.toUpperCase()); // 类型: string[]\n}\n```\n\n### 3. 断言函数\n\n```typescript\nfunction assertIsString(value: unknown): asserts value is string {\n  if (typeof value !== \"string\") {\n    throw new Error(\"不是字符串\");\n  }\n}\n\nfunction processValue(value: unknown) {\n  assertIsString(value);\n  // value 现在被类型化为 string\n  console.log(value.toUpperCase());\n}\n```\n\n## 最佳实践\n\n1. **使用 `unknown` 而非 `any`**：强制进行类型检查\n2. **统一使用 `type` 定义类型**：语法一致，支持联合、交叉、映射等所有类型操作\n3. **善用类型别名**：提高代码可读性\n4. **利用类型推断**：让 TypeScript 在可能时自动推断\n5. **创建辅助类型**：构建可复用的类型工具\n6. **使用 const 断言**：保留字面量类型\n7. **避免类型断言**：使用类型守卫代替\n8. **为复杂类型添加文档**：添加 JSDoc 注释\n9. **使用严格模式**：启用所有严格编译器选项\n10. **测试你的类型**：使用类型测试验证类型行为\n\n## 类型测试\n\n```typescript\n// 类型断言测试\ntype AssertEqual<T, U> = [T] extends [U]\n  ? [U] extends [T]\n    ? true\n    : false\n  : false;\n\ntype Test1 = AssertEqual<string, string>; // true\ntype Test2 = AssertEqual<string, number>; // false\ntype Test3 = AssertEqual<string | number, string>; // false\n\n// 期望错误辅助类型\ntype ExpectError<T extends never> = T;\n\n// 使用示例\ntype ShouldError = ExpectError<AssertEqual<string, number>>;\n```\n\n## 常见陷阱\n\n1. **过度使用 `any`**：违背了 TypeScript 的目的\n2. **忽略严格空值检查**：可能导致运行时错误\n3. **类型过于复杂**：可能拖慢编译速度\n4. **不使用可辨识联合**：错失类型收窄的机会\n5. **忘记 readonly 修饰符**：允许意外的修改\n6. **循环类型引用**：可能导致编译器错误\n7. **未处理边界情况**：如空数组或 null 值\n\n## 性能考虑\n\n- 避免深度嵌套的条件类型\n- 尽可能使用简单类型\n- 缓存复杂的类型计算\n- 限制递归类型的递归深度\n- 在生产环境使用构建工具跳过类型检查\n\n## 资源\n\n- **TypeScript 手册**：https://www.typescriptlang.org/docs/handbook/\n- **Type Challenges**：https://github.com/type-challenges/type-challenges\n- **TypeScript Deep Dive**：https://basarat.gitbook.io/typescript/\n- **Effective TypeScript**：Dan Vanderkam 著\n"},"lastSynced":"2026-03-08T02:03:27.733Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Generation Agents needing robust type safety and advanced typing capabilities in TypeScript.","zh":"非常适合需要 TypeScript 中强大的类型安全和高级类型功能的代码生成代理。","ja":"TypeScript の強力な型セーフティと高度な型機能を必要とするコード生成エージェントに最適です。","ko":"TypeScript의 강력한 타입 안전성과 고급 타입 기능이 필요한 코드 생성 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Generación de Código que necesitan una seguridad de tipo robusta y capacidades de tipado avanzadas en TypeScript.","fr":"Parfait pour les agents de génération de code nécessitant une sécurité de type robuste et des fonctionnalités de typage avancées dans TypeScript.","de":"Perfekt für Code-Generierungsagenten, die eine robuste Typsicherheit und erweiterte Typisierungsfunktionen in TypeScript benötigen.","pt":"Perfeito para Agentes de Geração de Código que necessitam de segurança de tipo robusta e capacidades de digitação avançadas em TypeScript.","ru":"Идеально для агентов генерации кода, требующих надежной безопасности типов и продвинутых возможностей типизации в TypeScript.","ar":"مثالي للوكلاء الذين يحتاجون إلى تكامل قوي ومتقدم لتنسيق النوع في TypeScript."},"recommendation":{"en":"Empowers agents to create type-safe applications using TypeScript''s advanced type system, including generics, conditional types, and mapping types, ensuring robust and maintainable codebases with tools like type inference and template literal types.","zh":"赋予代理创建使用 TypeScript 高级类型系统的类型安全应用程序的能力，包括泛型、条件类型和映射类型，并确保使用诸如类型推断和模板字面量类型等工具来实现强健且可维护的代码库。","ja":"エージェントが、ジェネリクス、条件付きタイプ、型マッピングなど、TypeScript の高度な型システムを使用して型セーフなアプリケーションを作成できるようにし、型推論やテンプレートリテラルタイプなどのツールを使用して、堅牢で保守可能なコードベースを保証します。","ko":"에이전트가 TypeScript의 고급 타입 시스템을 사용하여 제네릭, 조건부 타입, 타입 매핑 등을 포함한 타입 안전한 애플리케이션을 생성할 수 있도록 하며, 타입 추론이나 템플릿 리터럴 타입과 같은 도구를 사용하여 견고하고 유지 보수 가능한 코드베이스를 보장합니다.","es":"Habilita a los agentes a crear aplicaciones seguras mediante el sistema de tipos avanzado de TypeScript, incluyendo genéricos, tipos condicionales y tipos de mapeo, garantizando códigos base robustos y mantenibles con herramientas como inferencia de tipos y tipos de literales de plantilla.","fr":"Permet aux agents de créer des applications sécurisées en utilisant le système de types avancé de TypeScript, y compris les génériques, les types conditionnels et les types de mappage, garantissant des bases de code robustes et maintenables avec des outils tels que l''inférence de types et les types de littéraux de modèle.","de":"Ermöglicht es Agenten, typsichere Anwendungen mit dem erweiterten Typsystem von TypeScript zu erstellen, einschließlich Generics, konditionale Typen und Mapping-Typen, und stellt so robuste und wartbare Codebasen mit Tools wie Typinferenz und Template-Literal-Typen sicher.","pt":"Habilita os agentes a criar aplicações seguras com tipos usando o sistema de tipo avançado do TypeScript, incluindo genéricos, tipos condicionais e tipos de mapeamento, garantindo códigos robustos e manteníveis com ferramentas como inferência de tipo e tipos de literal de modelo.","ru":"Наделяет агентов возможностью создавать приложения с безопасностью типов, используя продвинутую систему типов TypeScript, включая обобщенные типы, условные типы и типы отображения, обеспечивая надежные и поддерживаемые кодовые базы с помощью инструментов, таких как вывод типов и типы шаблонных литералов.","ar":"يمكّن الوكلاء من إنشاء تطبيقات آمنة بأAYERة باستخدام نظام TypeScript المتقدم، بما في ذلك الإشارات العامة والأنواع الشرطية وأنواع الخريطة، مما يضمن قواعد بيانات آمنة وقابلة للصيانة بأدوات مثل استنتاج النوع وأنواع النماذج الحرفية."},"useCases":{"en":["Building reusable generic components","Implementing complex type inference logic","Designing type-safe API clients","Creating strongly typed configuration objects"],"zh":["构建可重用的泛型组件","实现复杂的类型推断逻辑","设计类型安全的 API 客户端","创建强类型的配置对象"],"ja":["再利用可能なジェネリックコンポーネントの構築","複雑な型推論ロジックの実装","型セーフな API クライアントの設計","強い型付けの構成オブジェクトの作成"],"ko":["재사용 가능한 제네릭 컴포넌트 구축","복잡한 타입 추론 논리의 구현","타입 안전한 API 클라이언트 설계","강한 타입의 구성 객체 생성"],"es":["Construcción de componentes genéricos reutilizables","Implementación de lógica de inferencia de tipos compleja","Diseño de clientes de API seguros mediante tipos","Creación de objetos de configuración con tipos fuertes"],"fr":["Construction de composants génériques réutilisables","Mise en œuvre de la logique d''inférence de types complexe","Conception de clients d''API sécurisés par les types","Création d''objets de configuration fortement typés"],"de":["Erstellung wiederverwendbarer generischer Komponenten","Implementierung komplexer Typinferenzlogik","Entwurf typsicherer API-Clients","Erstellung stark typisierter Konfigurationsobjekte"],"pt":["Construir componentes genéricos reutilizáveis","Implementar lógica de inferência de tipo complexa","Projetar clientes de API seguros com tipos","Criar objetos de configuração fortemente tipados"],"ru":["Построение многократно используемых общих компонентов","Реализация сложной логики вывода типов","Проектирование клиентов API с безопасностью типов","Создание сильно типизированных объектов конфигурации"],"ar":["بناء مكونات جينية قابلة لإعادة الاستخدام","تنفيذ منطق استنتاج النوع المعقد","تصميم عملاء API آمنون بالنوع","إنشاء كائنات تكوين قوية النوع"]},"limitations":{"en":["Requires TypeScript compiler and ecosystem","Steep learning curve for advanced type concepts"],"zh":["需要 TypeScript 编译器和生态系统","高级类型概念的陡峭的学习曲线"],"ja":["TypeScript コンパイラとエコシステムの必要性","高度な型概念の急な学習曲線"],"ko":["TypeScript 컴파일러와 생태계의 필요성","고급 타입 개념의 급한 학습 곡선"],"es":["Requiere compilador y ecosistema de TypeScript","Curva de aprendizaje pronunciada para conceptos de tipos avanzados"],"fr":["Nécessite un compilateur et un écosystème TypeScript","Courbe d''apprentissage abrupte pour les concepts de types avancés"],"de":["Benötigt TypeScript-Compiler und -Ökosystem","Steile Lernkurve für erweiterte Typkonzepte"],"pt":["Exige compilador TypeScript e ecossistema","Curva de aprendizado acentuada para conceitos de tipo avançados"],"ru":["Требует компилятора TypeScript и экосистемы","Крутая кривая обучения для продвинутых концепций типов"],"ar":["يتطلب مترجم TypeScript وبيئته","منحنى تعليمي حاد لمفاهيم النوع المتقدمة"]},"version":4},"contentHash":"7acbd365ffdf56b876f532836cb328d6399bf06d917a2bcca034a27295e9ed1c","qualityScore":33}');
