INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('erwinkn/ai-config/context7', 'context7', 'erwinkn', 'ai-config', 'community', 'context7 erwinkn ai-config community context7 is a cross-platform AI tool configuration skill that fetches up-to-date documentation and code examples from libraries using the Context7 API, benefiting AI agent developers. Context7是一种跨平台AI工具配置技能，支持Claude Code等 Context7は、Claude Codeなどを含むクロスプラットフォームAIツールの設定を可能にするスキルです Context7는 Claude Code 등을 포함한 크로스 플랫폼 AI 도구 구성 스킬입니다 Context7 es una herramienta de IA que permite la configuración de bibliotecas como React y Nextjs Context7 est un outil d''IA qui permet la configuration de bibliothèques comme React et Nextjs Context7 ist ein KI-Tool, das die Konfiguration von Bibliotheken wie React und Nextjs ermöglicht O Context7 é uma ferramenta de AI que permite a configuração cross-plataforma de bibliotecas, incluindo Claude Code, e fornece documentação e exemplos de código atualizados Context7 - это ИИ инструмент, который позволяет настраивать кроссплатформенные библиотеки, включая Claude Code, и предоставляет актуальную документацию и примеры кода Context7 هو أداة ذكاء اصطناعي يسمح بإعداد المكتبات متعددة المنصات، بما في ذلك Claude Code، ويقدم توثيقًا وأمثلة رمز محدثة how to use context7 context7 API documentation context7 alternative context7 setup guide context7 vs Claude Code what is context7 context7 install context7 library configuration Context7 AI工具配置 跨平台 Claude Code Context7 API React Next.js FastAPI Fetches documentation and code examples using the Context7 API Supports search for library IDs via GET https://context7.com/api/v2/libs/search Requires a two-step process for configuration Utilizes parameters such as libraryName and query for search context Enables access to libraries like Claude Code context7 is a cross-platform AI tool configuration skill that utilizes the Context7 API to provide up-to-date documentation and code examples for various libraries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('christian289/task_20260212/enforcing-dto-record', 'community', 'christian289', 'task_20260212', 'christian289/task_20260212', 'enforcing-dto-record', 0, 0, 33, '2026-03-08T01:57:15.344Z', '2026-03-08T02:03:32.677Z', '60c5241625d345b4ad6de545e3cea549afc979239e0d8ebeeb7018fc40d4dff6', '{"id":"christian289/task_20260212/enforcing-dto-record","name":"enforcing-dto-record","description":{"en":"The enforcing-dto-record skill ensures that Data Transfer Objects (DTOs) are implemented as records in C#, providing immutability and value equality. This skill benefits C# developers working with DTOs.","zh":"本文介绍了如何在C#中使用record强制实现DTO，包括规则和最佳实践","ja":"この記事では、C#でレコードを使用してDTOを強制的に実装する方法、ルール、およびベストプラクティスについて説明します","ko":"본 문서는 C#에서 record를 사용하여 DTO를 강제로 구현하는 방법, 규칙 및 최적화에 대해 설명합니다","es":"El skill ''enforcing-dto-record'' garantiza la implementación de registros DTO en C# para objetos de transferencia de datos inmutables","fr":"Le skill ''enforcing-dto-record'' assure la mise en œuvre d''enregistrements DTO en C# pour des objets de transfert de données immuables","de":"Das Skill ''enforcing-dto-record'' stellt sicher, dass DTO-Records in C# für unveränderliche Datenübertragungsobjekte implementiert werden","pt":"DTO records são objetos de transferência de dados imutáveis implementados em C# como records. Eles fornecem imutabilidade, igualdade de valores e expressões ''with'' por padrão.","ru":"DTO записи - это неизменяемые объекты передачи данных, реализованные в C# как записи. Они предоставляют иммутабельность, равенство значений и выражения ''with'' по умолчанию для ИИ Агентов","ar":"سجلات DTO هي كائنات نقل بيانات غير قابلة للتغيير مطبقة في C# كسجلات. أنها توفر الثبات والمساواة في القيم والتعابير ''with'' افتراضيًا لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"enforcing-dto-record: C# Record Implementation Setup Guid...","zh":"强制DTO记录设置指南 - C# record优化","ja":"DTOレコードの強制設定ガイド - C# record最適化","ko":"DTO 레코드 구현 강제 설정 가이드 - C# record 최적화","es":"Guía de configuración de registros DTO","fr":"Meilleures pratiques pour les enregistrements DTO","de":"DTO-Record-Implementierung: Einrichtungsanleitung","pt":"Guia de Configuração de DTO Record para Desenvolvedores","ru":"Настройка DTO Записи: Лучшие Практики для Разработчиков И...","ar":"دليل تنفيذ DTO Record لأدوات الذكاء الاصطناعي"},"description":{"en":"Learn how to enforce DTO records in C# and improve your code''s immutability and value equality. Get started with our setup guide and expert tips.","zh":"了解如何在C#中使用record强制实现DTO，提高代码的可读性和可维护性","ja":"C#でレコードを使用してDTOを強制的に実装し、コードの可読性とメンテナンス性を向上させる方法を学びます","ko":"C#에서 record를 사용하여 DTO를 강제로 구현하고 코드의 가독성과 유지 보수성을 향상시키는 방법을 알아보세요","es":"Aprende a implementar registros DTO en C# para mejorar la inmutabilidad y la igualdad de valores en tus objetos de transferencia de datos","fr":"Découvrez comment mettre en œuvre des enregistrements DTO en C# pour améliorer l''immutabilité et l''égalité des valeurs dans vos objets de transfert de données","de":"Erfahren Sie, wie Sie DTO-Records in C# implementieren, um die Unveränderlichkeit und Wertgleichheit in Ihren Datenübertragungsobjekten zu verbessern","pt":"Aprenda a implementar DTO records em C# para melhorar a imutabilidade e a igualdade de valores em seus objetos de transferência de dados","ru":"Узнайте, как реализовать DTO записи в C# для улучшения иммутабельности и равенства значений в ваших объектах передачи данных с помощью ИИ Агентов","ar":"تعلم كيفية تنفيذ سجلات DTO في C# لتحسين الثبات والإمكانية المتساوية للقيم في كائنات نقل البيانات لأدوات الذكاء الاصطناعي"},"definition":{"en":"enforcing-dto-record is a skill that enforces the implementation of Data Transfer Objects (DTOs) as records in C#, ensuring immutability and value equality.","zh":"DTO记录强制是指在C#中使用record类型代替class类型来实现数据传输对象","ja":"DTOレコードの強制とは、C#でレコード型を使用してデータ転送オブジェクトを実装すること","ko":"DTO 레코드 구현 강제는 C#에서 record 타입을 사용하여 데이터 전송 객체를 구현하는 것을 의미합니다","es":"Un registro DTO es un objeto de transferencia de datos inmutable implementado como un registro en C#","fr":"Un enregistrement DTO est un objet de transfert de données immuable implémenté comme un enregistrement en C#","de":"Ein DTO-Record ist ein unveränderliches Datenübertragungsobjekt, das als Record in C# implementiert wird","pt":"DTO record é um objeto de transferência de dados imutável implementado em C# como record","ru":"DTO запись - это неизменяемый объект передачи данных, реализованный в C# как запись для ИИ Агентов","ar":"سجل DTO هو كائن نقل بيانات غير قابل للتغيير مطبق في C# كسجل لأدوات الذكاء الاصطناعي"},"features":{"en":["Enforces DTO implementation as C# records","Provides immutability and value equality for DTOs","Replaces `sealed class` + `{ get; set; }` pattern with `record` + positional parameters or `{ get; init; }`","Excludes entities and domain models that require state changes","Improves code quality with `with` expression support"],"zh":["使用record类型代替class类型","实现不变性和值基于的相等性","支持with表达式","将sealed class + { get; set; }模式转换为record + 位置参数或{ get; init; }模式"],"ja":["レコード型をクラス型に代入する","不変性と値ベースの等価性を実装する","with式をサポートする","シールドクラス + { get; set; }パターンをレコード + 位置パラメータまたは{ get; init; }パターンに変換する"],"ko":["record 타입을 class 타입으로 대체","불변성과 값 기반의 동등성을 구현","with 식을 지원","sealed class + { get; set; } 패턴을 record + 위치 매개변수 또는 { get; init; } 패턴으로 변환"],"es":["Implementación de registros DTO en C#","Inmutabilidad y igualdad de valores","Uso de la palabra clave ''record'' en lugar de ''class''","Patrón de posición para la inicialización de registros","Compatibilidad con serialización y deserialización"],"fr":["Mise en œuvre d''enregistrements DTO en C#","Immutabilité et égalité des valeurs","Utilisation du mot-clé ''record'' au lieu de ''class''","Modèle de position pour l''initialisation des enregistrements","Compatibilité avec la sérialisation et la désérialisation"],"de":["Implementierung von DTO-Records in C#","Unveränderlichkeit und Wertgleichheit","Verwendung des Schlüsselworts ''record'' anstelle von ''class''","Positionsmodell für die Initialisierung von Records","Kompatibilität mit Serialisierung und Deserialisierung"],"pt":["Implementação de DTO como records em C#","Fornecimento de imutabilidade e igualdade de valores por padrão","Suporte a expressões ''with'' para atualização de propriedades","Substituição de padrões ''sealed class'' + ''{ get; set; }'' por ''record'' + parâmetros posicionais","Melhoria da segurança e performance com objetos imutáveis"],"ru":["Реализация DTO как записей в C# для ИИ Агентов","Предоставление иммутабельности и равенства значений по умолчанию","Поддержка выражений ''with'' для обновления свойств","Замена паттернов ''sealed class'' + ''{ get; set; }'' на ''record'' + позиционные параметры","Улучшение безопасности и производительности с помощью неизменяемых объектов"],"ar":["تنفيذ DTO كسجلات في C# لأدوات الذكاء الاصطناعي","توفير الثبات والمساواة في القيم افتراضيًا","دعم التعبيرات ''with'' لتحديث الخواص","استبدال الأنماط ''sealed class'' + ''{ get; set; }'' بسجلات + معاملات موضعية","تحسين الأمان والاداء باستخدام الكائنات الثابتة"]},"keywords":{"en":["enforcing-dto-record setup guide","C# record implementation","DTO immutability","value equality in C#","enforcing-dto-record vs class implementation","how to use enforcing-dto-record in C#","enforcing-dto-record install","C# record benefits","enforcing-dto-record best practices"],"zh":["C# record","DTO记录强制","数据传输对象","不变性","值基于的相等性","with表达式","sealed class","位置参数"],"ja":["C#レコード","DTOレコードの強制","データ転送オブジェクト","不変性","値ベースの等価性","with式","シールドクラス","位置パラメータ"],"ko":["C# record","DTO 레코드 구현 강제","데이터 전송 객체","불변성","값 기반의 동등성","with 식","sealed class","위치 매개변수"],"es":["registrar DTO","implementación de registros DTO","inmutabilidad en C#","igualdad de valores en C#","serialización y deserialización en C#","herramientas de desarrollo de software","Agentes de IA para desarrolladores"],"fr":["enregistrement DTO","mise en œuvre d''enregistrements DTO","immutabilité en C#","égalité des valeurs en C#","sérialisation et désérialisation en C#","outils de développement de logiciels","Agents IA pour les développeurs"],"de":["DTO-Record","Implementierung von DTO-Records","Unveränderlichkeit in C#","Wertgleichheit in C#","Serialisierung und Deserialisierung in C#","Software-Entwicklungstools","KI-Agents für Entwickler"],"pt":["DTO record C#","implementação de DTO em C#","imutabilidade em C#","igualdade de valores em C#","expressões ''with'' em C#","desenvolvimento de software com C#","programação em C#","C# para desenvolvedores"],"ru":["DTO запись C#","реализация DTO в C# для ИИ Агентов","иммутабельность в C#","равенство значений в C#","выражения ''with'' в C#","разработка программного обеспечения на C#","программирование на C#","C# для разработчиков ИИ Агентов"],"ar":["سجل DTO C#","تنفيذ DTO في C# لأدوات الذكاء الاصطناعي","الثبات في C#","المساواة في القيم في C#","التعبيرات ''with'' في C#","تطوير البرمجيات باستخدام C#","برمجة بلغة C#","C# لمنشئي أدوات الذكاء الاصطناعي"]}},"owner":"christian289","repo":"task_20260212","repoPath":"christian289/task_20260212","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.344Z","topics":[],"category":"community","skillMd":{"name":"enforcing-dto-record","description":"Force all DTO (Data Transfer Object) types to be declared as record instead of class for immutability and value-based equality.","bodyPreview":"# DTO는 record로 구현 강제\n\n## 설명\n\nDTO(Data Transfer Object)는 읽기 전용(ReadOnly) 객체입니다. C#에서 `class`가 아닌 `record`로 구현해야 합니다.\n`record`는 불변성(immutability), 값 기반 동등성(value equality), `with` 식을 기본 제공하므로 DTO에 최적입니다.\n\n## 규칙\n\n- 모든 DTO 클래스는 `class` 대신 `record`로 선언합니다\n- 응답/요청 전용 객체, 직렬화/역직렬화 전용 객체가 대상입니다\n- 엔티티(Entity)나 상태 변경이 필요한 도메인 모델은 제외합니다\n- `sealed class` + `{ get; set; }` 패턴을 `record` + 위치 매개변수(positional parameter) 또는 `{ get; init; }` 패턴으로 변환합니다\n\n## Worst Case (나쁜 예)\n\n```csharp\n// DTO를 class로 구현 - 불변성 보장 없","body":"# DTO는 record로 구현 강제\n\n## 설명\n\nDTO(Data Transfer Object)는 읽기 전용(ReadOnly) 객체입니다. C#에서 `class`가 아닌 `record`로 구현해야 합니다.\n`record`는 불변성(immutability), 값 기반 동등성(value equality), `with` 식을 기본 제공하므로 DTO에 최적입니다.\n\n## 규칙\n\n- 모든 DTO 클래스는 `class` 대신 `record`로 선언합니다\n- 응답/요청 전용 객체, 직렬화/역직렬화 전용 객체가 대상입니다\n- 엔티티(Entity)나 상태 변경이 필요한 도메인 모델은 제외합니다\n- `sealed class` + `{ get; set; }` 패턴을 `record` + 위치 매개변수(positional parameter) 또는 `{ get; init; }` 패턴으로 변환합니다\n\n## Worst Case (나쁜 예)\n\n```csharp\n// DTO를 class로 구현 - 불변성 보장 없음, 보일러플레이트 과다\nprivate sealed class PagedResponse\n{\n    public int Page { get; set; }\n    public int PageSize { get; set; }\n    public int TotalCount { get; set; }\n    public int TotalPages { get; set; }\n    public EmployeeDto[] Data { get; set; } = [];\n}\n\nprivate sealed class CreatedResponse\n{\n    public int Count { get; set; }\n    public EmployeeDto[] Data { get; set; } = [];\n}\n\nprivate sealed class EmployeeDto\n{\n    public string Name { get; set; } = \"\";\n    public string Email { get; set; } = \"\";\n    public string Tel { get; set; } = \"\";\n    public DateTime Joined { get; set; }\n}\n\n// JSON 역직렬화용 DTO를 class로 구현\nprivate sealed class JsonEmployeeDto\n{\n    public string? Name { get; set; }\n    public string? Email { get; set; }\n    public string? Tel { get; set; }\n    public string? Joined { get; set; }\n}\n```\n\n## Best Case (좋은 예)\n\n```csharp\n// DTO를 record로 구현 - 불변성 보장, 간결한 코드\nprivate sealed record PagedResponse(\n    int Page,\n    int PageSize,\n    int TotalCount,\n    int TotalPages,\n    EmployeeDto[] Data);\n\nprivate sealed record CreatedResponse(\n    int Count,\n    EmployeeDto[] Data);\n\nprivate sealed record EmployeeDto(\n    string Name,\n    string Email,\n    string Tel,\n    DateTime Joined);\n\n// JSON 역직렬화용 DTO도 record로 구현\nprivate sealed record JsonEmployeeDto(\n    string? Name,\n    string? Email,\n    string? Tel,\n    string? Joined);\n```\n\n## 적용 대상\n\n- API 응답/요청 DTO\n- JSON 직렬화/역직렬화 매핑 객체\n- 테스트 코드의 역직렬화 DTO\n- 내부 데이터 전달용 객체\n"},"lastSynced":"2026-03-08T02:03:32.677Z","agentAnalysis":{"suitability":{"en":"Perfect for C# Code Analysis Agents specializing in DTO validation and API contract enforcement.","zh":"适用于专门从事DTO验证和API契约执行的C#代码分析代理。","ja":"DTOの検証とAPI契約の実施を専門とするC#コード分析エージェントに最適です。","ko":"DTO 유효성 검사 및 API 계약 적용을 전문으로 하는 C# 코드 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis de Código C# especializados en validación de DTO y aplicación de contratos de API.","fr":"Parfait pour les Agents d''Analyse de Code C# spécialisés dans la validation des DTO et l''application des contrats d''API.","de":"Perfekt für C# Code Analysis Agents, die sich auf die Validierung von DTOs und die Durchsetzung von API-Verträgen spezialisieren.","pt":"Perfeito para Agentes de Análise de Código C# especializados em validação de DTO e aplicação de contrato de API.","ru":"Идеально подходит для Агентов анализа кода C#, специализирующихся на проверке DTO и обеспечении соблюдения контрактов API.","ar":"مثالي لوكلاء تحليل كود #C المتخصصين في التحقق من صحة كائنات نقل البيانات (DTO) وإنفاذ عقود واجهة برمجة التطبيقات (API)."},"recommendation":{"en":"Enforces DTO immutability and value equality by mandating record types over classes, leveraging C#''s positional parameters and init-only properties. Provides automated detection of DTO patterns and transformation from class-based implementations with { get; set; } to record-based patterns with { get; init; }.","zh":"通过强制使用记录类型而不是类来执行DTO的不可变性和值相等性，利用C#的位置参数和仅初始化属性。提供自动检测DTO模式和从基于类的实现转换为记录基于模式的自动检测，从{ get; set; }到{ get; init; }。","ja":"レコード型をクラスよりも優先することでDTOの不変性と値の等価性を実施し、C#の位置パラメータとinit-onlyプロパティを利用する。DTOパターンの自動検出とクラスベースの実装からレコードベースのパターンへの変換を提供する、{ get; set; } から { get; init; } への自動検出。","ko":"레코드 유형을 클래스보다 우선하여 DTO의 불변성 및 값 동등성을 시행하고 C#의 위치 매개 변수 및 init 전용 속성을 활용합니다. DTO 패턴 자동 감지 및 클래스 기반 구현에서 레코드 기반 패턴으로의 자동 변환을 제공합니다. { get; set; }에서 { get; init; }로의 자동 변환을 제공합니다.","es":"Impone la inmutabilidad y la igualdad de valor de los DTO al exigir el uso de tipos record en lugar de clases, aprovechando los parámetros posicionales y las propiedades de solo inicialización (init-only) de C#. Proporciona detección automatizada de patrones de DTO y transformación de implementaciones basadas en clases con { get; set; } a patrones basados en records con { get; init; }.","fr":"Impose l''immuabilité et l''égalité de valeur des DTO en exigeant l''utilisation de types record plutôt que des classes, en tirant parti des paramètres positionnels et des propriétés en lecture seule d''initialisation (init-only) de C#. Fournit une détection automatisée des modèles de DTO et une transformation des implémentations basées sur des classes avec { get; set; } vers des modèles basés sur des records avec { get; init; }.","de":"Erzwingt die Unveränderlichkeit und Wertgleichheit von DTOs, indem Record-Typen anstelle von Klassen vorgeschrieben werden, unter Ausnutzung der Positionsparameter und Init-Only-Eigenschaften von C#. Bietet eine automatisierte Erkennung von DTO-Mustern und die Transformation von klassenbasierten Implementierungen mit { get; set; } zu record-basierten Mustern mit { get; init; }.","pt":"Impõe a imutabilidade e a igualdade de valor do DTO ao obrigar o uso de tipos record em vez de classes, aproveitando os parâmetros posicionais e as propriedades init-only do C#. Fornece deteção automatizada de padrões DTO e transformação de implementações baseadas em classe com { get; set; } para padrões baseados em record com { get; init; }.","ru":"Обеспечивает неизменяемость DTO и равенство значений, предписывая использование типов record вместо классов, с использованием позиционных параметров и свойств только для инициализации в C#. Обеспечивает автоматическое обнаружение шаблонов DTO и преобразование из реализаций на основе классов с { get; set; } в шаблоны на основе record с { get; init; }.","ar":"يفرض عدم قابلية التعديل وكائنات نقل البيانات (DTO) والمساواة في القيمة من خلال إلزام استخدام أنواع السجلات (record) بدلاً من الفئات (classes)، مع الاستفادة من المعاملات الموضعية وخصائص التهيئة فقط في #C. يوفر الكشف التلقائي عن أنماط كائنات نقل البيانات (DTO) والتحويل من التطبيقات القائمة على الفئات باستخدام { get; set; } إلى الأنماط القائمة على السجلات باستخدام { get; init; }."},"useCases":{"en":["Validating API request/response object immutability","Automating DTO refactoring from class to record syntax","Enforcing value equality semantics in serialization/deserialization scenarios"],"zh":["验证API请求/响应对象的不可变性","自动将DTO重构从类语法到记录语法","在序列化/反序列化场景中强制执行值相等语义"],"ja":["APIリクエスト/レスポンスオブジェクトの不変性の検証","DTOをクラス構文からレコード構文に自動リファクタリング","シリアル化/デシリアル化シナリオで値の等価性のセマンティクスを強制する"],"ko":["API 요청/응답 개체의 불변성 검증","DTO를 클래스 구문에서 레코드 구문으로 자동 리팩토링","직렬화/비직렬화 시나리오에서 값 동등성 의미를 강제 적용"],"es":["Validación de la inmutabilidad de objetos de solicitud/respuesta de API","Automatización de la refactorización de DTOs desde sintaxis de clase a record","Aplicación de semánticas de igualdad de valor en escenarios de serialización/deserialización"],"fr":["Validation de l''immuabilité des objets de requête/réponse d''API","Automatisation du refactoring des DTO de la syntaxe de classe vers record","Application de la sémantique d''égalité de valeur dans les scénarios de sérialisation/désérialisation"],"de":["Validierung der Unveränderlichkeit von API-Anforderungs-/Antwortobjekten","Automatisierung der DTO-Refaktorierung von Klassen- zur Record-Syntax","Durchsetzung von Wertgleichheitssemantik in Serialisierungs-/Deserialisierungsszenarien"],"pt":["Validação da imutabilidade de objetos de requisição/resposta da API","Automatização da refatoração de DTO da sintaxe de classe para record","Aplicação da semântica de igualdade de valor em cenários de serialização/desserialização"],"ru":["Проверка неизменяемости объектов запроса/ответа API","Автоматизация рефакторинга DTO из синтаксиса класса в record","Обеспечение семантики равенства значений в сценариях сериализации/десериализации"],"ar":["التحقق من عدم قابلية التعديل لكائنات طلب/استجابة واجهة برمجة التطبيقات (API)","أتمتة إعادة هيكلة كائنات نقل البيانات (DTO) من بناء جملة الفئة (class) إلى بناء جملة السجل (record)","إنفاذ دلالات المساواة في القيمة في سيناريوهات التسلسل/إلغاء التسلسل"]},"limitations":{"en":["C# language specific","Excludes entities and state-changing domain models","Requires .NET 5+ for record support"],"zh":["C#语言特有","排除实体和状态更改域模型","需要.NET 5+来支持记录"],"ja":["C#言語固有","エンティティや状態変更ドメインモデルを除外","レコードのサポートには.NET 5+が必要"],"ko":["C# 언어 전용","엔티티 및 상태 변경 도메인 모델 제외",".NET 5+가 필요하여 레코드 지원"],"es":["Específico del lenguaje C#","Excluye entidades y modelos de dominio que cambian de estado","Requiere .NET 5+ para soporte de records"],"fr":["Spécifique au langage C#","Exclut les entités et les modèles de domaine avec changement d''état","Nécessite .NET 5+ pour la prise en charge des records"],"de":["C#-sprachspezifisch","Schließt Entitäten und zustandsändernde Domänenmodelle aus","Erfordert .NET 5+ für Record-Unterstützung"],"pt":["Específico da linguagem C#","Exclui entidades e modelos de domínio que alteram o estado","Requer .NET 5+ para suporte a record"],"ru":["Специфично для языка C#","Исключает сущности и модели предметной области, изменяющие состояние","Требует .NET 5+ для поддержки record"],"ar":["خاص بلغة #C","يستثني الكيانات ونماذج المجال التي تغير الحالة","يتطلب .NET 5+ لدعم السجلات (records)"]},"version":4},"contentHash":"60c5241625d345b4ad6de545e3cea549afc979239e0d8ebeeb7018fc40d4dff6","qualityScore":33}');
