INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('christian289/task_20260212/enforcing-dto-record', 'enforcing-dto-record', 'christian289', 'task_20260212', 'community', 'enforcing-dto-record christian289 task_20260212 community The enforcing-dto-record skill ensures that Data Transfer Objects (DTOs) are implemented as records in C#, providing immutability and value equality. This skill benefits C# developers working with DTOs. 本文介绍了如何在C#中使用record强制实现DTO，包括规则和最佳实践 この記事では、C#でレコードを使用してDTOを強制的に実装する方法、ルール、およびベストプラクティスについて説明します 본 문서는 C#에서 record를 사용하여 DTO를 강제로 구현하는 방법, 규칙 및 최적화에 대해 설명합니다 El skill ''enforcing-dto-record'' garantiza la implementación de registros DTO en C# para objetos de transferencia de datos inmutables Le skill ''enforcing-dto-record'' assure la mise en œuvre d''enregistrements DTO en C# pour des objets de transfert de données immuables Das Skill ''enforcing-dto-record'' stellt sicher, dass DTO-Records in C# für unveränderliche Datenübertragungsobjekte implementiert werden DTO records são objetos de transferência de dados imutáveis implementados em C# como records. Eles fornecem imutabilidade, igualdade de valores e expressões ''with'' por padrão. DTO записи - это неизменяемые объекты передачи данных, реализованные в C# как записи. Они предоставляют иммутабельность, равенство значений и выражения ''with'' по умолчанию для ИИ Агентов سجلات DTO هي كائنات نقل بيانات غير قابلة للتغيير مطبقة في C# كسجلات. أنها توفر الثبات والمساواة في القيم والتعابير ''with'' افتراضيًا لأدوات الذكاء الاصطناعي enforcing-dto-record setup guide C# record implementation DTO immutability value equality in C# enforcing-dto-record vs class implementation how to use enforcing-dto-record in C# enforcing-dto-record install C# record benefits enforcing-dto-record best practices C# record DTO记录强制 数据传输对象 不变性 值基于的相等性 with表达式 sealed class 位置参数 Enforces DTO implementation as C# records Provides immutability and value equality for DTOs Replaces `sealed class` + `{ get; set; }` pattern with `record` + positional parameters or `{ get; init; }` Excludes entities and domain models that require state changes Improves code quality with `with` expression support enforcing-dto-record is a skill that enforces the implementation of Data Transfer Objects (DTOs) as records in C#, ensuring immutability and value equality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cluesmith/codev/codev', 'community', 'cluesmith', 'codev', 'cluesmith/codev', 'codev', 0, 0, 33, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:37.293Z', 'a2013ff6390448cfd2197d450164bb79e5ef433357b6b18e828cd6e6dd53b014', '{"id":"cluesmith/codev/codev","name":"codev","description":{"en":"codev helps humans and agents co-develop project context and code. It provides a structured approach to project management through its command-line interface.","zh":"Codev 是一个项目管理 CLI 工具，帮助人类和 AI 代理共同开发代码和上下文","ja":"Codev は、コードとコンテキストの共同開発を実現するプロジェクト管理 CLI ツールです","ko":"Codev는 코드와 컨텍스트의 공동 개발을 실현하는 프로젝트 관리 CLI 도구입니다","es":"Codev es una herramienta de gestión de proyectos que facilita la colaboración entre humanos y agentes en el desarrollo de proyectos.","fr":"Codev est un outil de gestion de projet qui facilite la collaboration entre humains et agents dans le développement de projets.","de":"Codev ist ein Projektmanagement-Tool, das die Zusammenarbeit zwischen Menschen und Agenten im Projektentwicklung erleichtert.","pt":"O Codev é uma ferramenta de gerenciamento de projeto CLI que facilita a colaboração entre humanos e agentes no desenvolvimento de projetos","ru":"Codev - это инструмент управления проектами с поддержкой ИИ Агентов, который упрощает сотрудничество между людьми и агентами при разработке проектов","ar":"Codev هو أداة إدارة المشاريع CLI تدعم التعاون بين البشر ووكلاء الذكاء الاصطناعي في تطوير المشاريع"},"seo":{"title":{"en":"codev: Project Management Setup Guide | AI Agent Skill","zh":"Codev 项目管理 CLI 设置指南","ja":"Codev プロジェクト管理 CLI 導入ガイド","ko":"Codev 프로젝트 관리 CLI 설정 가이드","es":"Guía de configuración de codev: Herramienta de gestión de...","fr":"Guide d''installation de codev : Outil de gestion de proje...","de":"Codev-Setup-Anleitung: Projektmanagement-CLI-Tool","pt":"Guia de Configuração do Codev: Ferramenta de Gerenciament...","ru":"Настройка Codev: Инструмент управления проектами с поддер...","ar":"دليل إعداد Codev: أداة إدارة المشاريع CLI مع دعم وكلاء ال..."},"description":{"en":"Unlock efficient project management with codev. Learn how to initialize, adopt, and update projects with codev''s CLI commands and discover its features.","zh":"了解 Codev 的强大功能，包括代码和上下文的协同开发，通过 CLI 命令行工具实现项目管理","ja":"Codev の強力な機能を紹介します。コードとコンテキストの共同開発を実現する CLI コマンドラインツールを使用したプロジェクト管理","ko":"Codev의 강력한 기능을 알아보세요. 코드와 컨텍스트의 공동 개발을 구현하는 CLI 명령줄 도구를 사용한 프로젝트 관리","es":"Descubre cómo codev facilita la colaboración entre humanos y agentes en el desarrollo de proyectos con su CLI","fr":"Découvrez comment codev facilite la collaboration entre humains et agents dans le développement de projets avec sa CLI","de":"Erfahren Sie, wie codev die Zusammenarbeit zwischen Menschen und Agenten im Projektentwicklung mit seiner CLI erleichtert","pt":"Aprenda a configurar o Codev, uma ferramenta de gerenciamento de projeto CLI que ajuda humanos e agentes a co-desenvolver contextos e códigos de projetos","ru":"Узнайте, как настроить Codev, инструмент управления проектами с поддержкой ИИ Агентов для совместного развития контекстов и кодов проектов","ar":"تعلم كيفية設定 Codev، أداة إدارة المشاريع CLI التي تساعد البشر ووكلاء الذكاء الاصطناعي على التعاون في تطوير السياقات وأكواد المشاريع"},"definition":{"en":"codev is a project management CLI tool that enables collaborative development of project context and code.","zh":"Codev 是一个项目管理 CLI 工具，实现代码和上下文的协同开发","ja":"Codev は、コードとコンテキストの共同開発を実現するプロジェクト管理 CLI ツール","ko":"Codev는 코드와 컨텍스트의 공동 개발을 실현하는 프로젝트 관리 CLI 도구","es":"Codev es una herramienta de línea de comandos (CLI) para la gestión de proyectos que permite la colaboración entre humanos y agentes.","fr":"Codev est un outil en ligne de commande (CLI) pour la gestion de projets qui permet la collaboration entre humains et agents.","de":"Codev ist ein Kommandozeilen-Tool (CLI) für das Projektmanagement, das die Zusammenarbeit zwischen Menschen und Agenten ermöglicht.","pt":"O Codev é uma ferramenta de gerenciamento de projeto que permite a criação de diretórios de projetos com estrutura completa","ru":"Codev - это инструмент управления проектами, который позволяет создавать директории проектов с полной структурой","ar":"Codev هو أداة إدارة المشاريع التي تمكن من إنشاء دليل مشروع مع هيكل كامل"},"features":{"en":["Initializes new project directories with codev init command","Adds codev to existing directories using the adopt command","Updates protocols, roles, and skills from packages with the update command","Checks system dependencies with the doctor command","Creates a full codev structure including specs/, plans/, and reviews/ directories"],"zh":["支持代码和上下文的协同开发","提供 CLI 命令行工具进行项目管理","包含 codev init、codev adopt、codev update 和 codev doctor 命令","创建新目录并初始化 codev 项目结构","支持协议、角色和技能的更新"],"ja":["コードとコンテキストの共同開発をサポート","CLI コマンドラインツールを使用したプロジェクト管理","codev init、codev adopt、codev update、codev doctor コマンドを含む","新しいディレクトリを作成し、codev プロジェクト構造を初期化","プロトコル、ロール、スキルの更新をサポート"],"ko":["코드와 컨텍스트의 공동 개발을 지원","CLI 명령줄 도구를 사용한 프로젝트 관리","codev init, codev adopt, codev update, codev doctor 명령을 포함","새로운 디렉토리를 생성하고 codev 프로젝트 구조를 초기화","프로토콜, 역할, 스킬의 업데이트를 지원"],"es":["Crea un nuevo directorio de proyecto con la estructura completa de codev","Incorpora comandos como ''codev init'', ''codev adopt'' y ''codev update'' para la gestión de proyectos","Permite la actualización de protocolos, roles y habilidades desde el paquete","Incluye un comando ''codev doctor'' para verificar las dependencias del sistema","Genera archivos como CLAUDE.md, AGENTS.md y af-config.json","Soporta la creación de un archivo .gitignore"],"fr":["Crée un nouveau répertoire de projet avec la structure complète de codev","Intègre des commandes comme ''codev init'', ''codev adopt'' et ''codev update'' pour la gestion de projets","Permet la mise à jour des protocoles, rôles et compétences depuis le paquet","Inclut une commande ''codev doctor'' pour vérifier les dépendances du système","Génère des fichiers comme CLAUDE.md, AGENTS.md et af-config.json","Prend en charge la création d''un fichier .gitignore"],"de":["Erstellt ein neues Projektverzeichnis mit der vollständigen codev-Struktur","Integriert Befehle wie ''codev init'', ''codev adopt'' und ''codev update'' für die Projektverwaltung","Ermöglicht die Aktualisierung von Protokollen, Rollen und Fähigkeiten aus dem Paket","Enthält einen Befehl ''codev doctor'' zur Überprüfung der Systemabhängigkeiten","Erzeugt Dateien wie CLAUDE.md, AGENTS.md und af-config.json","Unterstützt die Erstellung einer .gitignore-Datei"],"pt":["Criação de diretórios de projetos com estrutura completa","Suporte a comandos CLI para gerenciamento de projetos","Integração com habilidades e protocolos de agentes","Verificação de dependências do sistema","Atualização de protocolos e habilidades de agentes"],"ru":["Создание директорий проектов с полной структурой","Поддержка команд CLI для управления проектами","Интеграция с навыками и протоколами ИИ Агентов","Проверка зависимостей системы","Обновление протоколов и навыков ИИ Агентов"],"ar":["إنشاء دليل مشروع مع هيكل كامل","دعم أوامر CLI لإدارة المشاريع","التكامل مع مهارات وبروتوكولات وكلاء الذكاء الاصطناعي","فحص الإعتماديات النظام","تحديث بروتوكولات ومهارات وكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use codev","codev setup guide","codev alternative","codev vs github","codev install","codev project management","codev CLI commands","codev adopt command","codev update command"],"zh":["Codev","项目管理","CLI","代码协同开发","AI 代理","AI 工具","代码管理","项目结构","协议更新"],"ja":["Codev","プロジェクト管理","CLI","コード共同開発","AI エージェント","AI ツール","コード管理","プロジェクト構造","プロトコル更新"],"ko":["Codev","프로젝트 관리","CLI","코드 공동 개발","AI 에이전트","AI 도구","코드 관리","프로젝트 구조","프로토콜 업데이트"],"es":["codev","herramienta de gestión de proyectos","CLI","colaboración entre humanos y agentes","desarrollo de proyectos","gestión de proyectos","protocolos de proyecto","roles y habilidades en proyectos"],"fr":["codev","outil de gestion de projet","CLI","collaboration entre humains et agents","développement de projets","gestion de projets","protocoles de projet","rôles et compétences dans les projets"],"de":["codev","Projektmanagement-Tool","CLI","Zusammenarbeit zwischen Menschen und Agenten","Projektentwicklung","Projektverwaltung","Projektprotokolle","Rollen und Fähigkeiten in Projekten"],"pt":["codev","gerenciamento de projeto","CLI","desenvolvimento de projetos","colaboração entre humanos e agentes","ferramenta de gerenciamento de projeto","criação de diretórios de projetos","comandos CLI"],"ru":["codev","управление проектами","CLI","разработка проектов","сотрудничество между людьми и ИИ Агентами","инструмент управления проектами","создание директорий проектов","команды CLI"],"ar":["codev","إدارة المشاريع","CLI","تطوير المشاريع","التعاون بين البشر ووكلاء الذكاء الاصطناعي","أداة إدارة المشاريع","إنشاء دليل مشروع","أوامر CLI"]}},"owner":"cluesmith","repo":"codev","repoPath":"cluesmith/codev","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.347Z","topics":[],"category":"community","skillMd":{"name":"codev","description":"Codev project management CLI — init, adopt, update, and doctor commands. Check this skill before running any `codev` command (except `consult`, `porch`, or `af` which have their own skills). Use when setting up new projects, adding codev to existing repos, updating framework files, or diagnosing missing dependencies.","bodyPreview":"# codev - Project Management CLI\n\n## Commands\n\n```\ncodev init [project-name]      Create a new codev project directory\ncodev adopt                    Add codev to the current directory\ncodev update                   Update protocols, roles, skills from package\ncodev doctor                   Check system dependencies\n```\n\n## codev init\n\nCreates a **new directory** with the full codev structure: specs/, plans/, reviews/, protocols, CLAUDE.md, AGENTS.md, .claude/skills/, af-config.json, .gitignore.","body":"# codev - Project Management CLI\n\n## Commands\n\n```\ncodev init [project-name]      Create a new codev project directory\ncodev adopt                    Add codev to the current directory\ncodev update                   Update protocols, roles, skills from package\ncodev doctor                   Check system dependencies\n```\n\n## codev init\n\nCreates a **new directory** with the full codev structure: specs/, plans/, reviews/, protocols, CLAUDE.md, AGENTS.md, .claude/skills/, af-config.json, .gitignore.\n\n```bash\ncodev init my-app              # Interactive setup\ncodev init my-app -y           # Non-interactive with defaults\n```\n\n## codev adopt\n\nAdds codev to the **current directory** (existing project). Run from the project root. If CLAUDE.md or AGENTS.md already exists, creates `.codev-new` versions and spawns Claude to merge.\n\n```bash\ncodev adopt                    # Interactive\ncodev adopt -y                 # Skip conflict prompts\n```\n\n## codev update\n\nUpdates framework files (protocols, roles, skills) from the installed `@cluesmith/codev` package. **Never touches user data** (specs, plans, reviews). Creates `.codev-new` versions for customized files.\n\n```bash\ncodev update                   # Interactive update\ncodev update --dry-run         # Preview changes\ncodev update --force           # Overwrite all framework files\ncodev update --agent           # Agent mode: JSON stdout, no interactive merge\n```\n\n## codev doctor\n\nChecks all required dependencies: Node.js (>=18), git (>=2.5), gh (authenticated), and at least one AI CLI (Claude, Gemini, or Codex).\n\n```bash\ncodev doctor\n```\n\n## Common mistakes\n\n- There is NO `codev tower` command — use `af tower start/stop`\n- `codev init` creates a new directory — use `codev adopt` for existing projects\n- Always run `codev adopt` and `codev update` from the project root\n- `codev update` only updates framework files — it never touches specs/plans/reviews\n"},"lastSynced":"2026-03-08T02:03:37.293Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured project management through command-line interfaces.","zh":"非常适合需要通过命令行界面进行结构化项目管理的开发代理。","ja":"コマンドラインインターフェイスを介した構造化されたプロジェクト管理が必要な開発エージェントに最適です。","ko":"명령줄 인터페이스를 통해 구조화된 프로젝트 관리가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión de proyectos estructurada a través de interfaces de línea de comandos.","fr":"Parfait pour les Agents de Développement qui nécessitent une gestion de projets structurée via des interfaces en ligne de commande.","de":"Perfekt für Entwicklungsmittel, die eine strukturierte Projektverwaltung über Kommandozeilenoberflächen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de projetos estruturado por meio de interfaces de linha de comando.","ru":"Идеально подходит для агентов разработки, которым необходим структурированный менеджмент проектов через командную строку.","ar":"مثالي للوكلاء النموزجيون الذين يحتاجون إلى إدارة مشاريع منظمّة من خلال واجهات سطر الأوامر."},"recommendation":{"en":"Empowers agents to co-develop project context and code using protocols, roles, and skills from packages, while managing dependencies with commands like codev init, adopt, update, and doctor.","zh":"使代理能够使用协议、角色和技能包中的代码共同开发项目背景和代码，同时使用诸如codev init、adopt、update和doctor的命令管理依赖项。","ja":"エージェントがプロトコル、ロール、スキルパッケージ内のコードを使用してプロジェクトのコンテキストとコードを共同で開発し、codev init、adopt、update、doctorなどのコマンドを使用して依存関係を管理できるようにします。","ko":"에이전트가 프로토콜, 역할 및 스킬 패키지 내의 코드를 사용하여 프로젝트 컨텍스트 및 코드를 공동으로 개발하고 codev init, adopt, update 및 doctor 같은 명령을 사용하여 종속성을 관리할 수 있도록 합니다.","es":"Habilita a los agentes a codesarrollar el contexto y el código del proyecto utilizando protocolos, roles y habilidades de paquetes, mientras gestiona las dependencias con comandos como codev init, adopt, update y doctor.","fr":"Permet aux agents de co-développer le contexte et le code du projet en utilisant des protocoles, des rôles et des compétences provenant de packages, tout en gérant les dépendances avec des commandes comme codev init, adopt, update et doctor.","de":"Ermöglicht es den Agenten, den Projektinhalt und den Code mithilfe von Protokollen, Rollen und Fähigkeiten aus Paketen zu koentwickeln, während es Abhängigkeiten mit Befehlen wie codev init, adopt, update und doctor verwaltet.","pt":"Habilita os agentes a co-desenvolver o contexto e o código do projeto usando protocolos, papéis e habilidades de pacotes, enquanto gerenciam dependências com comandos como codev init, adopt, update e doctor.","ru":"Наделяет агентов возможностью совместного развития контекста и кода проекта с использованием протоколов, ролей и навыков из пакетов, а также управления зависимостями с помощью команд seperti codev init, adopt, update и doctor.","ar":"يمنح الوكلاء القدرة على التعاون في تطوير سياق المشروع والرمز البرمجي باستخدام البروتوكولات والأدوار والمهارات من الحزم، مع إدارة التبعيات بأوامر مثل codev init و adopt و update و doctor."},"useCases":{"en":["Initializing new project directories with codev init","Adopting codev into existing projects for streamlined management","Updating protocols and skills with codev update"],"zh":["使用codev init初始化新项目目录","将codev采用到现有项目中以实现流线型管理","使用codev update更新协议和技能"],"ja":["codev initを使用して新しいプロジェクトディレクトリを初期化する","codevを既存のプロジェクトに採用して管理をストリームライン化する","codev updateを使用してプロトコルとスキルを更新する"],"ko":["codev init를 사용하여 새로운 프로젝트 디렉토리를 초기화하는 것","codev를 기존 프로젝트에採用하여 관리를 스트림라인화하는 것","codev update를 사용하여 프로토콜 및 스킬을 업데이트하는 것"],"es":["Inicializar nuevos directorios de proyectos con codev init","Adoptar codev en proyectos existentes para una gestión optimizada","Actualizar protocolos y habilidades con codev update"],"fr":["Initialiser de nouveaux répertoires de projets avec codev init","Adopter codev dans des projets existants pour une gestion optimisée","Mettre à jour les protocoles et les compétences avec codev update"],"de":["Initialisieren neuer Projektmappen mit codev init","Integration von codev in bestehende Projekte für eine optimierte Verwaltung","Aktualisieren von Protokollen und Fähigkeiten mit codev update"],"pt":["Inicializando novos diretórios de projeto com codev init","Adotando codev em projetos existentes para gerenciamento simplificado","Atualizando protocolos e habilidades com codev update"],"ru":["Инициализация новых директорий проекта с помощью codev init","Внедрение codev в существующие проекты для упрощенного управления","Обновление протоколов и навыков с помощью codev update"],"ar":["تثبيت دليل مشروع جديد مع codev init","استخدام codev في مشاريع موجودة من أجل إدارة مبسطة","تحديث البروتوكولات والمهارات مع codev update"]},"limitations":{"en":["Requires command-line interface access","Dependent on system dependencies checked by codev doctor"],"zh":["需要命令行界面访问","依赖于codev doctor检查的系统依赖"],"ja":["コマンドラインインターフェイスへのアクセスが必要","codev doctorによってチェックされるシステム依存関係に依存する"],"ko":["명령줄 인터페이스 접근이 필요함","codev doctor에 의해 확인되는 시스템 종속성에 의존"],"es":["Requiere acceso a la interfaz de línea de comandos","Dependiente de las dependencias del sistema verificadas por codev doctor"],"fr":["Nécessite un accès à l''interface en ligne de commande","Dépend des dépendances du système vérifiées par codev doctor"],"de":["Benötigt Zugriff auf die Kommandozeilenoberfläche","Abhängig von den Systemabhängigkeiten, die von codev doctor überprüft werden"],"pt":["Requer acesso à interface de linha de comando","Dependente de dependências de sistema verificadas pelo codev doctor"],"ru":["Требуется доступ к командной строке","Зависит от системных зависимостей, проверяемых codev doctor"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر","يعتمد على التبعيات النظامية التي يتم فحصها بواسطة codev doctor"]},"version":4},"contentHash":"a2013ff6390448cfd2197d450164bb79e5ef433357b6b18e828cd6e6dd53b014","qualityScore":33}');
