INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aniketpanjwani/payload-plugin-email-newsletter/payload-v3-endpoints', 'payload-v3-endpoints', 'aniketpanjwani', 'payload-plugin-email-newsletter', 'community', 'payload-v3-endpoints aniketpanjwani payload-plugin-email-newsletter community The payload-v3-endpoints skill ensures correct patterns for Payload v3 endpoints and logger calls, preventing runtime errors and TypeScript issues for developers. 本文介绍了 Payload v3 Endpoints 的正确使用方法，包括请求体访问和日志记录调用，帮助开发者避免常见错误 この記事では、Payload v3 Endpoints の正しい使用方法について説明します。リクエストボディのアクセスとログ出力の呼び出し方を紹介し、開発者が一般的なエラーを避けることができます 이 문서는 Payload v3 Endpoints의 올바른 사용 방법을介绍하며, 요청 본문 접근 및 로깅 호출을 포함하여 개발자가 일반적인 오류를 피하는 데 도움이 됩니다 El plugin de Payload CMS para crear newsletters de correo electrónico requiere una configuración correcta de los endpoints v3 para evitar errores Le plugin Payload CMS pour créer des newsletters par e-mail nécessite une configuration correcte des endpoints v3 pour éviter les erreurs Das Payload-CMS-Plugin zum Erstellen von E-Mail-Newslettern erfordert eine korrekte Konfiguration der Endpunkte v3, um Fehler zu vermeiden O plugin Payload CMS para criar um boletim de notícias por e-mail requer configuração correta de endpoints v3. Aprenda a evitar erros de tempo de execução e problemas de TypeScript. Плагин Payload CMS для создания электронного бюллетеня требует правильной настройки конечных точек v3. Узнайте, как избежать ошибок во время выполнения и проблем с TypeScript при использовании ИИ Агентов. ملحق Payload CMS لإنشاء نشرة إخبارية بالبريد الإلكتروني يتطلب إعدادًا صحيحًا لنقاط النهاية v3. تعرف على كيفية تجنب الأخطاء أثناء التنفيذ ومشاكل TypeScript في الآليات الذكية. how to use payload-v3-endpoints payload-v3-endpoints setup guide typescript best practices for payload-v3-endpoints payload-v3-endpoints vs payload-v2 payload-v3-endpoints install avoiding runtime errors in payload-v3-endpoints Payload v3 Endpoints AI エージェント开发 请求体访问 日志记录调用 TypeScript 问题 运行时错误 电子邮件新闻稿 CMS 插件 Implements correct TypeScript handler patterns for Payload v3 endpoints Uses async/await for req.json() to handle request body data Avoids undefined req.data by using the correct req.json() method Supports logger calls with correct patterns to prevent runtime errors Ensures compatibility with Payload v3 and TypeScript payload-v3-endpoints is a CMS plugin for creating email newsletters, focusing on correct TypeScript patterns for endpoint handling and logging.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hw-native-sys/pypto/github-pr', 'community', 'hw-native-sys', 'pypto', 'hw-native-sys/pypto', 'github-pr', 0, 0, 33, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:39.638Z', '0c2aa6732a895231102b6c7f1a18925388d3f350613b8f2d5c0a32b7fe421acc', '{"id":"hw-native-sys/pypto/github-pr","name":"github-pr","description":{"en":"The github-pr skill automates GitHub pull requests for developers, simplifying the workflow with features like rebasing and conflict resolution. It benefits developers working with GitHub repositories.","zh":"GitHub PR 工作流是一个社区驱动的 PyPTO 实现，自动化代码审查和合并","ja":"GitHub PR ワークフローはコミュニティ主導の PyPTO 実装であり、コードレビューとマージを自動化します","ko":"GitHub PR 워크플로우는 커뮤니티 주도형 PyPTO 구현으로 코드 리뷰와 머지를 자동화합니다","es":"github-pr es una implementación de PyPTO que automatiza las solicitudes de extracción en GitHub, mejorando la colaboración y la eficiencia en el desarrollo de software","fr":"github-pr est une implémentation de PyPTO qui automatise les demandes d''extraction sur GitHub, améliorant la collaboration et l''efficacité dans le développement de logiciels","de":"github-pr ist eine Implementierung von PyPTO, die Pull-Requests auf GitHub automatisiert und die Zusammenarbeit und Effizienz in der Softwareentwicklung verbessert","pt":"O github-pr é uma implementação de pypto que automatiza o fluxo de trabalho de pull request no GitHub. Ele resolve conflitos e cria PRs com facilidade.","ru":"github-pr - это реализация pypto, которая автоматизирует работу с пулл-запросами в GitHub. Он решает конфликты и создает PR с легкостью.","ar":"github-pr هو تطبيق pypto يسرع سير عمل طلبات السحب في GitHub. ي 해결 النزاعات وإنشاء طلبات السحب بسهولة."},"seo":{"title":{"en":"github-pr: Automated Pull Request Workflow Setup Guide | ...","zh":"GitHub PR 工作流设置指南","ja":"GitHub PR ワークフロー設定ガイド - AIエージェント","ko":"GitHub PR 워크플로우 설정 가이드 - AI 도구","es":"Guía de Configuración para github-pr: Automatización de S...","fr":"Guide de Configuration pour github-pr : Automation des De...","de":"Konfigurationsleitfaden für github-pr: Automatisierung vo...","pt":"Guia de Configuração do github-pr: Fluxo de Trabalho de P...","ru":"Настройка github-pr: Работа с Пулл-Запросами в GitHub","ar":"دليل إعداد github-pr: سير عمل طلبات السحب"},"description":{"en":"Streamline your GitHub workflow with github-pr. Learn how to automate pull requests and simplify your development process. Get started now!","zh":"学习如何使用 GitHub PR 工作流自动化代码审查和合并，提高开发效率","ja":"GitHub PR ワークフローを使用してコードレビューとマージを自動化し、開発効率を向上させる方法を学びます - AIエージェント","ko":"GitHub PR 워크플로우를 사용하여 코드 리뷰와 머지 자동화를 통해 개발 효율성을 높이는 방법을 알아보세요 - AI 도구","es":"Aprende a configurar github-pr para automatizar las solicitudes de extracción en GitHub y optimiza tu flujo de trabajo con PyPTO","fr":"Découvrez comment configurer github-pr pour automatiser les demandes d''extraction sur GitHub et optimisez votre workflow avec PyPTO","de":"Erfahren Sie, wie Sie github-pr konfigurieren, um Pull-Requests auf GitHub zu automatisieren und Ihren Workflow mit PyPTO zu optimieren","pt":"Aprenda a configurar o github-pr para automatizar o fluxo de trabalho de pull request no GitHub. Descubra como resolver conflitos e criar PRs com facilidade.","ru":"Узнайте, как настроить github-pr для автоматизации работы с пулл-запросами в GitHub. Откройте для себя, как решать конфликты и создавать PR с легкостью.","ar":"تعلم كيفية إعداد github-pr لتسريع سير عمل طلبات السحب في GitHub. اكتشف كيفية حل النزاعات وإنشاء طلبات السحب بسهولة."},"definition":{"en":"github-pr is a community-driven Python implementation for automating GitHub pull request workflows, utilizing commands like git branch and gh CLI.","zh":"GitHub PR 工作流是指使用 PyPTO 实现的自动化代码审查和合并过程","ja":"GitHub PR ワークフローとは、PyPTO を使用したコードレビューとマージの自動化プロセスです","ko":"GitHub PR 워크플로우는 PyPTO를 사용한 코드 리뷰와 머지 자동화 프로세스를 말합니다","es":"github-pr es una herramienta de automatización de solicitudes de extracción en GitHub que utiliza PyPTO","fr":"github-pr est un outil d''automatisation des demandes d''extraction sur GitHub qui utilise PyPTO","de":"github-pr ist ein Tool zur Automatisierung von Pull-Requests auf GitHub, das PyPTO verwendet","pt":"O github-pr é uma ferramenta que automatiza o fluxo de trabalho de pull request no GitHub.","ru":"github-pr - это инструмент, который автоматизирует работу с пулл-запросами в GitHub.","ar":"github-pr هو أداة تسرع سير عمل طلبات السحب في GitHub."},"features":{"en":["Prepares branches and commits using git branch and git status","Checks for existing pull requests and exits if found","Fetches upstream changes and rebases onto upstream/main","Resolves conflicts using git commands","Pushes to forks with --force-with-lease and creates PRs using gh CLI"],"zh":["自动准备分支和提交","检查现有 PR 并退出","获取上游更改并重置","解决冲突并强制推送","使用 gh CLI 创建 PR"],"ja":["自動でブランチとコミットを準備","既存の PR を確認して終了","上流の変更を取得してリセット","コンフリクトを解決して強制的にプッシュ","gh CLI を使用して PR を作成"],"ko":["자동으로 브랜치와 커밋을 준비","既存의 PR를 확인하고 종료","업스트림 변경을 가져와 리셋","충돌을 해결하고 강제로 푸시","gh CLI를 사용하여 PR을 생성"],"es":["Automatización de solicitudes de extracción en GitHub","Integración con PyPTO para mejorar la colaboración","Rebase automático en la rama principal","Resolución de conflictos y push forzado con --force-with-lease","Creación de solicitudes de extracción utilizando gh CLI"],"fr":["Automation des demandes d''extraction sur GitHub","Intégration avec PyPTO pour améliorer la collaboration","Rebase automatique sur la branche principale","Résolution de conflits et push forcé avec --force-with-lease","Création de demandes d''extraction en utilisant gh CLI"],"de":["Automatisierung von Pull-Requests auf GitHub","Integration mit PyPTO für verbesserte Zusammenarbeit","Automatischer Rebase auf dem Hauptbranch","Konfliktlösung und erzwungener Push mit --force-with-lease","Erstellung von Pull-Requests mithilfe von gh CLI"],"pt":["Preparação de branch e commit","Verificação de PR existente","Rebase onto upstream/main","Resolução de conflitos","Criação de PR usando gh CLI"],"ru":["Подготовка ветки и коммита","Проверка существующего PR","Rebase onto upstream/main","Решение конфликтов","Создание PR с помощью gh CLI"],"ar":["إعداد الفرع والالتزام","التحقق من طلب السحب الموجود","Rebase onto upstream/main","حل النزاعات","إنشاء طلب السحب باستخدام غه CLI"]},"keywords":{"en":["github-pr setup guide","automated pull request workflow","github-pr vs git flow","how to use github-pr","github-pr install","github-pr alternative","github-pr workflow automation","github-pr and git cli","github-pr for developers"],"zh":["GitHub PR","PyPTO","代码审查","自动化合并","gh CLI","代码管理","版本控制","开发工具"],"ja":["GitHub PR","PyPTO","コードレビュー","自動マージ","gh CLI","コード管理","バージョン管理","開発ツール","AIエージェント"],"ko":["GitHub PR","PyPTO","코드 리뷰","자동 머지","gh CLI","코드 관리","버전 관리","개발 도구","AI 도구"],"es":["github-pr","PyPTO","automatización de solicitudes de extracción","colaboración en GitHub","desarrollo de software","herramientas de automatización","gh CLI","rebase automático","resolución de conflictos"],"fr":["github-pr","PyPTO","automatisation des demandes d''extraction","collaboration sur GitHub","développement de logiciels","outils d''automatisation","gh CLI","rebase automatique","résolution de conflits"],"de":["github-pr","PyPTO","Automatisierung von Pull-Requests","Zusammenarbeit auf GitHub","Softwareentwicklung","Automatisierungstools","gh CLI","automatischer Rebase","Konfliktlösung"],"pt":["github-pr","pypto","fluxo de trabalho de pull request","automatização de PR","resolução de conflitos","criação de PR","gh CLI","GitHub","desenvolvimento de software"],"ru":["github-pr","pypto","работа с пулл-запросами","автоматизация PR","решение конфликтов","создание PR","gh CLI","GitHub","разработка программного обеспечения"],"ar":["github-pr","pypto","سير عمل طلبات السحب","تسريع طلبات السحب","حل النزاعات","إنشاء طلبات السحب","غه CLI","GitHub","تطوير البرمجيات"]}},"owner":"hw-native-sys","repo":"pypto","repoPath":"hw-native-sys/pypto","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.347Z","topics":[],"category":"community","skillMd":{"name":"github-pr","description":"Create a GitHub pull request after committing, rebasing, and pushing changes. Use when the user asks to create a PR, submit changes for review, or open a pull request.","bodyPreview":"# PyPTO GitHub Pull Request Workflow\n\n## Workflow Steps\n\n1. **Prepare branch and commit** (if on main or uncommitted changes)\n2. Check for existing PR (exit if found)\n3. Fetch upstream changes\n4. Rebase onto upstream/main\n5. Resolve conflicts if needed\n6. Push to fork with `--force-with-lease`\n7. Create PR using gh CLI\n\n## Step 1: Prepare Branch and Commit\n\n**Check current state:**\n\n```bash\nBRANCH_NAME=$(git branch --show-current)\ngit status --porcelain                              # Check for u","body":"# PyPTO GitHub Pull Request Workflow\n\n## Workflow Steps\n\n1. **Prepare branch and commit** (if on main or uncommitted changes)\n2. Check for existing PR (exit if found)\n3. Fetch upstream changes\n4. Rebase onto upstream/main\n5. Resolve conflicts if needed\n6. Push to fork with `--force-with-lease`\n7. Create PR using gh CLI\n\n## Step 1: Prepare Branch and Commit\n\n**Check current state:**\n\n```bash\nBRANCH_NAME=$(git branch --show-current)\ngit status --porcelain                              # Check for uncommitted changes\ngit fetch upstream 2>/dev/null || git fetch origin  # Fetch latest\nif git rev-parse --verify upstream/main >/dev/null 2>&1; then\n  BASE_REF=upstream/main\nelse\n  BASE_REF=origin/main\nfi\ngit rev-list HEAD --not \"$BASE_REF\" --count         # Commits ahead of base\n```\n\nA branch \"needs a new branch\" when it is effectively on main — either the branch name is `main`/`master`, **or** it has zero commits ahead of upstream/main (e.g., a local branch that was never diverged).\n\n**Decision logic:**\n\n| Needs new branch? | Uncommitted changes? | Action |\n| ----------------- | -------------------- | ------ |\n| Yes | Yes | Create new branch, then commit via `/git-commit` |\n| Yes | No | Error — nothing to PR. Tell user to make changes first |\n| No | Yes | Commit on current branch via `/git-commit` |\n| No | No | Skip — already committed on a feature branch |\n\n**If a new branch is needed:**\n\n1. Auto-generate a branch name with a meaningful prefix (`feat/`, `fix/`, `refactor/`, `chore/`, `docs/`, `test/`) based on the changes — do NOT ask the user\n2. Create and switch to the new branch:\n\n```bash\ngit checkout -b <branch-name>\n```\n\n1. Commit via `/git-commit` skill (mandatory — runs code review, testing, linting)\n\n**If on an existing feature branch with uncommitted changes:**\n\nCommit via `/git-commit` skill before proceeding.\n\n## Step 2: Check for Existing PR\n\n```bash\nBRANCH_NAME=$(git branch --show-current)\ngh pr list --head \"$BRANCH_NAME\" --state open\n```\n\n**If PR exists**: Display with `gh pr view` and exit immediately.\n\n## Step 3: Fetch Upstream\n\n```bash\ngit remote add upstream https://github.com/hw-native-sys/pypto.git  # If needed\ngit fetch upstream\n```\n\n## Step 4: Rebase\n\n```bash\ngit rebase upstream/main  # Or user-specified branch\n```\n\n**On conflicts**:\n\n```bash\ngit status                     # View conflicts\n# Edit files, remove markers\ngit add path/to/resolved/file\ngit rebase --continue\n# If stuck: git rebase --abort\n```\n\n## Step 5: Push\n\n```bash\n# First push\ngit push --set-upstream origin BRANCH_NAME\n\n# After rebase (use --force-with-lease, NOT --force)\ngit push --force-with-lease origin BRANCH_NAME\n```\n\n⚠️ **Use `--force-with-lease`** - safer than `--force`, fails if remote has unexpected changes.\n\n## Step 6: Create PR\n\n**Check gh CLI**:\n\n```bash\ngh auth status\n```\n\n**If gh NOT available**: Report to user and provide manual URL: `https://github.com/hw-native-sys/pypto/compare/main...BRANCH_NAME`\n\n**If gh available**:\n\n```bash\ngh pr create \\\n  --title \"Brief description of changes\" \\\n  --body \"$(cat <<''EOF''\n## Summary\n- Key change 1\n- Key change 2\n\n## Testing\n- [ ] All tests pass\n- [ ] Code review completed\n- [ ] Documentation updated\n\n## Related Issues\nFixes #ISSUE_NUMBER (if applicable)\nEOF\n)\"\n```\n\n**PR Title/Body**: Auto-extracted from commit messages since upstream/main.\n\n**Important**:\n\n- ❌ Do NOT add footers like \"🤖 Generated with Claude Code\" or similar branding\n- ✅ Keep PR descriptions professional and focused on technical content only\n\n## Common Issues\n\n| Issue | Solution |\n| ----- | -------- |\n| PR already exists | `gh pr view` then exit |\n| Merge conflicts | Resolve, `git add`, `git rebase --continue` |\n| Push rejected | `git push --force-with-lease` |\n| gh not authenticated | Tell user to run `gh auth login` |\n| Wrong upstream branch | Use `git rebase upstream/BRANCH` |\n\n## Checklist\n\n- [ ] Branch prepared (created from main if needed)\n- [ ] Changes committed via `/git-commit` (if uncommitted changes existed)\n- [ ] No existing PR for branch (exit if found)\n- [ ] Fetched upstream and rebased successfully\n- [ ] Conflicts resolved\n- [ ] Pushed with `--force-with-lease`\n- [ ] PR created with clear title/body\n\n## Remember\n\n- Always rebase before creating PR\n- Use `--force-with-lease`, not `--force`\n- Don''t auto-install gh CLI - let user do it\n"},"lastSynced":"2026-03-08T02:03:39.638Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring streamlined GitHub workflow automation and conflict resolution","zh":"适用于需要简化GitHub工作流自动化和冲突解决的DevOps代理","ja":"GitHubのワークフロー自動化とコンフリクト解決を効率化する必要があるDevOpsエージェントに適しています","ko":"GitHub 워크플ロー 자동화 및 충돌 해결을 간소화해야 하는 DevOps 에이전트에 적합합니다","es":"Ideal para agentes de DevOps que requieren una automatización de flujo de trabajo de GitHub optimizada y resolución de conflictos","fr":"Idéal pour les agents DevOps nécessitant une automatisation du flux de travail GitHub rationalisée et une résolution de conflits","de":"Ideal für DevOps-Agents, die eine optimierte GitHub-Workflow-Automatisierung und Konfliktlösung erfordern","pt":"Ideal para Agentes DevOps que exigem automação de fluxo de trabalho do GitHub simplificada e resolução de conflitos","ru":"Идеально для агентов DevOps, требующих упрощенной автоматизации рабочего процесса GitHub и разрешения конфликтов","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى تسهيل تلقائي لتدفق العمل على GitHub وحل النزاعات"},"recommendation":{"en":"Empowers agents to automate GitHub pull requests using gh CLI, handling rebasing and conflict resolution with features like force-with-lease push, simplifying the workflow for developers working with GitHub repositories","zh":"赋予代理使用gh CLI自动化GitHub拉取请求的能力，处理变基和冲突解决，并具有force-with-lease推送等功能，简化开发人员与GitHub仓库合作的工作流","ja":"エージェントがgh CLIを使用してGitHubのプルリクエストを自動化し、リベースとコンフリクト解決を処理する機能を提供し、force-with-leaseプッシュなどの機能で開発者のGitHubリポジトリでの作業を簡素化する","ko":"에이전트가 gh CLI를 사용하여 GitHub 풀 요청을 자동화하고 리베이스 및 충돌 해결을 처리하며 force-with-lease 푸시 등과 같은 기능으로 GitHub 리포지토리에서 개발자들의 작업을 간소화하는 기능을 제공합니다","es":"Habilita a los agentes a automatizar solicitudes de extracción de GitHub utilizando gh CLI, manejo de rebasing y resolución de conflictos con características como force-with-lease push, simplificando el flujo de trabajo para los desarrolladores que trabajan con repositorios de GitHub","fr":"Permet aux agents d''automatiser les demandes d''extraction GitHub à l''aide de gh CLI, en gérant le rebasing et la résolution des conflits avec des fonctionnalités comme force-with-lease push, simplifiant ainsi le flux de travail pour les développeurs travaillant avec des référentiels GitHub","de":"Ermächtigt die Agents, GitHub-Pull-Requests mit gh CLI zu automatisieren, das Rebasing und die Konfliktlösung mit Funktionen wie force-with-lease push zu verwalten, wodurch der Workflow für Entwickler, die mit GitHub-Repositorys arbeiten, vereinfacht wird","pt":"Habilita os agentes a automatizar solicitações de pull do GitHub usando o gh CLI, lidando com rebase e resolução de conflitos com recursos como force-with-lease push, simplificando o fluxo de trabalho para desenvolvedores que trabalham com repositórios do GitHub","ru":"Наделяет агентов возможностью автоматизировать запросы на включение изменений в GitHub с помощью gh CLI, обрабатывая ребейзинг и разрешение конфликтов с функциями, такими как force-with-lease push, упрощая рабочий процесс для разработчиков, работающих с репозиториями GitHub","ar":"يُمنح الوكلاء القدرة على تلقين طلبات السحب من GitHub باستخدام gh CLI، والتَعامل مع إعادة التحديث وحل النزاعات بميزات مثل force-with-lease push، وبذلك يُبسط تدفق العمل للمطورين الذين يعملون مع مستودعات GitHub"},"useCases":{"en":["Automating pull requests for continuous integration","Rebasing branches onto upstream/main for synchronized development","Resolving conflicts for seamless merge operations"],"zh":["持续集成的拉取请求自动化","将分支重新基准到上游/主分支以实现同步开发","解决冲突以实现无缝合并操作"],"ja":["継続的インテグレーションのプルリクエスト自動化","ブランチを上流/メインブランチにリベースして同期開発を行う","コンフリクトを解決してシームレスなマージ操作を実行する"],"ko":["지속적인 통합을 위한 풀 요청 자동화","브랜치를 업스트림/메인 브랜치로 리베이스하여 동기화된 개발을 수행하는 것","충돌을 해결하여无缝な 머지 동작을 수행하는 것"],"es":["Automatización de solicitudes de extracción para integración continua","Rebasing de ramas en upstream/main para desarrollo sincronizado","Resolución de conflictos para operaciones de fusión sin problemas"],"fr":["Automatisation des demandes d''extraction pour l''intégration continue","Rebasing des branches sur upstream/main pour un développement synchronisé","Résolution de conflits pour des opérations de fusion sans problème"],"de":["Automatisierung von Pull-Requests für kontinuierliche Integration","Rebasing von Branches auf upstream/main für synchronisierte Entwicklung","Auflösung von Konflikten für nahtlose Merge-Vorgänge"],"pt":["Automatizar solicitações de pull para integração contínua","Rebaser ramificações para desenvolvimento sincronizado","Resolver conflitos para operações de mesclagem sem interrupção"],"ru":["Автоматизация запросов на включение изменений для непрерывной интеграции","Ребейзинг веток для синхронного развития","Разрешение конфликтов для бесперебойных операций слияния"],"ar":["تلقين طلبات السحب للاستمرار والتكامل","إعادة تحديث الفروع للتنمية المتزامنة","حل النزاعات لعمليات الدمج المتواصلة"]},"limitations":{"en":["Requires gh CLI installation","Limited to GitHub repositories","Needs proper git configuration for rebasing and pushing"],"zh":["需要安装gh CLI","仅限于GitHub仓库","需要正确的git配置以进行变基和推送"],"ja":["gh CLIのインストールが必要","GitHubリポジトリのみに限定される","リベースとプッシュを行うために適切なGitの設定が必要"],"ko":["gh CLI 설치가 필요합니다","GitHub 리포지토리만 해당됩니다","리베이스 및 푸시를 위해 적절한 Git 설정이 필요합니다"],"es":["Requiere la instalación de gh CLI","Limitado a repositorios de GitHub","Necesita una configuración adecuada de git para rebasing y envío"],"fr":["Nécessite l''installation de gh CLI","Limité aux référentiels GitHub","Nécessite une configuration git appropriée pour le rebasing et l''envoi"],"de":["Erfordert die Installation von gh CLI","Begrenzt auf GitHub-Repositorys","Benötigt eine ordnungsgemäße git-Konfiguration für Rebasing und Pushen"],"pt":["Exige instalação do gh CLI","Limitado a repositórios do GitHub","Necessita de configuração adequada do git para rebase e push"],"ru":["Требует установки gh CLI","Ограничен репозиториями GitHub","Требует правильной настройки git для ребейзинга и пуша"],"ar":["يتطلب تثبيت gh CLI","محدود بمستودعات GitHub","يحتاج إلى تكوين مناسب ل git من أجل إعادة التحديث والدفع"]},"version":4},"contentHash":"0c2aa6732a895231102b6c7f1a18925388d3f350613b8f2d5c0a32b7fe421acc","qualityScore":33}');
