INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hw-native-sys/pypto/github-pr', 'github-pr', 'hw-native-sys', 'pypto', 'community', 'github-pr hw-native-sys pypto community The github-pr skill automates GitHub pull requests for developers, simplifying the workflow with features like rebasing and conflict resolution. It benefits developers working with GitHub repositories. GitHub PR 工作流是一个社区驱动的 PyPTO 实现，自动化代码审查和合并 GitHub PR ワークフローはコミュニティ主導の PyPTO 実装であり、コードレビューとマージを自動化します GitHub PR 워크플로우는 커뮤니티 주도형 PyPTO 구현으로 코드 리뷰와 머지를 자동화합니다 github-pr es una implementación de PyPTO que automatiza las solicitudes de extracción en GitHub, mejorando la colaboración y la eficiencia en el desarrollo de software github-pr est une implémentation de PyPTO qui automatise les demandes d''extraction sur GitHub, améliorant la collaboration et l''efficacité dans le développement de logiciels github-pr ist eine Implementierung von PyPTO, die Pull-Requests auf GitHub automatisiert und die Zusammenarbeit und Effizienz in der Softwareentwicklung verbessert O github-pr é uma implementação de pypto que automatiza o fluxo de trabalho de pull request no GitHub. Ele resolve conflitos e cria PRs com facilidade. github-pr - это реализация pypto, которая автоматизирует работу с пулл-запросами в GitHub. Он решает конфликты и создает PR с легкостью. github-pr هو تطبيق pypto يسرع سير عمل طلبات السحب في GitHub. ي 해결 النزاعات وإنشاء طلبات السحب بسهولة. github-pr setup guide automated pull request workflow github-pr vs git flow how to use github-pr github-pr install github-pr alternative github-pr workflow automation github-pr and git cli github-pr for developers GitHub PR PyPTO 代码审查 自动化合并 gh CLI 代码管理 版本控制 开发工具 Prepares branches and commits using git branch and git status Checks for existing pull requests and exits if found Fetches upstream changes and rebases onto upstream/main Resolves conflicts using git commands Pushes to forks with --force-with-lease and creates PRs using gh CLI github-pr is a community-driven Python implementation for automating GitHub pull request workflows, utilizing commands like git branch and gh CLI.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('C20-40A/mr-wplace/add-tutorial', 'community', 'C20-40A', 'mr-wplace', 'C20-40A/mr-wplace', 'add-tutorial', 0, 0, 33, '2026-03-08T01:57:15.348Z', '2026-03-08T02:03:41.845Z', '63c8245215711ba1fd99f80e5b1bf2115b70607745f6698c352661061f500024', '{"id":"C20-40A/mr-wplace/add-tutorial","name":"add-tutorial","description":{"en":"The add-tutorial skill allows developers to create interactive tutorials by adding GIF files, Japanese and English titles, and step-by-step instructions. It benefits AI agent developers and users alike.","zh":"add-tutorial技能允许开发者通过命令行界面添加教程，支持GIF文件和多语言标题","ja":"add-tutorialスキルは、開発者がコマンドラインインターフェースからチュートリアルを追加できるようにします。GIFファイルと多言語タイトルをサポート","ko":"add-tutorial 기능은 개발자가 명령줄 인터페이스를 통해 튜토리얼을 추가할 수 있게 해줍니다. GIF 파일 및 다국어 제목 지원","es":"Add-tutorial es una habilidad que permite a los desarrolladores agregar tutoriales con GIF y títulos en japonés e inglés, utilizando comandos como /add-tutorial","fr":"Add-tutorial est une compétence qui permet aux développeurs d''ajouter des didacticiels avec des GIF et des titres en japonais et en anglais, en utilisant des commandes comme /add-tutorial","de":"Add-tutorial ist eine Fähigkeit, die es Entwicklern ermöglicht, Tutorien mit GIF und Titeln in Japanisch und Englisch hinzuzufügen, indem sie Befehle wie /add-tutorial verwenden","pt":"O add-tutorial é uma habilidade que permite criar tutoriais personalizados com GIFs e títulos em japonês e inglês para Ferramentas de IA","ru":"add-tutorial - это навык, который позволяет создавать индивидуальные уроки с GIF и заголовками на японском и английском языках для ИИ Агентов","ar":"إضافة add-tutorial هي مهارة تسمح بإنشاء دروس مخصصة مع ملفات GIF وأسماء باللغة اليابانية والإنجليزية لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"add-tutorial: Tutorial Creation Guide for AI Agents","zh":"添加教程 Setup Guide - AI工具","ja":"チュートリアル追加 Setup Guide - AIエージェント","ko":"튜토리얼 추가 Setup Guide - AI 툴","es":"Guía de configuración de add-tutorial para desarrolladores","fr":"Guide d''installation d''add-tutorial pour les développeurs","de":"Einrichtungsanleitung für add-tutorial-Entwickler","pt":"Guia de Configuração do add-tutorial para Ferramentas de IA","ru":"Настройка ИИ Агентов с помощью add-tutorial: Руководство","ar":"دليل إعداد إضافة add-tutorial لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create interactive tutorials with add-tutorial. Learn to add GIFs, titles, and steps with ease. Get started now!","zh":"使用add-tutorial技能，通过简单的命令行界面添加教程，支持GIF文件和多语言标题","ja":"add-tutorialスキルを使用して、コマンドラインインターフェースからチュートリアルを追加します。GIFファイルと多言語タイトルをサポート","ko":"add-tutorial 기능을 사용하여 간단한 명령줄 인터페이스를 통해 튜토리얼을 추가합니다. GIF 파일 및 다국어 제목 지원","es":"Aprende a configurar add-tutorial con nuestra guía paso a paso para desarrolladores, incluyendo la adición de GIF y títulos en japonés e inglés","fr":"Découvrez comment configurer add-tutorial avec notre guide étape par étape pour les développeurs, y compris l''ajout de GIF et de titres en japonais et en ang...","de":"Erfahren Sie, wie Sie add-tutorial mit unserer Schritt-für-Schritt-Anleitung für Entwickler konfigurieren, einschließlich der Hinzufügung von GIF und Titeln ...","pt":"Aprenda a configurar o add-tutorial para criar tutoriais personalizados com GIFs e títulos em japonês e inglês para Ferramentas de IA","ru":"Узнайте, как настроить add-tutorial для создания индивидуальных уроков с GIF и заголовками на японском и английском языках для ИИ Агентов","ar":"تعرف على كيفية إعداد إضافة add-tutorial لإنشاء دروس مخصصة مع ملفات GIF وأسماء باللغة اليابانية والإنجليزية لأدوات الذكاء الاصطناعي"},"definition":{"en":"add-tutorial is a skill that enables the creation of interactive tutorials with GIF files, multi-language support, and step-by-step guidance.","zh":"add-tutorial是AI工具中的一个技能，允许开发者添加教程","ja":"add-tutorialはAIエージェントのスキルであり、開発者がチュートリアルを追加できるようにします","ko":"add-tutorial은 AI 툴의 기능으로 개발자가 튜토리얼을 추가할 수 있게 해줍니다","es":"Add-tutorial es una habilidad de agente de inteligencia artificial que permite la creación de tutoriales interactivos","fr":"Add-tutorial est une compétence d''agent d''intelligence artificielle qui permet la création de didacticiels interactifs","de":"Add-tutorial ist eine Fähigkeit von künstlicher Intelligenz, die die Erstellung interaktiver Tutorien ermöglicht","pt":"O add-tutorial é uma habilidade de IA que permite adicionar tutoriais personalizados com recursos multimídia","ru":"add-tutorial - это навык ИИ, который позволяет добавлять индивидуальные уроки с мультимедийными ресурсами","ar":"إضافة add-tutorial هي مهارة ذكاء اصطناعي تسمح بإضافة دروس مخصصة مع موارد متعددة"},"features":{"en":["Supports GIF file addition via `/add-tutorial` command","Allows for Japanese and English title input","Enables step-by-step addition through interactive prompts","Requires `manifest.json` and `manifest.template.json` updates for web-accessible resources","Supports 2-5 step inputs for customizable tutorial lengths"],"zh":["支持GIF文件","多语言标题支持","命令行界面添加教程","对话式界面添加步骤","支持2-5个步骤"],"ja":["GIFファイルをサポート","多言語タイトルをサポート","コマンドラインインターフェースからチュートリアルを追加","対話式インターフェースからステップを追加","2-5個のステップをサポート"],"ko":["GIF 파일 지원","다국어 제목 지원","명령줄 인터페이스를 통해 튜토리얼 추가","대화식 인터페이스를 통해 단계 추가","2-5개의 단계 지원"],"es":["Compatibilidad con comandos como /add-tutorial","Adición de GIF y títulos en japonés e inglés","Interfaz de diálogo para agregar pasos","Soporte para archivos JSON y manifest","Personalización de recursos web accesibles"],"fr":["Compatibilité avec des commandes comme /add-tutorial","Ajout de GIF et de titres en japonais et en anglais","Interface de dialogue pour ajouter des étapes","Prise en charge de fichiers JSON et de manifeste","Personnalisation de ressources web accessibles"],"de":["Kompatibilität mit Befehlen wie /add-tutorial","Hinzufügung von GIF und Titeln in Japanisch und Englisch","Dialogschnittstelle zum Hinzufügen von Schritten","Unterstützung für JSON- und Manifestdateien","Anpassung von webzugänglichen Ressourcen"],"pt":["Criação de tutoriais personalizados com GIFs","Suporte a títulos em japonês e inglês","Integração com manifest.json e manifest.template.json","Adição de passos personalizados via CLI","Suporte a recursos acessíveis na web"],"ru":["Создание индивидуальных уроков с GIF","Поддержка заголовков на японском и английском языках","Интеграция с manifest.json и manifest.template.json","Добавление индивидуальных шагов через CLI","Поддержка веб-доступных ресурсов"],"ar":["إنشاء دروس مخصصة مع ملفات GIF","دعم أسماء باللغة اليابانية والإنجليزية","التكامل مع manifest.json وmanifest.template.json","إضافة خطوات مخصصة عبر واجهة سطر الأوامر","دعم موارد وصول الويب"]},"keywords":{"en":["how to use add-tutorial","add-tutorial setup guide","add-tutorial alternative","add-tutorial vs tutorial maker","add-tutorial install","what is add-tutorial","add-tutorial tutorial creation","add-tutorial AI agent skill","add-tutorial GIF support"],"zh":["AI工具","添加教程","GIF文件","多语言标题","命令行界面","对话式界面","教程添加","AI开发","命令行工具"],"ja":["AIエージェント","チュートリアル追加","GIFファイル","多言語タイトル","コマンドラインインターフェース","対話式インターフェース","チュートリアル追加","AI開発","コマンドラインツール"],"ko":["AI 툴","튜토리얼 추가","GIF 파일","다국어 제목","명령줄 인터페이스","대화식 인터페이스","튜토리얼 추가","AI 개발","명령줄 도구"],"es":["add-tutorial","agentes de inteligencia artificial","desarrollo de tutoriales","GIF y títulos en japonés e inglés","comandos de interfaz de línea de comandos","JSON y manifest","recursos web accesibles"],"fr":["add-tutorial","agents d''intelligence artificielle","développement de didacticiels","GIF et titres en japonais et en anglais","commandes d''interface de ligne de commande","JSON et manifeste","ressources web accessibles"],"de":["add-tutorial","künstliche Intelligenz-Entwickler","Tutorien-Entwicklung","GIF und Titel in Japanisch und Englisch","Befehle der Kommandozeilen-Schnittstelle","JSON und Manifest","webzugängliche Ressourcen"],"pt":["add-tutorial","Ferramentas de IA","tutoriais personalizados","GIFs","títulos em japonês e inglês","manifest.json","CLI","recursos acessíveis na web"],"ru":["add-tutorial","ИИ Агенты","индивидуальные уроки","GIF","заголовки на японском и английском языках","manifest.json","CLI","веб-доступные ресурсы"],"ar":["إضافة add-tutorial","أدوات الذكاء الاصطناعي","دروس مخصصة","ملفات GIF","أسماء باللغة اليابانية والإنجليزية","manifest.json","واجهة سطر الأوامر","موارد وصول الويب"]}},"owner":"C20-40A","repo":"mr-wplace","repoPath":"C20-40A/mr-wplace","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.348Z","topics":[],"category":"community","skillMd":{"name":"add-tutorial","description":"チュートリアルGIFを追加し、Tutorial機能に新しいチュートリアル項目を登録するSKILL","bodyPreview":"## 使用方法\n\n```\n/add-tutorial <gif-filename> <title-ja> <title-en>\n```\n\n### パラメータ\n\n- `gif-filename`: GIFファイル名（例: `how_to_draw_text.gif`）\n- `title-ja`: 日本語タイトル（例: \"テキストをマップ上に表示する方法\"）\n- `title-en`: 英語タイトル（例: \"How to Display Text on Map\"）\n\n### ステップの追加\n\nコマンド実行後、対話形式でステップを追加します：\n\n1. ステップ数を入力（2-5推奨）\n2. 各ステップの日本語と英語のテキストを入力\n\n## 実装手順\n\n### 1. Manifestファイルへの追加\n\n`manifest.json` と `manifest.template.json` の `web_accessible_resources` に GIF ファイルを追加：\n\n```json\n{\n  \"web_accessible_resources\": [\n    {\n      \"resour","body":"## 使用方法\n\n```\n/add-tutorial <gif-filename> <title-ja> <title-en>\n```\n\n### パラメータ\n\n- `gif-filename`: GIFファイル名（例: `how_to_draw_text.gif`）\n- `title-ja`: 日本語タイトル（例: \"テキストをマップ上に表示する方法\"）\n- `title-en`: 英語タイトル（例: \"How to Display Text on Map\"）\n\n### ステップの追加\n\nコマンド実行後、対話形式でステップを追加します：\n\n1. ステップ数を入力（2-5推奨）\n2. 各ステップの日本語と英語のテキストを入力\n\n## 実装手順\n\n### 1. Manifestファイルへの追加\n\n`manifest.json` と `manifest.template.json` の `web_accessible_resources` に GIF ファイルを追加：\n\n```json\n{\n  \"web_accessible_resources\": [\n    {\n      \"resources\": [\n        \"assets/images/tutorial/how_to_draw.gif\",\n        \"assets/images/tutorial/<new-gif-filename>\" // 追加\n      ]\n    }\n  ]\n}\n```\n\n### 2. Tutorial クラスへの項目追加\n\n`src/features/tutorial/index.ts` の `tutorials` 配列に新しい項目を追加：\n\n```typescript\n{\n  id: \"tutorial_id\",\n  titleKey: \"tutorial_<id>_title\",\n  gifUrl: runtime.getURL(\"assets/images/tutorial/<gif-filename>\"),\n  steps: [\n    \"tutorial_<id>_step1\",\n    \"tutorial_<id>_step2\",\n    \"tutorial_<id>_step3\",\n  ],\n}\n```\n\n### 3. 国際化キーの追加\n\n#### 英語 (`src/i18n/locales/en.ts`)\n\n```typescript\ntutorial_<id>_title: \"English Title\",\ntutorial_<id>_step1: \"Step 1 description\",\ntutorial_<id>_step2: \"Step 2 description\",\ntutorial_<id>_step3: \"Step 3 description\",\n```\n\n#### 日本語 (`src/i18n/locales/ja.ts`)\n\n```typescript\ntutorial_<id>_title: \"日本語タイトル\",\ntutorial_<id>_step1: \"ステップ1の説明\",\ntutorial_<id>_step2: \"ステップ2の説明\",\ntutorial_<id>_step3: \"ステップ3の説明\",\n```\n\n## 命名規則\n\n### Tutorial ID\n\n- フォーマット: `how_to_<action>` または `how_to_<action>_<target>`\n- 例:\n  - `how_to_draw` - 画像描画\n  - `how_to_archive` - アーカイブ保存\n  - `how_to_draw_archive` - アーカイブ描画\n  - `how_to_draw_text` - テキスト描画\n\n### i18n キー\n\n- タイトル: `tutorial_<id>_title`\n- ステップ: `tutorial_<id>_step1`, `tutorial_<id>_step2`, ...\n\n## 既存のチュートリアル例\n\n### 1. 画像描画 (how_to_draw)\n\n```typescript\n{\n  id: \"how_to_draw\",\n  titleKey: \"tutorial_how_to_draw_title\",\n  gifUrl: runtime.getURL(\"assets/images/tutorial/how_to_draw.gif\"),\n  steps: [\n    \"tutorial_how_to_draw_step1\",  // ギャラリーに画像を保存する\n    \"tutorial_how_to_draw_step2\",  // マップをクリックして、「画像」ボタンを選択\n    \"tutorial_how_to_draw_step3\",  // 配置したい画像をクリック\n  ],\n}\n```\n\n### 2. アーカイブ保存 (how_to_archive)\n\n```typescript\n{\n  id: \"how_to_archive\",\n  titleKey: \"tutorial_how_to_archive_title\",\n  gifUrl: runtime.getURL(\"assets/images/tutorial/how_to_archive.gif\"),\n  steps: [\n    \"tutorial_how_to_archive_step1\",  // マップをクリックして「アーカイブ」を選択\n    \"tutorial_how_to_archive_step2\",  // 「Save Current Tile」ボタンをクリック\n  ],\n}\n```\n\n### 3. テキスト描画 (how_to_draw_text)\n\n```typescript\n{\n  id: \"how_to_draw_text\",\n  titleKey: \"tutorial_how_to_draw_text_title\",\n  gifUrl: runtime.getURL(\"assets/images/tutorial/how_to_draw_text.gif\"),\n  steps: [\n    \"tutorial_how_to_draw_text_step1\",  // マップをクリックして「テキスト」を選択\n    \"tutorial_how_to_draw_text_step2\",  // テキストを入力し、フォントを選んで「Draw」ボタンをクリック\n    \"tutorial_how_to_draw_text_step3\",  // オプション：矢印ボタンで位置を調節\n  ],\n}\n```\n\n## チェックリスト\n\n実装時に確認すべき項目：\n\n- [ ] GIFファイルが `public/assets/images/tutorial/` に配置されている\n- [ ] `manifest.json` に GIF が追加されている\n- [ ] `manifest.template.json` に GIF が追加されている\n- [ ] `src/features/tutorial/index.ts` に項目が追加されている\n- [ ] `src/i18n/locales/en.ts` に英語キーが追加されている\n- [ ] `src/i18n/locales/ja.ts` に日本語キーが追加されている\n- [ ] ステップ数が2-5個の範囲である\n- [ ] ID が他のチュートリアルと重複していない\n\n## ファイル構造\n\n```\nwplace-studio/\n├── public/\n│   └── assets/\n│       └── images/\n│           └── tutorial/\n│               ├── how_to_draw.gif\n│               ├── how_to_archive.gif\n│               ├── how_to_draw_archive.gif\n│               ├── how_to_draw_text.gif\n│               └── <new-tutorial>.gif\n├── manifest.json\n├── manifest.template.json\n└── src/\n    ├── features/\n    │   └── tutorial/\n    │       └── index.ts\n    └── i18n/\n        └── locales/\n            ├── en.ts\n            └── ja.ts\n```\n\n## 注意事項\n\n1. **GIFファイルのサイズ**: できるだけ軽量に（推奨: 1MB以下）\n2. **ステップ数**: 多すぎると読みにくいため、2-5個を推奨\n3. **命名規則**: 一貫性のため `how_to_*` パターンを使用\n4. **i18nキーの順序**: 既存のチュートリアルキーの後に追加\n5. **空状態メッセージ**: 必要に応じて `empty_*_message` キーも追加\n\n## コミットメッセージ例\n\n```\nfeat(tutorial): add <action> tutorial\n\n- Add <gif-filename> to web accessible resources\n- Add <action> tutorial to Tutorial class\n- Add i18n keys for <action> tutorial (en/ja)\n```\n\n## トラブルシューティング\n\n### GIFが表示されない\n\n1. ブラウザの開発者ツールでネットワークタブを確認\n2. GIF ファイルが正しいパスに配置されているか確認\n3. manifest.json を更新後、拡張機能を再読み込み\n\n### チュートリアルが一覧に表示されない\n\n1. `src/features/tutorial/index.ts` の構文エラーを確認\n2. i18n キーが正しく登録されているか確認\n3. ブラウザコンソールでエラーがないか確認\n"},"lastSynced":"2026-03-08T02:03:41.845Z","agentAnalysis":{"suitability":{"en":"Perfect for Educational Agents needing interactive tutorial creation capabilities with GIF support.","zh":"非常适合需要交互式教程创建功能并支持GIF的教育代理。","ja":"教育エージェントがインタラクティブなチュートリアル作成機能を必要とする場合に最適で、GIFをサポートします。","ko":"GIF를 지원하는 교육 에이전트가 인터랙티브 튜토리얼 생성 기능을 필요로 할 때 완벽합니다.","es":"Perfecto para Agentes Educativos que necesitan capacidades de creación de tutoriales interactivos con soporte de GIF.","fr":"Parfait pour les agents éducatifs qui ont besoin de capacités de création de tutoriels interactifs avec prise en charge de GIF.","de":"Perfekt für Bildungsagenten, die interaktive Tutorial-Erstellungsfähigkeiten mit GIF-Unterstützung benötigen.","pt":"Perfeito para Agentes Educacionais que precisam de capacidades de criação de tutoriais interativos com suporte a GIF.","ru":"Идеально для образовательных агентов, которым необходимы функции создания интерактивных уроков с поддержкой GIF.","ar":"مثالي للوكلاء التعليميين الذين يحتاجون إلى إمكانيات إنشاء دروس تعليمية تفاعلية مع دعم GIF."},"recommendation":{"en":"Empowers agents to generate step-by-step tutorials using GIF files, Japanese and English titles, and interactive text inputs, leveraging web-accessible resources like manifest.json files.","zh":"赋予代理生成使用GIF文件、日语和英语标题以及交互式文本输入的分步教程的能力，利用web可访问的资源，如manifest.json文件。","ja":"GIFファイル、英語および日本語のタイトル、インタラクティブなテキスト入力を使用してステップバイステップのチュートリアルを生成するエージェントの能力を提供し、manifest.jsonファイルのようなWebでアクセス可能なリソースを利用します。","ko":"GIF 파일, 영어 및 일본어 제목, 인터랙티브 텍스트 입력을 사용하여 단계별 튜토리얼을 생성하는 에이전트의 능력을 제공하며, manifest.json 파일과 같은 웹에서 접근 가능한 리소스를 활용합니다.","es":"Habilita a los agentes a generar tutoriales paso a paso utilizando archivos GIF, títulos en japonés e inglés y entradas de texto interactivas, aprovechando recursos accesibles desde la web como archivos manifest.json.","fr":"Permet aux agents de générer des tutoriels étape par étape en utilisant des fichiers GIF, des titres en japonais et en anglais et des entrées de texte interactives, en exploitant des ressources accessibles sur le web comme des fichiers manifest.json.","de":"Ermächtigt Agenten, schrittweise Tutorien zu erstellen, die GIF-Dateien, japanische und englische Titel sowie interaktive Texteingaben verwenden, unter Ausnutzung webzugänglicher Ressourcen wie manifest.json-Dateien.","pt":"Permite que os agentes criem tutoriais passo a passo usando arquivos GIF, títulos em japonês e inglês e entradas de texto interativas, aproveitando recursos acessíveis na web como arquivos manifest.json.","ru":"Позволяет агентам создавать пошаговые уроки, используя файлы GIF, японские и английские названия, а также интерактивные текстовые поля, используя веб-доступные ресурсы, такие как файлы manifest.json.","ar":"يسمح للوكلاء بإنشاء دروس تعليمية خطوة بخطوة باستخدام ملفات GIF وأسماء باليابانية والإنجليزية ومدخلات نصية تفاعلية، واستغلال الموارد المتاحة على الويب مثل ملفات manifest.json."},"useCases":{"en":["Creating interactive software tutorials","Generating language lessons with GIF examples","Developing step-by-step guides for complex tasks"],"zh":["创建交互式软件教程","生成带有GIF示例的语言课程","开发复杂任务的分步指南"],"ja":["インタラクティブなソフトウェアチュートリアルの作成","GIFの例を使用した言語レッスンの生成","複雑なタスクのステップバイステップガイドの開発"],"ko":["인터랙티브 소프트웨어 튜토리얼 생성","GIF 예시를 사용한 언어 수업 생성","복잡한 작업을 위한 단계별 가이드 개발"],"es":["Creación de tutoriales de software interactivos","Generación de lecciones de idiomas con ejemplos de GIF","Desarrollo de guías paso a paso para tareas complejas"],"fr":["Création de tutoriels de logiciels interactifs","Génération de leçons de langues avec des exemples de GIF","Développement de guides étape par étape pour des tâches complexes"],"de":["Erstellung interaktiver Software-Tutorien","Generierung von Sprachunterricht mit GIF-Beispielen","Entwicklung von Schritt-für-Schritt-Anleitungen für komplexe Aufgaben"],"pt":["Criação de tutoriais de software interativos","Geração de lições de linguagem com exemplos GIF","Desenvolvimento de guias passo a passo para tarefas complexas"],"ru":["Создание интерактивных программных уроков","Генерация языковых уроков с примерами GIF","Разработка пошаговых руководств для сложных задач"],"ar":["إنشاء دروس برمجية تفاعلية","توليد دروس لغة مع أمثلة GIF","تنمية دلائل خطوة بخطوة لمهام معقدة"]},"limitations":{"en":["Requires GIF file availability","Limited to 2-5 steps per tutorial","Needs web_accessible_resources configuration in manifest files"],"zh":["需要GIF文件可用","每个教程限制为2-5步","需要在manifest文件中配置web_accessible_resources"],"ja":["GIFファイルの可用性が必要","各チュートリアルは2〜5ステップに制限される","manifestファイルでweb_accessible_resourcesを構成する必要がある"],"ko":["GIF 파일이 필요","각 튜토리얼은 2-5단계로 제한됨","manifest 파일에서 웹 접근 가능한 리소스를 구성해야 함"],"es":["Requiere disponibilidad de archivos GIF","Limitado a 2-5 pasos por tutorial","Necesita configuración de web_accessible_resources en archivos de manifiesto"],"fr":["Nécessite la disponibilité de fichiers GIF","Limité à 2-5 étapes par tutoriel","Nécessite une configuration de web_accessible_resources dans les fichiers de manifeste"],"de":["Benötigt Verfügbarkeit von GIF-Dateien","Begrenzt auf 2-5 Schritte pro Tutorial","Benötigt Konfiguration von web_accessible_resources in Manifestdateien"],"pt":["Requer disponibilidade de arquivos GIF","Limitado a 2-5 etapas por tutorial","Necessita de configuração de recursos acessíveis na web em arquivos de manifesto"],"ru":["Требует доступности файлов GIF","Ограничен 2-5 шагами на урок","Требует настройки веб-доступных ресурсов в файлах манифеста"],"ar":["يتطلب توافر ملفات GIF","محدود بـ 2-5 خطوات لكل درس","يحتاج إلى تكوين موارد يمكن الوصول إليها على الويب في ملفات المظهر"]},"version":4},"contentHash":"63c8245215711ba1fd99f80e5b1bf2115b70607745f6698c352661061f500024","qualityScore":33}');
