INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('C20-40A/mr-wplace/add-tutorial', 'add-tutorial', 'C20-40A', 'mr-wplace', 'community', 'add-tutorial C20-40A mr-wplace community The add-tutorial skill allows developers to create interactive tutorials by adding GIF files, Japanese and English titles, and step-by-step instructions. It benefits AI agent developers and users alike. add-tutorial技能允许开发者通过命令行界面添加教程，支持GIF文件和多语言标题 add-tutorialスキルは、開発者がコマンドラインインターフェースからチュートリアルを追加できるようにします。GIFファイルと多言語タイトルをサポート add-tutorial 기능은 개발자가 명령줄 인터페이스를 통해 튜토리얼을 추가할 수 있게 해줍니다. GIF 파일 및 다국어 제목 지원 Add-tutorial es una habilidad que permite a los desarrolladores agregar tutoriales con GIF y títulos en japonés e inglés, utilizando comandos como /add-tutorial Add-tutorial est une compétence qui permet aux développeurs d''ajouter des didacticiels avec des GIF et des titres en japonais et en anglais, en utilisant des commandes comme /add-tutorial Add-tutorial ist eine Fähigkeit, die es Entwicklern ermöglicht, Tutorien mit GIF und Titeln in Japanisch und Englisch hinzuzufügen, indem sie Befehle wie /add-tutorial verwenden O add-tutorial é uma habilidade que permite criar tutoriais personalizados com GIFs e títulos em japonês e inglês para Ferramentas de IA add-tutorial - это навык, который позволяет создавать индивидуальные уроки с GIF и заголовками на японском и английском языках для ИИ Агентов إضافة add-tutorial هي مهارة تسمح بإنشاء دروس مخصصة مع ملفات GIF وأسماء باللغة اليابانية والإنجليزية لأدوات الذكاء الاصطناعي how to use add-tutorial add-tutorial setup guide add-tutorial alternative add-tutorial vs tutorial maker add-tutorial install what is add-tutorial add-tutorial tutorial creation add-tutorial AI agent skill add-tutorial GIF support AI工具 添加教程 GIF文件 多语言标题 命令行界面 对话式界面 教程添加 AI开发 命令行工具 Supports GIF file addition via `/add-tutorial` command Allows for Japanese and English title input Enables step-by-step addition through interactive prompts Requires `manifest.json` and `manifest.template.json` updates for web-accessible resources Supports 2-5 step inputs for customizable tutorial lengths add-tutorial is a skill that enables the creation of interactive tutorials with GIF files, multi-language support, and step-by-step guidance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dennislee928/Smart_Zone/oauth-integrations', 'community', 'dennislee928', 'Smart_Zone', 'dennislee928/Smart_Zone', 'oauth-integrations', 0, 0, 33, '2026-03-08T01:57:15.351Z', '2026-03-08T02:03:49.371Z', '75affa91dcec597c0b04ac93e5d3f91aa4ff91a3e266deacc2d61f8e537021fa', '{"id":"dennislee928/Smart_Zone/oauth-integrations","name":"oauth-integrations","description":{"en":"The oauth-integrations skill enables developers to implement GitHub and Microsoft OAuth in edge environments, such as Cloudflare Workers. It provides required headers and authentication protocols for secure integration.","zh":"本文介绍如何在Cloudflare Workers和其他边缘运行时中实现GitHub和Microsoft OAuth集成，包括所需的头部和配置","ja":"この記事では、Cloudflare Workersおよびその他のエッジランタイムでGitHubとMicrosoft OAuthを実装する方法を紹介します","ko":"이 문서에서는 Cloudflare Workers 및 기타 에지 런타임에서 GitHub 및 Microsoft OAuth를 구현하는 방법을 설명합니다","es":"Implementa GitHub y Microsoft OAuth en Cloudflare Workers y otros entornos de edge con nuestras integraciones de OAuth","fr":"Mettez en œuvre GitHub et Microsoft OAuth dans Cloudflare Workers et d''autres environnements de edge avec nos intégrations OAuth","de":"Implementieren Sie GitHub und Microsoft OAuth in Cloudflare Workers und anderen Edge-Umgebungen mit unseren OAuth-Integrationen","pt":"O skill oauth-integrations permite a implementação de autenticação OAuth em ambientes de borda, incluindo GitHub e Microsoft OAuth em Cloudflare Workers.","ru":"Навык oauth-integrations позволяет реализовать аутентификацию OAuth в краевых средах, включая GitHub и Microsoft OAuth в Cloudflare Workers.","ar":"تمكن مهارة oauth-integrations من تنفيذ المصادقة OAuth في بيئات الحافة، بما في ذلك GitHub و Microsoft OAuth في Cloudflare Workers."},"seo":{"title":{"en":"oauth-integrations: Setup Guide for Edge Environments | A...","zh":"OAuth集成设置指南 - GitHub和Microsoft OAuth集成","ja":"OAuth統合セットア