INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dennislee928/Smart_Zone/oauth-integrations', 'oauth-integrations', 'dennislee928', 'Smart_Zone', 'community', 'oauth-integrations dennislee928 Smart_Zone community The oauth-integrations skill enables developers to implement GitHub and Microsoft OAuth in edge environments, such as Cloudflare Workers. It provides required headers and authentication protocols for secure integration. 本文介绍如何在Cloudflare Workers和其他边缘运行时中实现GitHub和Microsoft OAuth集成，包括所需的头部和配置 この記事では、Cloudflare Workersおよびその他のエッジランタイムでGitHubとMicrosoft OAuthを実装する方法を紹介します 이 문서에서는 Cloudflare Workers 및 기타 에지 런타임에서 GitHub 및 Microsoft OAuth를 구현하는 방법을 설명합니다 Implementa GitHub y Microsoft OAuth en Cloudflare Workers y otros entornos de edge con nuestras integraciones de OAuth Mettez en œuvre GitHub et Microsoft OAuth dans Cloudflare Workers et d''autres environnements de edge avec nos intégrations OAuth Implementieren Sie GitHub und Microsoft OAuth in Cloudflare Workers und anderen Edge-Umgebungen mit unseren OAuth-Integrationen O skill oauth-integrations permite a implementação de autenticação OAuth em ambientes de borda, incluindo GitHub e Microsoft OAuth em Cloudflare Workers. Навык oauth-integrations позволяет реализовать аутентификацию OAuth в краевых средах, включая GitHub и Microsoft OAuth в Cloudflare Workers. تمكن مهارة oauth-integrations من تنفيذ المصادقة OAuth في بيئات الحافة، بما في ذلك GitHub و Microsoft OAuth في Cloudflare Workers. how to use oauth-integrations oauth-integrations setup guide oauth-integrations alternative oauth-integrations vs Okta implementing GitHub OAuth in Cloudflare Workers Microsoft OAuth in edge environments oauth-integrations install oauth-integrations for AI agents edge environment authentication protocols OAuth集成 GitHub OAuth Microsoft OAuth Cloudflare Workers OAuth认证 fetch API User-Agent Accept Implements GitHub OAuth with required `User-Agent` header Supports Microsoft OAuth in Cloudflare Workers Uses `application/vnd.github+json` Accept header for GitHub API requests Enables authentication in edge environments using OAuth protocols Provides `fetch` API implementation for OAuth requests Requires specific headers for GitHub API requests, such as `User-Agent` and `Accept` oauth-integrations is a skill that implements OAuth authentication protocols for edge environments, supporting GitHub and Microsoft OAuth in Cloudflare Workers and other edge runtimes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SYUNTA99/NS-ENGINE/plan-doc-checker', 'community', 'SYUNTA99', 'NS-ENGINE', 'SYUNTA99/NS-ENGINE', 'plan-doc-checker', 0, 0, 33, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:55.531Z', '218d19be3e69fa5708abf1d714c201a22b17e7e8a59ddf54b038490269b04836', '{"id":"SYUNTA99/NS-ENGINE/plan-doc-checker","name":"plan-doc-checker","description":{"en":"The plan-doc-checker skill checks plan and document integrity, identifying discrepancies, completeness, and contradictions. It benefits developers and project managers by ensuring consistency in their project plans.","zh":"Plan-Doc Checker 是一个工具，用于检查计划和文档的一致性，包括齟齬、完全性和矛盾。它可以帮助开发者确保计划和文档的准确性和完整性","ja":"Plan-Doc Checker は、計画とドキュメントの整合性を検証するツールです。齟齬、完全性、矛盾をチェックし、開発者が計画とドキュメントの正確性と完全性を確保するのに役立ちます","ko":"Plan-Doc Checker는 계획과 문서의 일관성을 확인하는 도구로,齟齬, 완전성, 모순 등을 확인하여 개발자가 계획과 문서의 정확성과 완전성을 확보하는 데 도움이 됩니다","es":"Plan-doc-checker es una herramienta que verifica la integridad de los documentos y planes, detectando discrepancias y contradicciones","fr":"Plan-doc-checker est un outil qui vérifie l''intégrité des documents et plans, en détectant les disparités et contradictions","de":"Plan-doc-checker ist ein Tool, das die Integrität von Dokumenten und Plänen überprüft, indem es Diskrepanzen und Widersprüche erkennt","pt":"O Plan-Doc Checker é uma ferramenta que verifica a consistência entre planos e documentos de referência em projetos de desenvolvimento de games com DirectX11","ru":"Plan-Doc Checker - это инструмент, который проверяет согласованность между планами и документами в проектах разработки игр на базе DirectX11","ar":"Plan-Doc Checker هو أداة لفحص التوافق بين الخطط والوثائق المرجعية في مشاريع تطوير الألعاب باستخدام DirectX11"},"seo":{"title":{"en":"plan-doc-checker: Document Integrity Checker for AI Agent...","zh":"Plan-Doc Checker 设置指南：确保计划和文档的一致性","ja":"Plan-Doc Checker セットアップガイド：計画とドキュメントの整合性を検証","ko":"Plan-Doc Checker 설정 가이드: 계획과 문서의 일관성을 확인","es":"Guía de configuración de plan-doc-checker para análisis d...","fr":"Guide d''installation de plan-doc-checker pour l''analyse d...","de":"Einrichtungsleitfaden für plan-doc-checker zur Dokumenten...","pt":"Guia de Configuração do Plan-Doc Checker: Verificador de ...","ru":"Настройка Plan-Doc Checker: Проверка Документов ИИ Агенты","ar":"دليل إعداد Plan-Doc Checker: أداة فحص الوثائق الإلكترونية"},"description":{"en":"Verify plan and document consistency with plan-doc-checker. Learn how to use this AI agent skill to identify discrepancies and contradictions in your project...","zh":"使用 Plan-Doc Checker 确保您的计划和文档的一致性，减少错误和矛盾。了解如何设置和使用此工具","ja":"Plan-Doc Checker を使用して、計画とドキュメントの整合性を検証し、エラーと矛盾を減らします。設定方法と使い方を学びましょう","ko":"Plan-Doc Checker를 사용하여 계획과 문서의 일관성을 확인하고 오류 및 모순을 줄여보세요. 설정 방법과 사용법을 알아보세요","es":"Aprende a configurar plan-doc-checker para verificar la integridad de tus documentos y planes, y mejora la eficiencia de tus proyectos","fr":"Découvrez comment installer plan-doc-checker pour vérifier l''intégrité de vos documents et plans, et améliorer l''efficacité de vos projets","de":"Erfahren Sie, wie Sie plan-doc-checker einrichten, um die Integrität Ihrer Dokumente und Pläne zu überprüfen und die Effizienz Ihrer Projekte zu verbessern","pt":"Aprenda a configurar o Plan-Doc Checker para verificar a consistência entre planos e documentos de referência em projetos de desenvolvimento de games com Dir...","ru":"Узнайте, как настроить Plan-Doc Checker для проверки согласованности между планами и документами в проектах разработки игр на базе DirectX11 с помощью ИИ Аге...","ar":"اكتشف كيفية إعداد Plan-Doc Checker لفحص التوافق بين الخطط والوثائق المرجعية في مشاريع تطوير الألعاب باستخدام DirectX11"},"definition":{"en":"plan-doc-checker is a document integrity checking tool that verifies the consistency of plans and documents, analyzing for discrepancies, completeness, and contradictions.","zh":"Plan-Doc Checker 是一个用于检查计划和文档的一致性和完整性的工具","ja":"Plan-Doc Checker は、計画とドキュメントの整合性と完全性を検証するツールです","ko":"Plan-Doc Checker는 계획과 문서의 일관성과 완전성을 확인하는 도구입니다","es":"Plan-doc-checker es una herramienta de análisis de documentos que verifica la coherencia entre planes y documentos","fr":"Plan-doc-checker est un outil d''analyse de documents qui vérifie la cohérence entre les plans et les documents","de":"Plan-doc-checker ist ein Dokumentenanalyse-Tool, das die Kohärenz zwischen Plänen und Dokumenten überprüft","pt":"O Plan-Doc Checker é um verificador de documentos que analisa a consistência entre planos e documentos de referência","ru":"Plan-Doc Checker - это проверка документов, который анализирует согласованность между планами и документами","ar":"Plan-Doc Checker هو أداة فحص وثائق تحليل التوافق بين الخطط والوثائق المرجعية"},"features":{"en":["Checks for discrepancies between plan files and reference documents","Analyzes completeness of document requirements and specifications","Detects contradictions within plans using .claude/plans/current/task_plan.md files","Supports user-specified plan files and reference documents","Extracts mandatory requirements from reference documents using keywords like MUST and required"],"zh":["检查计划和文档的一致性","检测齟齬、完全性和矛盾","支持多种文档格式","提供详细的分析报告","帮助开发者确保计划和文档的准确性和完整性"],"ja":["計画とドキュメントの整合性を検証","齟齬、完全性、矛盾をチェック","複数のドキュメント形式をサポート","詳細な分析レポートを提供","開発者が計画とドキュメントの正確性と完全性を確保するのに役立ちます"],"ko":["계획과 문서의 일관성을 확인","齟齬, 완전성, 모순 등을 확인","여러 가지 문서 형식을 지원","상세한 분석 보고서를 제공","개발자가 계획과 문서의 정확성과 완전성을 확보하는 데 도움이 됩니다"],"es":["Análisis de discrepancias entre documentos y planes","Verificación de la completitud de los requisitos y especificaciones","Detección de contradicciones internas en los planes","Compatibilidad con archivos Markdown","Soporte para la especificación de documentos de referencia personalizados"],"fr":["Analyse des disparités entre les documents et les plans","Vérification de l''exhaustivité des exigences et spécifications","Détection des contradictions internes dans les plans","Compatibilité avec les fichiers Markdown","Prise en charge de la spécification de documents de référence personnalisés"],"de":["Analyse von Diskrepanzen zwischen Dokumenten und Plänen","Überprüfung der Vollständigkeit der Anforderungen und Spezifikationen","Erkennung von Widersprüchen innerhalb der Pläne","Kompatibilität mit Markdown-Dateien","Unterstützung für die Spezifikation von benutzerdefinierten Referenzdokumenten"],"pt":["Verificação de discrepâncias entre planos e documentos","Análise de completude dos requisitos e especificações","Detecção de contradições internas nos planos","Suporte a DirectX11 para desenvolvimento de games","Integração com documentos de referência como design e especificações"],"ru":["Проверка несоответствий между планами и документами","Анализ полноты требований и спецификаций","Обнаружение внутренних противоречий в планах","Поддержка DirectX11 для разработки игр","Интеграция с документами-справочниками, такими как дизайн и спецификации"],"ar":["فحص التناقضات بين الخطط والوثائق","تحليل اكتمال المتطلبات والمواصفات","اكتشاف التناقضات الداخلية في الخطط","دعم DirectX11 لتطوير الألعاب","التكامل مع الوثائق المرجعية مثل التصميم والمواصفات"]},"keywords":{"en":["how to use plan-doc-checker","plan-doc-checker alternative","plan-doc-checker setup guide","document integrity checking tools","plan consistency analysis","discrepancy detection in project plans","plan-doc-checker vs competing tools","install plan-doc-checker","plan-doc-checker for AI agents"],"zh":["Plan-Doc Checker","AIエージェント","文档一致性","计划准确性","开发工具","代码检查","文档检查","AI工具"],"ja":["Plan-Doc Checker","AIエージェント","ドキュメントの一致性","計画の正確性","開発ツール","コードチェック","ドキュメントチェック","AIツール"],"ko":["Plan-Doc Checker","AI 에이전트","문서 일관성","계획 정확성","개발 도구","코드 검사","문서 검사","AI 도구"],"es":["herramientas de análisis de documentos","plan-doc-checker","análisis de planes","verificación de documentos","detección de contradicciones","AI Agentes","desarrollo de software","eficiencia de proyectos"],"fr":["outils d''analyse de documents","plan-doc-checker","analyse de plans","vérification de documents","détection de contradictions","Agents IA","développement de logiciels","efficacité de projets"],"de":["Dokumentenanalyse-Tools","plan-doc-checker","Plananalyse","Dokumentenüberprüfung","Widerspruchserkennung","KI-Agents","Software-Entwicklung","Projekteffizienz"],"pt":["Plan-Doc Checker","Verificador de documentos","Desenvolvimento de games","DirectX11","Análise de consistência","Ferramentas de desenvolvimento","AI Agents","Tecnologias de desenvolvimento"],"ru":["Plan-Doc Checker","Проверка документов","Разработка игр","DirectX11","Анализ согласованности","Инструменты разработки","ИИ Агенты","Технологии разработки"],"ar":["Plan-Doc Checker","أداة فحص الوثائق","تطوير الألعاب","DirectX11","تحليل التوافق","أدوات التطوير","الوكلاء الذكية","تكنولوجيا التطوير"]}},"owner":"SYUNTA99","repo":"NS-ENGINE","repoPath":"SYUNTA99/NS-ENGINE","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.353Z","topics":[],"category":"community","skillMd":{"name":"plan-doc-checker","description":"|","bodyPreview":"# Plan-Doc Checker\n\n計画と参照ドキュメントの整合性を検証し、スコアとカテゴリ別分析を出力する。\n\n## チェック対象\n\n1. **齟齬 (Discrepancy)**: ドキュメントの記述と計画の内容が矛盾していないか\n2. **完全性 (Completeness)**: ドキュメントの要件・仕様が計画で網羅されているか\n3. **矛盾 (Contradiction)**: 計画内部で自己矛盾がないか\n\n## 実行手順\n\n### 1. 入力の特定\n\n計画ファイルと参照ドキュメントを特定する:\n\n```\n計画ファイル:\n- .claude/plans/current/task_plan.md\n- ユーザーが指定した計画ファイル\n- 直前のPlan Modeで作成した計画\n\n参照ドキュメント:\n- 計画作成時に参照したドキュメント（設計書、仕様書、SDK docs等）\n- ユーザーが明示的に指定したドキュメント\n```\n\n### 2. ドキュメント分析\n\n参照ドキュメントから以下を抽出:\n\n- **必須要件**: MUST、必須、required等で示される要件\n- *","body":"# Plan-Doc Checker\n\n計画と参照ドキュメントの整合性を検証し、スコアとカテゴリ別分析を出力する。\n\n## チェック対象\n\n1. **齟齬 (Discrepancy)**: ドキュメントの記述と計画の内容が矛盾していないか\n2. **完全性 (Completeness)**: ドキュメントの要件・仕様が計画で網羅されているか\n3. **矛盾 (Contradiction)**: 計画内部で自己矛盾がないか\n\n## 実行手順\n\n### 1. 入力の特定\n\n計画ファイルと参照ドキュメントを特定する:\n\n```\n計画ファイル:\n- .claude/plans/current/task_plan.md\n- ユーザーが指定した計画ファイル\n- 直前のPlan Modeで作成した計画\n\n参照ドキュメント:\n- 計画作成時に参照したドキュメント（設計書、仕様書、SDK docs等）\n- ユーザーが明示的に指定したドキュメント\n```\n\n### 2. ドキュメント分析\n\n参照ドキュメントから以下を抽出:\n\n- **必須要件**: MUST、必須、required等で示される要件\n- **制約条件**: 技術的制約、禁止事項、注意事項\n- **API/インターフェース仕様**: 関数シグネチャ、型定義、戻り値\n- **依存関係**: 前提条件、実行順序の制約\n\n### 3. 計画との照合\n\n| チェック項目 | 検証内容 |\n|-------------|---------|\n| 齟齬 | API名、型、引数がドキュメントと一致するか |\n| 齟齬 | 処理フローがドキュメントの記述と整合するか |\n| 完全性 | 必須要件が全て計画に含まれているか |\n| 完全性 | エラーハンドリング要件が網羅されているか |\n| 矛盾 | 計画内のステップ間で前提条件が矛盾しないか |\n| 矛盾 | 同一機能の複数記述が一貫しているか |\n\n### 4. 出力フォーマット\n\n```markdown\n## 整合性チェック結果\n\n### スコア: XX/100\n\n| カテゴリ | スコア | 問題数 |\n|---------|-------|-------|\n| 齟齬    | XX/100 | N件   |\n| 完全性  | XX/100 | N件   |\n| 矛盾    | XX/100 | N件   |\n\n### 詳細分析\n\n#### 齟齬 (Discrepancy)\n- [CRITICAL/WARNING/INFO] 問題の説明\n  - ドキュメント: 該当箇所の引用\n  - 計画: 該当箇所の引用\n  - 推奨修正: 修正案\n\n#### 完全性 (Completeness)\n- [CRITICAL/WARNING/INFO] 欠落している要件\n  - ドキュメント: 要件の引用\n  - 推奨: 追加すべき計画ステップ\n\n#### 矛盾 (Contradiction)\n- [CRITICAL/WARNING/INFO] 矛盾の説明\n  - 計画ステップA: 該当箇所\n  - 計画ステップB: 矛盾する箇所\n  - 推奨解決: 解決案\n\n### 総評\nスコアに基づく総合評価と、実装に進む前に修正すべき優先事項。\n```\n\n## スコア計算\n\n```\n基礎点: 100点\n減点:\n- CRITICAL: -20点/件\n- WARNING: -5点/件\n- INFO: -1点/件\n\n最低点: 0点\n```\n\n## 重大度判定\n\n| 重大度 | 条件 |\n|-------|------|\n| CRITICAL | 実装が失敗する、または仕様違反になる問題 |\n| WARNING | 実装は可能だが品質・保守性に影響する問題 |\n| INFO | 改善推奨だが影響は軽微 |\n\n## 自動トリガー\n\nExitPlanMode前に以下を確認:\n1. 参照ドキュメントが存在するか\n2. 存在する場合、整合性チェックを実行\n3. スコア70未満の場合、警告を表示し修正を推奨\n"},"lastSynced":"2026-03-08T02:03:55.531Z","agentAnalysis":{"suitability":{"en":"Perfect for Project Management Agents needing advanced plan and document integrity checking capabilities.","zh":"非常适合需要高级计划和文档完整性检查功能的项目管理代理。","ja":"プロジェクト管理エージェントが高度な計画および文書の完全性の検証機能を必要とする場合に最適です。","ko":"고급 계획 및 문서 무결성 확인 기능이 필요한 프로젝트 관리 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Gestión de Proyectos que necesitan capacidades avanzadas de verificación de integridad de planes y documentos.","fr":"Parfait pour les Agents de Gestion de Projet nécessitant des capacités avancées de vérification de l''intégrité des plans et des documents.","de":"Perfekt für Projektmanagement-Agenten, die erweiterte Funktionen zur Überprüfung der Integrität von Plänen und Dokumenten benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Projetos que necessitam de capacidades avançadas de verificação de integridade de planos e documentos.","ru":"Идеально подходит для агентов управления проектами, которым необходимы продвинутые возможности проверки целостности планов и документов.","ar":"مثالي لعميل إدارة المشاريع الذين يحتاجون إلى возможности متقدمة لتحقق سلامة الخطة والوثائق."},"recommendation":{"en":"Empowers agents to verify plan and document consistency, identifying discrepancies, completeness, and contradictions using task plans and reference documents, and provides score and category-based analysis.","zh":"赋予代理人验证计划和文档的一致性、识别不一致、完整性和矛盾的能力，使用任务计划和参考文档，并提供基于评分和类别的分析。","ja":"エージェントがタスクプランと参考文書を使用して、計画および文書の一貫性を検証し、不一致、完全性、矛盾を特定し、スコアとカテゴリベースの分析を提供する力を与えます。","ko":"에이전트가 작업 계획과 참조 문서를 사용하여 계획 및 문서의 일관성을 검증하고, 불일치, 완전성, 모순을 식별하며, 점수 및 카테고리 기반 분석을 제공하는 능력을 부여합니다.","es":"Habilita a los agentes para verificar la coherencia del plan y del documento, identificando discrepancias, completitud y contradicciones utilizando planes de tareas y documentos de referencia, y proporciona un análisis basado en puntuación y categorías.","fr":"Permet aux agents de vérifier la cohérence du plan et du document, en identifiant les disparités, l''exhaustivité et les contradictions en utilisant les plans de tâches et les documents de référence, et fournit une analyse basée sur les scores et les catégories.","de":"Ermächtigt die Agenten, die Konsistenz von Plan und Dokument zu überprüfen, indem sie Unstimmigkeiten, Vollständigkeit und Widersprüche unter Verwendung von Aufgabenplänen und Referenzdokumenten identifizieren und eine Analyse auf der Grundlage von Punktzahlen und Kategorien bereitstellen.","pt":"Habilita os agentes a verificar a consistência do plano e do documento, identificando discrepâncias, completude e contradições usando planos de tarefas e documentos de referência, e fornece análise baseada em pontuação e categoria.","ru":"Наделяет агентов возможностью проверять согласованность планов и документов, выявлять несоответствия, полноту и противоречия с помощью планов задач и справочных документов, и предоставляет анализ на основе оценки и категории.","ar":"يمكن العميل من التحقق من توافق الخطة والوثيقة، وتحديد الاختلافات والكامل والمتناقضات باستخدام خطط المهام والوثائق المرجعية، ويقدم تحليلًا قائمًا على الدرجة والفئة."},"useCases":{"en":["Validating task plan consistency with reference documents","Identifying discrepancies in project plans","Ensuring completeness of document requirements and specifications"],"zh":["验证任务计划与参考文档的一致性","识别项目计划中的不一致","确保文档要求和规格的完整性"],"ja":["タスクプランと参考文書の一貫性を検証する","プロジェクトプラン内の不一致を特定する","文書の要件と仕様の完全性を確保する"],"ko":["작업 계획과 참조 문서의 일관성을 검증하는 것","프로젝트 계획 내의 불일치를 식별하는 것","문서 요구 사항과 명세의 완전성을 보장하는 것"],"es":["Validar la coherencia del plan de tareas con los documentos de referencia","Identificar discrepancias en los planes de proyecto","Garantizar la completitud de los requisitos y especificaciones de los documentos"],"fr":["Valider la cohérence du plan de tâches avec les documents de référence","Identifier les disparités dans les plans de projet","Assurer l''exhaustivité des exigences et spécifications des documents"],"de":["Überprüfen der Konsistenz des Aufgabenplans mit den Referenzdokumenten","Identifizieren von Unstimmigkeiten in den Projektplänen","Sicherstellen der Vollständigkeit der Anforderungen und Spezifikationen der Dokumente"],"pt":["Validar a consistência do plano de tarefas com documentos de referência","Identificar discrepâncias nos planos de projeto","Garantir a completude dos requisitos e especificações do documento"],"ru":["Проверка согласованности плана задач с справочными документами","Определение несоответствий в планах проекта","Обеспечение полноты требований и спецификаций документа"],"ar":["التحقق من توافق خطة المهام مع الوثائق المرجعية","تحديد الاختلافات في خطط المشروع","ضمان اكمال متطلبات وتفاصيل الوثيقة"]},"limitations":{"en":["Requires access to plan files and reference documents","Limited to task plans in .md format","Dependent on user-specified plan files and documents"],"zh":["需要访问计划文件和参考文档","仅限于.md格式的任务计划","依赖于用户指定的计划文件和文档"],"ja":["計画ファイルと参考文書へのアクセスが必要",".md形式のタスクプランのみに限られる","ユーザー指定の計画ファイルと文書に依存する"],"ko":["계획 파일과 참조 문서에 대한 액세스가 필요함",".md 형식의 작업 계획만 해당함","사용자 지정 계획 파일 및 문서에 의존함"],"es":["Requiere acceso a archivos de plan y documentos de referencia","Limitado a planes de tareas en formato .md","Dependiente de los archivos de plan y documentos especificados por el usuario"],"fr":["Nécessite l''accès aux fichiers de plan et aux documents de référence","Limité aux plans de tâches au format .md","Dépendant des fichiers de plan et des documents spécifiés par l''utilisateur"],"de":["Erfordert den Zugriff auf Plan- und Referenzdokumente","Begrenzt auf Aufgabenpläne im .md-Format","Abhängig von den vom Benutzer festgelegten Plan- und Dokumentdateien"],"pt":["Requer acesso a arquivos de plano e documentos de referência","Limitado a planos de tarefas no formato .md","Dependente de arquivos de plano e documentos especificados pelo usuário"],"ru":["Требует доступа к файлам планов и справочным документам","Ограничен планами задач в формате .md","Зависит от файлов планов и документов, указанных пользователем"],"ar":["يتطلب الوصول إلى ملفات الخطة والوثائق المرجعية","محدود بخطط المهام بتنسيق .md","يعتمد على ملفات الخطة والوثائق المحددة من قبل المستخدم"]},"version":4},"contentHash":"218d19be3e69fa5708abf1d714c201a22b17e7e8a59ddf54b038490269b04836","qualityScore":33}');
