INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SYUNTA99/NS-ENGINE/plan-doc-checker', 'plan-doc-checker', 'SYUNTA99', 'NS-ENGINE', 'community', 'plan-doc-checker SYUNTA99 NS-ENGINE community The plan-doc-checker skill checks plan and document integrity, identifying discrepancies, completeness, and contradictions. It benefits developers and project managers by ensuring consistency in their project plans. Plan-Doc Checker 是一个工具，用于检查计划和文档的一致性，包括齟齬、完全性和矛盾。它可以帮助开发者确保计划和文档的准确性和完整性 Plan-Doc Checker は、計画とドキュメントの整合性を検証するツールです。齟齬、完全性、矛盾をチェックし、開発者が計画とドキュメントの正確性と完全性を確保するのに役立ちます Plan-Doc Checker는 계획과 문서의 일관성을 확인하는 도구로,齟齬, 완전성, 모순 등을 확인하여 개발자가 계획과 문서의 정확성과 완전성을 확보하는 데 도움이 됩니다 Plan-doc-checker es una herramienta que verifica la integridad de los documentos y planes, detectando discrepancias y contradicciones Plan-doc-checker est un outil qui vérifie l''intégrité des documents et plans, en détectant les disparités et contradictions Plan-doc-checker ist ein Tool, das die Integrität von Dokumenten und Plänen überprüft, indem es Diskrepanzen und Widersprüche erkennt O Plan-Doc Checker é uma ferramenta que verifica a consistência entre planos e documentos de referência em projetos de desenvolvimento de games com DirectX11 Plan-Doc Checker - это инструмент, который проверяет согласованность между планами и документами в проектах разработки игр на базе DirectX11 Plan-Doc Checker هو أداة لفحص التوافق بين الخطط والوثائق المرجعية في مشاريع تطوير الألعاب باستخدام DirectX11 how to use plan-doc-checker plan-doc-checker alternative plan-doc-checker setup guide document integrity checking tools plan consistency analysis discrepancy detection in project plans plan-doc-checker vs competing tools install plan-doc-checker plan-doc-checker for AI agents Plan-Doc Checker AIエージェント 文档一致性 计划准确性 开发工具 代码检查 文档检查 AI工具 Checks for discrepancies between plan files and reference documents Analyzes completeness of document requirements and specifications Detects contradictions within plans using .claude/plans/current/task_plan.md files Supports user-specified plan files and reference documents Extracts mandatory requirements from reference documents using keywords like MUST and required plan-doc-checker is a document integrity checking tool that verifies the consistency of plans and documents, analyzing for discrepancies, completeness, and contradictions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('get-caio/harness/react-best-practices', 'community', 'get-caio', 'harness', 'get-caio/harness', 'react-best-practices', 0, 0, 33, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:57.323Z', '912fc8bea6f2167a77efbd4438b512decee15b2dd665fbc971956922b3bde330', '{"id":"get-caio/harness/react-best-practices","name":"react-best-practices","description":{"en":"The react-best-practices skill provides a performance optimization guide for React and Next.js applications, helping developers maximize performance gains when writing or reviewing code.","zh":"React 和 Next.js 应用的性能优化指南，包括代码审查和重构","ja":"React と Next.js アプリのパフォーマンス最適化ガイド","ko":"React와 Next.js 애플리케이션의 성능 최적화 가이드","es":"Mejore el rendimiento de sus aplicaciones React y Next.js con estas prácticas recomendadas","fr":"Améliorez les performances de vos applications React et Next.js avec ces meilleures pratiques","de":"Verbessern Sie die Leistung Ihrer React- und Next.js-Anwendungen mit diesen bewährten Methoden","pt":"Guia de otimização de desempenho para aplicações React e Next.js, com dicas para escrita de componentes e implementação de busca de dados","ru":"Руководство по оптимизации производительности для приложений React и Next.js, с советами по написанию компонентов и реализации поиска данных","ar":"دليل تحسين الأداء لتطبيقات ري액ت و نيكست.جس، مع نصائح لكتابة المكونات وتنفيذ بحث البيانات"},"seo":{"title":{"en":"React Best Practices: Performance Optimization Guide for ...","zh":"React 最佳实践设置指南","ja":"React ベストプラクティス設定ガイド","ko":"React 최적화 가이드","es":"Guía de Mejores Prácticas para React","fr":"Guide des Meilleures Pratiques pour React","de":"Leitfaden für Beste Praktiken bei React","pt":"Melhores Práticas React: Guia de Otimização de Desempenho","ru":"Лучшие практики React: Руководство по оптимизации произво...","ar":"أفضل الممارسات لري액ت: دليل تحسين الأداء للوكلاء