INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('get-caio/harness/react-best-practices', 'react-best-practices', 'get-caio', 'harness', 'community', 'react-best-practices get-caio harness community The react-best-practices skill provides a performance optimization guide for React and Next.js applications, helping developers maximize performance gains when writing or reviewing code. React 和 Next.js 应用的性能优化指南，包括代码审查和重构 React と Next.js アプリのパフォーマンス最適化ガイド React와 Next.js 애플리케이션의 성능 최적화 가이드 Mejore el rendimiento de sus aplicaciones React y Next.js con estas prácticas recomendadas Améliorez les performances de vos applications React et Next.js avec ces meilleures pratiques Verbessern Sie die Leistung Ihrer React- und Next.js-Anwendungen mit diesen bewährten Methoden Guia de otimização de desempenho para aplicações React e Next.js, com dicas para escrita de componentes e implementação de busca de dados Руководство по оптимизации производительности для приложений React и Next.js, с советами по написанию компонентов и реализации поиска данных دليل تحسين الأداء لتطبيقات ري액ت و نيكست.جس، مع نصائح لكتابة المكونات وتنفيذ بحث البيانات react best practices guide how to optimize react performance next.js performance optimization react-best-practices alternative react-best-practices setup guide react-best-practices vs webpack React 优化 Next.js 优化 React 性能优化 代码审查 重构 数据获取优化 Bundle 大小优化 加载时间优化 Provides a priority-ordered guide for performance optimization Covers data fetching for client and server-side implementations Supports code review and refactoring for existing React and Next.js code Offers guidance on optimizing bundle size and load times Applies to writing new React components and Next.js pages react-best-practices is a set of guidelines for optimizing React and Next.js application performance, covering data fetching, code review, and refactoring');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('saxjax/saxjaxTuner/build-iphone-apps', 'community', 'saxjax', 'saxjaxTuner', 'saxjax/saxjaxTuner', 'build-iphone-apps', 0, 0, 33, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:57.577Z', '3e63827c85b782a080acd451cfac9dcb621ea7e53e4ae55f53af146b661c09f0', '{"id":"saxjax/saxjaxTuner/build-iphone-apps","name":"build-iphone-apps","description":{"en":"The build-iphone-apps skill enables users to develop iPhone apps without writing code. It implements, verifies, and reports outcomes using xcodebuild and iOS Simulator.","zh":"使用 AI Agent 构建和测试 iPhone 应用，利用 xcodebuild 和 Xcode 测试实现高效开发","ja":"AIエージェントを使用して iPhone アプリを構築およびテストします。xcodebuild および Xcode テストを使用して開発を効率化します","ko":"AI 에이전트를 사용하여 아이폰 앱을 구축하고 테스트하세요. xcodebuild 및 Xcode 테스트를 통해 효율적인 개발을实现합니다","es":"Construye aplicaciones iPhone con nuestro agente AI, que implementa y verifica resultados con xcodebuild y Xcode Simulator.","fr":"Créez des applications iPhone avec notre outil AI, qui implémente et vérifie les résultats avec xcodebuild et Xcode Simulator.","de":"Erstellen Sie iPhone-Apps mit unserem KI-Tool, das Ergebnisse mit xcodebuild und Xcode Simulator implementiert und überprüft.","pt":"Construa aplicativos iPhone com Claude, sem necessidade de escrever código. Aprenda sobre como implementar e testar aplicativos móveis com xcodebuild","ru":"Создайте приложения для iPhone с помощью Claude без написания кода. Узнайте о реализации и тестировании мобильных приложений с помощью xcodebuild","ar":"ابني تطبيقات أيفون مع كلود بدون الحاجة إلى كتابة كود. تعلم كيفية تنفيذ واختبار التطبيقات المحمولة باستخدام xcodebuild"},"seo":{"title":{"en":"build-iphone-apps: iPhone App Development Setup Guide | A...","zh":"iPhone 应用开发设置指南 - 使用 AI Agent","ja":"iPhone アプリ開発のベストプラクティス - AIエージェントを使用","ko":"아이폰 앱 개발 설정 가이드 - AI 에이전트 사용","es":"Guía de configuración para construir aplicaciones iPhone ...","fr":"Guide de configuration pour construire des applications i...","de":"Einrichtungsleitfaden für die Erstellung von iPhone-Apps ...","pt":"Guia de Configuração para Construir Aplicativos iPhone co...","ru":"Инструмент ИИ Агентов для Создания Приложений iPhone: Рук...","ar":"دليل إنشاء تطبيقات أيفون باستخدام كلود - أدوات ذكاء اصطناعي"},"description":{"en":"Learn how to build iPhone apps with our AI agent skill, featuring xcodebuild and iOS Simulator. Get started with iPhone app development today!","zh":"学习如何使用 AI Agent 构建和测试 iPhone 应用，包括使用 xcodebuild 和 Xcode 测试","ja":"AIエージェントを使用して iPhone アプリを構築およびテストする方法を学びます。xcodebuild および Xcode テストを含みます","ko":"AI 에이전트를 사용하여 아이폰 앱을 구축하고 테스트하는 방법을 배우세요. xcodebuild 및 Xcode 테스트 포함","es":"Aprende a crear aplicaciones iPhone con nuestro agente AI. Descubre cómo implementar y verificar resultados con xcodebuild y Xcode Simulator.","fr":"Découvrez comment créer des applications iPhone avec notre outil AI. Apprenez à implémenter et à vérifier les résultats avec xcodebuild et Xcode Simulator.","de":"Erfahren Sie, wie Sie iPhone-Apps mit unserem KI-Tool erstellen. Entdecken Sie, wie Sie Ergebnisse mit xcodebuild und Xcode Simulator implementieren und über...","pt":"Aprenda a criar aplicativos iPhone sem escrever código, com o auxílio do Claude, uma ferramenta de desenvolvimento de aplicativos móveis","ru":"Создавайте приложения для iPhone без написания кода с помощью ИИ Агентов, таких как Claude, и узнайте о лучших практиках","ar":"استخدم أدوات الذكاء الاصطناعي، مثل كلود، لإنشاء تطبيقات أيفون بدون كتابة كود، وتعلم عن أفضل الممارسات"},"definition":{"en":"build-iphone-apps is a skill that allows users to describe and develop iPhone apps, leveraging xcodebuild and iOS Simulator for implementation and testing.","zh":"iPhone 应用开发是使用 AI Agent 构建和测试 iOS 应用的过程，涉及 xcodebuild 和 Xcode 测试","ja":"iPhone アプリ開発とは、AIエージェントを使用して iOS アプリを構築およびテストするプロセスであり、xcodebuild および Xcode テストを含みます","ko":"아이폰 앱 개발은 AI 에이전트를 사용하여 iOS 앱을 구축하고 테스트하는 과정으로, xcodebuild 및 Xcode 테스트를 포함합니다","es":"Un agente AI para construir aplicaciones iPhone es una herramienta que ayuda a los desarrolladores a crear aplicaciones móviles para iOS.","fr":"Un outil AI pour construire des applications iPhone est un outil qui aide les développeurs à créer des applications mobiles pour iOS.","de":"Ein KI-Tool zum Erstellen von iPhone-Apps ist ein Werkzeug, das Entwicklern hilft, mobile Anwendungen für iOS zu erstellen.","pt":"Construir aplicativos iPhone refere-se ao processo de criar aplicativos móveis para dispositivos iOS, utilizando ferramentas como xcodebuild","ru":"Создание приложений для iPhone означает процесс разработки мобильных приложений для устройств iOS, используя инструменты, такие как xcodebuild","ar":"بناء تطبيقات أيفون يعني عملية إنشاء تطبيقات محمولة لأجهزة أيفون، باستخدام أدوات مثل xcodebuild"},"features":{"en":["Implements iPhone app development using xcodebuild","Utilizes iOS Simulator for testing and verification","Supports command-line builds with xcodebuild -destination","Enables testing with xcodebuild test -destination","Reports outcomes and proves implementation results"],"zh":["使用 xcodebuild 命令行工具构建和测试 iPhone 应用","利用 Xcode 测试框架验证应用功能","支持 iOS Simulator 和真机测试","无需手动编写代码，AI Agent 代为实现","支持多种测试环境和配置"],"ja":["xcodebuild コマンドラインツールを使用して iPhone アプリを構築およびテスト","Xcode テストフレームワークを使用してアプリの機能を検証","iOS Simulator および実機テストをサポート","手動でのコード作成は不要、AIエージェントが代行","複数のテスト環境および設定をサポート"],"ko":["xcodebuild 명령줄 도구를 사용하여 아이폰 앱을 구축하고 테스트","Xcode 테스트 프레임워크를 사용하여 앱의 기능을 검증","iOS 시뮬레이터 및 실제 기기 테스트를 지원","수동 코드 작성 불필요, AI 에이전트가 대신 구현","다중 테스트 환경 및 설정을 지원"],"es":["Implementación de aplicaciones iPhone con xcodebuild","Verificación de resultados con Xcode Simulator","Soporte para iOS Simulator","Uso de CLI para la implementación y verificación","Compatibilidad con iPhone 16 y otros dispositivos iOS","Automatización de pruebas con xcsift"],"fr":["Implémentation d''applications iPhone avec xcodebuild","Vérification des résultats avec Xcode Simulator","Prise en charge d''iOS Simulator","Utilisation de CLI pour l''implémentation et la vérification","Compatibilité avec iPhone 16 et d''autres appareils iOS","Automatisation des tests avec xcsift"],"de":["Implementierung von iPhone-Apps mit xcodebuild","Überprüfung von Ergebnissen mit Xcode Simulator","Unterstützung für iOS Simulator","Verwendung von CLI für die Implementierung und Überprüfung","Kompatibilität mit iPhone 16 und anderen iOS-Geräten","Automatisierung von Tests mit xcsift"],"pt":["Implementação de aplicativos móveis com xcodebuild","Testes de aplicativos com xcodebuild test","Suporte a simuladores de iOS","Desenvolvimento de aplicativos sem necessidade de escrever código","Integração com ferramentas de desenvolvimento de aplicativos móveis","Suporte a destinos de plataforma iOS"],"ru":["Реализация мобильных приложений с помощью xcodebuild","Тестирование приложений с помощью xcodebuild test","Поддержка симуляторов iOS","Разработка приложений без необходимости написания кода","Интеграция с инструментами разработки мобильных приложений","Поддержка целей платформы iOS"],"ar":["تنفيذ تطبيقات محمولة باستخدام xcodebuild","اختبار التطبيقات باستخدام xcodebuild test","دعم محاكيات أيفون","إنشاء تطبيقات بدون الحاجة إلى كتابة كود","التكامل مع أدوات تطوير التطبيقات المحمولة","دعم أهداف منصة أيفون"]},"keywords":{"en":["how to build iphone apps","build-iphone-apps alternative","xcodebuild tutorial","ios simulator setup guide","build-iphone-apps install","iphone app development with ai","what is build-iphone-apps","build-iphone-apps vs xcode","build-iphone-apps setup guide"],"zh":["iPhone 应用开发","AI Agent","xcodebuild","Xcode 测试","iOS Simulator","iOS 应用构建","自动化测试","移动应用开发"],"ja":["iPhone アプリ開発","AIエージェント","xcodebuild","Xcode テスト","iOS Simulator","iOS アプリ構築","自動テスト","モバイルアプリ開発"],"ko":["아이폰 앱 개발","AI 에이전트","xcodebuild","Xcode 테스트","iOS 시뮬레이터","iOS 앱 구축","자동화 테스트","모바일 앱 개발"],"es":["construir aplicaciones iPhone","agente AI para iPhone","xcodebuild","Xcode Simulator","iOS Simulator","CLI","xcsift","desarrollo de aplicaciones móviles","herramientas de desarrollo para iPhone"],"fr":["créer des applications iPhone","outil AI pour iPhone","xcodebuild","Xcode Simulator","iOS Simulator","CLI","xcsift","développement d''applications mobiles","outils de développement pour iPhone"],"de":["iPhone-Apps erstellen","KI-Tool für iPhone","xcodebuild","Xcode Simulator","iOS Simulator","CLI","xcsift","Entwicklung von mobilen Anwendungen","Entwicklungstools für iPhone"],"pt":["construir aplicativos iphone","desenvolvimento de aplicativos móveis","xcodebuild","testes de aplicativos","simuladores de ios","ferramentas de desenvolvimento de aplicativos","criar aplicativos sem código","aplicativos móveis para iphone","desenvolvimento de aplicativos para ios"],"ru":["создание приложений для iphone","разработка мобильных приложений","xcodebuild","тестирование приложений","симуляторы ios","инструменты разработки мобильных приложений","создание приложений без кода","мобильные приложения для iphone","разработка приложений для ios"],"ar":["بناء تطبيقات أيفون","تطوير التطبيقات المحمولة","xcodebuild","اختبار التطبيقات","محاكيات أيفون","أدوات تطوير التطبيقات المحمولة","إنشاء تطبيقات بدون كود","تطبيقات محمولة لأيفون","تطوير تطبيقات لمنصة أيفون"]}},"owner":"saxjax","repo":"saxjaxTuner","repoPath":"saxjax/saxjaxTuner","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.353Z","topics":[],"category":"community","skillMd":{"name":"build-iphone-apps","description":"Build professional native iPhone apps in Swift with SwiftUI and UIKit. Full lifecycle - build, debug, test, optimize, ship. CLI-only, no Xcode. Targets iOS 26 with iOS 18 compatibility.","bodyPreview":"<essential_principles>\n## How We Work\n\n**The user is the product owner. Claude is the developer.**\n\nThe user does not write code. The user does not read code. The user describes what they want and judges whether the result is acceptable. Claude implements, verifies, and reports outcomes.\n\n### 1. Prove, Don''t Promise\n\nNever say \"this should work.\" Prove it:\n```bash\nxcodebuild -destination ''platform=iOS Simulator,name=iPhone 16'' build 2>&1 | xcsift\nxcodebuild test -destination ''platform=iOS Simula","body":"<essential_principles>\n## How We Work\n\n**The user is the product owner. Claude is the developer.**\n\nThe user does not write code. The user does not read code. The user describes what they want and judges whether the result is acceptable. Claude implements, verifies, and reports outcomes.\n\n### 1. Prove, Don''t Promise\n\nNever say \"this should work.\" Prove it:\n```bash\nxcodebuild -destination ''platform=iOS Simulator,name=iPhone 16'' build 2>&1 | xcsift\nxcodebuild test -destination ''platform=iOS Simulator,name=iPhone 16''\nxcrun simctl boot \"iPhone 16\" && xcrun simctl launch booted com.app.bundle\n```\nIf you didn''t run it, you don''t know it works.\n\n### 2. Tests for Correctness, Eyes for Quality\n\n| Question | How to Answer |\n|----------|---------------|\n| Does the logic work? | Write test, see it pass |\n| Does it look right? | Launch in simulator, user looks at it |\n| Does it feel right? | User uses it |\n| Does it crash? | Test + launch |\n| Is it fast enough? | Profiler |\n\nTests verify *correctness*. The user verifies *desirability*.\n\n### 3. Report Outcomes, Not Code\n\n**Bad:** \"I refactored DataService to use async/await with weak self capture\"\n**Good:** \"Fixed the memory leak. `leaks` now shows 0 leaks. App tested stable for 5 minutes.\"\n\nThe user doesn''t care what you changed. The user cares what''s different.\n\n### 4. Small Steps, Always Verified\n\n```\nChange → Verify → Report → Next change\n```\n\nNever batch up work. Never say \"I made several changes.\" Each change is verified before the next. If something breaks, you know exactly what caused it.\n\n### 5. Ask Before, Not After\n\nUnclear requirement? Ask now.\nMultiple valid approaches? Ask which.\nScope creep? Ask if wanted.\nBig refactor needed? Ask permission.\n\nWrong: Build for 30 minutes, then \"is this what you wanted?\"\nRight: \"Before I start, does X mean Y or Z?\"\n\n### 6. Always Leave It Working\n\nEvery stopping point = working state. Tests pass, app launches, changes committed. The user can walk away anytime and come back to something that works.\n\n### 7. Debug Logging Protocol\n\nWhen adding debug logging (print statements, NSLog, etc.):\n\n1. **Mark clearly:** Comment with `// DEBUG:` prefix\n   ```swift\n   // DEBUG: Testing YIN accuracy corrections\n   print(\"YIN Detected: \\(frequency) Hz\")\n   ```\n\n2. **Gather data:** Use logging to understand the problem\n\n3. **Remove before final commit:** Unless user explicitly wants it kept\n   - Production code should not have debug prints\n   - Use proper logging frameworks (os_log) for production if needed\n\n4. **Ask before committing:** \"Should I remove the debug logging now?\"\n\n**Exception:** Logging that provides user value (error messages, diagnostics) should stay but use proper frameworks.\n</essential_principles>\n\n<intake>\n**Ask the user:**\n\nWhat would you like to do?\n1. Build a new app\n2. Debug an existing app\n3. Add a feature\n4. Write/run tests\n5. Optimize performance\n6. Ship/release\n7. Something else\n\n**Then read the matching workflow from `workflows/` and follow it.**\n</intake>\n\n<routing>\n| Response | Workflow |\n|----------|----------|\n| 1, \"new\", \"create\", \"build\", \"start\" | `workflows/build-new-app.md` |\n| 2, \"broken\", \"fix\", \"debug\", \"crash\", \"bug\" | `workflows/debug-app.md` |\n| 3, \"add\", \"feature\", \"implement\", \"change\" | `workflows/add-feature.md` |\n| 4, \"test\", \"tests\", \"TDD\", \"coverage\" | `workflows/write-tests.md` |\n| 5, \"slow\", \"optimize\", \"performance\", \"fast\" | `workflows/optimize-performance.md` |\n| 6, \"ship\", \"release\", \"TestFlight\", \"App Store\" | `workflows/ship-app.md` |\n| 7, other | Clarify, then select workflow or references |\n</routing>\n\n<verification_loop>\n## After Every Change\n\n```bash\n# 1. Does it build?\nxcodebuild -scheme AppName -destination ''platform=iOS Simulator,name=iPhone 16'' build 2>&1 | xcsift\n\n# 2. Do tests pass?\nxcodebuild -scheme AppName -destination ''platform=iOS Simulator,name=iPhone 16'' test\n\n# 3. Does it launch? (if UI changed)\nxcrun simctl boot \"iPhone 16\" 2>/dev/null || true\nxcrun simctl install booted ./build/Build/Products/Debug-iphonesimulator/AppName.app\nxcrun simctl launch booted com.company.AppName\n```\n\nReport to the user:\n- \"Build: ✓\"\n- \"Tests: 12 pass, 0 fail\"\n- \"App launches in simulator, ready for you to check [specific thing]\"\n</verification_loop>\n\n<when_to_test>\n## Testing Decision\n\n**Write a test when:**\n- Logic that must be correct (calculations, transformations, rules)\n- State changes (add, delete, update operations)\n- Edge cases that could break (nil, empty, boundaries)\n- Bug fix (test reproduces bug, then proves it''s fixed)\n- Refactoring (tests prove behavior unchanged)\n\n**Skip tests when:**\n- Pure UI exploration (\"make it blue and see if I like it\")\n- Rapid prototyping (\"just get something on screen\")\n- Subjective quality (\"does this feel right?\")\n- One-off verification (launch and check manually)\n\n**The principle:** Tests let the user verify correctness without reading code. If the user needs to verify it works, and it''s not purely visual, write a test.\n</when_to_test>\n\n<reference_index>\n## Domain Knowledge\n\nAll in `references/`:\n\n**Architecture:** app-architecture, swiftui-patterns, navigation-patterns\n**Data:** data-persistence, networking\n**Platform Features:** push-notifications, storekit, background-tasks\n**Quality:** polish-and-ux, accessibility, performance\n**Assets & Security:** app-icons, security, app-store\n**Development:** project-scaffolding, cli-workflow, cli-observability, testing, ci-cd\n</reference_index>\n\n<workflows_index>\n## Workflows\n\nAll in `workflows/`:\n\n| File | Purpose |\n|------|---------|\n| build-new-app.md | Create new iOS app from scratch |\n| debug-app.md | Find and fix bugs |\n| add-feature.md | Add to existing app |\n| write-tests.md | Write and run tests |\n| optimize-performance.md | Profile and speed up |\n| ship-app.md | TestFlight, App Store submission |\n</workflows_index>\n"},"lastSynced":"2026-03-08T02:03:57.577Z","agentAnalysis":{"suitability":{"en":"Ideal for iOS Development Agents seeking to create iPhone apps without writing code, utilizing xcodebuild and iOS Simulator.","zh":"适用于iOS开发代理，通过xcodebuild和iOS Simulator创建iPhone应用程序，无需编写代码。","ja":"iOS開発エージェントがコードを書かずにiPhoneアプリを作成するのに適しており、xcodebuildとiOS Simulatorを使用します。","ko":"iOS 개발 에이전트가 코드 작성 없이 iPhone 앱을 만들 수 있게 해주며, xcodebuild와 iOS Simulator를 사용합니다.","es":"Ideal para agentes de desarrollo de iOS que buscan crear aplicaciones de iPhone sin escribir código, utilizando xcodebuild y iOS Simulator.","fr":"Idéal pour les agents de développement iOS qui cherchent à créer des applications iPhone sans écrire de code, en utilisant xcodebuild et iOS Simulator.","de":"Ideal für iOS-Entwicklungsagenten, die iPhone-Apps ohne Code erstellen möchten, unter Verwendung von xcodebuild und iOS Simulator.","pt":"Ideal para Agentes de Desenvolvimento do iOS que buscam criar aplicativos do iPhone sem escrever código, utilizando xcodebuild e iOS Simulator.","ru":"Идеально для агентов по разработке iOS, стремящихся создавать приложения для iPhone без написания кода, используя xcodebuild и iOS Simulator.","ar":"مثالي لعميل تطوير iOS الذي يبحث عن إنشاء تطبيقات iPhone دون كتابة التعليمات البرمجية، باستخدام xcodebuild و محاكي iOS."},"recommendation":{"en":"Empowers agents to implement, verify, and report iPhone app development outcomes using xcodebuild and iOS Simulator, streamlining the development process without requiring users to write or read code.","zh":"赋予代理实施、验证和报告iPhone应用程序开发结果的能力，使用xcodebuild和iOS Simulator简化开发流程，无需用户编写或阅读代码。","ja":"エージェントがxcodebuildとiOS Simulatorを使用して、iPhoneアプリの開発結果を実装、検証、報告できるようにし、コードの書き込みや読み取りを必要とせずに開発プロセスを簡素化します。","ko":"에이전트가 xcodebuild와 iOS Simulator를 사용하여 iPhone 앱 개발 결과를 구현, 검증, 보고할 수 있게 해주며, 사용자가 코드를 작성하거나 읽을 필요 없이 개발 프로세스를 간소화합니다.","es":"Permite a los agentes implementar, verificar y informar los resultados del desarrollo de aplicaciones de iPhone utilizando xcodebuild y iOS Simulator, simplificando el proceso de desarrollo sin requerir que los usuarios escriban o lean código.","fr":"Permet aux agents de mettre en œuvre, de vérifier et de signaler les résultats du développement d''applications iPhone en utilisant xcodebuild et iOS Simulator, en simplifiant le processus de développement sans exiger que les utilisateurs écrivent ou lisent du code.","de":"Ermächtigt Agenten, iPhone-App-Entwicklungsresultate mit xcodebuild und iOS Simulator umzusetzen, zu überprüfen und zu melden, wodurch der Entwicklungsprozess ohne Codieren oder Lesen von Code durch die Benutzer vereinfacht wird.","pt":"Habilita os agentes a implementar, verificar e relatar os resultados do desenvolvimento de aplicativos do iPhone usando xcodebuild e iOS Simulator, simplificando o processo de desenvolvimento sem exigir que os usuários escrevam ou leiam código.","ru":"Наделяет агентов возможностью реализовывать, проверять и сообщать о результатах разработки приложений для iPhone с помощью xcodebuild и iOS Simulator, упрощая процесс разработки без необходимости написания или чтения кода пользователями.","ar":"يمكّن الوكالات من تنفيذ وتحقق وتقديم نتائج تطوير تطبيقات iPhone باستخدام xcodebuild ومحاكي iOS، وبذلك يُبسط عملية التطوير دون الحاجة إلى كتابة أو قراءة التعليمات البرمجية من قبل المستخدمين."},"useCases":{"en":["Automating iPhone app builds with xcodebuild","Verifying app functionality using iOS Simulator","Debugging and testing iPhone apps without manual coding"],"zh":["使用xcodebuild自动化iPhone应用程序构建","使用iOS Simulator验证应用程序功能","在不需要手动编码的情况下调试和测试iPhone应用程序"],"ja":["xcodebuildを使用してiPhoneアプリのビルドを自動化する","iOS Simulatorを使用してアプリの機能を検証する","手動コーディングを必要とせずにiPhoneアプリをデバッグしてテストする"],"ko":["xcodebuild를 사용하여 iPhone 앱 빌드를 자동화하는 것","iOS Simulator를 사용하여 앱 기능을 검증하는 것","수동 코딩 없이 iPhone 앱을 디버깅하고 테스트하는 것"],"es":["Automatización de compilaciones de aplicaciones de iPhone con xcodebuild","Verificación de la funcionalidad de la aplicación utilizando iOS Simulator","Depuración y prueba de aplicaciones de iPhone sin codificación manual"],"fr":["Automatisation des builds d''applications iPhone avec xcodebuild","Vérification de la fonctionnalité de l''application en utilisant iOS Simulator","Débogage et test d''applications iPhone sans codage manuel"],"de":["Automatisierung von iPhone-App-Builds mit xcodebuild","Überprüfung der App-Funktionalität unter Verwendung von iOS Simulator","Fehlerbehebung und Testen von iPhone-Apps ohne manuelles Codieren"],"pt":["Automatizar compilações de aplicativos do iPhone com xcodebuild","Verificar a funcionalidade do aplicativo usando iOS Simulator","Depurar e testar aplicativos do iPhone sem codificação manual"],"ru":["Автоматизация сборки приложений для iPhone с помощью xcodebuild","Проверка функциональности приложения с помощью iOS Simulator","Отладка и тестирование приложений для iPhone без ручного кодирования"],"ar":["أتمتة إنشاء تطبيقات iPhone باستخدام xcodebuild","تحقق من وظيفة التطبيق باستخدام محاكي iOS","تصحيح أخطاء وتجريب تطبيقات iPhone دون 编程 يدوي"]},"limitations":{"en":["Requires xcodebuild and iOS Simulator access","Limited to iPhone app development only"],"zh":["需要访问xcodebuild和iOS Simulator","仅限于iPhone应用程序开发"],"ja":["xcodebuildとiOS Simulatorへのアクセスが必要","iPhoneアプリの開発のみに限定される"],"ko":["xcodebuild와 iOS Simulator에 접근할 수 있어야 함","iPhone 앱 개발에만 제한됨"],"es":["Requiere acceso a xcodebuild y iOS Simulator","Limitado solo al desarrollo de aplicaciones de iPhone"],"fr":["Nécessite l''accès à xcodebuild et iOS Simulator","Limité uniquement au développement d''applications iPhone"],"de":["Erfordert Zugriff auf xcodebuild und iOS Simulator","Nur für die Entwicklung von iPhone-Apps beschränkt"],"pt":["Requer acesso ao xcodebuild e ao iOS Simulator","Limitado apenas ao desenvolvimento de aplicativos do iPhone"],"ru":["Требует доступа к xcodebuild и iOS Simulator","Ограничен только разработкой приложений для iPhone"],"ar":["يتطلب الوصول إلى xcodebuild ومحاكي iOS","محدود بالتطوير فقط لتطبيقات iPhone"]},"version":4},"contentHash":"3e63827c85b782a080acd451cfac9dcb621ea7e53e4ae55f53af146b661c09f0","qualityScore":33}');
