INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jwplatta/ml_gym/python-practice', 'python-practice', 'jwplatta', 'ml_gym', 'community', 'python-practice jwplatta ml_gym community The python-practice skill generates Jupyter notebooks with practice challenges for data manipulation and algorithms. It benefits developers looking to improve their Python skills. Python实践技能，生成Jupyter笔记本，包含pandas和算法练习挑战 Pythonプラクティススキル：Pandasとアルゴリズムの練習チャレンジを含むJupyter Notebookを生成 파이썬 연습 스킬: Pandas 및 알고리즘 연습 챌린지를 포함하는 Jupyter Notebook 생성 Python-practice es una herramienta que genera un cuaderno de Jupyter con desafíos prácticos de pandas y algoritmos Python-practice est un outil qui génère un cahier Jupyter avec des défis pratiques de pandas et algorithmes Python-practice ist ein Tool, das ein Jupyter-Notebook mit praktischen Herausforderungen in pandas und Algorithmen generiert O python-practice é um agente que gera um notebook Jupyter com desafios de pandas e algoritmos para prática. ИИ Агент python-practice генерирует блокнот Jupyter с задачами по pandas и алгоритмам для практики وكلاء بايثون-مارس هو وكيل يولد دفتر جupyter مع تحديات بيانداس وخوارزميات لممارسة how to use python-practice python-practice setup guide python-practice alternative python-practice vs data science tutorials python-practice install python-practice for AI agents pandas practice challenges algorithm practice questions Python实践 pandas练习 算法练习 Jupyter Notebook 数据操作 vanilla Python AIエージェント Python Tutor Generates Jupyter notebooks with practice challenges on pandas Covers algorithms including vanilla Python data structures and recursion Allows users to focus on specific categories or generate a random mix Utilizes AskUserQuestion to gather parameters Supports practice challenges on time series and data exploration python-practice is a skill that generates Jupyter notebooks filled with practice challenges and questions on pandas and algorithms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ereferen/rustfeed/rustfeed-architecture', 'community', 'ereferen', 'rustfeed', 'ereferen/rustfeed', 'rustfeed-architecture', 0, 0, 33, '2026-03-08T01:57:15.363Z', '2026-03-08T02:04:18.326Z', '373278dbef500306d7caf59915a09c9a171c02c25f6002a790a477a6d50f49e4', '{"id":"ereferen/rustfeed/rustfeed-architecture","name":"rustfeed-architecture","description":{"en":"The rustfeed-architecture skill provides a comprehensive guide to the rustfeed project''s architecture and structure, benefiting developers working with RSS feeds and CLI tools.","zh":"Rustfeed 是一个用 Rust 语言编写的命令行 RSS 阅读器，包括共享库和 CLI 二进制文件","ja":"Rustfeed は Rust 言語で書かれた CLI RSS リーダーであり、共有ライブラリと CLI バイナリを含む","ko":"Rustfeed는 Rust 언어로 작성된 명령行 RSS 리더로, 공유 라이브러리와 CLI 바이너리를 포함합니다","es":"Rustfeed es un lector de RSS en CLI escrito en Rust, diseñado para recopilar información de RSS de manera eficiente","fr":"Rustfeed est un lecteur RSS en ligne de commande écrit en Rust, conçu pour collecter des informations RSS de manière efficace","de":"Rustfeed ist eine CLI-RSS-Leseanwendung in Rust, die für die effiziente Erfassung von RSS-Informationen entwickelt wurde","pt":"O Rustfeed é um leitor RSS em Rust que oferece funcionalidades avançadas para gerenciar feeds e artigos. Aprenda a configurar e utilizar essa ferramenta poderosa","ru":"Rustfeed - это ИИ Агент для чтения RSS, написанный на Rust, который предлагает передовые возможности для управления лентами и статьями. Узнайте, как настроить и использовать эту мощную herramienta","ar":"رستفيد هو قارئ إرشادات RSS باستخدام رست الذي يقدم ميزات متقدمة لتدبير الإرشادات والمقالات. تعرف على كيفية تكوين واستخدام هذه الأداة القوية"},"seo":{"title":{"en":"rustfeed-architecture: CLI RSS Reader Setup Guide | AI Ag...","zh":"Rustfeed 架构指南 - 命令行 RSS 阅读器","ja":"Rustfeed アーキテクチャガイド - CLI RSS リーダー","ko":"Rustfeed 아키텍처 가이드 - 명령行 RSS 리더