INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Krual-T/LifeKernel/recorder', 'recorder', 'Krual-T', 'LifeKernel', 'community', 'recorder Krual-T LifeKernel community The recorder skill unifies knowledge, news, lifelog, and task records into a single JSONL format, ensuring data consistency and ease of management for AI agents. Recorder 技术实现了记录类数据的统一 JSONL 记录和 CRUD 操作，确保数据的一致性和可靠性 Recorder AIエージェントは、記録クラスのデータを統一的な JSONL 記録と CRUD 操作で管理することで、データの一貫性と信頼性を確保する Recorder는 기록 데이터를 통합적인 JSONL 기록과 CRUD 연산으로 관리하여 데이터的一貫性와 신뢰성을 보장 Recorder es una herramienta para unificar datos en JSONL con esquemas de datos fuertemente restringidos. Permite la creación, actualización y eliminación de registros de conocimiento, noticias, lifelog y más. L''enregistreur est un outil pour unifier les données en JSONL avec des schémas de données fortement restrictifs. Il permet la création, la mise à jour et la suppression d''enregistrements de connaissances, de nouvelles, de lifelog et plus encore. Recorder ist ein Tool, um Daten in JSONL mit stark eingeschränkten Datenschemata zu vereinheitlichen. Es ermöglicht die Erstellung, Aktualisierung und Löschung von Wissens-, Nachrichten-, Lifelog- und weiteren Einträgen. O recorder é uma ferramenta que unifica registros em JSONL, garantindo UTF-8 sem BOM e seguindo o schema da .codex/schema.json Запись - это инструмент, который объединяет записи в JSONL, обеспечивая UTF-8 без BOM и следуя схеме .codex/schema.json для ИИ Агентов التسجيل هو أداة توحيد السجلات في JSONL، وضمان UTF-8 بدون BOM ومتابعة مخطط .codex/schema.json how to use recorder recorder skill for AI agents JSONL recording format UTF-8 encoding without BOM recorder setup guide recorder alternative unified record management Recorder 技术 JSONL 记录 CRUD 操作 记录类数据 统一管理 强约束 Schema UTF-8 无 BOM Unifies records into a single JSONL format Ensures UTF-8 encoding without BOM Follows a strict schema defined in .codex/schema.json Supports CRUD operations for records Allows for automatic recording and updating of records Recorder is a skill that unifies JSONL recording for various data types, following a strict schema defined in .codex/schema.json.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('narumiruna/telegram-bot/python-cli-typer', 'community', 'narumiruna', 'telegram-bot', 'narumiruna/telegram-bot', 'python-cli-typer', 0, 0, 33, '2026-03-08T01:57:15.380Z', '2026-03-08T02:05:38.846Z', '9ff2ddb82e48cb6dc6726d54955f9b5edd0ee8aea4178981aaf708ac988d8675', '{"id":"narumiruna/telegram-bot/python-cli-typer","name":"python-cli-typer","description":{"en":"Python-cli-typer is a skill for building command-line interfaces with Typer. It helps developers create explicit and testable CLI entry points.","zh":"使用 Typer 构建 Python 命令行界面，实现可测试和可维护的 CLI 应用","ja":"Typer を使用して Python CLI を構築し、テスト可能でメンテナンスが容易な CLI アプリケーションを作成します","ko":"Typer를 사용하여 Python CLI를 구축하고 테스트 가능하며 유지 보수가 쉬운 CLI 애플리케이션을 만듭니다","es":"Typer es una biblioteca para crear interfaces de línea de comandos en Python. Ofrece una forma ergonómica de construir CLI.","fr":"Typer est une bibliothèque pour créer des interfaces de ligne de commande en Python. Elle offre une façon ergonomique de construire des CLI.","de":"Typer ist eine Bibliothek zum Erstellen von Befehlszeilen-Interfaces in Python. Sie bietet eine ergonomische Möglichkeit, CLI zu erstellen.","pt":"Typer é uma biblioteca Python para construir interfaces de linha de comando ergonomicas. Aprenda a usá-la para criar CLIs explicitas e testáveis","ru":"Typer - это библиотека Python для построения эргономичных интерфейсов командной строки. Узнайте, как использовать ее для создания явных и тестируемых CLI, ИИ Агенты","ar":"Typer هي مكتبة Python لإنشاء واجهات سطر الأوامر المريحة. تعلم كيفية استخدامها لإنشاء واجهات سطر الأوامر الصريحة والقابلة للاختبار، أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"python-cli-typer: Typer CLI Setup Guide | AI Agent Skill","zh":"Python CLI Typer 设计指南","ja":"Python CLI Typer のベストプラクティス","ko":"Python CLI Typer 설정 가이드","es":"Guía de configuración de Python CLI con Typer","fr":"Guide de mise en place de Python CLI avec Typer","de":"Einrichtungsleitfaden für Python CLI mit Typer","pt":"Guia de Configuração do Python CLI com Typer","ru":"Настройка Python CLI с Typer: Лучшие Практики","ar":"دليل إعداد واجهة سطر الأوامر Python مع Typer"},"description":{"en":"Discover how to build ergonomic CLIs with python-cli-typer. Learn to install and use Typer for explicit and testable CLI entry points. Get started now!","zh":"了解如何使用 Typer 构建 Python 命令行界面，包括安装、快速参考和工作流","ja":"Typer を使用して Python CLI を構築する方法を学びます。インストール、クイックリファレンス、ワークフローなど","ko":"Typer를 사용한 Python CLI 구축 방법에 대해 알아보세요. 설치, 퀵 레퍼런스, 워크플로우 등","es":"Aprende a crear interfaces de línea de comandos en Python con Typer. Mejora la experiencia del usuario con nuestra guía paso a paso.","fr":"Découvrez comment créer des interfaces de ligne de commande en Python avec Typer. Améliorez l''expérience utilisateur avec notre guide étape par étape.","de":"Erfahren Sie, wie Sie Befehlszeilen-Interfaces in Python mit Typer erstellen. Verbessern Sie die Benutzererfahrung mit unserem Schritt-für-Schritt-Leitfaden.","pt":"Aprenda a criar interfaces de linha de comando Python com Typer. Descubra como instalar e usar Typer para construir CLIs ergonomicas","ru":"Узнайте, как создать интерфейс командной строки Python с помощью Typer. Откройте для себя, как установить и использовать Typer для построения эргономичных CL...","ar":"تعلم كيفية إنشاء واجهات سطر الأوامر Python باستخدام Typer. اكتشف كيفية تثبيت Typer واستخدامه لبناء واجهات سطر الأوامر المريحة، أدوات الذكاء الاصطناعي"},"definition":{"en":"python-cli-typer is a Python library for constructing command-line interfaces using Typer, emphasizing explicit and testable entry points.","zh":"Python CLI Typer 是一个用于构建命令行界面的 Python 库","ja":"Python CLI Typer は、コマンドラインインターフェイスを構築するための Python ライブラリです","ko":"Python CLI Typer는 명령줄 인터페이스를 구축하기 위한 Python 라이브러리입니다","es":"Typer es una herramienta de línea de comandos de Python para crear interfaces de usuario intuitivas.","fr":"Typer est un outil de ligne de commande Python pour créer des interfaces utilisateur intuitives.","de":"Typer ist ein Befehlszeilen-Tool für Python, um benutzerfreundliche Schnittstellen zu erstellen.","pt":"Typer é uma biblioteca Python para construir interfaces de linha de comando","ru":"Typer - это библиотека Python для построения интерфейсов командной строки","ar":"Typer هي مكتبة Python لإنشاء واجهات سطر الأوامر"},"features":{"en":["Uses Typer for ergonomic CLI construction","Supports single and multiple commands via @app.command()","Utilizes function args with defaults for options","Defines a typer.Typer() app in cli.py for CLI setup","Allows running CLI via uv add typer"],"zh":["使用 @app.command() 定义单个命令","使用函数参数和默认值定义选项","支持多个命令","使用 typer.Typer() 定义 CLI 应用","保持命令函数小巧，逻辑移到单独的模块","通过 CLI 运行应用"],"ja":["単一のコマンドを @app.command() で定義","関数パラメータとデフォルト値を使用してオプションを定義","複数のコマンドをサポート","typer.Typer() を使用して CLI アプリケーションを定義","コマンド関数を小さく保ち、ロジックを別モジュールに移動","CLI を介してアプリケーションを実行"],"ko":["단일 명령을 @app.command()로 정의","함수 매개변수 및 기본값을 사용하여 옵션 정의","다중 명령 지원","typer.Typer()를 사용하여 CLI 애플리케이션 정의","명령 함수를 작게 유지하고 로직을 별도의 모듈로 이동","CLI를 통해 애플리케이션 실행"],"es":["Creación de interfaces de línea de comandos con Typer","Uso de decoradores para definir comandos","Soporte para opciones y argumentos","Posibilidad de crear comandos múltiples","Integración con otras bibliotecas de Python"],"fr":["Création d''interfaces de ligne de commande avec Typer","Utilisation de décorateurs pour définir des commandes","Prise en charge des options et des arguments","Possibilité de créer des commandes multiples","Intégration avec d''autres bibliothèques Python"],"de":["Erstellung von Befehlszeilen-Interfaces mit Typer","Verwendung von Dekoratoren zur Definition von Befehlen","Unterstützung für Optionen und Argumente","Möglichkeit zur Erstellung mehrerer Befehle","Integration mit anderen Python-Bibliotheken"],"pt":["Criação de interfaces de linha de comando ergonomicas","Uso de @app.command() para definir comandos","Suporte a opções e argumentos","Possibilidade de criar múltiplos comandos","Instalação via uv add typer"],"ru":["Построение эргономичных интерфейсов командной строки","Использование @app.command() для определения команд","Поддержка опций и аргументов","Возможность создания нескольких команд","Установка через uv add typer, ИИ Агенты"],"ar":["إنشاء واجهات سطر الأوامر المريحة","استخدام @app.command() لتعريف الأوامر","دعم الخيارات والوسائط","إمكانية إنشاء أوامر متعددة","التثبيت عبر uv add typer، أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use python-cli-typer","python-cli-typer install","python-cli-typer setup guide","what is python-cli-typer","python-cli-typer alternative","python-cli-typer vs click"],"zh":["Python CLI","Typer","命令行界面","CLI 构建","Python 开发","AIエージェント","Python 库","命令行工具"],"ja":["Python CLI","Typer","コマンドラインインターフェイス","CLI 構築","Python 開発","AIエージェント","Python ライブラリ","コマンドラインツール"],"ko":["Python CLI","Typer","명령줄 인터페이스","CLI 구축","Python 개발","AI 에이전트","Python 라이브러리","명령줄 도구"],"es":["python cli","typer","herramientas de línea de comandos","interfaces de usuario","desarrollo de software","programación en python","bibliotecas de python","cli python","typer python"],"fr":["python cli","typer","outils de ligne de commande","interfaces utilisateur","développement de logiciels","programmation en python","bibliothèques python","cli python","typer python"],"de":["python cli","typer","Befehlszeilen-Tools","Benutzerschnittstellen","Software-Entwicklung","Python-Programmierung","Python-Bibliotheken","cli python","typer python"],"pt":["python cli","typer","interfaces de linha de comando","cli python","uv add typer","criar cli python","bibliotecas python"],"ru":["python cli","typer","интерфейсы командной строки","cli python","uv add typer","создать cli python","библиотеки python","ИИ Агенты"],"ar":["python cli","typer","واجهات سطر الأوامر","cli python","uv add typer","إنشاء واجهة سطر الأوامر python","مكتبات python","أدوات الذكاء الاصطناعي"]}},"owner":"narumiruna","repo":"telegram-bot","repoPath":"narumiruna/telegram-bot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.380Z","topics":[],"category":"community","skillMd":{"name":"python-cli-typer","description":"Use when building or structuring Python CLI commands with Typer, including commands, options, and multi-command apps.","bodyPreview":"# Python CLI with Typer\n\n## Overview\n\nUse Typer for ergonomic CLI construction. Core principle: keep CLI entry points explicit and testable.\n\n## Install\n\n```bash\nuv add typer\n```\n\n## Quick Reference\n\n| Task | Pattern |\n| --- | --- |\n| Single command | `@app.command()` |\n| Options | function args with defaults |\n| Multiple commands | multiple `@app.command()` |\n\n## Workflow\n\n- Define a `typer.Typer()` app in `cli.py`.\n- Keep command functions small; move logic into separate modules.\n- Run CLI via","body":"# Python CLI with Typer\n\n## Overview\n\nUse Typer for ergonomic CLI construction. Core principle: keep CLI entry points explicit and testable.\n\n## Install\n\n```bash\nuv add typer\n```\n\n## Quick Reference\n\n| Task | Pattern |\n| --- | --- |\n| Single command | `@app.command()` |\n| Options | function args with defaults |\n| Multiple commands | multiple `@app.command()` |\n\n## Workflow\n\n- Define a `typer.Typer()` app in `cli.py`.\n- Keep command functions small; move logic into separate modules.\n- Run CLI via `uv run python -m <module>` or `uv run python cli.py`.\n\n## Example\n\n```python\nimport typer\n\napp = typer.Typer()\n\n@app.command()\ndef greet(name: str, count: int = 1) -> None:\n    for _ in range(count):\n        typer.echo(f\"Hello, {name}!\")\n\nif __name__ == \"__main__\":\n    app()\n```\n\nUsage:\n```bash\nuv run python cli.py --help\nuv run python cli.py Alice\nuv run python cli.py Alice --count 3\n```\n\nMultiple commands:\n```python\nimport typer\n\napp = typer.Typer()\n\n\n@app.command()\ndef create(name: str) -> None:\n    \"\"\"Create a new item.\"\"\"\n    typer.echo(f\"Creating {name}...\")\n\n\n@app.command()\ndef delete(name: str, force: bool = False) -> None:\n    \"\"\"Delete an item.\"\"\"\n    if not force:\n        if not typer.confirm(f\"Delete {name}?\"):\n            raise typer.Abort()\n    typer.echo(f\"Deleted {name}\")\n\n\nif __name__ == \"__main__\":\n    app()\n```\n\n## Common Mistakes\n\n- Putting heavy business logic inside CLI functions.\n- Forgetting to wire `if __name__ == \"__main__\"` for script entry.\n\n## Red Flags\n\n- CLI guidance that ignores Typer when Typer is the chosen framework.\n"},"lastSynced":"2026-03-08T02:05:38.846Z","agentAnalysis":{"suitability":{"en":"Perfect for Python CLI Agents needing explicit and testable command-line interfaces with Typer.","zh":"非常适合需要明确和可测试的命令行接口的Python CLI代理，使用Typer。","ja":"Typerを使用して明確でテスト可能なコマンドラインインターフェイスを必要とするPython CLIエージェントに最適です。","ko":"Typer를 사용하여 명확하고 테스트 가능한 명령줄 인터페이스를 필요한 Python CLI 에이전트에 적합합니다.","es":"Perfecto para agentes de CLI de Python que necesitan interfaces de línea de comandos explícitas y verificables con Typer.","fr":"Parfait pour les agents CLI Python ayant besoin d''interfaces de ligne de commande explicites et testables avec Typer.","de":"Perfekt für Python-CLI-Agents, die explizite und testbare Kommandozeilen-Schnittstellen mit Typer benötigen.","pt":"Perfeito para Agents CLI Python que precisam de interfaces de linha de comando explícitas e testáveis com Typer.","ru":"Идеально подходит для агентов Python CLI, требующих явных и тестируемых командных интерфейсов с Typer.","ar":"مثالي لعميل Python CLI الذي يحتاج إلى واجهات سطر أوامر صريحة وقابلة للاختبار مع Typer."},"recommendation":{"en":"Empowers agents to construct ergonomic CLI applications using Typer, providing explicit and testable CLI entry points with features like single commands, options, and multiple commands. It utilizes the Typer library for efficient CLI construction and supports patterns like `@app.command()` for defining commands.","zh":"赋予代理构建使用Typer的直观CLI应用程序的能力，提供明确和可测试的CLI入口点，具有单个命令、选项和多个命令等功能。它利用Typer库进行高效的CLI构造，并支持诸如@app.command()之类的模式来定义命令。","ja":"Typerを使用してエージェントが直感的なCLIアプリケーションを構築できるようにし、シングルコマンド、オプション、マルチコマンドなどの機能で明確でテスト可能なCLIエントリーポイントを提供します。Typerライブラリを使用して効率的なCLI構築を実現し、@app.command()などのパターンを使用してコマンドを定義します。","ko":"에이전트가 Typer를 사용하여 편리한 CLI 응용 프로그램을 구축할 수 있도록 강화하여 명확하고 테스트 가능한 CLI 진입점을 제공하며 단일 명령, 옵션 및 여러 명령과 같은 기능을 제공합니다. Typer 라이브러리를 사용하여 효율적인 CLI 구성을 지원하며 @app.command()와 같은 패턴을 사용하여 명령을 정의합니다.","es":"Habilita a los agentes a construir aplicaciones de CLI ergonómicas utilizando Typer, proporcionando puntos de entrada de CLI explícitos y verificables con características como comandos únicos, opciones y múltiples comandos. Utiliza la biblioteca Typer para la construcción eficiente de CLI y admite patrones como `@app.command()` para definir comandos.","fr":"Permet aux agents de construire des applications CLI ergonomiques en utilisant Typer, en fournissant des points d''entrée de CLI explicites et testables avec des fonctionnalités comme des commandes uniques, des options et des commandes multiples. Il utilise la bibliothèque Typer pour une construction de CLI efficace et prend en charge des modèles comme `@app.command()` pour définir des commandes.","de":"Ermöglicht es Agenten, ergonomische CLI-Anwendungen mit Typer zu erstellen, indem explizite und testbare CLI-Einstiegspunkte mit Funktionen wie einzelnen Befehlen, Optionen und mehreren Befehlen bereitgestellt werden. Es nutzt die Typer-Bibliothek für eine effiziente CLI-Konstruktion und unterstützt Muster wie `@app.command()` zur Definition von Befehlen.","pt":"Habilita os agentes a construir aplicações CLI ergonômicas usando Typer, fornecendo pontos de entrada CLI explícitos e testáveis com recursos como comandos únicos, opções e vários comandos. Ele utiliza a biblioteca Typer para uma construção eficiente de CLI e suporta padrões como `@app.command()` para definir comandos.","ru":"Наделяет агентов возможностью создавать эргономичные приложения CLI с помощью Typer, предоставляя явные и тестируемые точки входа CLI с функциями, такими как единичные команды, опции и несколько команд. Он использует библиотеку Typer для эффективного построения CLI и поддерживает шаблоны, такие как `@app.command()`, для определения команд.","ar":"تمكّن الوكيل من إنشاء تطبيقات واجهة سطر أوامر متوافقة باستخدام Typer، مع توفير نقاط دخول واجهة سطر أوامر صريحة وقابلة للاختبار مع ميزات مثل أوامر مفردة وخيارات وأوامر متعددة. يستخدم مكتبة Typer لبناء واجهة سطر أوامر فعالة ودعم أنماط مثل `@app.command()` لتعريف الأوامر."},"useCases":{"en":["Building explicit CLI entry points","Creating testable command-line interfaces","Defining single and multiple commands with Typer"],"zh":["构建明确的CLI入口点","创建可测试的命令行接口","使用Typer定义单个和多个命令"],"ja":["明確なCLIエントリーポイントの構築","テスト可能なコマンドラインインターフェイスの作成","Typerを使用したシングルコマンドとマルチコマンドの定義"],"ko":["명확한 CLI 진입점 구축","테스트 가능한 명령줄 인터페이스 생성","Typer를 사용한 단일 명령 및 다중 명령 정의"],"es":["Construir puntos de entrada de CLI explícitos","Crear interfaces de línea de comandos verificables","Definir comandos únicos y múltiples con Typer"],"fr":["Construire des points d''entrée de CLI explicites","Créer des interfaces de ligne de commande testables","Définir des commandes uniques et multiples avec Typer"],"de":["Explizite CLI-Einstiegspunkte erstellen","Testbare Kommandozeilen-Schnittstellen erstellen","Einzelne und multiple Befehle mit Typer definieren"],"pt":["Construir pontos de entrada CLI explícitos","Criar interfaces de linha de comando testáveis","Definir comandos simples e múltiplos com Typer"],"ru":["Создание явных точек входа CLI","Создание тестируемых командных интерфейсов","Определение единичных и множественных команд с помощью Typer"],"ar":["بناء نقاط دخول واجهة سطر أوامر صريحة","إنشاء واجهات سطر أوامر قابلة للاختبار","تعريف أوامر مفردة ومножية مع Typer"]},"limitations":{"en":["Requires Typer installation via `uv add typer`","Python environment required"],"zh":["需要通过`uv add typer`安装Typer","需要Python环境"],"ja":["`uv add typer`を使用してTyperをインストールする必要があります","Python環境が必要です"],"ko":["`uv add typer`를 통해 Typer 설치가 필요합니다","Python 환경이 필요합니다"],"es":["Requiere la instalación de Typer a través de `uv add typer`","Entorno de Python requerido"],"fr":["Nécessite l''installation de Typer via `uv add typer`","Environnement Python requis"],"de":["Erfordert die Installation von Typer über `uv add typer`","Python-Umgebung erforderlich"],"pt":["Requer instalação do Typer via `uv add typer`","Ambiente Python necessário"],"ru":["Требуется установка Typer через `uv add typer`","Требуется среда Python"],"ar":["يتطلب تثبيت Typer عبر `uv add typer`","يتطلب بيئة Python"]},"version":4},"contentHash":"9ff2ddb82e48cb6dc6726d54955f9b5edd0ee8aea4178981aaf708ac988d8675","qualityScore":33}');
