INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('narumiruna/telegram-bot/python-cli-typer', 'python-cli-typer', 'narumiruna', 'telegram-bot', 'community', 'python-cli-typer narumiruna telegram-bot community Python-cli-typer is a skill for building command-line interfaces with Typer. It helps developers create explicit and testable CLI entry points. 使用 Typer 构建 Python 命令行界面，实现可测试和可维护的 CLI 应用 Typer を使用して Python CLI を構築し、テスト可能でメンテナンスが容易な CLI アプリケーションを作成します Typer를 사용하여 Python CLI를 구축하고 테스트 가능하며 유지 보수가 쉬운 CLI 애플리케이션을 만듭니다 Typer es una biblioteca para crear interfaces de línea de comandos en Python. Ofrece una forma ergonómica de construir CLI. Typer est une bibliothèque pour créer des interfaces de ligne de commande en Python. Elle offre une façon ergonomique de construire des CLI. Typer ist eine Bibliothek zum Erstellen von Befehlszeilen-Interfaces in Python. Sie bietet eine ergonomische Möglichkeit, CLI zu erstellen. Typer é uma biblioteca Python para construir interfaces de linha de comando ergonomicas. Aprenda a usá-la para criar CLIs explicitas e testáveis Typer - это библиотека Python для построения эргономичных интерфейсов командной строки. Узнайте, как использовать ее для создания явных и тестируемых CLI, ИИ Агенты Typer هي مكتبة Python لإنشاء واجهات سطر الأوامر المريحة. تعلم كيفية استخدامها لإنشاء واجهات سطر الأوامر الصريحة والقابلة للاختبار، أدوات الذكاء الاصطناعي how to use python-cli-typer python-cli-typer install python-cli-typer setup guide what is python-cli-typer python-cli-typer alternative python-cli-typer vs click Python CLI Typer 命令行界面 CLI 构建 Python 开发 AIエージェント Python 库 命令行工具 Uses Typer for ergonomic CLI construction Supports single and multiple commands via @app.command() Utilizes function args with defaults for options Defines a typer.Typer() app in cli.py for CLI setup Allows running CLI via uv add typer python-cli-typer is a Python library for constructing command-line interfaces using Typer, emphasizing explicit and testable entry points.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('toshi-hm/dialy/react-component', 'community', 'toshi-hm', 'dialy', 'toshi-hm/dialy', 'react-component', 0, 0, 33, '2026-03-08T01:57:15.396Z', '2026-03-08T02:06:22.850Z', 'ab6f9b841c3b3fe83afba529d32f87497e48f15a3108b0e39c907ade7328018d', '{"id":"toshi-hm/dialy/react-component","name":"react-component","description":{"en":"The react-component skill creates high-quality React components using Next.js 16.1.5 and React 19.2.4, benefiting developers who need to build reusable UI elements","zh":"使用 React 和 Next.js 创建高质量的组件，包括 Atomic Design 阶层和组件实现","ja":"React と Next.js を使用した高品質なコンポーネントの作成，包括 Atomic Design 階層とコンポーネントの実装","ko":"React와 Next.js를 사용하여 고품질의 컴포넌트를 생성합니다. Atomic Design 계층과 컴포넌트 구현을 포함합니다","es":"Crea componentes de React de alta calidad con Next.js 16.1.5 y React 19.2.4","fr":"Créez des composants React de haute qualité avec Next.js 16.1.5 et React 19.2.4","de":"Erstellen Sie hochwertige React-Komponenten mit Next.js 16.1.5 und React 19.2.4","pt":"O react-component é uma ferramenta para criar componentes React de alta qualidade, utilizando o framework Next.js e seguindo as diretrizes de design atômico","ru":"React-компонент - это инструмент для создания высококачественных компонентов React, использующий фреймворк Next.js и следуя руководящим принципам атомарного дизайна","ar":"مكون React هو أداة لإنشاء مكونات عالية الجودة باستخدام إطار العمل Next.js ومتابعة إرشادات تصميم الذرات"},"seo":{"title":{"en":"react-component: Next.js Component Creation Setup Guide |...","zh":"React 组件创建最佳实践","ja":"React コンポーネントの作成ガイド","ko":"React 컴포넌트 생성 튜토리얼","es":"Guía de configuración de componentes de React","fr":"Guide de mise en place de composants React","de":"React-Component-Setup-Leitfaden","pt":"Guia de Configuração do React-Component para Desenvolvedores","ru":"Настройка React-Компонента: Лучшие Практики для Разработ