INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('malue-ai/dazee-small/trend-spotter', 'trend-spotter', 'malue-ai', 'dazee-small', 'community', 'trend-spotter malue-ai dazee-small community The trend-spotter skill discovers new trends and hot topics from news, social media, and search data, benefiting content creators, product managers, and users seeking recent AI trends. Trend-Spotter 是一个发现新兴趋势和热门话题的 AI 工具，利用 Google Trends 和搜索数据 Trend-Spotter は新しいトレンドやホットトピックを発見する AI ツールで、Google Trends や検索データを使用 Trend-Spotter는 새로운 트렌드와 핫 토픽을 발견하는 AI 도구로, 구글 트렌드와 검색 데이터를 이용 Trend-Spotter es una habilidad que utiliza datos de Google Trends y RSS para descubrir tendencias y temas calientes. Permite a los desarrolladores crear aplicaciones que ofrecen información en tiempo real Trend-Spotter est une compétence qui utilise des données de Google Trends et RSS pour découvrir les tendances et les sujets chauds. Elle permet aux développeurs de créer des applications qui offrent des informations en temps réel Trend-Spotter ist eine Fähigkeit, die Google-Trends- und RSS-Daten verwendet, um Trends und heiße Themen zu entdecken. Sie ermöglicht es Entwicklern, Anwendungen zu erstellen, die Echtzeitinformationen bieten O Trend-Spotter é uma ferramenta de IA que descobre tendências e tópicos quentes usando dados de notícias, mídias sociais e pesquisas Trend-Spotter - это инструмент ИИ, который обнаруживает тенденции и горячие темы с помощью данных новостей, социальных сетей и поиска Trend-Spotter هو أداة ذكاء اصطناعي لاكتشاف التوجهات والمواضيع الساخنة باستخدام بيانات الأخبار والوسائط الاجتماعية والبحث how to use trend-spotter trend-spotter setup guide google trends api tutorial trend-spotter alternative tools trend-spotter vs google alerts install trend-spotter skill trend-spotter for content creators trend-spotter for product managers what is trend-spotter trend-spotter install Trend-Spotter AI 工具 Google Trends 搜索数据分析 实时热搜 行业动向分析 Python 数据分析 CLI 工具 Utilizes Google Trends API for real-time hot search data Parses RSS feeds from Google Trends for daily trending searches Employs XML parsing with ElementTree for data extraction Supports geographic-specific trend analysis with geo parameter Executes bash commands for curl and python script integration Analyzes trending searches with Python scripting trend-spotter is a skill that identifies emerging trends and popular topics from various data sources, including Google Trends and social media.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mtthsnc/autonome/use-tdd', 'community', 'mtthsnc', 'autonome', 'mtthsnc/autonome', 'use-tdd', 0, 0, 33, '2026-03-08T01:57:15.402Z', '2026-03-08T02:06:48.812Z', 'e17cc5b01fc1621ace0ab30d29e0306e1ce743d0dfe3fa1a7dc02306a7fcdc56', '{"id":"mtthsnc/autonome/use-tdd","name":"use-tdd","description":{"en":"use-tdd is a skill for intent-driven AI agents that enforces Test-Driven Development principles. It benefits developers by ensuring production code is test-driven, following the core principle of writing minimal code to pass tests.","zh":"使用TDD开发AI代理，通过测试驱动开发提高代码质量和开发效率","ja":"TDDを使用してAIエージェントの開発を改善し、コードの品質と開発効率を向上させる","ko":"TDD를 사용하여 AI 에이전트 개발을 개선하고 코드 품질 및 개발 효율성을 향상합니다","es":"use-tdd es una habilidad para Agentes de Inteligencia Artificial que sigue el principio de escribir la prueba antes de escribir el código","fr":"use-tdd est une compétence pour les Agents d''Intelligence Artificielle qui suit le principe d''écrire la test avant d''écrire le code","de":"use-tdd ist eine Fähigkeit für KI-Agents, die dem Prinzip folgt, den Test vor dem Code zu schreiben","pt":"use-tdd é uma abordagem de desenvolvimento que prioriza a escrita de testes antes do código, garantindo uma base sólida para o desenvolvimento de software","ru":"use-tdd - это подход к разработке, который отдает приоритет написанию тестов перед кодом, обеспечивая прочную основу для разработки программного обеспечения ИИ Агентов","ar":"use-tdd هو نهج في التطوير ي ưu tiên كتابة الاختبارات قبل الكود، đảm_secure قاعدة صلبة لتطوير البرمجيات لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"use-tdd: Red-Green-Refactor Setup Guide | AI Agent Skill","zh":"使用TDD的AI代理技术Setup Guide","ja":"TDDを使用したAIエージェントのBest Practices","ko":"TDD를 사용하는 AI 에이전트 개발 가이드","es":"Guía de configuración de use-tdd para Agentes de Intelige...","fr":"Configurer use-tdd pour les Agents d''Intelligence Artific...","de":"Einrichtungsleitfaden für use-tdd in KI-Agents","pt":"Guia de Configuração use-tdd: Desenvolvimento Dirigido po...","ru":"Настройка use-tdd: Руководство по Разработке через Тестир...","ar":"دليل الإعداد use-tdd: تطوير مدفوع بالاختبار لأدوات الذكاء..."},"description":{"en":"Unlock efficient coding with use-tdd! Discover how to apply the Iron Law and Red-Green-Refactor principles to your AI agent development. Get started now!","zh":"了解如何使用TDD（测试驱动开发）创建更可靠的AI代理，提高代码质量和开发效率","ja":"TDDを使用してAIエージェントの開発を改善し、コードの品質と開発効率を向上させる方法を学びます","ko":"TDD를 사용하여 더 신뢰할 수 있는 AI 에이전트를 만들고 코드 품질 및 개발 효율성을 향상하는 방법을 알아보세요","es":"Aprende a implementar use-tdd en tus Agentes de Inteligencia Artificial con nuestra guía paso a paso","fr":"Découvrez comment configurer use-tdd pour vos Agents d''Intelligence Artificielle avec notre guide étape par étape","de":"Erfahren Sie, wie Sie use-tdd in Ihren KI-Agents implementieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a implementar o uso de testes dirigidos por intenção com use-tdd para melhorar a qualidade do código","ru":"Узнайте, как реализовать использование тестов, управляемых намерением, с use-tdd для повышения качества кода ИИ Агентов","ar":"تعرف على كيفية تنفيذ اختبارات مدفوعة بالغرض مع use-tdd لتحسين جودة الكود لأدوات الذكاء الاصطناعي"},"definition":{"en":"use-tdd is a Test-Driven Development skill that adheres to the Iron Law, requiring a failing test before writing production code, and follows the Red-Green-Refactor cycle.","zh":"TDD是测试驱动开发的英文缩写，指的是在编写代码之前先编写测试用例","ja":"TDDはテスト駆動開発のことであり、コードを書く前にテストケースを書くことを意味する","ko":"TDD는 테스트 주도 개발을 의미하며, 코드를 작성하기 전에 테스트 케이스를 작성하는 것을 의미합니다","es":"use-tdd es una técnica de desarrollo de software que implica escribir pruebas antes de escribir el código","fr":"use-tdd est une technique de développement de logiciels qui consiste à écrire des tests avant d''écrire le code","de":"use-tdd ist eine Technik der Softwareentwicklung, bei der Tests vor dem Code geschrieben werden","pt":"use-tdd é uma técnica de desenvolvimento que envolve a escrita de testes antes do código para garantir a qualidade","ru":"use-tdd - это техника разработки, которая включает в себя написание тестов перед кодом для обеспечения качества ИИ Агентов","ar":"use-tdd هو تقنية تطوير تشمل كتابة الاختبارات قبل الكود لضمان الجودة لأدوات الذكاء الاصطناعي"},"features":{"en":["Enforces the Iron Law: NO PRODUCTION CODE WITHOUT A FAILING TEST FIRST","Implements Red-Green-Refactor cycle for efficient coding","Writes minimal code to pass tests, ensuring test-driven development","Deletes existing code if not written with a failing test first, promoting a clean start","Follows a strict principle of not keeping or adapting existing code as reference"],"zh":["编写测试用例之前不编写生产代码","使用Red-Green-Refactor开发流程","确保测试用例失败后再编写生产代码","删除不需要的代码，避免代码冗余","提高代码质量和开发效率"],"ja":["プロダクションコードを書く前にテストケースを書く","Red-Green-Refactor開発プロセスを使用する","テストケースが失敗した後にのみプロダクションコードを書く","不要なコードを削除し、コードの冗長性を避ける","コードの品質と開発効率を向上させる"],"ko":["생산 코드를 작성하기 전에 테스트 케이스를 작성합니다","Red-Green-Refactor 개발 프로세스를 사용합니다","테스트 케이스가 실패한 후에만 생산 코드를 작성합니다","필요하지 않은 코드를 삭제하여 코드 중복을 피합니다","코드 품질과 개발 효율성을 향상합니다"],"es":["Escribe la prueba antes de escribir el código","Sigue el principio de Red-Green-Refactor","No permite código de producción sin una prueba previa","Elimina el código existente si no se ajusta a la prueba","Permite refactorizar el código después de pasar la prueba"],"fr":["Écrire la test avant d''écrire le code","Suivre le principe de Red-Green-Refactor","Ne pas permettre de code de production sans test préalable","Éliminer le code existant si celui-ci ne correspond pas à la test","Permettre de refactoriser le code après avoir passé la test"],"de":["Schreibe den Test vor dem Code","Folge dem Prinzip von Red-Green-Refactor","Erlaube keinen Produktionscode ohne vorherigen Test","Lösche den bestehenden Code, wenn er nicht zum Test passt","Ermögliche das Refaktorisieren des Codes nach bestandener Test"],"pt":["Escrita de testes antes do código","Uso do princípio do ''Iron Law'' para garantir a qualidade","Implementação do ciclo Red-Green-Refactor","Priorização da escrita de testes minimalistas","Uso de testes para validar a funcionalidade do código"],"ru":["Написание тестов перед кодом","Использование принципа ''Iron Law'' для обеспечения качества","Реализация цикла Red-Green-Refactor","Приоритет написания минимальных тестов","Использование тестов для проверки функциональности кода ИИ Агентов"],"ar":["كتابة الاختبارات قبل الكود","استخدام مبدأ ''القانون الحديدي'' لضمان الجودة","تنفيذ دورة التكرار-الأخضر-إعادة الهيكلة","التركيز على كتابة اختبارات صغيرة","استخدام الاختبارات لتحقق من وظيفة الكود لأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use use-tdd","what is use-tdd","use-tdd alternative","use-tdd vs TDD","use-tdd install","use-tdd setup guide","Red-Green-Refactor principle","Iron Law in TDD","test-driven development for AI agents"],"zh":["TDD","测试驱动开发","AI代理","代码质量","开发效率","Red-Green-Refactor","测试用例","生产代码"],"ja":["TDD","テスト駆動開発","AIエージェント","コード品質","開発効率","Red-Green-Refactor","テストケース","プロダクションコード"],"ko":["TDD","테스트 주도 개발","AI 에이전트","코드 품질","개발 효율성","Red-Green-Refactor","테스트 케이스","생산 코드"],"es":["use-tdd","Agentes de Inteligencia Artificial","desarrollo de software","pruebas unitarias","Red-Green-Refactor","principios de desarrollo de software","mejores prácticas de desarrollo"],"fr":["use-tdd","Agents d''Intelligence Artificielle","développement de logiciels","tests unitaires","Red-Green-Refactor","principes de développement de logiciels","bonnes pratiques de développement"],"de":["use-tdd","KI-Agents","Softwareentwicklung","Einheitstests","Red-Green-Refactor","Prinzipien der Softwareentwicklung","Best Practices für die Entwicklung"],"pt":["use-tdd","desenvolvimento dirigido por testes","testes unitários","ciclo Red-Green-Refactor","Iron Law","qualidade de código","desenvolvimento de software"],"ru":["use-tdd","разработка через тестирование","юнит-тесты","цикл Red-Green-Refactor","Iron Law","качество кода","разработка программного обеспечения ИИ Агентов"],"ar":["use-tdd","تطوير مدفوع بالاختبار","اختبارات الوحدة","دورة التكرار-الأخضر-إعادة الهيكلة","القانون الحديدي","جودة الكود","تطوير البرمجيات لأدوات الذكاء الاصطناعي"]}},"owner":"mtthsnc","repo":"autonome","repoPath":"mtthsnc/autonome","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.402Z","topics":[],"category":"community","skillMd":{"name":"use-tdd","description":"Use when implementing any feature or bugfix, before writing implementation code","bodyPreview":"Write the test first. Watch it fail. Write minimal code to pass.\n\n**Core principle:** If you didn''t watch the test fail, you don''t know if it tests the right thing.\n\n# The Iron Law\n\n```\nNO PRODUCTION CODE WITHOUT A FAILING TEST FIRST\n```\n\nWrite code before the test? Delete it. Start over.\n\n**No exceptions:**\n- Don''t keep it as \"reference\"\n- Don''t \"adapt\" it while writing tests\n- Delete means delete\n\n# Red-Green-Refactor\n\n## RED - Write Failing Test\n\nWrite one minimal test showing what should hap","body":"Write the test first. Watch it fail. Write minimal code to pass.\n\n**Core principle:** If you didn''t watch the test fail, you don''t know if it tests the right thing.\n\n# The Iron Law\n\n```\nNO PRODUCTION CODE WITHOUT A FAILING TEST FIRST\n```\n\nWrite code before the test? Delete it. Start over.\n\n**No exceptions:**\n- Don''t keep it as \"reference\"\n- Don''t \"adapt\" it while writing tests\n- Delete means delete\n\n# Red-Green-Refactor\n\n## RED - Write Failing Test\n\nWrite one minimal test showing what should happen.\n\n**Requirements:**\n- One behavior\n- Clear name\n- Real code (no mocks unless unavoidable)\n\n## Verify RED - Watch It Fail\n\n**MANDATORY. Never skip.**\n\n```bash\nnpm test path/to/test.test.ts\n```\n\nConfirm:\n- Test fails (not errors)\n- Failure message is expected\n- Fails because feature missing (not typos)\n\n**Test passes?** You''re testing existing behavior. Fix test.\n\n## GREEN - Minimal Code\n\nWrite simplest code to pass the test.\n\nDon''t add features, refactor other code, or \"improve\" beyond the test.\n\n## Verify GREEN - Watch It Pass\n\n**MANDATORY.**\n\n```bash\nnpm test path/to/test.test.ts\n```\n\nConfirm:\n- Test passes\n- Other tests still pass\n- Output pristine (no errors, warnings)\n\n**Test fails?** Fix code, not test.\n\n## REFACTOR - Clean Up\n\nAfter green only:\n- Remove duplication\n- Improve names\n- Extract helpers\n\nKeep tests green. Don''t add behavior.\n\n# Why Order Matters\n\n**\"I''ll write tests after to verify it works\"**\n\nTests written after code pass immediately. Passing immediately proves nothing:\n- Might test wrong thing\n- Might test implementation, not behavior\n- Might miss edge cases you forgot\n\nTest-first forces you to see the test fail, proving it actually tests something.\n\n**\"I already manually tested all the edge cases\"**\n\nManual testing is ad-hoc:\n- No record of what you tested\n- Can''t re-run when code changes\n- Easy to forget cases under pressure\n\nAutomated tests are systematic and run the same way every time.\n\n**\"Deleting X hours of work is wasteful\"**\n\nSunk cost fallacy. Your choice now:\n- Delete and rewrite with TDD (X more hours, high confidence)\n- Keep it and add tests after (30 min, low confidence, likely bugs)\n\nThe \"waste\" is keeping code you can''t trust.\n\n**\"TDD is dogmatic, being pragmatic means adapting\"**\n\nTDD IS pragmatic:\n- Finds bugs before commit (faster than debugging after)\n- Prevents regressions (tests catch breaks immediately)\n- Documents behavior (tests show how to use code)\n- Enables refactoring (change freely, tests catch breaks)\n\n**\"Tests after achieve the same goals - it''s spirit not ritual\"**\n\nNo. Tests-after answer \"What does this do?\" Tests-first answer \"What should this do?\"\n\nTests-after are biased by your implementation. You test what you built, not what''s required.\n\nTests-first force edge case brainstorm before implementing.\n\n# Common Rationalizations\n\n| Excuse | Reality |\n|--------|---------|\n| \"Too simple to test\" | Simple code breaks. Test takes 30 seconds. |\n| \"I''ll test after\" | Tests passing immediately prove nothing. |\n| \"Tests after achieve same goals\" | Tests-after = \"what does this do?\" Tests-first = \"what should this do?\" |\n| \"Already manually tested\" | Ad-hoc ≠ systematic. No record, can''t re-run. |\n| \"Deleting X hours is wasteful\" | Sunk cost fallacy. Keeping unverified code is technical debt. |\n| \"Keep as reference\" | You''ll adapt it. That''s testing after. Delete means delete. |\n| \"Need to explore first\" | Fine. Throw away exploration, start with TDD. |\n| \"Test hard = design unclear\" | Listen to test. Hard to test = hard to use. |\n\n# Red Flags - STOP\n\n- Code before test\n- Test after implementation\n- Test passes immediately\n- Can''t explain why test failed\n- Tests added \"later\"\n- \"I already manually tested it\"\n- \"Tests after achieve the same purpose\"\n- \"Keep as reference\" or \"adapt existing code\"\n- \"Already spent X hours, deleting is wasteful\"\n\n**All of these mean: Delete code. Start over with TDD.**\n\n# Verification Checklist\n\nBefore marking work complete:\n\n- [ ] Every new function/method has a test\n- [ ] Watched each test fail before implementing\n- [ ] Each test failed for expected reason (feature missing, not typo)\n- [ ] Wrote minimal code to pass each test\n- [ ] All tests pass\n- [ ] Output pristine (no errors, warnings)\n- [ ] Tests use real code (mocks only if unavoidable)\n- [ ] Edge cases and errors covered\n\nCan''t check all boxes? You skipped TDD. Start over.\n\n# Final Rule\n\n```\nProduction code → test exists and failed first\nOtherwise → not TDD\n```\n\nNo exceptions without your human partner''s permission.\n"},"lastSynced":"2026-03-08T02:06:48.812Z","agentAnalysis":{"suitability":{"en":"Perfect for intent-driven AI Agents needing rigorous Test-Driven Development capabilities.","zh":"非常适合需要严格的测试驱动开发能力的意图驱动 AI 代理。","ja":"意図によって動作する AI エージェントが、徹底的なテスト駆動開発機能を必要とする場合に最適です。","ko":"의도에 따라 동작하는 AI 에이전트가 엄격한 테스트 주도 개발 기능을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de IA impulsados por intención que necesitan capacidades de Desarrollo Dirigido por Pruebas rigurosas.","fr":"Parfait pour les agents IA à base d''intention nécessitant des capacités de développement piloté par les tests rigoureuses.","de":"Perfekt für intendenzgetriebene KI-Agents, die strenge Test-Driven Development-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de IA orientados a intenções que necessitam de capacidades rigorosas de Desenvolvimento Dirigido por Testes.","ru":"Идеально подходит для агентов ИИ, ориентированных на намерения, которым требуются строгие возможности разработки, управляемой тестированием.","ar":"مثالي للوكلاء الذكاء الاصطناعي الموجهة بالغرض التي تحتاج إلى قدرات التطوير القائمة على الاختبار الشديدة."},"recommendation":{"en":"Empowers agents to enforce Test-Driven Development principles, ensuring production code is test-driven using the Red-Green-Refactor methodology, strictly following the Iron Law of no production code without a failing test first.","zh":"赋予代理人执行测试驱动开发原则的能力，确保生产代码使用红绿重构方法进行测试驱动开发，严格遵循无测试即无生产代码的铁律。","ja":"エージェントがテスト駆動開発の原則を遵守する能力を提供し、Red-Green-Refactor メソッドologyを使用してテスト駆動開発でプロダクション コードを保証することで、テストなしのプロダクション コードは存在しないという鉄則を厳格に遵守します。","ko":"에이전트가 테스트 주도 개발 원칙을 강제할 수 있는 능력을 부여하여, 프로덕션 코드가 Red-Green-Refactor 방법론을 사용하여 테스트 주도 개발을 보장하고, 테스트 없이 프로덕션 코드는 없다는 철칙을 엄格히 준수합니다.","es":"Habilita a los agentes a hacer cumplir los principios de Desarrollo Dirigido por Pruebas, asegurando que el código de producción sea dirigido por pruebas utilizando la metodología Red-Verde-Reconstruir, siguiendo estrictamente la Ley de Hierro de que no hay código de producción sin una prueba fallida primero.","fr":"Permet aux agents d''appliquer les principes de développement piloté par les tests, en garantissant que le code de production est piloté par les tests en utilisant la méthodologie Rouge-Verte-Réfactorer, en suivant strictement la Loi de Fer selon laquelle il n''y a pas de code de production sans test échoué au préalable.","de":"Ermächtigt Agents, die Grundsätze von Test-Driven Development durchzusetzen, indem sichergestellt wird, dass Produktionscode testgetrieben ist, unter Verwendung der Red-Green-Refactor-Methodik, strikt gemäß dem Eisernen Gesetz, dass es keinen Produktionscode ohne zuerst fehlgeschlagenen Test gibt.","pt":"Habilita os agentes a impor os princípios do Desenvolvimento Dirigido por Testes, garantindo que o código de produção seja orientado por testes usando a metodologia Red-Green-Refactor, seguindo estritamente a Lei de Ferro de que não há código de produção sem um teste com falha primeiro.","ru":"Наделяет агентов возможностью реализовывать принципы разработки, управляемой тестированием, гарантируя, что производственный код проходит тестирование с использованием методологии Red-Green-Refactor, строго следуя Железному Закону о том, что нет производственного кода без сначала провалившегося теста.","ar":"تمكين الوكلاء من فرض مبادئ التطوير القائم على الاختبار، وضمان أن يكون رمز الإنتاج مدفوعًا بالاختبار باستخدام منهجية Red-Green-Refactor، متبعة القانون الحديدي الذي ينص على عدم وجود رمز الإنتاج بدون اختبار فاشل أولاً."},"useCases":{"en":["Writing minimal code to pass tests","Debugging using the Red-Green-Refactor cycle","Ensuring test reliability with the core principle of watching tests fail"],"zh":["编写最小代码以通过测试","使用红绿重构周期进行调试","确保测试可靠性以核心原则为测试失败"],"ja":["テストに合格するための最小限のコードを記述する","Red-Green-Refactorサイクルを使用したデバッグ","テストの信頼性を確保するためのコア原則としてのテストの失敗"],"ko":["테스트를 통과하기 위한 최소한의 코드를 작성","Red-Green-Refactor 주기를 사용한 디버깅","테스트 신뢰성을 보장하기 위한 핵심 원칙으로 테스트 실패 시"],"es":["Escribir código mínimo para aprobar pruebas","Depurar utilizando el ciclo Red-Verde-Reconstruir","Garantizar la confiabilidad de las pruebas con el principio fundamental de ver pruebas fallidas"],"fr":["Écrire un code minimal pour passer les tests","Déboguer en utilisant le cycle Rouge-Verte-Réfactorer","Assurer la fiabilité des tests avec le principe fondamental de voir les tests échouer"],"de":["Minimale Code-Schreibung, um Tests zu bestehen","Fehlerbehebung unter Verwendung des Red-Green-Refactor-Zyklus","Sicherstellung der Testzuverlässigkeit mit dem Grundprinzip, Tests fehlschlagen zu sehen"],"pt":["Escrever código mínimo para passar nos testes","Depurar usando o ciclo Red-Green-Refactor","Garantir a confiabilidade dos testes com o princípio fundamental de assistir à falha dos testes"],"ru":["Написание минимального кода для прохождения тестов","Отладка с использованием цикла Red-Green-Refactor","Обеспечение надежности тестов с основным принципом наблюдения за неудачными тестами"],"ar":["كتابة رمز tối thiểu لتمرير الاختبارات","تصحيح الأخطاء باستخدام دورة Red-Green-Refactor","ضمان موثوقية الاختبارات مع المبدأ الأساسي لمشاهدة فشل الاختبارات"]},"limitations":{"en":["Requires strict adherence to the Iron Law","No exceptions for production code without prior failing tests","Deletes code not following Test-Driven Development principles"],"zh":["需要严格遵循铁律","没有先行失败测试的生产代码不允许例外","不遵循测试驱动开发原则的代码将被删除"],"ja":["鉄則を厳格に遵守する必要がある","事前に失敗したテストがないプロダクション コードは例外なく許可されない","テスト駆動開発の原則に従わないコードは削除される"],"ko":["鐵則을 엄격히 준수해야 함","先에 실패한 테스트 없이 프로덕션 코드는 예외 없이 허용되지 않음","테스트 주도 개발 원칙을 따르지 않는 코드는 삭제됨"],"es":["Requiere una adherencia estricta a la Ley de Hierro","No hay excepciones para el código de producción sin pruebas fallidas previas","Elimina el código que no sigue los principios de Desarrollo Dirigido por Pruebas"],"fr":["Nécessite une adhésion stricte à la Loi de Fer","Pas d''exceptions pour le code de production sans tests échoués préalables","Supprime le code qui ne suit pas les principes de développement piloté par les tests"],"de":["Erfordert eine strikte Einhaltung des Eisernen Gesetzes","Keine Ausnahmen für Produktionscode ohne vorherige fehlgeschlagene Tests","Löscht Code, der den Grundsätzen von Test-Driven Development nicht folgt"],"pt":["Exige adesão estrita à Lei de Ferro","Não há exceções para o código de produção sem testes com falha anteriores","Exclui código que não segue os princípios do Desenvolvimento Dirigido por Testes"],"ru":["Требует строгого соблюдения Железного Закона","Нет исключений для производственного кода без предварительно провалившихся тестов","Удаляет код, не соответствующий принципам разработки, управляемой тестированием"],"ar":["يتطلب اتباعًا صارمًا للقانون الحديدي","لا استثناءات للرمز الإنتاجي بدون اختبارات فاشلة مسبقًا","حذف الرمز الذي لا يتبع مبادئ التطوير القائم على الاختبار"]},"version":4},"contentHash":"e17cc5b01fc1621ace0ab30d29e0306e1ce743d0dfe3fa1a7dc02306a7fcdc56","qualityScore":33}');
