INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mtthsnc/autonome/use-tdd', 'use-tdd', 'mtthsnc', 'autonome', 'community', 'use-tdd mtthsnc autonome community use-tdd is a skill for intent-driven AI agents that enforces Test-Driven Development principles. It benefits developers by ensuring production code is test-driven, following the core principle of writing minimal code to pass tests. 使用TDD开发AI代理，通过测试驱动开发提高代码质量和开发效率 TDDを使用してAIエージェントの開発を改善し、コードの品質と開発効率を向上させる TDD를 사용하여 AI 에이전트 개발을 개선하고 코드 품질 및 개발 효율성을 향상합니다 use-tdd es una habilidad para Agentes de Inteligencia Artificial que sigue el principio de escribir la prueba antes de escribir el código use-tdd est une compétence pour les Agents d''Intelligence Artificielle qui suit le principe d''écrire la test avant d''écrire le code use-tdd ist eine Fähigkeit für KI-Agents, die dem Prinzip folgt, den Test vor dem Code zu schreiben use-tdd é uma abordagem de desenvolvimento que prioriza a escrita de testes antes do código, garantindo uma base sólida para o desenvolvimento de software use-tdd - это подход к разработке, который отдает приоритет написанию тестов перед кодом, обеспечивая прочную основу для разработки программного обеспечения ИИ Агентов use-tdd هو نهج في التطوير ي ưu tiên كتابة الاختبارات قبل الكود، đảm_secure قاعدة صلبة لتطوير البرمجيات لأدوات الذكاء الاصطناعي how to use use-tdd what is use-tdd use-tdd alternative use-tdd vs TDD use-tdd install use-tdd setup guide Red-Green-Refactor principle Iron Law in TDD test-driven development for AI agents TDD 测试驱动开发 AI代理 代码质量 开发效率 Red-Green-Refactor 测试用例 生产代码 Enforces the Iron Law: NO PRODUCTION CODE WITHOUT A FAILING TEST FIRST Implements Red-Green-Refactor cycle for efficient coding Writes minimal code to pass tests, ensuring test-driven development Deletes existing code if not written with a failing test first, promoting a clean start Follows a strict principle of not keeping or adapting existing code as reference use-tdd is a Test-Driven Development skill that adheres to the Iron Law, requiring a failing test before writing production code, and follows the Red-Green-Refactor cycle.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('privatenumber/lintroll/lintroll', 'community', 'privatenumber', 'lintroll', 'privatenumber/lintroll', 'lintroll', 0, 0, 33, '2026-03-08T01:57:15.404Z', '2026-03-08T02:06:51.321Z', '123802e2bd2cca63523489fa485de51a11b767021ce60f7950f846ce3567f92f', '{"id":"privatenumber/lintroll/lintroll","name":"lintroll","description":{"en":"lintroll is a comprehensive code linter for TypeScript, Vue, React, JSON, YAML, and Markdown, offering auto-fix and caching capabilities. It benefits developers working on multi-technology projects.","zh":"Lintroll是一个代码检查工具，支持TypeScript、Vue、React、JSON、YAML和Markdown","ja":"Lintrollは、TypeScript、Vue、React、JSON、YAML、Markdownをサポートするコードリントツールです","ko":"Lintroll은 TypeScript, Vue, React, JSON, YAML, Markdown을 지원하는 코드 검사 도구입니다","es":"Lintroll es un linter de código que incluye ESLint con 12+ plugins para TypeScript, Vue, React, JSON, YAML y Markdown","fr":"Lintroll est un linter de code qui inclut ESLint avec 12+ plugins pour TypeScript, Vue, React, JSON, YAML et Markdown","de":"Lintroll ist ein Code-Linter, der ESLint mit 12+ Plugins für TypeScript, Vue, React, JSON, YAML und Markdown enthält","pt":"O Lintroll é uma ferramenta de análise de código que inclui 12+ plugins para linguagens como TypeScript, Vue e React.","ru":"Lintroll — это инструмент анализа кода, включающий 12+ плагинов для языков seperti TypeScript, Vue и React.","ar":"Lintroll هو أداة تحليل الشفرة التي تتضمن أكثر من 12 مكون إضافي للغات مثل TypeScript و Vue و React"},"seo":{"title":{"en":"lintroll: Setup Guide for TypeScript and React Developmen...","zh":"Lintroll_setup_guide：TypeScript、Vue和React代码检查","ja":"Lintrollのセットアップガイド：TypeScript、Vue、Reactのコードリント","ko":"Lintroll 설정 가이드: TypeScript, Vue, React 코드 검사","es":"Lintroll: Guía de configuración para ESLint con TypeScrip...","fr":"Lintroll: Guide de mise en place pour ESLint avec TypeScr...","de":"Lintroll: Einrichtungsleitfaden für ESLint mit TypeScript...","pt":"Guia de Configuração do Lintroll: Ferramenta de Análise d...","ru":"Настройка Lintroll: Инструмент анализа кода для разработч...","ar":"دليل إعداد Lintroll: أداة تحليل الشفرة لمطوري الإدوات الذكية"},"description":{"en":"Unlock efficient code linting with lintroll. Discover how to integrate this batteries-included ESLint solution into your TypeScript and React projects today!","zh":"使用Lintroll优化代码质量，支持TypeScript、Vue、React、JSON、YAML和Markdown","ja":"Lintrollを使用してコード品質を高める：TypeScript、Vue、React、JSON、YAML、Markdown対応","ko":"Lintroll을 사용하여 코드 품질을 높이기: TypeScript, Vue, React, JSON, YAML, Markdown 지원","es":"Descubre cómo utilizar Lintroll para mejorar la calidad de tu código con ESLint y 12+ plugins para TypeScript, Vue, React y más","fr":"Découvrez comment utiliser Lintroll pour améliorer la qualité de votre code avec ESLint et 12+ plugins pour TypeScript, Vue, React et plus","de":"Erfahren Sie, wie Sie Lintroll verwenden können, um die Qualität Ihres Codes mit ESLint und 12+ Plugins für TypeScript, Vue, React und mehr zu verbessern","pt":"Descubra como o Lintroll pode ajudar a melhorar a qualidade do seu código com 12+ plugins para TypeScript, Vue, React e mais","ru":"Узнайте, как Lintroll может помочь улучшить качество вашего кода с 12+ плагинами для TypeScript, Vue, React и др.","ar":"اكتشف كيف يمكن لـ Lintroll مساعدتك على تحسين جودة شفرتك مع أكثر من 12 مكون إضافي لTypeScript و Vue و React وغيرها"},"definition":{"en":"lintroll is a batteries-included ESLint solution with 12+ plugins for various file formats and frameworks, including TypeScript, Vue, and React.","zh":"Lintroll是一种代码检查工具，用于识别和修复代码中的错误和不规则","ja":"Lintrollは、コード内のエラーと不規則を識別して修正するコードリントツールです","ko":"Lintroll은 코드 내의 오류와 비규칙을 식별하여 수정하는 코드 검사 도구입니다","es":"Lintroll es una herramienta de linter de código que utiliza ESLint con plugins adicionales para mejorar la calidad del código","fr":"Lintroll est un outil de linter de code qui utilise ESLint avec des plugins supplémentaires pour améliorer la qualité du code","de":"Lintroll ist ein Code-Linter-Tool, das ESLint mit zusätzlichen Plugins verwendet, um die Code-Qualität zu verbessern","pt":"O Lintroll é uma ferramenta de análise de código que ajuda a detectar erros e melhorar a qualidade do código.","ru":"Lintroll — это инструмент анализа кода, помогающий обнаруживать ошибки и улучшать качество кода.","ar":"Lintroll هو أداة تحليل الشفرة التي تساعد على اكتشاف الأخطاء وتحسين جودة الشفرة"},"features":{"en":["Supports TypeScript, Vue, React, JSON, YAML, and Markdown linting","Offers auto-fix capabilities with the --fix command","Includes caching for improved performance with the --cache option","Allows linting of only git-tracked files with the --git flag","Enables pre-commit hook functionality with the --staged option","Supports Node.js integration with the --node flag"],"zh":["支持TypeScript、Vue、React、JSON、YAML和Markdown","12+个插件可用","命令行界面（CLI）","自动修复功能","缓存支持","Git集成"],"ja":["TypeScript、Vue、React、JSON、YAML、Markdownをサポート","12+のプラグインを使用可能","コマンドラインインターフェース（CLI）","自動修正機能","キャッシュ対応","Git統合"],"ko":["TypeScript, Vue, React, JSON, YAML, Markdown 지원","12+개의 플러그인 사용 가능","명령줄 인터페이스（CLI）","자동 수정 기능","캐시 지원","Git 통합"],"es":["Soporte para TypeScript, Vue, React, JSON, YAML y Markdown","Incluye 12+ plugins para mejorar la calidad del código","Opción de autoreparación de errores con --fix","Compatibilidad con caché para mejorar el rendimiento","Opción de solo analizar archivos de Git con --git","Compatibilidad con hooks de precompilación con --staged"],"fr":["Prise en charge de TypeScript, Vue, React, JSON, YAML et Markdown","Inclut 12+ plugins pour améliorer la qualité du code","Option de correction automatique des erreurs avec --fix","Compatibilité avec le cache pour améliorer les performances","Option d''analyse uniquement des fichiers Git avec --git","Compatibilité avec les hooks de précompilation avec --staged"],"de":["Unterstützung für TypeScript, Vue, React, JSON, YAML und Markdown","Enthält 12+ Plugins, um die Code-Qualität zu verbessern","Option zur automatischen Fehlerkorrektur mit --fix","Kompatibilität mit Cache für bessere Leistung","Option, nur Git-Dateien mit --git zu analysieren","Kompatibilität mit Pre-Commit-Hooks mit --staged"],"pt":["Suporte a 12+ plugins para linguagens como TypeScript, Vue e React","Análise de código com opção de correção automática","Compatibilidade com CLI para execução de comandos","Suporte a caching para melhorar a performance","Integração com Git para análise de arquivos trackeados"],"ru":["Поддержка 12+ плагинов для языков seperti TypeScript, Vue и React","Анализ кода с возможностью автоматической исправления","Совместимость с CLI для выполнения команд","Поддержка кэширования для улучшения производительности","Интеграция с Git для анализа отслеживаемых файлов"],"ar":["دعم أكثر من 12 مكون إضافي للغات مثل TypeScript و Vue و React","تحليل الشفرة مع خيار التصحيح التلقائي","توافق مع CLI لتشغيل الأوامر","دعم التخزين المؤقت لتحسين الأداء","تكامل مع Git لتحليل الملفات المتابعة"]},"keywords":{"en":["how to use lintroll","lintroll setup guide","lintroll vs eslint","lintroll install","what is lintroll","lintroll alternative","typescript linting tools","react code linting","eslint plugins for vue"],"zh":["代码检查工具","TypeScript代码检查","Vue代码检查","React代码检查","JSON代码检查","YAML代码检查","Markdown代码检查","代码优化","代码质量"],"ja":["コードリントツール","TypeScriptコードリント","Vueコードリント","Reactコードリント","JSONコードリント","YAMLコードリント","Markdownコードリント","コード最適化","コード品質"],"ko":["코드 검사 도구","TypeScript 코드 검사","Vue 코드 검사","React 코드 검사","JSON 코드 검사","YAML 코드 검사","Markdown 코드 검사","코드 최적화","코드 품질"],"es":["lintroll","ESLint","TypeScript","Vue","React","JSON","YAML","Markdown","herramientas de desarrollo","mejora de código","análisis de código"],"fr":["lintroll","ESLint","TypeScript","Vue","React","JSON","YAML","Markdown","outils de développement","amélioration de code","analyse de code"],"de":["lintroll","ESLint","TypeScript","Vue","React","JSON","YAML","Markdown","Entwicklertools","Code-Optimierung","Code-Analyse"],"pt":["Lintroll","análise de código","desenvolvimento de software","TypeScript","Vue","React","ferramentas de desenvolvimento","otimização de código","qualidade de código"],"ru":["Lintroll","анализ кода","разработка программного обеспечения","TypeScript","Vue","React","инструменты разработки","оптимизация кода","качество кода","ИИ Агенты"],"ar":["Lintroll","تحليل الشفرة","تطوير البرمجيات","TypeScript","Vue","React","أدوات التطوير","تحسين الشفرة","جودة الشفرة","أدوات ذكية"]}},"owner":"privatenumber","repo":"lintroll","repoPath":"privatenumber/lintroll","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.404Z","topics":[],"category":"community","skillMd":{"name":"lintroll","description":"Opinionated ESLint configuration and CLI for TypeScript, Vue, React, JSON, YAML, and Markdown. Use when linting code, fixing style issues, or configuring ESLint in projects using lintroll.","bodyPreview":"# Lintroll\n\nBatteries-included ESLint with 12+ plugins for TypeScript, Vue, React, JSON, YAML, and Markdown.\n\n## CLI\n\n```bash\nlintroll .                          # Lint directory\nlintroll . --fix                    # Auto-fix\nlintroll . --fix --cache            # Fix with caching\nlintroll --git .                    # Only git-tracked files\nlintroll --git --fix .              # Fix only tracked files\nlintroll --staged --fix             # Pre-commit hook\nlintroll . --node                   # Enabl","body":"# Lintroll\n\nBatteries-included ESLint with 12+ plugins for TypeScript, Vue, React, JSON, YAML, and Markdown.\n\n## CLI\n\n```bash\nlintroll .                          # Lint directory\nlintroll . --fix                    # Auto-fix\nlintroll . --fix --cache            # Fix with caching\nlintroll --git .                    # Only git-tracked files\nlintroll --git --fix .              # Fix only tracked files\nlintroll --staged --fix             # Pre-commit hook\nlintroll . --node                   # Enable Node.js rules\nlintroll . --node=./scripts         # Node.js rules for specific paths\nlintroll . --quiet                  # Errors only (no warnings)\nlintroll . --allow-abbreviation db  # Allow specific abbreviations\n```\n\n## Style Rules\n\n| Rule | Enforced style |\n|------|---------------|\n| Indentation | Tabs |\n| Quotes | Single |\n| Semicolons | Always |\n| Line length | 100 chars max |\n| Trailing commas | Multiline only |\n| Functions | Arrow (except `this`/`arguments`/generators/hoisting) |\n| Types | `type =` over `interface` |\n| Type imports | Separate `import type` from value imports |\n| No `any` | Use `unknown` and narrow |\n| Unused vars | Prefix with `_` (e.g. `_unused`) |\n| No abbreviations | `db` → `database`, `env` → `environment`, `pkg` → `packageJson` |\n| Import extensions | `.js` not `.ts` (unless `allowImportingTsExtensions: true`) |\n| React filenames | PascalCase (`UserProfile.tsx`) |\n\n### Abbreviation Mapping\n\nCommon renames enforced by `unicorn/prevent-abbreviations`:\n\n| Abbreviation | Full name |\n|-------------|-----------|\n| `args` | `arguments_` (reserved word) |\n| `db` | `database` |\n| `env` | `environment` |\n| `pkg` | `packageJson` |\n| `temp` | `temporary` |\n| `res` | `response` |\n| `req` | `request` |\n| `dir` | `directory` |\n| `err` | `error` |\n| `msg` | `message` |\n\nLoop indices `i`, `j` are always allowed. Add more with `--allow-abbreviation`.\n\n## ESLint Config\n\nZero-config:\n\n```js\n// eslint.config.js\nexport { default } from ''lintroll''\n```\n\nCustom:\n\n```js\n// eslint.config.ts\nimport { defineConfig, pvtnbr } from ''lintroll''\n\nexport default defineConfig([\n    { ignores: [''tests/fixtures/**/*''] },\n    ...pvtnbr({\n        node: true,\n        allowAbbreviations: {\n            exactWords: [''i'', ''j''],\n            substrings: [''db'', ''env'']\n        }\n    })\n])\n```\n\nFor full API types, see `node_modules/lintroll/dist/index.d.mts`.\n\n## Auto-Detection\n\n| Feature | Detection |\n|---------|-----------|\n| Vue.js | `*.vue` files present — rules apply automatically |\n| TypeScript | `tsconfig.json` present |\n| Node.js | `.cjs`, `.mts`, `scripts/**`, `bin` entries |\n\n## Ignored by Default\n\n- `node_modules/**`, `dist/**`, `vendor/**`\n- `package-lock.json`, `pnpm-lock.yaml`\n- `*.min.js`, `.vitepress`\n- AI assistant files: `CLAUDE.md`, `.claude/`, `copilot.json`, `.cursorrules`\n\n## JSON/YAML\n\n- package.json keys auto-sorted: `name → version → description → ... → scripts → dependencies → devDependencies`\n- JSON style: tabs, trailing commas, spaces around braces `{ \"key\": \"value\" }`\n\n## Gotchas\n\n- **Abbreviation rules disabled in `.d.ts`** — declaration files follow standard conventions\n- **`.ts` extensions in imports** — use `.js` unless tsconfig has `allowImportingTsExtensions: true`\n- **Markdown code blocks in `skills/` directories** — automatically ignored (not linted as project code)\n"},"lastSynced":"2026-03-08T02:06:51.321Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing comprehensive linting capabilities for TypeScript, Vue, React, JSON, YAML, and Markdown.","zh":"适用于需要对TypeScript、Vue、React、JSON、YAML和Markdown进行全面linting的代码审查代理。","ja":"TypeScript、Vue、React、JSON、YAML、Markdownに対する包括的なlinting機能を必要とするコードレビュー代理に最適です。","ko":"TypeScript, Vue, React, JSON, YAML 및 Markdown에 대한 종합적인 린팅 기능을 필요로 하는 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para Agentes de Revisión de Código que necesitan capacidades de linting comprehensivas para TypeScript, Vue, React, JSON, YAML y Markdown.","fr":"Idéal pour les Agents de Revue de Code nécessitant des capacités de linting complètes pour TypeScript, Vue, React, JSON, YAML et Markdown.","de":"Ideal für Code-Review-Agenten, die umfassende Linting-Funktionen für TypeScript, Vue, React, JSON, YAML und Markdown benötigen.","pt":"Ideal para Agentes de Revisão de Código que necessitam de capacidades de linting abrangentes para TypeScript, Vue, React, JSON, YAML e Markdown.","ru":"Идеально для агентов проверки кода, которые требуют всесторонних возможностей линтинга для TypeScript, Vue, React, JSON, YAML и Markdown.","ar":"مثالي لعمليات المراجعة البرمجية التي تحتاج إلى قدرات لينتينج شاملة لTypeScript و Vue و React و JSON و YAML و Markdown."},"recommendation":{"en":"Empowers agents to enforce coding standards across multiple technologies with auto-fix and caching capabilities using ESLint and 12+ plugins, supporting formats like JSON and YAML, and frameworks such as React and Vue.","zh":"赋予代理在多种技术中强制执行编码标准的能力，具有自动修复和缓存功能，使用ESLint和12+插件，支持JSON和YAML等格式，以及React和Vue等框架。","ja":"ESLintと12以上のプラグインを使用して、自動修復とキャッシュ機能を備え、JSONやYAMLなどの形式やReactとVueなどのフレームワークをサポートし、複数のテクノロジーでコーディング規範を強制する代理の能力を提供します。","ko":"ESLint와 12개 이상의 플러그인을 사용하여 자동 수정 및 캐싱 기능을 제공하며 JSON 및 YAML과 같은 형식과 React 및 Vue와 같은 프레임워크를 지원하여 다중 기술에서 코딩 표준을 강제 적용할 수 있는 에이전트의 능력을 제공합니다.","es":"Habilita a los agentes a aplicar estándares de codificación en varias tecnologías con capacidades de auto-corrección y caché utilizando ESLint y más de 12 plugins, que admiten formatos como JSON y YAML, y frameworks como React y Vue.","fr":"Permet aux agents d''appliquer des normes de codage à plusieurs technologies avec des capacités d''auto-correction et de mise en cache utilisant ESLint et plus de 12 plugins, prenant en charge des formats tels que JSON et YAML, et des frameworks tels que React et Vue.","de":"Ermächtigt Agenten, Coding-Standards über mehrere Technologien hinweg mit Auto-Fix- und Cachefunktionen unter Verwendung von ESLint und mehr als 12 Plugins durchzusetzen, die Formate wie JSON und YAML sowie Frameworks wie React und Vue unterstützen.","pt":"Habilita os agentes a impor padrões de codificação em várias tecnologias com capacidades de auto-correção e cache utilizando ESLint e 12+ plugins, suportando formatos como JSON e YAML, e estruturas como React e Vue.","ru":"Наделяет агентов возможностью обеспечивать соблюдение стандартов кодирования в нескольких технологиях с помощью функций автоматического исправления и кэширования, используя ESLint и 12+ плагинов, поддерживающих форматы, такие как JSON и YAML, и фреймворки, такие как React и Vue.","ar":"تمكّن الوكلاء من فرض معايير البرمجة عبر تقنيات متعددة باستخدام إمكانيات الإصلاح التلقائي والแคش باستخدام ESLint و 12+ من الإضافات، ودعم صيغ مثل JSON و YAML، والاطارات مثل React و Vue."},"useCases":{"en":["Linting multi-technology project directories","Auto-fixing errors in TypeScript and JavaScript files","Caching linting results for improved performance","Integrating linting into git workflows for pre-commit hooks"],"zh":["linting多技术项目目录","自动修复TypeScript和JavaScript文件中的错误","缓存linting结果以提高性能","将linting集成到git工作流中以进行预提交钩子"],"ja":["複数のテクノロジーでプロジェクトディレクトリをlintingする","TypeScriptとJavaScriptのファイル内のエラーを自動修復する","パフォーマンスの向上のためにlinting結果をキャッシュする","Gitワークフローにlintingを統合してプレコミットフックを実行する"],"ko":["다중 기술 프로젝트 디렉토리를 린팅하는 것","TypeScript 및 JavaScript 파일의 오류를 자동으로 수정하는 것","성능 향상을 위해 린팅 결과를 캐싱하는 것","프리 커밋 후크를 위해 린팅을 깃 워크플로에 통합하는 것"],"es":["Linting de directorios de proyectos multi-tecnología","Auto-corrección de errores en archivos TypeScript y JavaScript","Almacenamiento en caché de resultados de linting para mejorar el rendimiento","Integración de linting en flujos de trabajo de git para ganchos de pre-compromiso"],"fr":["Linting de répertoires de projets multi-technologies","Auto-correction d''erreurs dans les fichiers TypeScript et JavaScript","Mise en cache des résultats de linting pour améliorer les performances","Intégration de linting dans les flux de travail git pour les hooks de pré-commit"],"de":["Linting von Projektverzeichnissen mit mehreren Technologien","Auto-Korrektur von Fehlern in TypeScript- und JavaScript-Dateien","Zwischenspeicherung von Linting-Ergebnissen zur Leistungsverbesserung","Integration von Linting in Git-Workflows für Pre-Commit-Hooks"],"pt":["Linting de diretórios de projetos multi-tecnologia","Auto-correção de erros em arquivos TypeScript e JavaScript","Cache de resultados de linting para melhor desempenho","Integração do linting em fluxos de trabalho git para ganchos de pré-compromisso"],"ru":["Линтинг директорий проектов с несколькими технологиями","Автоматическое исправление ошибок в файлах TypeScript и JavaScript","Кэширование результатов линтинга для улучшения производительности","Интеграция линтинга в рабочие процессы git для хуков предкоммита"],"ar":["لينتينج لمشاريع الدلائل متعددة التكنولوجيا","الإصلاح التلقائي للأخطاء في ملفات TypeScript و JavaScript","แคช للنتائج لينتينج لتحسين الأداء","إدماج لينتينج في سلاسل العمل git ل Ganchoes pre-commit"]},"limitations":{"en":["Requires ESLint compatibility","Limited to supported file formats and frameworks"],"zh":["需要ESLint兼容性","仅限支持的文件格式和框架"],"ja":["ESLintの互換性が必要","サポートされているファイル形式とフレームワークのみ"],"ko":["ESLint 호환성이 필요함","지원되는 파일 형식 및 프레임워크만 해당"],"es":["Requiere compatibilidad con ESLint","Limitado a formatos de archivo y frameworks compatibles"],"fr":["Nécessite la compatibilité avec ESLint","Limité aux formats de fichiers et aux frameworks pris en charge"],"de":["Benötigt ESLint-Kompatibilität","Begrenzt auf unterstützte Dateiformate und Frameworks"],"pt":["Requer compatibilidade com ESLint","Limitado a formatos de arquivo e estruturas suportados"],"ru":["Требует совместимости с ESLint","Ограничен поддерживаемыми форматами файлов и фреймворками"],"ar":["يتطلب توافقًا مع ESLint","محدود بالتنسيقات والاطارات المدعومة للملفات"]},"version":4},"contentHash":"123802e2bd2cca63523489fa485de51a11b767021ce60f7950f846ce3567f92f","qualityScore":33}');
