INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('privatenumber/lintroll/lintroll', 'lintroll', 'privatenumber', 'lintroll', 'community', 'lintroll privatenumber lintroll community lintroll is a comprehensive code linter for TypeScript, Vue, React, JSON, YAML, and Markdown, offering auto-fix and caching capabilities. It benefits developers working on multi-technology projects. Lintroll是一个代码检查工具，支持TypeScript、Vue、React、JSON、YAML和Markdown Lintrollは、TypeScript、Vue、React、JSON、YAML、Markdownをサポートするコードリントツールです Lintroll은 TypeScript, Vue, React, JSON, YAML, Markdown을 지원하는 코드 검사 도구입니다 Lintroll es un linter de código que incluye ESLint con 12+ plugins para TypeScript, Vue, React, JSON, YAML y Markdown Lintroll est un linter de code qui inclut ESLint avec 12+ plugins pour TypeScript, Vue, React, JSON, YAML et Markdown Lintroll ist ein Code-Linter, der ESLint mit 12+ Plugins für TypeScript, Vue, React, JSON, YAML und Markdown enthält O Lintroll é uma ferramenta de análise de código que inclui 12+ plugins para linguagens como TypeScript, Vue e React. Lintroll — это инструмент анализа кода, включающий 12+ плагинов для языков seperti TypeScript, Vue и React. Lintroll هو أداة تحليل الشفرة التي تتضمن أكثر من 12 مكون إضافي للغات مثل TypeScript و Vue و React how to use lintroll lintroll setup guide lintroll vs eslint lintroll install what is lintroll lintroll alternative typescript linting tools react code linting eslint plugins for vue 代码检查工具 TypeScript代码检查 Vue代码检查 React代码检查 JSON代码检查 YAML代码检查 Markdown代码检查 代码优化 代码质量 Supports TypeScript, Vue, React, JSON, YAML, and Markdown linting Offers auto-fix capabilities with the --fix command Includes caching for improved performance with the --cache option Allows linting of only git-tracked files with the --git flag Enables pre-commit hook functionality with the --staged option Supports Node.js integration with the --node flag lintroll is a batteries-included ESLint solution with 12+ plugins for various file formats and frameworks, including TypeScript, Vue, and React.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('umatoma/claude-example/sdd-plan', 'community', 'umatoma', 'claude-example', 'umatoma/claude-example', 'sdd-plan', 0, 0, 33, '2026-03-08T01:57:15.407Z', '2026-03-08T02:06:57.166Z', '0fff44c1c060325ffb13d8d064fa436920104bc20b879b59eb26f28bc448ccf9', '{"id":"umatoma/claude-example/sdd-plan","name":"sdd-plan","description":{"en":"The sdd-plan skill generates an implementation plan based on a specification document, benefiting developers working with SDD. It automates the planning process, ensuring consistency and accuracy.","zh":"SDD 计划是实现高效的仕様駆動開発的关键步骤，涉及创建实装计划和验证条件","ja":"SDD Plan は効率的な仕様駆動開発を実現するための重要なステップであり、実装計画の作成と条件の検証を含む","ko":"SDD 계획은 효율적인仕様駆動개발을 실현하는 중요한 단계로, 구현 계획의 생성과 조건의 검증을 포함","es":"SDD Plan es una herramienta de implementación de especificaciones que utiliza el framework de 仕様駆動開発 (SDD). Permite a los desarrolladores crear planes de implementación precisos","fr":"SDD Plan est un outil de mise en œuvre de spécifications qui utilise le framework de 仕様駆動開発 (SDD). Il permet aux développeurs de créer des plans de mise en œuvre précis","de":"SDD Plan ist ein Tool für die Implementierung von Spezifikationen, das den Framework von 仕様駆動開発 (SDD) verwendet. Es ermöglicht Entwicklern, präzise Implementierungspläne zu erstellen","pt":"O sdd-plan é uma ferramenta de desenvolvimento que permite criar planos de implementação com base em especificações. Ele automatiza o processo de verificação do gate 1","ru":"sdd-plan - это инструмент разработки, который позволяет создавать планы реализации на основе спецификаций. Он автоматизирует процесс проверки gate 1 для ИИ Агентов","ar":"sdd-plan هو أداة تطوير تمكنك من إنشاء خطط تنفيذ بناءً على المواصفات. يؤتم过程 التحقق من بوابة 1"},"seo":{"title":{"en":"sdd-plan: Implementation Planning for SDD | AI Agent Skill","zh":"SDD 计划设置指南 - AIエージェント","ja":"SDD Plan セットアップガイド - AIエージェント","ko":"SDD 계획 설정 가이드 - AI 에이전트","es":"Guía de configuración de SDD Plan: Implementación de espe...","fr":"Guide de configuration de SDD Plan : Mise en œuvre de spé...","de":"SDD-Plan-Konfigurationsleitfaden: Umsetzung von Spezifika...","pt":"Guia de Configuração do sdd-plan: Implemente com Eficiência","ru":"Настройка sdd-plan: Лучшие Практики для ИИ Агентов","ar":"دليل الإعداد ل sdd-plan: تحقيق التخطيط الفعال"},"description":{"en":"Discover how to create an implementation plan based on your SDD specification with the sdd-plan skill. Learn more and get started today!","zh":"了解 SDD 计划的设置步骤和最佳实践，实现高效的仕様駆動開発","ja":"SDD Plan の設定手順とベストプラクティスを学び、効率的な仕様駆動開発を実現","ko":"SDD 계획 설정 단계와 최선의 방법을 배우고 효율적인仕様駆動開発을 실현","es":"Aprende a configurar SDD Plan, una herramienta de AI Agent para implementar especificaciones con precisión. Descubre cómo funciona y benefíciate de su potencial","fr":"Découvrez comment configurer SDD Plan, un outil d''agent IA pour mettre en œuvre des spécifications avec précision. Comprenez son fonctionnement et tirez part...","de":"Erfahren Sie, wie Sie SDD Plan konfigurieren, ein AI-Tool für die Implementierung von Spezifikationen mit Präzision. Entdecken Sie seine Funktionsweise und n...","pt":"Aprenda a configurar o sdd-plan para implementação eficaz baseada em especificações. Descubra como otimizar seu fluxo de trabalho com essa ferramenta de dese...","ru":"Узнайте, как настроить sdd-plan для эффективной реализации на основе спецификаций. Откройте для себя, как оптимизировать свой рабочий процесс с помощью этого...","ar":"تعرف على كيفية إعداد sdd-plan لتنفيذ فعال بناءً على المواصفات. اكتشف كيفية تحسين تدفق العمل الخاص بك باستخدام أداة التطوير هذه"},"definition":{"en":"sdd-plan is a skill that creates an implementation plan from a specification document, following the principles of Specification-Driven Development (SDD).","zh":"SDD 计划是指根据仕様書创建实装计划的过程","ja":"SDD Plan は仕様書に基づいて実装計画を作成するプロセス","ko":"SDD 계획은仕様서에 따라 구현 계획을 생성하는 프로세스","es":"SDD Plan es una herramienta de AI Agent que implementa especificaciones utilizando el framework de 仕様駆動開発 (SDD)","fr":"SDD Plan est un outil d''agent IA qui met en œuvre des spécifications en utilisant le framework de 仕様駆動開発 (SDD)","de":"SDD Plan ist ein AI-Tool, das Spezifikationen mithilfe des Frameworks von 仕様駆動開発 (SDD) implementiert","pt":"O sdd-plan é uma ferramenta de desenvolvimento que cria planos de implementação com base em especificações","ru":"sdd-plan - это инструмент разработки, создающий планы реализации на основе спецификаций","ar":"sdd-plan هو أداة تطوير لإنشاء خطط تنفيذ بناءً على المواصفات"},"features":{"en":["Loads SDD principles and phase gates using the sdd-principles skill","Identifies target specification files in the .steering/ directory","Reads Part 1 of the specification document for planning","Verifies Gate 1 conditions, including the absence of [NEEDS CLARIFICATION] markers","Supports file name specification via $ARGUMENTS or automatic detection of the latest file"],"zh":["创建实装计划","验证条件","支持 `/sdd-specify` 仕様書","自动检测 `.steering/` 目录中的最新文件","集成 `sdd-principles` 技术"],"ja":["実装計画の作成","条件の検証"," `/sdd-specify` 仕様書のサポート"," `.steering/` ディレクトリ内の最新ファイルの自動検出"," `sdd-principles` 技術の統合"],"ko":["구현 계획의 생성","조건의 검증"," `/sdd-specify`仕様서 지원"," `.steering/` 디렉토리 내의 최신 파일 자동 감지"," `sdd-principles` 기술 통합"],"es":["Implementación de especificaciones con precisión","Utiliza el framework de 仕様駆動開発 (SDD)","Crea planes de implementación precisos","Verificación de condiciones de fase","Compatibilidad con `$ARGUMENTS` para especificar archivos","Soporte para `.steering/` directorios"],"fr":["Mise en œuvre de spécifications avec précision","Utilise le framework de 仕様駆動開発 (SDD)","Crée des plans de mise en œuvre précis","Vérification des conditions de phase","Compatibilité avec `$ARGUMENTS` pour spécifier des fichiers","Prise en charge des répertoires `.steering/`"],"de":["Implementierung von Spezifikationen mit Präzision","Verwendet den Framework von 仕様駆動開発 (SDD)","Erstellt präzise Implementierungspläne","Überprüfung von Phasenbedingungen","Kompatibilität mit `$ARGUMENTS` zur Angabe von Dateien","Unterstützung für `.steering/`-Verzeichnisse"],"pt":["Criação de planos de implementação baseados em especificações","Verificação automática do gate 1","Integração com o skill sdd-principles","Leitura de especificações do diretório .steering/","Suporte à seleção de arquivos de especificação via $ARGUMENTS"],"ru":["Создание планов реализации на основе спецификаций","Автоматическая проверка gate 1","Интеграция с навыком sdd-principles","Чтение спецификаций из директории .steering/","Поддержка выбора файлов спецификации через $ARGUMENTS для ИИ Агентов"],"ar":["إنشاء خطط تنفيذ بناءً على المواصفات","التحقق التلقائي من بوابة 1","التكامل مع مهارة sdd-principles","قراءة المواصفات من الدليل .steering/","دعم اختيار ملفات المواصفات عبر $ARGUMENTS"]},"keywords":{"en":["how to use sdd-plan","sdd-plan setup guide","what is sdd-plan","sdd-plan alternative","sdd-plan vs waterfall methodology","implementation planning for SDD","specification-driven development tools","sdd-plan install"],"zh":["SDD 计划","AIエージェント","仕様駆動開発","实装计划","条件验证"," `/sdd-specify` "," `.steering/` "," `sdd-principles` "],"ja":["SDD Plan","AIエージェント","仕様駆動開発","実装計画","条件検証"," `/sdd-specify` "," `.steering/` "," `sdd-principles` "],"ko":["SDD 계획","AI 에이전트","仕様駆動開発","구현 계획","조건 검증"," `/sdd-specify` "," `.steering/` "," `sdd-principles` "],"es":["SDD Plan","herramientas de AI Agent","implementación de especificaciones","framework de 仕様駆動開発","planes de implementación","verificación de condiciones de fase","desarrollo de software","ingeniería de software"],"fr":["SDD Plan","outils d''agent IA","mise en œuvre de spécifications","framework de 仕様駆動開発","plans de mise en œuvre","vérification des conditions de phase","développement de logiciels","ingénierie de logiciels"],"de":["SDD Plan","AI-Tools","Implementierung von Spezifikationen","Framework von 仕様駆動開発","Implementierungspläne","Überprüfung von Phasenbedingungen","Softwareentwicklung","Softwareingenieurwesen"],"pt":["sdd-plan","desenvolvimento baseado em especificações","ferramentas de desenvolvimento","gate 1","sdd-principles","CLI","Python","React"],"ru":["sdd-plan","разработка на основе спецификаций","инструменты разработки","gate 1","sdd-principles","CLI","Python","React","ИИ Агенты"],"ar":["sdd-plan","التطوير بناءً على المواصفات","أدوات التطوير","بوابة 1","sdd-principles","CLI","Python","React"]}},"owner":"umatoma","repo":"claude-example","repoPath":"umatoma/claude-example","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.407Z","topics":[],"category":"community","skillMd":{"name":"sdd-plan","description":"SDD実装計画。仕様書（Part 1）を読み込み、実装計画（Part 2）を追記する。ユーザーが「実装計画を作成して」「計画を立てて」「SDDの計画フェーズに進みたい」と言った場合に使用する。","bodyPreview":"# SDD Plan スキル\n\n仕様駆動開発（SDD）の2番目のステップ。仕様書に基づいて実装計画を作成する。\n\n## 前提条件\n\n- `/sdd-specify` で仕様書（Part 1）が作成済みであること\n- `.steering/` ディレクトリに対象の仕様書が存在すること\n\n## ワークフロー\n\n### ステップ1: 準備\n\n1. `sdd-principles` スキルを読み込み、SDD原則・フェーズゲートを確認する\n2. `.steering/` から対象の仕様書を特定する\n   - `$ARGUMENTS` でファイル名が指定された場合はそれを使用\n   - 指定がない場合は `.steering/` 内の最新ファイルを候補として提示\n3. 仕様書の Part 1（仕様セクション）を読み込む\n\n### ステップ2: フェーズゲート1 検証\n\nゲート1（Specify → Plan）の通過条件を検証する:\n\n| # | 条件 | 確認方法 |\n|---|------|---------|\n| G1-1 | `[NEEDS CLARIFICATION]` マーカーがゼロ |","body":"# SDD Plan スキル\n\n仕様駆動開発（SDD）の2番目のステップ。仕様書に基づいて実装計画を作成する。\n\n## 前提条件\n\n- `/sdd-specify` で仕様書（Part 1）が作成済みであること\n- `.steering/` ディレクトリに対象の仕様書が存在すること\n\n## ワークフロー\n\n### ステップ1: 準備\n\n1. `sdd-principles` スキルを読み込み、SDD原則・フェーズゲートを確認する\n2. `.steering/` から対象の仕様書を特定する\n   - `$ARGUMENTS` でファイル名が指定された場合はそれを使用\n   - 指定がない場合は `.steering/` 内の最新ファイルを候補として提示\n3. 仕様書の Part 1（仕様セクション）を読み込む\n\n### ステップ2: フェーズゲート1 検証\n\nゲート1（Specify → Plan）の通過条件を検証する:\n\n| # | 条件 | 確認方法 |\n|---|------|---------|\n| G1-1 | `[NEEDS CLARIFICATION]` マーカーがゼロ | 仕様書内を検索 |\n| G1-2 | 受入基準が1つ以上存在 | Given-When-Thenテーブルを確認 |\n| G1-3 | プロジェクト憲法チェックリストが全項目記入済み | チェックボックスを確認 |\n| G1-4 | ユーザーが仕様を承認済み | 明示的な承認を確認 |\n\n**未通過の場合**: 未達成の条件を報告し、`/sdd-specify` に戻ることを提案して中止する。\n\n### ステップ3: アーキテクチャ設計\n\n仕様の要件に基づいてアーキテクチャを設計する:\n- 新規ファイルの配置\n- 既存ファイルへの変更\n- レイヤー分離の確認（条I: モジュール先行、条VI: 関心の分離）\n- データフローの整理\n\n### ステップ4: フェーズ分解\n\n受入基準からアトミックなタスクに分解する:\n\n1. **テスト先行**（条III）: 各フェーズは「テスト作成→実装→検証」の順序\n2. **依存関係**: タスク間の依存関係を明示\n3. **完了条件**: 各タスクに受入基準ベースの完了条件を設定\n4. **ファイルパス**: 各タスクで変更するファイルを明記\n\n推奨フェーズ構成:\n```\nフェーズ1: テスト準備（テストヘルパー・フィクスチャ）\nフェーズ2: コアロジック（ビジネスロジック）\nフェーズ3: インターフェース統合（外部インターフェース層）\nフェーズ4: 統合テスト\n```\n\n### ステップ5: シンプリシティゲート\n\n条VII（簡潔性ゲート）準拠を事前チェック:\n- [ ] 関数・ファイルの行数が上限内に収まる見込み\n- [ ] ネスト深度が上限内に収まる見込み\n\n超過が見込まれる場合は、分割方針を計画に記載する。\n\n### ステップ6: リスク評価\n\n実装上のリスクを評価する:\n- 技術的リスク（未知のAPI、性能懸念等）\n- 依存関係リスク（外部サービス、パッケージ互換性等）\n- スコープリスク（要件の曖昧さ、変更の影響範囲等）\n\n### ステップ7: 計画書保存\n\n仕様書の **Part 2（実装計画セクション）** を追記する:\n- 2.1 進捗サマリー\n- 2.2 アーキテクチャ変更\n- 2.3 実装フェーズ（チェックボックス付きアトミックタスク）\n- 2.4 シンプリシティゲート\n- 2.5 リスク評価\n- 2.6 成功基準（Part 1 の受入基準から転記）\n- 2.7 実装ログ（空テーブル）\n\n### ステップ8: ユーザー承認\n\n計画の概要をユーザーに提示し、承認を待つ。\n\n承認後の次のステップ: `/sdd-implement` で実装を開始する。\n\n## 出力\n\n- 仕様書に Part 2（実装計画）を追記\n- フェーズゲート2の準備状況を報告\n\n## 他のスキルとの連携\n\n- 前のステップ: `/sdd-specify` - 仕様書の作成\n- 次のステップ: `/sdd-implement` - 計画に基づいて実装\n\n## 注意事項\n\n- このスキルではコードの変更は行わない（計画の作成のみ）\n- フェーズゲート1を通過していない仕様書に対しては計画を作成しない\n- 仕様書の Part 1 は変更しない（Part 2 の追記のみ）\n"},"lastSynced":"2026-03-08T02:06:57.166Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents working with SDD, needing automated implementation planning based on specification documents.","zh":"适合与 SDD 合作的开发代理，需要根据规格文档进行自动化的实施规划。","ja":"SDD を使用して開発エージェントが仕様書に基づいて自動化された実装計画を必要とする場合に適しています。","ko":"SDD와 협력하는 개발 에이전트에게 적합하며, 사양 문서를 기반으로 자동화된 구현 계획이 필요합니다.","es":"Perfecto para Agentes de Desarrollo que trabajan con SDD, necesitando una planificación de implementación automatizada basada en documentos de especificación.","fr":"Parfait pour les agents de développement travaillant avec SDD, nécessitant une planification d''implémentation automatisée basée sur des documents de spécification.","de":"Perfekt für Entwicklungsmittel, die mit SDD arbeiten und eine automatisierte Implementierungsplanung auf Basis von Spezifikationsdokumenten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que trabalham com SDD, necessitando de planejamento de implementação automatizado com base em documentos de especificação.","ru":"Идеально подходит для агентов разработки, работающих с SDD, требующих автоматического планирования реализации на основе спецификационных документов.","ar":"مثالي للوكلاء النموزجي الذين يعملون مع SDD ، وهم بحاجة إلى تخطيط تنفيذ 자동ي على أساس وثائق المواصفات."},"recommendation":{"en":"Empowers agents to generate consistent and accurate implementation plans using SDD principles and phase gates, interacting with specification files in the `.steering/` directory and validating conditions like `[NEEDS CLARIFICATION]` markers.","zh":"赋予代理生成一致且准确的实施计划的能力，使用 SDD 原则和阶段门，并与 `.steering/` 目录中的规格文件进行交互，并验证条件，如 `[NEEDS CLARIFICATION]` 标记。","ja":"SDD の原則とフェーズゲートを使用して一貫性のある実装計画を生成するエージェントの能力を提供し、`.steering/` ディレクトリ内の仕様ファイルと `[NEEDS CLARIFICATION]` マーカーなどの条件を検証します。","ko":"에이전트가 일관성 있고 정확한 구현 계획을 생성할 수 있는 능력을 제공하며, SDD 원칙 및 페이즈 게이트를 사용하고 `.steering/` 디렉토리内の 사양 파일과 `[NEEDS CLARIFICATION]` 마커와 같은 조건을 확인합니다.","es":"Habilita a los agentes a generar planes de implementación coherentes y precisos utilizando los principios y las puertas de fase de SDD, interactuando con archivos de especificación en el directorio `.steering/` y validando condiciones como marcadores `[NEEDS CLARIFICATION]`.","fr":"Permet aux agents de générer des plans d''implémentation cohérents et précis en utilisant les principes et les portes de phase de SDD, en interagissant avec des fichiers de spécification dans le répertoire `.steering/` et en validant des conditions comme des marqueurs `[NEEDS CLARIFICATION]`.","de":"Ermöglicht es den Agenten, konsistente und genaue Implementierungspläne unter Verwendung der SDD-Prinzipien und Phasentore zu generieren, indem sie mit Spezifikationsdateien im Verzeichnis `.steering/` interagieren und Bedingungen wie `[NEEDS CLARIFICATION]`-Marker überprüfen.","pt":"Habilita os agentes a gerar planos de implementação consistentes e precisos usando princípios e portas de fase SDD, interagindo com arquivos de especificação no diretório `.steering/` e validando condições como marcadores `[NEEDS CLARIFICATION]`.","ru":"Наделяет агентов возможностью генерировать последовательные и точные планы реализации с использованием принципов и фазовых ворот SDD, взаимодействуя со спецификационными файлами в каталоге `.steering/` и проверяя условия, такие как маркеры `[NEEDS CLARIFICATION]`.","ar":"يمنح الوكلاء القدرة على توليد خطط تنفيذ متسقة ودقيقة باستخدام مبادئ وبوابات مرحلية SDD ، والتفاعل مع ملفات المواصفات في الدليل `.steering/` والتحقق من الشروط مثل العلامات `[NEEDS CLARIFICATION]`."},"useCases":{"en":["Automating planning processes for SDD projects","Validating phase gate conditions for specification documents","Generating implementation plans based on latest specification files in `.steering/`"],"zh":["为 SDD 项目自动化规划流程","为规格文档验证阶段门条件","根据 `.steering/` 目录中最新的规格文件生成实施计划"],"ja":["SDD プロジェクトの計画プロセスを自動化する","仕様書のフェーズゲート条件を検証する","`.steering/` ディレクトリ内の最新の仕様ファイルに基づいて実装計画を生成する"],"ko":["SDD 프로젝트의 계획 프로세스를 자동화하는 것","사양 문서의 페이즈 게이트 조건을 확인하는 것","`.steering/` 디렉토리 내의最新 사양 파일을 기반으로 구현 계획을 생성하는 것"],"es":["Automatización de procesos de planificación para proyectos SDD","Validación de condiciones de puerta de fase para documentos de especificación","Generación de planes de implementación en función de los archivos de especificación más recientes en `.steering/`"],"fr":["Automatisation des processus de planification pour les projets SDD","Validation des conditions de porte de phase pour les documents de spécification","Génération de plans d''implémentation en fonction des fichiers de spécification les plus récents dans `.steering/`"],"de":["Automatisierung von Planungsprozessen für SDD-Projekte","Validierung von Phasentorbedingungen für Spezifikationsdokumente","Generierung von Implementierungsplänen auf der Grundlage der neuesten Spezifikationsdateien im Verzeichnis `.steering/`"],"pt":["Automatizar processos de planejamento para projetos SDD","Validar condições de portas de fase para documentos de especificação","Gerar planos de implementação com base nos arquivos de especificação mais recentes em `.steering/`"],"ru":["Автоматизировать процессы планирования для проектов SDD","Проверять условия фазовых ворот для спецификационных документов","Генерировать планы реализации на основе последних спецификационных файлов в `.steering/`"],"ar":["تأتمتة عمليات التخطيط لمشاريع SDD","التحقق من شروط بوابات المرحلة لوثائق المواصفات","توليد خطط التنفيذ على أساس أحدث ملفات المواصفات في `.steering/`"]},"limitations":{"en":["Requires `/sdd-specify` skill to have created a specification document","Needs access to the `.steering/` directory","Limited to SDD-based development projects"],"zh":["需要 `/sdd-specify` 技能来创建规格文档","需要访问 `.steering/` 目录","仅限于基于 SDD 的开发项目"],"ja":["仕様書を作成するために `/sdd-specify` スキルが必要","`.steering/` ディレクトリへのアクセスが必要","SDD ベースの開発プロジェクトにのみ制限"],"ko":["사양 문서를 생성하기 위해 `/sdd-specify` 스킬이 필요","`.steering/` 디렉토리에 접근할 수 있어야 함","SDD 기반 개발 프로젝트에만 제한"],"es":["Requiere la habilidad `/sdd-specify` para haber creado un documento de especificación","Necesita acceso al directorio `.steering/`","Limitado a proyectos de desarrollo basados en SDD"],"fr":["Nécessite la compétence `/sdd-specify` pour avoir créé un document de spécification","A besoin d''accès au répertoire `.steering/`","Limité aux projets de développement basés sur SDD"],"de":["Benötigt die Fähigkeit `/sdd-specify`, um ein Spezifikationsdokument erstellt zu haben","Benötigt Zugriff auf das Verzeichnis `.steering/`","Begrenzt auf SDD-basierte Entwicklungsprojekte"],"pt":["Exige que a habilidade `/sdd-specify` tenha criado um documento de especificação","Necessita de acesso ao diretório `.steering/`","Limitado a projetos de desenvolvimento baseados em SDD"],"ru":["Требует, чтобы навык `/sdd-specify` создал спецификационный документ","Требует доступа к каталогу `.steering/`","Ограничен проектами разработки на основе SDD"],"ar":["يتطلب أن يُنشئ مهارة `/sdd-specify` وثيقة مواصفات","يحتاج إلى الوصول إلى الدليل `.steering/`","محدود بمشاريع التطوير المستندة إلى SDD"]},"version":4},"contentHash":"0fff44c1c060325ffb13d8d064fa436920104bc20b879b59eb26f28bc448ccf9","qualityScore":33}');
