INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('umatoma/claude-example/sdd-plan', 'sdd-plan', 'umatoma', 'claude-example', 'community', 'sdd-plan umatoma claude-example community The sdd-plan skill generates an implementation plan based on a specification document, benefiting developers working with SDD. It automates the planning process, ensuring consistency and accuracy. SDD 计划是实现高效的仕様駆動開発的关键步骤，涉及创建实装计划和验证条件 SDD Plan は効率的な仕様駆動開発を実現するための重要なステップであり、実装計画の作成と条件の検証を含む SDD 계획은 효율적인仕様駆動개발을 실현하는 중요한 단계로, 구현 계획의 생성과 조건의 검증을 포함 SDD Plan es una herramienta de implementación de especificaciones que utiliza el framework de 仕様駆動開発 (SDD). Permite a los desarrolladores crear planes de implementación precisos SDD Plan est un outil de mise en œuvre de spécifications qui utilise le framework de 仕様駆動開発 (SDD). Il permet aux développeurs de créer des plans de mise en œuvre précis SDD Plan ist ein Tool für die Implementierung von Spezifikationen, das den Framework von 仕様駆動開発 (SDD) verwendet. Es ermöglicht Entwicklern, präzise Implementierungspläne zu erstellen O sdd-plan é uma ferramenta de desenvolvimento que permite criar planos de implementação com base em especificações. Ele automatiza o processo de verificação do gate 1 sdd-plan - это инструмент разработки, который позволяет создавать планы реализации на основе спецификаций. Он автоматизирует процесс проверки gate 1 для ИИ Агентов sdd-plan هو أداة تطوير تمكنك من إنشاء خطط تنفيذ بناءً على المواصفات. يؤتم过程 التحقق من بوابة 1 how to use sdd-plan sdd-plan setup guide what is sdd-plan sdd-plan alternative sdd-plan vs waterfall methodology implementation planning for SDD specification-driven development tools sdd-plan install SDD 计划 AIエージェント 仕様駆動開発 实装计划 条件验证 `/sdd-specify` `.steering/` `sdd-principles` Loads SDD principles and phase gates using the sdd-principles skill Identifies target specification files in the .steering/ directory Reads Part 1 of the specification document for planning Verifies Gate 1 conditions, including the absence of [NEEDS CLARIFICATION] markers Supports file name specification via $ARGUMENTS or automatic detection of the latest file sdd-plan is a skill that creates an implementation plan from a specification document, following the principles of Specification-Driven Development (SDD).');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('interactive-inc/open-stack-app/gemini', 'community', 'interactive-inc', 'open-stack-app', 'interactive-inc/open-stack-app', 'gemini', 0, 0, 33, '2026-03-08T01:57:15.409Z', '2026-03-08T02:06:58.133Z', '1372996e1ef6164106d72f13f7e21327272dfa7234c3cc8465573ff570284d5e', '{"id":"interactive-inc/open-stack-app/gemini","name":"gemini","description":{"en":"The Gemini skill enables AI agents to leverage the Google Gemini model for enhanced thinking precision, benefiting developers in design judgment, debugging, and critical decision-making.","zh":"Gemini是一种AI工具，帮助开发者提高代码质量和开发效率。通过Gemini CLI工具和API密钥，可以实现自动化的代码评估和优化","ja":"Geminiは、開発者のコード品質と開発効率を高めるためのAIエージェントです。Gemini CLIツールとAPIキーを使用して、自動的なコード評価と最適化を実現します","ko":"Gemini는 개발者の 코드 품질과 개발 효율을 높이는 데 도움이 되는 AI 에이전트입니다. Gemini CLI 도구와 API 키를 사용하여 자동적인 코드 평가와 최적화를 실현할 수 있습니다","es":"Gemini es una herramienta de inteligencia artificial que ayuda a los desarrolladores a mejorar la precisión del pensamiento en situaciones complejas","fr":"Gemini est un outil d''intelligence artificielle qui aide les développeurs à améliorer la précision de la pensée dans des situations complexes","de":"Gemini ist ein KI-Tool, das Entwicklern hilft, die Denkgenauigkeit in komplexen Situationen zu verbessern","pt":"O Gemini é uma ferramenta de AI que ajuda a melhorar a precisão do pensamento, ideal para desenvolvedores que precisam de ajuda em decisões complexas","ru":"Gemini - это инструмент ИИ, который помогает повысить точность мышления, идеальный для разработчиков, которым нужна помощь в сложных решениях","ar":"جيميني هي أداة ذكاء اصطناعي تساعد على تحسين دقة الفكر، مثالية للمطورين الذين يحتاجون إلى مساعدة في قرارات معقدة"},"seo":{"title":{"en":"Gemini: Expert Dialogue Setup Guide | AI Agent Skill","zh":"Gemini AI工具集成指南","ja":"Gemini AIエージェントのセットアップガイド","ko":"Gemini AI 에이전트 설정 가이드","es":"Guía de configuración de Gemini para desarrolladores","fr":"Guide de mise en route de Gemini pour les développeurs","de":"Einrichtungsleitfaden für Gemini-Entwickler","pt":"Guia de Configuração do Gemini: Otimizando a Precisão do ...","ru":"ИИ Агенты: Руководство по Настройке Gemini для Повышения ...","ar":"دليل إعداد جيميني: تحسين دقة الفكر باستخدام أدوات الذكاء ..."},"description":{"en":"Unlock the power of Gemini dialogue for AI agents - learn how to set up and use this skill to boost decision-making and problem-solving capabilities","zh":"了解Gemini AI工具的集成方法和最佳实践，提高代码质量和开发效率","ja":"Gemini AIエージェントを使用してコードの精度を高め、開発効率を向上させる","ko":"Gemini AI 에이전트를 사용하여 코드의 품질과 개발 효율을 향상시키는 방법","es":"Aprende a utilizar Gemini, una herramienta de inteligencia artificial para mejorar la precisión del pensamiento, y descubre cómo integrarla en tus proyectos ...","fr":"Découvrez comment utiliser Gemini, un outil d''intelligence artificielle pour améliorer la précision de la pensée, et intégrez-le dans vos projets de développ...","de":"Erfahren Sie, wie Sie Gemini, ein KI-Tool zur Verbesserung der Denkgenauigkeit, in Ihre Entwicklungsprojekte integrieren können","pt":"Aprenda a configurar o Gemini, uma ferramenta de AI que melhora a precisão do pensamento, e descubra como usá-la em seus projetos de desenvolvimento","ru":"Узнайте, как настроить Gemini, инструмент ИИ, повышающий точность мышления, и как использовать его в ваших разработках","ar":"تعرف على كيفية إعداد جيميني، أداة ذكاء اصطناعي تحسن دقة الفكر، واكتشف كيفية استخدامها في مشاريع التطوير الخاصة بك"},"definition":{"en":"Gemini is a skill that utilizes the Google Gemini AI model to provide an alternative perspective, enhancing thinking accuracy and decision-making capabilities.","zh":"Gemini是一种AI工具，通过CLI工具和API密钥实现代码评估和优化","ja":"Geminiは、CLIツールとAPIキーを使用してコード評価と最適化を実現するAIエージェントです","ko":"Gemini는 CLI 도구와 API 키를 사용하여 코드 평가와 최적화를 실현하는 AI 에이전트입니다","es":"Gemini es un agente de inteligencia artificial que proporciona una perspectiva única para mejorar la precisión del pensamiento","fr":"Gemini est un agent d''intelligence artificielle qui fournit une perspective unique pour améliorer la précision de la pensée","de":"Gemini ist ein KI-Agent, der eine einzigartige Perspektive zur Verbesserung der Denkgenauigkeit bietet","pt":"O que é Gemini? Uma ferramenta de AI que fornece uma perspectiva diferente para melhorar a precisão do pensamento","ru":"Что такое Gemini? Инструмент ИИ, обеспечивающий другой взгляд для повышения точности мышления","ar":"ما هي جيميني؟ أداة ذكاء اصطناعي توفر منظورًا مختلفًا لتحسين دقة الفكر"},"features":{"en":["Utilizes the Google Gemini CLI tool for execution","Requires a properly configured API key or authentication for setup","Automatically triggers in situations involving design judgment, debugging, and critical decisions","Supports code context passing via pipe input or file specification options","Executes with the basic command: gemini \"prompt\""],"zh":["支持Gemini CLI工具的安装和配置","通过API密钥实现自动化的代码评估和优化","支持代码 контекст的传递和处理","实现设计判断和问题解决的自动化","支持重要决定的自动化评估和优化"],"ja":["Gemini CLIツールのインストールと設定をサポート","APIキーを使用して自動的なコード評価と最適化を実現","コードコンテキストの伝達と処理をサポート","設計判断と問題解決の自動化を実現","重要な決定の自動化評価と最適化をサポート"],"ko":["Gemini CLI 도구의 설치와 설정을 지원","API 키를 사용하여 자동적인 코드 평가와 최적화를 실현","코드 컨텍스트의 전달과 처리를 지원","설계 판단과 문제 해결의 자동화를 실현","중요한 결정의 자동화 평가와 최적화를 지원"],"es":["Integración con la línea de comandos (CLI) para una ejecución sencilla","Uso de API keys o credenciales de autenticación para un acceso seguro","Análisis de código y contexto para una comprensión más profunda","Soporte para situaciones complejas, como la evaluación de enfoques y la depuración de errores","Uso de comandos básicos como ''gemini \"prompt\"'' para una interacción sencilla","Compatibilidad con la entrada de tuberías y opciones de archivo para una mayor flexibilidad"],"fr":["Intégration avec la ligne de commande (CLI) pour une exécution simple","Utilisation de clés API ou d''informations d''authentification pour un accès sécurisé","Analyse de code et de contexte pour une compréhension plus approfondie","Prise en charge de situations complexes, telles que l''évaluation d''approches et le débogage d''erreurs","Utilisation de commandes de base comme ''gemini \"prompt\"'' pour une interaction simple","Compatibilité avec l''entrée de pipes et les options de fichier pour une plus grande flexibilité"],"de":["Integration mit der Kommandozeile (CLI) für eine einfache Ausführung","Verwendung von API-Schlüsseln oder Authentifizierungsinformationen für einen sicheren Zugriff","Analyse von Code und Kontext für ein tieferes Verständnis","Unterstützung für komplexe Situationen, wie die Bewertung von Ansätzen und die Fehlersuche","Verwendung von Basisbefehlen wie ''gemini \"prompt\"'' für eine einfache Interaktion","Kompatibilität mit der Pipe-Eingabe und den Dateioptionen für eine größere Flexibilität"],"pt":["Integração com CLI para execução de comandos","Suporte a entrada de código via pipe ou arquivo","Análise de trade-offs em decisões complexas","Ajuda na depuração de problemas difíceis","Suporte a decisões importantes, como escolha de arquitetura"],"ru":["Интеграция с CLI для выполнения команд","Поддержка ввода кода через pipe или файл","Анализ компромиссов в сложных решениях","Помощь в отладке трудных проблем","Поддержка важных решений, таких как выбор архитектуры"],"ar":["التكامل مع CLI لتشغيل الأوامر","دعم إدخال الكود عبر الأنابيب أو الملف","تحليل التبادل في القرارات المعقدة","مساعدة في تصحيح الأخطاء الصعبة","دعم القرارات المهمة، مثل اختيار الهيكل التوجيهي"]},"keywords":{"en":["how to use gemini","gemini setup guide","google gemini ai model","gemini alternative","gemini vs google dialogflow","gemini install","what is gemini skill","gemini api key setup","gemini cli tool"],"zh":["Gemini AI工具","代码评估和优化","CLI工具","API密钥","自动化开发","代码质量提高","开发效率提高"],"ja":["Gemini AIエージェント","コード評価と最適化","CLIツール","APIキー","自動化開発","コード品質向上","開発効率向上"],"ko":["Gemini AI 에이전트","코드 평가와 최적화","CLI 도구","API 키","자동화 개발","코드 품질 향상","개발 효율 향상"],"es":["Gemini","herramienta de inteligencia artificial","desarrollo de software","integración con CLI","análisis de código","depuración de errores","evaluación de enfoques","agente de inteligencia artificial","desarrollo de aplicaciones","IA para desarrolladores"],"fr":["Gemini","outil d''intelligence artificielle","développement de logiciels","intégration avec la CLI","analyse de code","débogage d''erreurs","évaluation d''approches","agent d''intelligence artificielle","développement d''applications","IA pour les développeurs"],"de":["Gemini","KI-Tool","Software-Entwicklung","Integration mit der Kommandozeile","Code-Analyse","Fehlersuche","Bewertung von Ansätzen","KI-Agent","Anwendungs-Entwicklung","KI für Entwickler"],"pt":["gemini ai","ferramenta de ai para desenvolvedores","otimização da precisão do pensamento","desenvolvimento de software com ai","guias de configuração do gemini","ai para tomada de decisões"],"ru":["gemini ai","инструмент ИИ для разработчиков","оптимизация точности мышления","разработка программного обеспечения с ИИ","руководство по настройке gemini","ИИ для принятия решений"],"ar":["جيميني ai","أداة ذكاء اصطناعي للمطورين","تحسين دقة الفكر","تطوير البرمجيات باستخدام الذكاء الاصطناعي","دليل إعداد جيميني","الذكاء الاصطناعي للقرارات"]}},"owner":"interactive-inc","repo":"open-stack-app","repoPath":"interactive-inc/open-stack-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.409Z","topics":[],"category":"community","skillMd":{"name":"gemini","description":"Get alternative perspectives via Google Gemini on complex design decisions, architecture trade-offs, stuck debugging, or approach evaluation.","bodyPreview":"# Gemini Dialogue\n\n異なるAIモデル（Google Gemini）の視点を得て、思考の精度を高めるためのスキル。\n\n## 前提条件 (Prerequisites)\n\nこのスキルを実行するには、以下の環境が整っている必要があります：\n\n- 環境パス（PATH）に `gemini` CLIツールがインストールされていること\n- 適切なAPIキーまたは認証情報が設定済みで、CLIが実行可能な状態であること\n\n## いつ使うか\n\n以下の状況で自動的に発動する：\n\n- 設計判断で迷いがある時（複数アプローチのトレードオフ評価）\n- 問題が難航している時（デバッグの行き詰まり、原因特定の困難）\n- 重要な決定をする時（アーキテクチャ選定、破壊的変更、セキュリティ実装）\n\n## 使い方\n\n### Geminiへの相談\n\n基本コマンド：\n\n```bash\ngemini \"プロンプト\"\n```\n\n### コードコンテキストの渡し方（重要）\n\nGeminiにコードを読ませる場合は、以下の方法を使用する。シェルでのエスケープエラーを防ぐため、**パイプ入力**や**ファイル指定オプション*","body":"# Gemini Dialogue\n\n異なるAIモデル（Google Gemini）の視点を得て、思考の精度を高めるためのスキル。\n\n## 前提条件 (Prerequisites)\n\nこのスキルを実行するには、以下の環境が整っている必要があります：\n\n- 環境パス（PATH）に `gemini` CLIツールがインストールされていること\n- 適切なAPIキーまたは認証情報が設定済みで、CLIが実行可能な状態であること\n\n## いつ使うか\n\n以下の状況で自動的に発動する：\n\n- 設計判断で迷いがある時（複数アプローチのトレードオフ評価）\n- 問題が難航している時（デバッグの行き詰まり、原因特定の困難）\n- 重要な決定をする時（アーキテクチャ選定、破壊的変更、セキュリティ実装）\n\n## 使い方\n\n### Geminiへの相談\n\n基本コマンド：\n\n```bash\ngemini \"プロンプト\"\n```\n\n### コードコンテキストの渡し方（重要）\n\nGeminiにコードを読ませる場合は、以下の方法を使用する。シェルでのエスケープエラーを防ぐため、**パイプ入力**や**ファイル指定オプション**を優先する。\n\n**1. パイプ入力（推奨：エスケープ問題を回避）**\nファイルの中身を標準入力として渡す：\n\n```bash\ncat src/feature.ts | gemini \"このコードの潜在的なバグを指摘して\"\n```\n\n**2. コンテキストオプション（CLIがサポートしている場合）**\nファイルパスを明示的に指定する：\n\n```bash\ngemini \"リファクタリング案を出して\" --context src/App.tsx\n```\n\n**3. コマンド置換（短いテキストのみ）**\n```bash\ngemini \"次の設定値の意味を教えて: $(cat config.json)\"\n```\n\n### オプション\n\n- `-m gemini-2.5-pro` - モデル指定（デフォルトは2.5 Flash）\n- `--include-directories ../lib` - ディレクトリごとコンテキストに追加（トークン量に注意）\n\n### セッション引き継ぎ\n\n継続的な議論が必要な場合、前回のセッションを引き継げる：\n\n```bash\ngemini -r latest \"フォローアップの質問\"\n```\n\nセッション一覧を確認する場合：\n\n```bash\ngemini --list-sessions\n```\n\n## 注意事項\n\n- **対話モード禁止**: `-i` フラグは使用しない。Bashツールがタイムアウトするため、常にワンショットで実行する。\n- **シェルエスケープ**: プロンプト文字列内に `\"`（ダブルクォート）や `$`、バッククォートが含まれるとBashが誤解釈する可能性がある。複雑なプロンプトは外部ファイルに保存してから読み込ませるか、パイプ入力を活用する。\n- **機密情報**: `--include-directories` を使用する際は、`.env` ファイルや認証情報が含まれないよう注意する。\n\n## プロンプト構成\n\nGeminiに渡すプロンプトには以下を含める：\n\n- 現在の状況・コンテキスト\n- 試したこと・考えたこと\n- 具体的に意見が欲しい点\n\n### 回答の統合\n\nGeminiの回答を受け取ったら：\n\n- Claude Codeの考えと比較\n- 共通点と相違点を分析\n- 最終的な判断を導出\n\n## プロンプトテンプレート\n\n### 設計判断\n\n```\n現在、[機能名]の実装を検討しています。\n\nコンテキスト:\n- [技術スタック、制約条件]\n\n検討中のアプローチ:\nA) [アプローチA]\nB) [アプローチB]\n\n私の現時点での考え:\n- [Claude Codeとしての分析]\n\n以下の観点で意見をください:\n- 見落としているリスクはないか\n- より良いアプローチはないか\n- 長期的な保守性の観点\n```\n\n### 難航している問題\n\n```\n以下の問題で行き詰まっています。\n\n症状:\n- [エラーメッセージ、挙動]\n\n試したこと:\n1. [試行1] → [結果]\n2. [試行2] → [結果]\n\n関連コード:\n[コードスニペット または ファイル内容]\n\n別の角度からの調査アプローチを提案してください。\n```\n\n## 運用ルール\n\n- Geminiの意見は参考情報として扱う\n- 最終判断はClaude Codeが行う\n- 両者の意見が異なる場合は、その理由を分析してユーザーに提示する\n"},"lastSynced":"2026-03-08T02:06:58.133Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring enhanced thinking precision and critical decision-making capabilities via the Google Gemini model.","zh":"适用于需要增强思考精度和通过Google Gemini模型进行关键决策能力的AI代理。","ja":"Google Geminiモデルの高度な思考の精度と重要な意思決定能力が必要なAIエージェントに最適です。","ko":"Google Gemini 모델을 통해 향상된 사고 정확도와 중요한 의사 결정 능력이 필요한 AI 에이전트에 적합합니다.","es":"Ideal para Agentes de IA que requieren una precisión de pensamiento mejorada y capacidades de toma de decisiones críticas a través del modelo Google Gemini.","fr":"Idéal pour les agents IA nécessitant une précision de pensée améliorée et des capacités de prise de décision critique via le modèle Google Gemini.","de":"Ideal für KI-Agents, die eine verbesserte Denkgenauigkeit und kritische Entscheidungskompetenzen über das Google Gemini-Modell erfordern.","pt":"Ideal para Agentes de IA que requerem precisão de pensamento aprimorada e capacidades de tomada de decisão crítica via o modelo Google Gemini.","ru":"Идеально для ИИ-агентов, требующих повышенной точности мышления и критических возможностей принятия решений через модель Google Gemini.","ar":"مثالي لعمليات الوكيل الذكي التي تتطلب دقة في التفكير وتقدير القرار الحاسم من خلال نموذج جوجل جيمي"},"recommendation":{"en":"Empowers agents to leverage the Google Gemini model for design judgment, debugging, and critical decision-making, utilizing the Gemini CLI tool and API keys for seamless integration, and supporting complex tasks through code context passing via pipe input or file specification options.","zh":"赋予代理使用Google Gemini模型进行设计判断、调试和关键决策的能力，利用Gemini CLI工具和API密钥实现无缝集成，并通过管道输入或文件指定选项支持复杂任务。","ja":"Gemini CLIツールとAPIキーを使用してシームレスに統合し、パイプ入力またはファイル指定オプションを介してコードコンテキストをパスすることで複雑なタスクをサポートすることで、エージェントがGoogle Geminiモデルを使用して設計判断、デバッグ、重要な意思決定を行うことができるようにします。","ko":"Gemini CLI 도구 및 API 키를 사용하여 무결점 통합을 구현하고, 파이프 입력 또는 파일 지정 옵션을 통해 코드 컨텍스트 전달을 지원하여 복잡한 작업을 지원함으로써, 에이전트가 Google Gemini 모델을 사용하여 디자인 판단, 디버깅 및 중요한 의사 결정에 대한 권한을 부여합니다.","es":"Habilita a los agentes a aprovechar el modelo Google Gemini para el juicio de diseño, la depuración y la toma de decisiones críticas, utilizando la herramienta Gemini CLI y las claves de API para una integración sin problemas, y admitiendo tareas complejas a través de la passing de contexto de código a través de opciones de entrada de tubería o especificación de archivos.","fr":"Permet aux agents d''exploiter le modèle Google Gemini pour le jugement de conception, le débogage et la prise de décision critique, en utilisant l''outil Gemini CLI et les clés d''API pour une intégration transparente, et en prenant en charge des tâches complexes via le passage de contexte de code via des options d''entrée de pipe ou de spécification de fichiers.","de":"Ermächtigt Agents, das Google Gemini-Modell für Designurteilsvermögen, Fehlersuche und kritische Entscheidungsfindung zu nutzen, indem es das Gemini CLI-Tool und API-Schlüssel für eine nahtlose Integration verwendet und komplexe Aufgaben durch Codekontextweitergabe über Pipe-Eingabemöglichkeiten oder Dateispezifikationsoptionen unterstützt.","pt":"Habilita os agentes a utilizar o modelo Google Gemini para julgamento de design, depuração e tomada de decisão crítica, utilizando a ferramenta Gemini CLI e chaves de API para integração sem problemas, e suporta tarefas complexas por meio da passagem de contexto de código via entrada de pipe ou opções de especificação de arquivo.","ru":"Позволяет агентам использовать модель Google Gemini для проектирования суждения, отладки и принятия критических решений, используя инструмент Gemini CLI и ключи API для бесшовной интеграции, и поддерживает сложные задачи посредством передачи контекста кода через входной поток или файловые спецификации.","ar":"تمكين الوكلاء من استخدام نموذج جوجل جيمي لتقدير التصميم وتصحيح الأخطاء واتخاذ القرارات الحاسمة، باستخدام أداة جيمي CLI ومفاتيح API للتكامل السلس، ودعم المهام المعقدة من خلال تمرير سياق الكود عبر مدخلات الأنابيب أو خيارات تحديد الملفات"},"useCases":{"en":["Enhancing design judgment through trade-off evaluations","Debugging complex issues with precise cause identification","Informing critical decisions such as architecture selection or security implementations"],"zh":["通过权衡评估增强设计判断","通过精确原因识别调试复杂问题","告知诸如架构选择或安全实施等关键决策"],"ja":["トレードオフ評価を通じて設計判断を強化する","正確な原因特定を通じて複雑な問題をデバッグする","アーキテクチャの選択やセキュリティの実装などの重要な意思決定を通知する"],"ko":["트레이드오프 평가를 통한 디자인 판단 강화","정확한 원인 식별을 통한 복잡한 문제 디버깅","아키텍처 선택 또는 보안 구현 등의 중요한 의사 결정에 대한 정보 제공"],"es":["Mejorar el juicio de diseño a través de evaluaciones de compensaciones","Depurar problemas complejos con una identificación precisa de causas","Informar decisiones críticas como la selección de arquitectura o la implementación de la seguridad"],"fr":["Améliorer le jugement de conception via des évaluations de compromis","Déboguer des problèmes complexes avec une identification précise des causes","Informer des décisions critiques comme la sélection de l''architecture ou la mise en œuvre de la sécurité"],"de":["Designurteilsvermögen durch Abwägungsbewertungen verbessern","Komplexe Probleme mit genauer Ursachenidentifizierung debuggen","Kritische Entscheidungen wie Architekturenauswahl oder Sicherheitsimplementierung informieren"],"pt":["Melhorar o julgamento de design por meio de avaliações de trade-off","Depurar problemas complexos com identificação precisa da causa","Informar decisões críticas, como seleção de arquitetura ou implementações de segurança"],"ru":["Улучшить суждение по дизайну посредством оценок компромиссов","Отладить сложные проблемы с точной идентификацией причины","Информировать критические решения, такие как выбор архитектуры или реализаций безопасности"],"ar":["تحسين تقدير التصميم من خلال تقييمات التبادل","تصحيح مشكلات معقدة مع تحديد دقيق للسبب","إبلاغ القرارات الحاسمة مثل اختيار الهندسة المعمارية أو تنفيذات الأمن"]},"limitations":{"en":["Requires Gemini CLI tool installation in the environment path","Needs appropriate API keys or authentication credentials for CLI execution"],"zh":["需要在环境路径中安装Gemini CLI工具","需要适当的API密钥或身份验证凭据进行CLI执行"],"ja":["環境パスにGemini CLIツールをインストールする必要がある","CLIの実行には適切なAPIキーまたは認証資格情報が必要"],"ko":["환경 경로에 Gemini CLI 도구를 설치해야 함","CLI 실행을 위해 적절한 API 키 또는 인증 자격 증명이 필요"],"es":["Requiere la instalación de la herramienta Gemini CLI en la ruta del entorno","Necesita claves de API o credenciales de autenticación adecuadas para la ejecución de CLI"],"fr":["Nécessite l''installation de l''outil Gemini CLI dans le chemin d''environnement","A besoin de clés d''API ou de informations d''authentification appropriées pour l''exécution de CLI"],"de":["Erfordert die Installation des Gemini CLI-Tools im Umgebungsverzeichnis","Benötigt geeignete API-Schlüssel oder Authentifizierungsanmeldeinformationen für die CLI-Ausführung"],"pt":["Requer instalação da ferramenta Gemini CLI no caminho do ambiente","Necessita de chaves de API ou credenciais de autenticação apropriadas para execução da CLI"],"ru":["Требует установки инструмента Gemini CLI в路径е окружения","Требует ключей API или учетных данных аутентификации для выполнения CLI"],"ar":["يتطلب تثبيت أداة جيمي CLI في مسار البيئة","يتطلب مفاتيح API أو أوراق اعتمادية مناسبة للتشغيل CLI"]},"version":4},"contentHash":"1372996e1ef6164106d72f13f7e21327272dfa7234c3cc8465573ff570284d5e","qualityScore":33}');
