INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tadams95/kardashev-network/framer-motion', 'framer-motion', 'tadams95', 'kardashev-network', 'community', 'framer-motion tadams95 kardashev-network community framer-motion is a library for creating animations in React applications. It benefits developers by providing an easy-to-use API for animating components. Framer Motion是一个强大的动画库，提供基本动画和属性动画功能 Framer Motionは強力なアニメーションライブラリで、基本的なアニメーションとプロパティアニメーション機能を提供します Framer Motion은 강력한 애니메이션 라이브러리로 기본 애니메이션과 속성 애니메이션 기능을 제공합니다 Framer Motion es una biblioteca de animación para React que permite crear animaciones personalizadas Framer Motion est une bibliothèque d''animation pour React qui permet de créer des animations personnalisées Framer Motion ist eine Animationsbibliothek für React, mit der Sie benutzerdefinierte Animationen erstellen können Framer Motion é uma biblioteca de animação para React que permite criar animações complexas de forma fácil Framer Motion - это библиотека анимации для React, которая позволяет создавать сложные анимации просто Framer Motion هو مكتبة حركة ل React التي تمكنك من إنشاء حركات معقدة بسهولة how to use framer-motion framer-motion alternative framer-motion install framer-motion setup guide what is framer-motion framer-motion vs react-spring framer-motion animation examples framer-motion react tutorial framer-motion documentation Framer Motion React动画 属性动画 过渡动画 网页交互性 动画库 前端开发 UI设计 用户体验 Initial and animate props for setting animation states Transition prop for customizing animation durations and timing Support for animating properties like x, y, scale, rotate, and opacity Ability to animate backgroundColor and borderRadius for dynamic styling Integration with React for seamless animation of components framer-motion is a JavaScript library for creating animations and gestures in React applications, utilizing APIs like initial, animate, and transition.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('takapom/trip-app/accessibility', 'community', 'takapom', 'trip-app', 'takapom/trip-app', 'accessibility', 0, 0, 33, '2026-03-08T01:57:15.410Z', '2026-03-08T02:07:01.365Z', '8bda8418799a4393fe76c49516633614c4fd11da75f45aa03698edf6f29f62f4', '{"id":"takapom/trip-app/accessibility","name":"accessibility","description":{"en":"The accessibility skill implements VoiceOver support and WCAG AA compliance for improved app usability, benefiting developers and users alike.","zh":"本文介绍提高无障碍访问的技术细节，包括Liquid Glass设计和WCAG AA标准","ja":"アクセシビリティ改善スキルを使用して、VoiceOver対応のアプリを開発できます","ko":"접근성 개선 설정 가이드는 AI 에이전트 도구를 사용하여 접근성 개선 설정을 구현하는 방법을 제공합니다","es":"La accesibilidad es crucial para desarrolladores. Nuestra guía cubre aspectos técnicos como la compatibilidad con VoiceOver y el cumplimiento de la norma WCAG AA","fr":"L''accessibilité est cruciale pour les développeurs. Notre guide couvre les aspects techniques tels que la compatibilité avec VoiceOver et le respect de la norme WCAG AA","de":"Die Barrierefreiheit ist für Entwickler von entscheidender Bedeutung. Unser Leitfaden behandelt technische Aspekte wie die Kompatibilität mit VoiceOver und die Einhaltung der WCAG-AA-Norm","pt":"Melhore a acessibilidade em seus projetos de IA com dicas técnicas para React Native e WCAG AA.","ru":"Улучшите доступность в ваших проектах ИИ с помощью технических советов для React Native и WCAG AA.","ar":"حسّن إمكانية الوصول في مشاريع الذكاء الاصطناعي باستخدام نصائح تقنية لـ React Native و WCAG AA"},"seo":{"title":{"en":"Accessibility: Setup Guide for AI Agents","zh":"AI智能体验：提高无障碍访问设置指南","ja":"アクセシビリティ強化スキル：VoiceOver対応設定ガイド","ko":"접근성 개선 설정 가이드: AI 에이전트 도구","es":"Guía de configuración de accesibilidad para desarrolladores","fr":"Guide de mise en place de l''accessibilité pour les dévelo...","de":"Accessibility-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração de Acessibilidade para Ferramentas d...","ru":"ИИ Агенты: Руководство по Настройке Доступности","ar":"إعداد أداة ذكاء اصطناعي للوصول الميسر"},"description":{"en":"Improve your app''s usability with our accessibility skill, featuring VoiceOver support and WCAG AA compliance - get started now!","zh":"了解提高无障碍访问的技术细节，包括Liquid Glass设计和WCAG AA标准","ja":"VoiceOverを中心にアクセシビリティ対応を実装する方法を紹介します","ko":"AI 에이전트 도구를 사용하여 접근성 개선 설정을 구현하는 방법을 알아보세요","es":"Mejora la accesibilidad en tus aplicaciones con nuestra guía de configuración y mejores prácticas para desarrolladores","fr":"Améliorez l''accessibilité de vos applications avec notre guide de configuration et les meilleures pratiques pour les développeurs","de":"Verbessern Sie die Barrierefreiheit in Ihren Anwendungen mit unserem Konfigurationsleitfaden und Best Practices für Entwickler","pt":"Aprenda a melhorar a acessibilidade em projetos de IA com nossa guia de configuração, incluindo dicas para React Native e WCAG AA","ru":"Узнайте, как настроить доступность в проектах ИИ с нашей инструкцией, включая советы для React Native и WCAG AA","ar":"تعلم كيفية تحسين إمكانية الوصول في مشاريع الذكاء الاصطناعي باستخدام دليلنا الإرشادي، بما في ذلك نصائحสำหรـ React Native و WCAG AA"},"definition":{"en":"Accessibility is the practice of designing products to be usable by people with disabilities, ensuring equal access to information and functionality.","zh":"无障碍访问是指让所有人都能使用的技术，包括视力或听力障碍者","ja":"アクセシビリティとは、すべての人々が利用できるようにする技術です","ko":"접근성은 모든 사람이 이용할 수 있는 기술을 말합니다","es":"La accesibilidad se refiere a la capacidad de una aplicación para ser utilizada por personas con discapacidades","fr":"L''accessibilité fait référence à la capacité d''une application à être utilisée par des personnes ayant des handicaps","de":"Die Barrierefreiheit bezieht sich auf die Fähigkeit einer Anwendung, von Menschen mit Behinderungen genutzt zu werden","pt":"Acessibilidade refere-se à capacidade de um sistema ou aplicativo ser utilizado por pessoas com deficiência.","ru":"Доступность означает способность системы или приложения быть использованной людьми с ограниченными возможностями.","ar":"الوصول الميسر يعني قدرة النظام أو التطبيق على الاستخدام من قبل الأشخاص ذوي الإعاقة"},"features":{"en":["Implements VoiceOver support for iPhone users","Ensures WCAG AA compliance for text contrast and readability","Utilizes Liquid Glass design with @callstack/liquid-glass","Automatically adapts text color using PlatformColor(''labelColor'')","Provides options for text shadow and font weight adjustment"],"zh":["Liquid Glass设计","WCAG AA标准","自动适应文本颜色","文本阴影和字体粗细增强","React Native支持"],"ja":["Liquid Glassデザイン","WCAG AA基準","テキスト色の自動適応","テキストの影やフォントウェイトの増加","React Native対応"],"ko":["Liquid Glass 디자인","WCAG AA 표준","자동으로 텍스트 색상 조정","텍스트 그림자 및 글꼴 두께 증가","React Native 지원"],"es":["Compatibilidad con VoiceOver para iPhone","Cumplimiento de la norma WCAG AA para contrastes de texto","Uso de PlatformColor(''labelColor'') para texto en fondos de vidrio","Aplicación de sombras de texto y aumento de peso de fuente para mejorar la legibilidad","Soporte para la configuración de transparencia reducida","Integración con React Native para accesibilidad en aplicaciones móviles"],"fr":["Compatibilité avec VoiceOver pour iPhone","Respect de la norme WCAG AA pour les contrastes de texte","Utilisation de PlatformColor(''labelColor'') pour le texte sur fond de verre","Application d''ombres de texte et d''augmentation de la taille de police pour améliorer la lisibilité","Prise en charge de la configuration de transparence réduite","Intégration avec React Native pour l''accessibilité dans les applications mobiles"],"de":["Kompatibilität mit VoiceOver für iPhone","Einhaltung der WCAG-AA-Norm für Textkontraste","Verwendung von PlatformColor(''labelColor'') für Text auf Glasflächen","Anwendung von Textschatten und Erhöhung der Schriftgröße zur Verbesserung der Lesbarkeit","Unterstützung für die Konfiguration reduzierter Transparenz","Integration mit React Native für Barrierefreiheit in mobilen Anwendungen"],"pt":["Implementação de contraste de texto em fundos de vidro líquido","Uso de `PlatformColor(''labelColor'')` para garantir legibilidade","Adaptação para configurações de transparência reduzida","Suporte a WCAG AA para acessibilidade","Integração com React Native para melhorias de acessibilidade"],"ru":["Реализация контрастного текста на фоне Liquid Glass","Использование `PlatformColor(''labelColor'')` для обеспечения читаемости","Адаптация для настроек пониженной прозрачности","Поддержка WCAG AA для доступности","Интеграция с React Native для улучшения доступности"],"ar":["تنفيذ تحكم في وضوح النص على خلفيات زجاجية سائلة","استخدام `PlatformColor(''labelColor'')` لضمان سهولة القراءة","التكيف مع إعدادات انخفاض الشفافية","دعم WCAG AA لتحسين إمكانية الوصول","التكامل مع React Native لتحسين إمكانية الوصول"]},"keywords":{"en":["accessibility setup guide","how to use VoiceOver","WCAG AA compliance checklist","accessibility vs usability","Liquid Glass design tutorial","accessibility install for react-native"],"zh":["AI智能体验","无障碍访问","Liquid Glass设计","WCAG AA标准","React Native","自动适应文本颜色","文本阴影","字体粗细增强"],"ja":["AIエージェント","アクセシビリティ","Liquid Glassデザイン","WCAG AA基準","React Native","テキスト色の自動適応","テキストの影","フォントウェイトの増加"],"ko":["AI 에이전트 도구","접근성 개선","Liquid Glass 디자인","WCAG AA 표준","React Native","자동으로 텍스트 색상 조정","텍스트 그림자","글꼴 두께 증가"],"es":["accesibilidad en aplicaciones","guias de configuracion de accesibilidad","mejores practicas de accesibilidad","WCAG AA","VoiceOver","React Native","desarrollo de aplicaciones móviles","accesibilidad en iPhone","compatibilidad con VoiceOver"],"fr":["accessibilité dans les applications","guides de configuration d''accessibilité","meilleures pratiques d''accessibilité","WCAG AA","VoiceOver","React Native","développement d''applications mobiles","accessibilité sur iPhone","compatibilité avec VoiceOver"],"de":["Barrierefreiheit in Anwendungen","Konfigurationsleitfäden für Barrierefreiheit","Best Practices für Barrierefreiheit","WCAG AA","VoiceOver","React Native","Entwicklung von mobilen Anwendungen","Barrierefreiheit auf iPhone","Kompatibilität mit VoiceOver"],"pt":["acessibilidade em IA","guias de configuração de acessibilidade","React Native e acessibilidade","WCAG AA e acessibilidade","ferramentas de IA para acessibilidade","desenvolvimento de acessibilidade em IA","melhorias de acessibilidade em projetos de IA","acessibilidade em sistemas de IA"],"ru":["доступность в ИИ","руководства по настройке доступности","React Native и доступность","WCAG AA и доступность","инструменты ИИ для доступности","разработка доступности в ИИ","улучшения доступности в проектах ИИ","доступность в системах ИИ"],"ar":["الوصول الميسر في الذكاء الاصطناعي","دلائل إرشادية لتحسين إمكانية الوصول","React Native و إمكانية الوصول","WCAG AA و إمكانية الوصول","أدوات الذكاء الاصطناعي لتحسين إمكانية الوصول","تنمية إمكانية الوصول في مشاريع الذكاء الاصطناعي","تحسينات إمكانية الوصول في مشاريع الذكاء الاصطناعي","إمكانية الوصول في أنظمة الذكاء الاصطناعي"]}},"owner":"takapom","repo":"trip-app","repoPath":"takapom/trip-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.410Z","topics":[],"category":"community","skillMd":{"name":"accessibility","description":"iPhoneのVoiceOver対応を中心にアクセシビリティを改善する。「アクセシビリティ対応して」「VoiceOver対応」「a11y改善」などのリクエストで使用する。","bodyPreview":"# アクセシビリティ改善スキル\n\niPhoneの VoiceOver を中心に、アクセシビリティ対応を実装する。\n\n## デザイン前提: Liquid Glass\n\n本プロジェクトは `@callstack/liquid-glass` による Liquid Glass デザインを前提とする。\nLiquid Glass はアクセシビリティ上の注意点が多い:\n\n### ガラス上テキストのコントラスト確保\n- ガラスの背景ブラーにより、テキストの可読性が低下しやすい\n- `LiquidGlassView` の高さが **65px超** の場合、テキスト色の自動適応が効かない。`PlatformColor(''labelColor'')` を明示的に使用する\n- WCAG AA 基準（コントラスト比 4.5:1 以上）を満たすよう、必要に応じてテキストに影 (`textShadowColor`) やフォントウェイトの増加で補完する\n\n### 「透明度を下げる」設定への対応\n```tsx\nimport { AccessibilityInfo } from ''react-native'';\nimport","body":"# アクセシビリティ改善スキル\n\niPhoneの VoiceOver を中心に、アクセシビリティ対応を実装する。\n\n## デザイン前提: Liquid Glass\n\n本プロジェクトは `@callstack/liquid-glass` による Liquid Glass デザインを前提とする。\nLiquid Glass はアクセシビリティ上の注意点が多い:\n\n### ガラス上テキストのコントラスト確保\n- ガラスの背景ブラーにより、テキストの可読性が低下しやすい\n- `LiquidGlassView` の高さが **65px超** の場合、テキスト色の自動適応が効かない。`PlatformColor(''labelColor'')` を明示的に使用する\n- WCAG AA 基準（コントラスト比 4.5:1 以上）を満たすよう、必要に応じてテキストに影 (`textShadowColor`) やフォントウェイトの増加で補完する\n\n### 「透明度を下げる」設定への対応\n```tsx\nimport { AccessibilityInfo } from ''react-native'';\nimport { isLiquidGlassSupported } from ''@callstack/liquid-glass'';\n\nconst [reduceTransparency, setReduceTransparency] = useState(false);\n\nuseEffect(() => {\n  AccessibilityInfo.isReduceTransparencyEnabled().then(setReduceTransparency);\n  const sub = AccessibilityInfo.addEventListener(\n    ''reduceTransparencyChanged'',\n    setReduceTransparency,\n  );\n  return () => sub.remove();\n}, []);\n\n// reduceTransparency が true の場合、ガラスエフェクトを無効化し不透明背景にする\n```\n\n### フォールバック\n- `isLiquidGlassSupported === false` または `reduceTransparency === true` の場合は、ガラスを使わず十分なコントラストを持つ不透明背景を提供する\n\n## 対象ファイル\n\n- `src/screens/**/*.tsx` — 画面コンポーネント\n- `src/components/**/*.tsx` — UIコンポーネント\n\n引数が指定された場合はその画面のみ、省略時は全ファイルを対象とする。\n\n## 手順\n\n### 1. 対象要素の特定\n\n以下の要素を検索し、アクセシビリティ属性の有無を確認する:\n- `Pressable`, `TouchableOpacity`, `TouchableHighlight` — ボタン系\n- `Image` — 画像\n- `TextInput` — 入力フィールド\n- `Switch` — トグル\n- `Text`（見出し相当） — ヘッダー\n\n### 2. アクセシビリティ属性の適用ルール\n\n#### ボタン / Pressable\n\n```tsx\n<Pressable\n  accessibilityRole=\"button\"\n  accessibilityLabel=\"戻る\"           // VoiceOverが読み上げるテキスト\n  accessibilityHint=\"前の画面に戻ります\"  // 操作の結果を説明（任意）\n  onPress={handleBack}\n>\n  <ChevronIcon />\n</Pressable>\n```\n\n| 要素の種類 | accessibilityRole | accessibilityLabel の指針 |\n|-----------|-------------------|--------------------------|\n| 通常ボタン | `button` | アクションを示す動詞（「保存する」「送信する」） |\n| リンクボタン | `link` | 遷移先を示す（「設定を開く」） |\n| 戻るボタン | `button` | 「戻る」 |\n| アイコンボタン | `button` | アイコンの意味（「設定」「メニュー」） |\n| いいねボタン | `button` | 状態を含む（「いいね、現在5件」） |\n| タブバー項目 | `tab` | タブ名（「ホーム」「通知」「設定」） |\n| 画像 | `image` | 画像の内容を説明する簡潔なテキスト |\n| 装飾的画像 | — | `accessible={false}` を設定 |\n| 入力フィールド | — | `accessibilityLabel` でフィールド名 |\n| トグル | `switch` | 設定名と現在の状態 |\n| 見出しテキスト | `header` | — （Text内容が自動で読まれる） |\n\n#### 画像\n\n```tsx\n// 意味のある画像\n<Image\n  source={{ uri: postImageUrl }}\n  accessibilityRole=\"image\"\n  accessibilityLabel=\"投稿画像: カフェの外観写真\"\n/>\n\n// 装飾的な画像（VoiceOverでスキップ）\n<Image\n  source={decorativeBlob}\n  accessible={false}\n/>\n```\n\n#### TextInput\n\n```tsx\n<TextInput\n  accessibilityLabel=\"メールアドレス\"\n  accessibilityHint=\"ログイン用のメールアドレスを入力してください\"\n  placeholder=\"example@mail.com\"\n/>\n```\n\n#### 見出し\n\n```tsx\n<Text\n  accessibilityRole=\"header\"\n  style={styles.sectionTitle}\n>\n  基本情報\n</Text>\n```\n\n#### 状態を持つ要素\n\n```tsx\n// いいねボタンの例\n<Pressable\n  accessibilityRole=\"button\"\n  accessibilityLabel={`いいね、現在${likesCount}件`}\n  accessibilityState={{ selected: isLiked }}\n  onPress={handleLike}\n>\n```\n\n### 3. グループ化\n\n関連する要素をまとめて1つの VoiceOver 項目にする:\n\n```tsx\n// カードをグループ化\n<View\n  accessible={true}\n  accessibilityRole=\"button\"\n  accessibilityLabel={`${hirobaTitle}、メンバー${memberCount}人、投稿${postCount}件`}\n>\n  <Text>{hirobaTitle}</Text>\n  <Text>{memberCount}人</Text>\n  <Text>{postCount}件</Text>\n</View>\n```\n\n### 4. 読み上げ順序\n\n重要な情報が先に読まれるよう、必要に応じて `accessibilityElementsHidden` や `importantForAccessibility` を使用:\n\n```tsx\n// 装飾要素をVoiceOverから除外\n<View accessibilityElementsHidden={true}>\n  <DecorativeBackground />\n</View>\n```\n\n### 5. 絵文字アイコンの対応\n\n絵文字をアイコンとして使用している箇所に `accessibilityLabel` を追加:\n\n```tsx\n// Before\n<Text>🏠</Text>\n\n// After\n<Text accessible={false}>🏠</Text>\n// 親要素に accessibilityLabel を設定\n```\n\n## ルール\n\n- `accessibilityLabel` は簡潔に、スクリーンリーダーで自然に聞こえる日本語にする\n- 装飾的な要素（背景画像、区切り線等）は `accessible={false}` で除外する\n- 動的な値（カウント、状態）を含むラベルは変数で構築する\n- `accessibilityHint` は必須ではない。操作結果が自明でない場合のみ追加する\n- 既存の `accessibilityRole=\"button\"` は維持し、`accessibilityLabel` が未設定の場合のみ追加する\n- テスト: 変更後「VoiceOverで全画面を操作できるか」を基準とする\n"},"lastSynced":"2026-03-08T02:07:01.365Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing enhanced user experience through VoiceOver support and WCAG AA compliance.","zh":"非常适合需要通过 VoiceOver 支持和 WCAG AA 合规性来增强用户体验的前端代理。","ja":"VoiceOver サポートと WCAG AA コンプライアンスを通じてユーザー エクスペリエンスを強化する必要があるフロントエンド エージェントに最適です。","ko":"VoiceOver 지원 및 WCAG AA 규정 준수를 통해 사용자 경험을 향상시키는 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan una experiencia de usuario mejorada a través del soporte de VoiceOver y la conformidad con WCAG AA.","fr":"Parfait pour les agents Frontend ayant besoin d''une expérience utilisateur améliorée grâce au support de VoiceOver et à la conformité WCAG AA.","de":"Perfekt für Frontend-Agents, die eine verbesserte Benutzererfahrung durch VoiceOver-Unterstützung und WCAG AA-Konformität benötigen.","pt":"Perfeito para Agentes Frontend que precisam de experiência do usuário aprimorada por meio do suporte ao VoiceOver e conformidade com WCAG AA.","ru":"Идеально подходит для агентов Frontend, которым требуется улучшенный пользовательский опыт посредством поддержки VoiceOver и соответствия требованиям WCAG AA.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى تجربة مستخدم محسنة عبر دعم VoiceOver وامتثال لwcag aa."},"recommendation":{"en":"Empowers agents to implement accessibility features using Liquid Glass design, ensuring sufficient contrast ratio and readability for users, while leveraging `@callstack/liquid-glass` and `react-native` libraries to provide a seamless experience.","zh":"赋予代理实现使用 Liquid Glass 设计的无障碍功能的能力，确保用户具有足够的对比度和可读性，同时利用 `@callstack/liquid-glass` 和 `react-native` 库提供无缝的体验。","ja":"`@callstack/liquid-glass` と `react-native` ライブラリを利用して、ユーザーに十分なコントラスト比と読みやすさを提供し、シームレスなエクスペリエンスを提供するための Liquid Glass デザインを使用したアクセシビリティ機能を実装するエージェントに権限を与えます。","ko":"`@callstack/liquid-glass` 및 `react-native` 라이브러리를 활용하여 사용자에게 충분한 대비 度와 가독성을 제공하고, 무결점의 경험을 제공하기 위한 Liquid Glass 디자인을 사용하여 접근성 기능을 구현하는 에이전트에게 권한을 부여합니다.","es":"Permite a los agentes implementar funciones de accesibilidad utilizando el diseño Liquid Glass, garantizando una relación de contraste y legibilidad suficientes para los usuarios, mientras aprovecha las bibliotecas `@callstack/liquid-glass` y `react-native` para proporcionar una experiencia sin interrupciones.","fr":"Permet aux agents de mettre en œuvre des fonctionnalités d''accessibilité en utilisant la conception Liquid Glass, en garantissant un rapport de contraste et de lisibilité suffisants pour les utilisateurs, tout en exploitant les bibliothèques `@callstack/liquid-glass` et `react-native` pour fournir une expérience sans interruption.","de":"Ermöglicht es Agenten, Zugänglichkeitsfunktionen mit dem Liquid Glass-Design zu implementieren, wodurch ein ausreichendes Kontrastverhältnis und eine Lesbarkeit für Benutzer gewährleistet werden, während die Bibliotheken `@callstack/liquid-glass` und `react-native` genutzt werden, um eine nahtlose Erfahrung zu bieten.","pt":"Habilita os agentes a implementar recursos de acessibilidade usando o design Liquid Glass, garantindo uma relação de contraste e legibilidade suficientes para os usuários, ao mesmo tempo em que aproveita as bibliotecas `@callstack/liquid-glass` e `react-native` para fornecer uma experiência sem interrupções.","ru":"Позволяет агентам реализовывать функции доступности с помощью дизайна Liquid Glass, обеспечивая достаточное соотношение контраста и читаемости для пользователей, а также использует библиотеки `@callstack/liquid-glass` и `react-native` для обеспечения бесшовного опыта.","ar":"تمكن الوكلاء من تنفيذ ميزات إمكانية الوصول باستخدام تصميم زجاج السائل، ضامنًا نسبةً كافية من التباين والقراءة للناس، مع الاستفادة من المكتبات `@callstack/liquid-glass` و `react-native` لتوفير تجربة متماسكة."},"useCases":{"en":["Implementing VoiceOver support for improved app usability","Ensuring WCAG AA compliance for enhanced accessibility","Optimizing text contrast and readability on Liquid Glass backgrounds"],"zh":["为改善应用程序的可用性而实现 VoiceOver 支持","为增强无障碍性而确保 WCAG AA 合规性","优化 Liquid Glass 背景下的文本对比度和可读性"],"ja":["アプリの使いやすさを向上させるために VoiceOver サポートを実装する","アクセシビリティを強化するために WCAG AA コンプライアンスを確保する","Liquid Glass 背景でのテキストのコントラスト比と読みやすさを最適化する"],"ko":["애플리케이션의 사용 편의성을 개선하기 위해 VoiceOver 지원을 구현하는 것","접근성을 향상시키기 위해 WCAG AA 규정 준수를 보장하는 것","Liquid Glass 배경에서의 텍스트 대비 度와 가독성을 최적화하는 것"],"es":["Implementar el soporte de VoiceOver para una mejor usabilidad de la aplicación","Garantizar la conformidad con WCAG AA para una mayor accesibilidad","Optimizar el contraste y la legibilidad del texto en fondos de Liquid Glass"],"fr":["Mettre en œuvre le support de VoiceOver pour améliorer l''utilisabilité de l''application","Assurer la conformité avec WCAG AA pour une accessibilité améliorée","Optimiser le contraste et la lisibilité du texte sur les fonds Liquid Glass"],"de":["Implementierung der VoiceOver-Unterstützung für eine verbesserte App-Benutzerfreundlichkeit","Sicherstellung der WCAG AA-Konformität für eine verbesserte Zugänglichkeit","Optimierung des Textkontrasts und der Lesbarkeit auf Liquid Glass-Hintergründen"],"pt":["Implementar suporte ao VoiceOver para melhorar a usabilidade do aplicativo","Garantir conformidade com WCAG AA para acessibilidade aprimorada","Otimizar contraste e legibilidade de texto em fundos de Liquid Glass"],"ru":["Реализовать поддержку VoiceOver для улучшения удобства использования приложения","Обеспечить соответствие требованиям WCAG AA для улучшения доступности","Оптимизировать контраст и читаемость текста на фонах Liquid Glass"],"ar":["تنفيذ دعم VoiceOver لتحسين سهولة استخدام التطبيق","ضمان امتثال لمعايير wcag aa لتحسين إمكانية الوصول","تحسين التباين والقراءة النصية على خلفيات زجاج السائل"]},"limitations":{"en":["Requires `@callstack/liquid-glass` library integration","Limited to iPhone''s VoiceOver functionality","May require manual adjustment of text color and shadow for optimal contrast"],"zh":["需要集成 `@callstack/liquid-glass` 库","仅限于 iPhone 的 VoiceOver 功能","可能需要手动调整文本颜色和阴影以获得最佳对比度"],"ja":["`@callstack/liquid-glass` ライブラリの統合が必要","iPhone の VoiceOver 機能のみに限定される","最適なコントラスト比を得るために、テキストの色と影を手動で調整する必要があるかもしれない"],"ko":["`@callstack/liquid-glass` 라이브러리의 통합이 필요","iPhone의 VoiceOver 기능에만 제한됨","최적의 대비 度를 얻기 위해 텍스트 색상과 그림자를 수동으로 조정해야 할 수 있음"],"es":["Requiere la integración de la biblioteca `@callstack/liquid-glass`","Limitado a la funcionalidad de VoiceOver del iPhone","Puede requerir un ajuste manual del color y la sombra del texto para un contraste óptimo"],"fr":["Nécessite l''intégration de la bibliothèque `@callstack/liquid-glass`","Limité à la fonctionnalité VoiceOver de l''iPhone","Peut nécessiter un ajustement manuel de la couleur et de l''ombre du texte pour un contraste optimal"],"de":["Erfordert die Integration der Bibliothek `@callstack/liquid-glass`","Begrenzt auf die VoiceOver-Funktionalität des iPhones","Kann ein manuelles Anpassen der Textfarbe und -schatten für einen optimalen Kontrast erfordern"],"pt":["Exige integração da biblioteca `@callstack/liquid-glass`","Limitado à funcionalidade VoiceOver do iPhone","Pode exigir ajuste manual da cor do texto e da sombra para contraste ótimo"],"ru":["Требует интеграции библиотеки `@callstack/liquid-glass`","Ограничен функциональностью VoiceOver на iPhone","Может потребовать ручной настройки цвета текста и тени для оптимального контраста"],"ar":["يتطلب دمج مكتبة `@callstack/liquid-glass`","محدود بوظيفة VoiceOver على هاتف أيفون","قد يتطلب تعديلًا يدويًا للون النص والظل لتباين مثالي"]},"version":4},"contentHash":"8bda8418799a4393fe76c49516633614c4fd11da75f45aa03698edf6f29f62f4","qualityScore":33}');
