INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('takapom/trip-app/accessibility', 'accessibility', 'takapom', 'trip-app', 'community', 'accessibility takapom trip-app community The accessibility skill implements VoiceOver support and WCAG AA compliance for improved app usability, benefiting developers and users alike. 本文介绍提高无障碍访问的技术细节，包括Liquid Glass设计和WCAG AA标准 アクセシビリティ改善スキルを使用して、VoiceOver対応のアプリを開発できます 접근성 개선 설정 가이드는 AI 에이전트 도구를 사용하여 접근성 개선 설정을 구현하는 방법을 제공합니다 La accesibilidad es crucial para desarrolladores. Nuestra guía cubre aspectos técnicos como la compatibilidad con VoiceOver y el cumplimiento de la norma WCAG AA L''accessibilité est cruciale pour les développeurs. Notre guide couvre les aspects techniques tels que la compatibilité avec VoiceOver et le respect de la norme WCAG AA Die Barrierefreiheit ist für Entwickler von entscheidender Bedeutung. Unser Leitfaden behandelt technische Aspekte wie die Kompatibilität mit VoiceOver und die Einhaltung der WCAG-AA-Norm Melhore a acessibilidade em seus projetos de IA com dicas técnicas para React Native e WCAG AA. Улучшите доступность в ваших проектах ИИ с помощью технических советов для React Native и WCAG AA. حسّن إمكانية الوصول في مشاريع الذكاء الاصطناعي باستخدام نصائح تقنية لـ React Native و WCAG AA accessibility setup guide how to use VoiceOver WCAG AA compliance checklist accessibility vs usability Liquid Glass design tutorial accessibility install for react-native AI智能体验 无障碍访问 Liquid Glass设计 WCAG AA标准 React Native 自动适应文本颜色 文本阴影 字体粗细增强 Implements VoiceOver support for iPhone users Ensures WCAG AA compliance for text contrast and readability Utilizes Liquid Glass design with @callstack/liquid-glass Automatically adapts text color using PlatformColor(''labelColor'') Provides options for text shadow and font weight adjustment Accessibility is the practice of designing products to be usable by people with disabilities, ensuring equal access to information and functionality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kevincrabbe/wrapkit/general', 'community', 'kevincrabbe', 'wrapkit', 'kevincrabbe/wrapkit', 'general', 0, 0, 33, '2026-03-08T01:57:15.414Z', '2026-03-08T02:07:11.441Z', '0bebeeb88e536abf5756ba6eabb7be556e6e420044ffe6527d68716f2a0ba84d', '{"id":"kevincrabbe/wrapkit/general","name":"general","description":{"en":"The general skill provides guidelines for coding best practices, focusing on readability and performance. It benefits developers by ensuring correctness, maintainability, and efficiency in their code.","zh":"本指南提供了优化代码的可读性和性能的最佳实践，适用于所有开发项目","ja":"このガイドでは、すべての開発プロジェクトに適用できるコードの可読性とパフォーマンスの最適化方法を提供します","ko":"이 가이드는 모든 개발 프로젝트에 적용할 수 있는 코드의 가독성과 성능을 최적화하는 방법을 제공합니다","es":"El desarrollo general de agentes de IA requiere prioridades claras y comentarios efectivos. Aprende a equilibrar la legibilidad y el rendimiento","fr":"Le développement général des outils d''IA nécessite des priorités claires et des commentaires efficaces. Apprenez à équilibrer la lisibilité et les performances","de":"Die allgemeine Entwicklung von KI-Agenten erfordert klare Prioritäten und effektive Kommentare. Lernen Sie, Lesbarkeit und Leistung auszugleichen","pt":"Desenvolvimento geral para ferramentas de IA com foco em legibilidade e desempenho","ru":"Общая разработка для ИИ Агентов с фокусом на читаемости и производительности","ar":"التطوير العام لأدوات الذكاء الاصطناعي مع التركيز على سهولة القراءة والأداء"},"seo":{"title":{"en":"General: Code Readability Setup Guide | AI Agent Skill","zh":"通用开发指南 Setup Guide","ja":"汎用開発ガイド Best Practices","ko":"일반 개발 가이드 Setup Guide","es":"Guía de Configuración de Desarrollo General para Agentes ...","fr":"Guide de Mise en Place du Développement Général pour les ...","de":"Einrichtungsleitfaden für die Allgemeine Entwicklung von ...","pt":"Guia de Configuração de Desenvolvimento Geral para Ferram...","ru":"Настройка общих рекомендаций по разработке для ИИ Агентов","ar":"دليل إعداد التطوير العام لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to prioritize code readability and performance with the general AI agent skill. Learn best practices for commenting and coding","zh":"了解通用开发指南，优化代码的可读性和性能，AIエージェント开发最佳实践","ja":"汎用開発ガイドを学び、コードの可読性とパフォーマンスを最適化する、AIエージェント開発のベストプラクティス","ko":"일반 개발 가이드를 통해 코드의 가독성과 성능을 최적화하는 방법, AI Tools 개발 모범 사례","es":"Aprende las mejores prácticas para el desarrollo general de agentes de IA, incluyendo prioridades, comentarios y rendimiento","fr":"Découvrez les meilleures pratiques pour le développement général des outils d''IA, y compris les priorités, les commentaires et les performances","de":"Erfahren Sie die besten Praktiken für die allgemeine Entwicklung von KI-Agenten, einschließlich Prioritäten, Kommentaren und Leistung","pt":"Aprenda as melhores práticas para desenvolvimento geral com foco em legibilidade e desempenho para ferramentas de IA","ru":"Узнайте общие рекомендации по разработке с фокусом на читаемости и производительности для ИИ Агентов","ar":"تعرف على أفضل الممارسات لتطوير عام مع التركيز على سهولة القراءة والأداء لأدوات الذكاء الاصطناعي"},"definition":{"en":"General is a set of coding guidelines that prioritize readability and performance, emphasizing correctness, maintainability, and efficiency in software development.","zh":"通用开发指南是一套优化代码的可读性和性能的原则和实践","ja":"汎用開発ガイドは、コードの可読性とパフォーマンスを最適化するための原則と実践の集合","ko":"일반 개발 가이드는 코드의 가독성과 성능을 최적화하는 원칙과 방법의 집합","es":"Desarrollo general de agentes de IA: conjunto de pautas para garantizar la legibilidad, el rendimiento y la funcionalidad","fr":"Développement général des outils d''IA : ensemble de lignes directrices pour assurer la lisibilité, les performances et la fonctionnalité","de":"Allgemeine Entwicklung von KI-Agenten: Satz von Richtlinien für die Sicherstellung von Lesbarkeit, Leistung und Funktionalität","pt":"Desenvolvimento geral refere-se às diretrizes de codificação que priorizam legibilidade e desempenho","ru":"Общая разработка относится к рекомендациям по кодированию, которые отдают приоритет читаемости и производительности","ar":"التطوير العام يُشير إلى إرشادات الترميز التي تُفضل سهولة القراءة والأداء"},"features":{"en":["Prioritizes code readability and performance with a 80/20 focus","Enforces commenting guidelines to explain code purpose","Supports maintainability by emphasizing correctness and functionality","Promotes efficient coding practices through performance optimization","Provides guidelines for commenting obvious operations","Encourages developers to focus on code explainability"],"zh":["优化代码的可读性和性能","注重正确性和功能性","使用清晰的注释解释代码","避免不必要的注释","优先考虑代码的可维护性"],"ja":["コードの可読性とパフォーマンスを最適化","正しさと機能性を重視","明確なコメントを使用してコードを説明","不要なコメントを避ける","コードの保守性を優先"],"ko":["코드의 가독성과 성능을 최적화","정확성과 기능성을 중시","명확한 주석을 사용하여 코드를 설명","불필요한 주석을避ける","코드의 유지 보수성을 우선"],"es":["Priorización de la legibilidad y el rendimiento","Comentarios efectivos que explican el porqué, no el qué","Evitación de comentarios obvios","Enfoque en la corrección y funcionalidad","Mejora de la mantenibilidad del código"],"fr":["Priorisation de la lisibilité et des performances","Commentaires efficaces qui expliquent le pourquoi, pas le quoi","Évitement des commentaires évidents","Focalisation sur la correction et la fonctionnalité","Amélioration de la maintenabilité du code"],"de":["Priorisierung von Lesbarkeit und Leistung","Effektive Kommentare, die das Warum, nicht das Was erklären","Vermeidung von offensichtlichen Kommentaren","Fokus auf Korrektheit und Funktionalität","Verbesserung der Wartbarkeit des Codes"],"pt":["Priorização de legibilidade e desempenho","Uso de comentários para explicar o porquê, não o que","Evitar comentários para operações óbvias","Foco em correção e funcionalidade"],"ru":["Приоритет читаемости и производительности","Использование комментариев для объяснения почему, а не что","Избегание комментариев для очевидных операций","Фокус на исправлении и функциональности"],"ar":["التركيز على سهولة القراءة والأداء","استخدام التعليقات لشرح السبب، وليس ما","تجنب التعليقات للعمليات الواضحة","التركيز على التصحيح والوظيفة"]},"keywords":{"en":["how to use general coding guidelines","general coding best practices","general vs clean code","general install guide","general setup for developers","what is general coding","general alternative coding guidelines","general coding performance optimization","general readability guidelines","general coding efficiency tips"],"zh":["通用开发指南","代码优化","可读性","性能","AIエージェント开发","代码注释","代码维护"],"ja":["汎用開発ガイド","コード最適化","可読性","パフォーマンス","AIエージェント開発","コードコメント","コードメンテナンス"],"ko":["일반 개발 가이드","코드 최적화","가독성","성능","AI Tools 개발","코드 주석","코드 유지 보수"],"es":["desarrollo de agentes de IA","mejores prácticas de desarrollo","prioridades de desarrollo","comentarios de código","rendimiento de código","legibilidad de código","mantenibilidad de código","desarrollo de software","herramientas de IA"],"fr":["développement d''outils d''IA","meilleures pratiques de développement","priorités de développement","commentaires de code","performances de code","lisibilité de code","maintenabilité de code","développement de logiciels","outils d''IA"],"de":["Entwicklung von KI-Agenten","beste Praktiken für die Entwicklung","Prioritäten für die Entwicklung","Code-Kommentare","Code-Leistung","Code-Lesbarkeit","Code-Wartbarkeit","Software-Entwicklung","KI-Tools"],"pt":["desenvolvimento geral","ferramentas de IA","legibilidade","desempenho","comentários","codificação","recomendações de desenvolvimento","melhores práticas"],"ru":["общая разработка","ИИ Агенты","читаемость","производительность","комментарии","кодирование","рекомендации по разработке","лучшие практики"],"ar":["التطوير العام","أدوات الذكاء الاصطناعي","سهولة القراءة","الأداء","التعليقات","الترميز","توجيهات التطوير","أفضل الممارسات"]}},"owner":"kevincrabbe","repo":"wrapkit","repoPath":"kevincrabbe/wrapkit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.414Z","topics":[],"category":"community","skillMd":{"name":"general","description":"General development guidelines prioritizing readability over performance, with rules for meaningful comments. Use when writing any code in this project.","bodyPreview":"# General Development Guidelines\n\nApply these general guidelines to all code.\n\n## Priorities\n\nFocus 80% on readability and 20% on performance.\n\nIn order of importance:\n1. Correctness and functionality\n2. Readability & Maintainability\n3. Performance\n\n## Comments\n\nAdd comments only when they explain WHY, not WHAT. The code itself should be readable enough to show WHAT it does.\n\n### DO NOT comment obvious operations\n\n```typescript\n// Bad\n// increment counter\ncounter++;\n```\n\n### DO comment\n\n- Busine","body":"# General Development Guidelines\n\nApply these general guidelines to all code.\n\n## Priorities\n\nFocus 80% on readability and 20% on performance.\n\nIn order of importance:\n1. Correctness and functionality\n2. Readability & Maintainability\n3. Performance\n\n## Comments\n\nAdd comments only when they explain WHY, not WHAT. The code itself should be readable enough to show WHAT it does.\n\n### DO NOT comment obvious operations\n\n```typescript\n// Bad\n// increment counter\ncounter++;\n```\n\n### DO comment\n\n- Business logic reasoning\n- Non-obvious decisions\n- Workarounds or edge cases\n- Complex algorithms (brief summary of approach)\n\n### Example of a good comment\n\n```typescript\n// Using ceil() here because partial units must be charged as full units per billing policy\nconst billableUnits = Math.ceil(usage / unitSize);\n```\n"},"lastSynced":"2026-03-08T02:07:11.441Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced coding standards and best practices for readability and performance.","zh":"适合需要高级编码标准和最佳实践以提高可读性和性能的代码审查代理。","ja":"コードレビュー代理が高度なコーディング規範とベストプラクティスを必要とする場合に最適です。可読性とパフォーマンスを向上させるためのものです。","ko":"코드 리뷰 에이전트가 고급 코딩 표준과 가독성 및 성능을 위한 최고의 관행을 필요로 할 경우 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan estándares de codificación avanzados y mejores prácticas para la legibilidad y el rendimiento.","fr":"Parfait pour les Agents de Révision de Code ayant besoin de normes de codage avancées et de meilleures pratiques pour la lisibilité et les performances.","de":"Perfekt für Code-Review-Agents, die erweiterte Codierungsstandards und Best Practices für Lesbarkeit und Leistung benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de padrões de codificação avançados e melhores práticas para legibilidade e desempenho.","ru":"Идеально для агентов проверки кода, которым необходимы продвинутые стандарты кодирования и лучшие практики для читаемости и производительности.","ar":"مثالي لعميل مراجعة الكود الذين يحتاجون إلى معايير برمجة متقدمة وأفضل ممارسات للقراءة والأداء."},"recommendation":{"en":"Empowers agents to prioritize correctness, maintainability, and efficiency in code development, utilizing guidelines for commenting and performance optimization, focusing on readability and functionality.","zh":"赋予代理优先考虑正确性、可维护性和效率在代码开发中的能力，利用注释和性能优化的指南，专注于可读性和功能。","ja":"コード開発において正しさ、保守性、効率性を優先するエージェントを可能にし、コメントとパフォーマンス最適化のガイドラインを利用し、可読性と機能に焦点を当てます。","ko":"에이전트가 코드 개발에서 올바름, 유지 보수, 효율성을 우선시할 수 있도록 하며, 주석 및 성능 최적화 지침을 사용하여 가독성 및 기능에 중점을 둡니다.","es":"Habilita a los agentes a priorizar la corrección, la mantenibilidad y la eficiencia en el desarrollo de código, utilizando directrices para comentarios y optimización del rendimiento, centrándose en la legibilidad y la funcionalidad.","fr":"Permet aux agents de donner la priorité à la correction, à la maintenabilité et à l''efficacité dans le développement de code, en utilisant des directives pour les commentaires et l''optimisation des performances, en se concentrant sur la lisibilité et la fonctionnalité.","de":"Ermächtigt die Agenten, Korrektheit, Wartbarkeit und Effizienz in der Code-Entwicklung zu priorisieren, unter Nutzung von Richtlinien für Kommentare und Leistungsoptimierung, mit Fokus auf Lesbarkeit und Funktionalität.","pt":"Habilita os agentes a priorizar a correção, a manutenção e a eficiência no desenvolvimento de código, utilizando diretrizes para comentários e otimização de desempenho, com foco na legibilidade e funcionalidade.","ru":"Наделяет агентов возможностью уделять приоритетное внимание правильности, поддерживаемости и эффективности при разработке кода, используя руководящие принципы для комментариев и оптимизации производительности, сосредотачиваясь на читаемости и функциональности.","ar":"يمنح الوكلاء القدرة على إعطاء الأولوية الصحة والصيانة والكفاءة في تطوير الكود، باستخدام إرشادات للتعليقات وتحسين الأداء، مع التركيز على القراءة والوظائف."},"useCases":{"en":["Enforcing coding standards for team collaboration","Improving code readability and maintainability","Optimizing performance while ensuring correctness"],"zh":["强制执行团队协作的编码标准","提高代码可读性和可维护性","在确保正确性的同时优化性能"],"ja":["チームコラボレーションのコーディング規範を適用する","コードの可読性と保守性を向上させる","正しさを確保しながらパフォーマンスを最適化する"],"ko":["팀 협업을 위한 코딩 표준 적용","코드 가독성 및 유지 보수성 향상","올바름을 보장하면서 성능 최적화"],"es":["Aplicar estándares de codificación para la colaboración en equipo","Mejorar la legibilidad y mantenibilidad del código","Optimizar el rendimiento garantizando la corrección"],"fr":["Mettre en œuvre des normes de codage pour la collaboration d''équipe","Améliorer la lisibilité et la maintenabilité du code","Optimiser les performances tout en garantissant la correction"],"de":["Durchsetzen von Codierungsstandards für Teamzusammenarbeit","Verbesserung der Lesbarkeit und Wartbarkeit von Code","Optimierung der Leistung unter Gewährleistung der Korrektheit"],"pt":["Aplicar padrões de codificação para colaboração em equipe","Melhorar a legibilidade e manutenção do código","Otimizar o desempenho garantindo a correção"],"ru":["Применение стандартов кодирования для командного сотрудничества","Улучшение читаемости и поддерживаемости кода","Оптимизация производительности при обеспечении правильности"],"ar":["تطبيق معايير البرمجة للتعاون الفريق","تحسين قراءة الكود والصيانة","تحسين الأداء مع ضمان الصحة"]},"limitations":{"en":["Requires adherence to specific commenting guidelines","Focus on TypeScript examples"],"zh":["需要遵守特定的注释指南","专注于TypeScript示例"],"ja":["特定のコメントガイドラインに従う必要がある","TypeScriptの例に焦点を当てている"],"ko":["특정 주석 지침을 따라야 함","TypeScript 예제에 중점을 두고 있음"],"es":["Requiere adherirse a directrices de comentarios específicas","Enfocarse en ejemplos de TypeScript"],"fr":["Nécessite d''adhérer à des directives de commentaires spécifiques","Se concentrer sur des exemples de TypeScript"],"de":["Erfordert die Einhaltung spezifischer Kommentar-Richtlinien","Fokus auf TypeScript-Beispiele"],"pt":["Exige aderência a diretrizes específicas de comentários","Foco em exemplos de TypeScript"],"ru":["Требует соблюдения конкретных руководящих принципов для комментариев","Фокус на примерах TypeScript"],"ar":["يتطلب الالتزام بإرشادات محددة للتعليقات","التركيز على أمثلة من TypeScript"]},"version":4},"contentHash":"0bebeeb88e536abf5756ba6eabb7be556e6e420044ffe6527d68716f2a0ba84d","qualityScore":33}');
