INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Sri-Krishna-V/Derived-WMD/creating-styled-wrappers', 'creating-styled-wrappers', 'Sri-Krishna-V', 'Derived-WMD', 'community', 'creating-styled-wrappers Sri-Krishna-V Derived-WMD community The creating-styled-wrappers skill helps developers create styled wrapper components that complement base primitives, focusing on proper consumption and wrapping with styling and behavior. 创建样式包装器，组合头部组件，并实现React应用的快速开发 スタイル付きラッパーを作成し、ヘッドレスベースのコンポーネントを組み合わせてReactアプリを迅速に開発 스타일된 래퍼를 생성하여 헤드리스 컴포넌트를 구성하고 React 애플리케이션 개발을 가속화 La creación de envolturas estilizadas permite combinar componentes de React con estilos y comportamientos personalizados La création d''envoltures stylisées permet de combiner des composants React avec des styles et des comportements personnalisés Die Erstellung von gestylten Wrappern ermöglicht die Kombination von React-Komponenten mit benutzerdefinierten Stilen und Verhaltensweisen O skill de criar wrappers estilizados permite compor componentes React com estilos e comportamentos adicionais, melhorando a experiência do usuário Навык создания стилизованных оболочек позволяет композировать компоненты React с стилями и дополнительным поведением, улучшая пользовательский опыт مهارة إنشاء حاويات مصممة تسمح بتركيب مكونات React مع أنماط و سلوكيات إضافية، مما يحسن تجربة المستخدم how to use creating-styled-wrappers creating-styled-wrappers react styled wrapper components creating-styled-wrappers alternative creating-styled-wrappers setup guide creating-styled-wrappers vs building-compound-components creating-styled-wrappers install react app development with creating-styled-wrappers creating-styled-wrappers tutorial creating-styled-wrappers documentation 创建样式包装器 Agentic Generative UI Platform React应用开发 Model Context Protocol E2B沙箱执行 自主Tambo代理 AIエージェント React组件 Creates styled wrapper components that compose headless base compound components Utilizes autonomous Tambo agents for efficient component creation Leverages Model Context Protocol (MCP) for codebase grounding Supports secure E2B sandboxed execution for reliable deployment Complements the building-compound-components skill for comprehensive React app development Provides a real-world example for refactoring MessageInput components creating-styled-wrappers is a skill that enables the creation of styled wrapper components for React apps, utilizing autonomous Tambo agents and Model Context Protocol (MCP)');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Schwartz10/llm-council-mcp/llm-council-context', 'community', 'Schwartz10', 'llm-council-mcp', 'Schwartz10/llm-council-mcp', 'llm-council-context', 0, 0, 33, '2026-03-08T01:57:15.417Z', '2026-03-08T02:07:16.492Z', '2efe2adf448fcd9ac47ff175e94e9f8d6d05bb434deaf41cc9828c7bd4b55e0f', '{"id":"Schwartz10/llm-council-mcp/llm-council-context","name":"llm-council-context","description":{"en":"The llm-council-context skill provides high-signal context for consult_llm_council requests, focusing on context budgeting and structured information. It benefits AI developers and users by outsourcing decisions to a multi-member AI council when necessary.","zh":"LLM Council Context 技术提供了结构化的信息和决策支持，帮助开发者优化 AI 工具的性能","ja":"LLM Council Context 技術は、構造化された情報と意思決定支援を提供し、開発者が AI エージェントのパフォーマンスを最適化できるようにします","ko":"LLM Council Context 기술은 구조화된 정보와 의사결정 지원을 제공하여 개발자가 효율적인 AI 도구를 개발할 수 있도록 합니다","es":"LLM Council Context es una habilidad que proporciona un resumen estructurado para solicitudes de consulta al consejo de IA, mejorando la toma de decisiones","fr":"LLM Council Context est une compétence qui fournit un résumé structuré pour les demandes de consultation au conseil d''IA, améliorant la prise de décision","de":"LLM Council Context ist eine Fähigkeit, die einen strukturierten Zusammenfassung für Anfragen an den KI-Rat bereitstellt, um die Entscheidungsfindung zu verbessern","pt":"O LLM Council Context é uma habilidade de IA que fornece contexto conciso e de alta qualidade para solicitações de consultoria. Ele se concentra em orçamento de contexto, estruturação de informações e evitação de truncamento.","ru":"LLM Council Context - это навык ИИ, который предоставляет краткий и высококачественный контекст для запросов на консультацию. Он фокусируется на бюджете контекста, структуризации информации и избегании обрезания.","ar":"سياق مجلس LLM هو مهارة ذكاء اصطناعي توفر سياقاً موجزاً وعالية الجودة لطلبات الاستشارة. انها تركز على ميزانية السياق وتنظيم المعلومات وتجنب تقطيع المعلومات."},"seo":{"title":{"en":"llm-council-context: Context Budgeting for AI Agents | AI...","zh":"LLM Council Context 技术指南：高效决策的 AI 工具","ja":"LLM Council Context のベストプラクティス：AIエージェントのためのコンテキスト管理","ko":"LLM Council Context 설정 가이드: 효율적인 의사결정을 위한 AI 도구","es":"Guía de Configuración de LLM Council Context para Agentes...","fr":"Guide de Mise en Place de LLM Council Context pour Outils...","de":"Einrichtungsleitfaden für LLM Council Context bei KI-Tools","pt":"Guia de Configuração para LLM Council Context - Ferrament...","ru":"Руководство по настройке LLM Council Context - ИИ Агенты","ar":"دليل إعداد سياق مجلس LLM - أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how llm-council-context optimizes AI decision-making with concise context and structured summaries. Learn how to implement it today!","zh":"了解 LLM Council Context 技术的核心指导原则，优化您的 AI 工具的决策过程","ja":"LLM Council Context のコアガイダンスを学び、AIエージェントのパフォーマンスを向上させる","ko":"LLM Council Context 기술의 핵심 지침을 익히고 효율적인 의사결정을 위한 AI 도구를 개발하세요","es":"Aprende a configurar LLM Council Context para mejorar la toma de decisiones en tus proyectos de IA con esta guía detallada","fr":"Découvrez comment configurer LLM Council Context pour améliorer la prise de décision dans vos projets d''IA avec ce guide détaillé","de":"Erfahren Sie, wie Sie LLM Council Context einrichten, um die Entscheidungsfindung in Ihren KI-Projekten zu verbessern","pt":"Aprenda a configurar o LLM Council Context para melhorar a tomada de decisões com IA. Descubra como otimizar o orçamento de contexto e evitar truncamento de ...","ru":"Узнайте, как настроить LLM Council Context для улучшения принятия решений с помощью ИИ. Откройте для себя, как оптимизировать бюджет контекста и избежать обр...","ar":"تعلم كيفية إعداد سياق مجلس LLM لتحسين اتخاذ القرارات بالذكاء الاصطناعي. اكتشف كيفية تحسين ميزانية السياق وتجنب تقطيع المعلومات."},"definition":{"en":"llm-council-context is a skill that enables personal and private AI leaders to outsource decisions to a multi-member AI council, utilizing persistent memory and context budgeting.","zh":"LLM Council Context 是一种 AI 技术，提供结构化的信息和决策支持","ja":"LLM Council Context は、構造化された情報と意思決定支援を提供する AI 技術です","ko":"LLM Council Context는 구조화된 정보와 의사결정 지원을 제공하는 AI 기술입니다","es":"LLM Council Context es una habilidad de IA que proporciona contexto conciso para solicitudes de consulta al consejo de IA","fr":"LLM Council Context est une compétence d''IA qui fournit un contexte concis pour les demandes de consultation au conseil d''IA","de":"LLM Council Context ist eine KI-Fähigkeit, die einen präzisen Kontext für Anfragen an den KI-Rat bereitstellt","pt":"O que é LLM Council Context? É uma habilidade de IA que fornece contexto para solicitações de consultoria, otimizando o orçamento de contexto e evitando truncamento de informações.","ru":"Что такое LLM Council Context? Это навык ИИ, который предоставляет контекст для запросов на консультацию, оптимизируя бюджет контекста и избегая обрезания информации.","ar":"ما هو سياق مجلس LLM؟ هو مهارة ذكاء اصطناعي توفر سياقاً لطلبات الاستشارة، وتحسين ميزانية السياق وتجنب تقطيع المعلومات."},"features":{"en":["Provides concise, high-signal context for consult_llm_council requests","Focuses on context budgeting and structuring information","Avoids truncation or irrelevant details in summaries","Reserves budget for model responses","Leads with goal and constraints in summaries","Includes only the most relevant excerpts in summaries"],"zh":["结构化的信息提供","决策支持","避免信息截断或不相关细节","预留模型响应预算","短结构化摘要"],"ja":["構造化された情報の提供","意思決定支援","情報の切り捨てや無関係な詳細の回避","モデル応答予算の予約","短い構造化されたサマリー"],"ko":["구조화된 정보 제공","의사결정 지원","정보截断이나 무関係한 세부사항 피하기","모델 응답 예산 예약","짧은 구조화된 요약"],"es":["Proporciona un resumen estructurado para solicitudes de consulta al consejo de IA","Mejora la toma de decisiones con un enfoque en la asignación de contexto","Evita la truncación o la inclusión de detalles irrelevantes","Reserva presupuesto para la respuesta del modelo","Permite la selección de modelo específico para la consulta","Incluye solo los extractos más relevantes"],"fr":["Fournit un résumé structuré pour les demandes de consultation au conseil d''IA","Améliore la prise de décision avec un focus sur l''allocation de contexte","Évite la troncation ou l''inclusion de détails non pertinents","Réserve un budget pour la réponse du modèle","Permet la sélection d''un modèle spécifique pour la consultation","Inclut seulement les extraits les plus pertinents"],"de":["Bietet eine strukturierte Zusammenfassung für Anfragen an den KI-Rat","Verbessert die Entscheidungsfindung durch einen Fokus auf die Kontextzuweisung","Vermeidet die Trunkierung oder die Einbeziehung nicht relevanter Details","Reserviert ein Budget für die Modellantwort","Ermöglicht die Auswahl eines spezifischen Modells für die Anfrage","Enthält nur die relevantesten Auszüge"],"pt":["Orçamento de contexto otimizado","Estruturação de informações para evitar truncamento","Inclusão de apenas as informações mais relevantes","Reserva de orçamento para a resposta do modelo"],"ru":["Оптимизированный бюджет контекста","Структуризация информации для избегания обрезания","Включение только наиболее актуальных сведений","Резервирование бюджета для ответа модели"],"ar":["تحسين ميزانية السياق","تنظيم المعلومات لتجنب تقطيع المعلومات","إدراج المعلومات الأكثر صلة فقط","تحفيز ميزانية لاستجابة النموذج"]},"keywords":{"en":["how to use llm-council-context","llm-council-context setup guide","what is llm-council-context","llm-council-context alternative","llm-council-context vs other AI skills","consult_llm_council requests","context budgeting for AI agents","structured summaries for AI decision-making"],"zh":["LLM Council Context","AI 工具","结构化信息","决策支持","AI 技术","信息截断","模型响应预算"],"ja":["LLM Council Context","AIエージェント","構造化情報","意思決定支援","AI 技術","情報の切り捨て","モデル応答予算"],"ko":["LLM Council Context","AI 도구","구조화된 정보","의사결정 지원","AI 기술","정보截断","모델 응답 예산"],"es":["LLM Council Context","Agentes de Inteligencia Artificial","Herramientas de IA","Toma de decisiones","Asignación de contexto","Configuración de LLM","Desarrollo de IA","Inteligencia Artificial","IA y Machine Learning"],"fr":["LLM Council Context","Outils d''Intelligence Artificielle","Agents d''IA","Prise de décision","Allocation de contexte","Configuration de LLM","Développement d''IA","Intelligence Artificielle","IA et Machine Learning"],"de":["LLM Council Context","KI-Tools","KI-Agenten","Entscheidungsfindung","Kontextzuweisung","Einrichtung von LLM","KI-Entwicklung","Künstliche Intelligenz","KI und Machine Learning"],"pt":["LLM Council Context","Ferramentas de IA","Orçamento de contexto","Estruturação de informações","Tomada de decisões com IA","Otimização de contexto","Truncamento de informações"],"ru":["LLM Council Context","ИИ Агенты","Бюджет контекста","Структуризация информации","Принятие решений с помощью ИИ","Оптимизация контекста","Обрезание информации"],"ar":["سياق مجلس LLM","أدوات الذكاء الاصطناعي","ميزانية السياق","تنظيم المعلومات","اتخاذ القرارات بالذكاء الاصطناعي","تحسين السياق","تقطيع المعلومات"]}},"owner":"Schwartz10","repo":"llm-council-mcp","repoPath":"Schwartz10/llm-council-mcp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.417Z","topics":[],"category":"community","skillMd":{"name":"llm-council-context","description":"Guidance for crafting high-quality context when using the consult_llm_council MCP tool. Use when a user wants help preparing context, summarizing files, or structuring prompts for council consultations.","bodyPreview":"# LLM Council Context Skill\n\n## Overview\n\nProvide concise, high-signal context for `consult_llm_council` requests. This skill focuses on context budgeting, structuring information, and avoiding truncation or irrelevant details.\n\n## Core Guidance\n\n- Prefer a short, structured summary over raw dumps.\n- Lead with the goal and constraints.\n- Include only the most relevant excerpts.\n- Reserve budget for the model response.\n\n## Model Selection Flow\n\nIf the user requests a specific model (e.g., \"use Cl","body":"# LLM Council Context Skill\n\n## Overview\n\nProvide concise, high-signal context for `consult_llm_council` requests. This skill focuses on context budgeting, structuring information, and avoiding truncation or irrelevant details.\n\n## Core Guidance\n\n- Prefer a short, structured summary over raw dumps.\n- Lead with the goal and constraints.\n- Include only the most relevant excerpts.\n- Reserve budget for the model response.\n\n## Model Selection Flow\n\nIf the user requests a specific model (e.g., \"use Claude\" or \"use Anthropic\"), translate that intent into the `models` array for `consult_llm_council`.\n\nWhen model names are uncertain, use this flow:\n1. Call `list_models` to retrieve the exact available model names.\n2. Pass one or more returned names to `consult_llm_council` via the `models` parameter.\n\nThis avoids guessing and ensures the server accepts the model selection.\n\n## Recommended Brief\n\nUse a concise schema for repeatable structure:\n\n```typescript\ninterface ContextBrief {\n  goal: string;\n  constraints: string[];\n  relevant_facts: string[];\n  avoid: string[];\n}\n```\n\n## When To Load The Reference Guide\n\nOpen `references/CONTEXT_GUIDE.md` when:\n\n- The user asks how to share context or what to include\n- You need concrete examples (code review, PR review, architecture decision, bug fix, feature request)\n- You need truncation/budget examples or provider context limits\n\n## How To Use This Skill\n\n1. Gather the user’s goal, constraints, and the minimal relevant facts.\n2. Propose a concise ContextBrief if none is provided.\n3. Suggest what to omit or summarize to stay within budget.\n4. If the context is large, include a short summary + targeted excerpts.\n\n## Resources\n\n- `references/CONTEXT_GUIDE.md`: Full context-sharing guide with budgets, truncation examples, and scenario templates.\n"},"lastSynced":"2026-03-08T02:07:16.492Z","agentAnalysis":{"suitability":{"en":"Ideal for Decision-Making Agents requiring optimized multi-LLM consultation workflows.","zh":"非常适合需要优化多LLM咨询工作流程的决策型Agent。","ja":"最適化されたマルチLLM相談ワークフローを必要とする意思決定エージェントに理想的です。","ko":"최적화된 다중 LLM 협의 워크플로우가 필요한 의사 결정 에이전트에 이상적입니다.","es":"Ideal para agentes de toma de decisiones que requieren flujos de trabajo optimizados de consulta multi-LLM.","fr":"Idéal pour les agents de prise de décision nécessitant des flux de travail de consultation multi-LLM optimisés.","de":"Ideal für Entscheidungsfindungs-Agents, die optimierte Multi-LLM-Konsultations-Workflows benötigen.","pt":"Ideal para Agentes de Tomada de Decisão que requerem workflows otimizados de consulta multi-LLM.","ru":"Идеально подходит для Принятия Решений Агентами, требующими оптимизированных рабочих процессов консультаций с несколькими LLM.","ar":"مثالي لوكلاء صنع القرار الذين يتطلبون سير عمل استشارات متعددة نماذج اللغة الكبيرة (LLM) مُحسّنة."},"recommendation":{"en":"Enables agents to implement context budgeting and structured information delivery for consult_llm_council requests, ensuring high-signal context while avoiding truncation and irrelevant details in multi-member AI council consultations.","zh":"使Agent能够为consult_llm_council请求实施上下文预算和结构化信息传递，确保在多成员AI委员会咨询中提供高价值上下文，同时避免截断和无关细节。","ja":"エージェントがconsult_llm_councilリクエストに対してコンテキスト予算編成と構造化された情報提供を実装できるようにし、高シグナルのコンテキストを確保しながら、多メンバーAI評議会での相談における切り捨てと無関係な詳細を回避します。","ko":"에이전트가 consult_llm_council 요청에 대해 컨텍스트 예산 책정 및 구조화된 정보 전달을 구현할 수 있도록 하여, 다중 구성원 AI 위원회 협의에서 고신호 컨텍스트를 보장하는 동시에 잘림 및 무관한 세부 사항을 방지합니다.","es":"Permite a los agentes implementar presupuestación de contexto y entrega estructurada de información para solicitudes consult_llm_council, asegurando contexto de alta señal mientras se evita el truncamiento y los detalles irrelevantes en consultas de consejos de IA con múltiples miembros.","fr":"Permet aux agents de mettre en œuvre une budgétisation du contexte et une livraison structurée de l''information pour les requêtes consult_llm_council, garantissant un contexte à haut signal tout en évitant la troncation et les détails non pertinents dans les consultations de conseils d''IA multi-membres.","de":"Ermöglicht es Agents, Kontext-Budgetierung und strukturierte Informationslieferung für consult_llm_council-Anfragen zu implementieren, um einen hochwertigen Kontext zu gewährleisten und gleichzeitig Kürzungen und irrelevante Details in Multi-Member-KI-Ratskonsultationen zu vermeiden.","pt":"Permite que os agentes implementem orçamentação de contexto e entrega estruturada de informação para pedidos consult_llm_council, garantindo contexto de alto sinal enquanto evita truncamento e detalhes irrelevantes em consultas de conselhos de IA com múltiplos membros.","ru":"Позволяет агентам реализовывать бюджетирование контекста и структурированную доставку информации для запросов consult_llm_council, обеспечивая высокоинформативный контекст, избегая усечения и нерелевантных деталей в консультациях совета ИИ с несколькими участниками.","ar":"يمكن الوكلاء من تنفيذ ميزانية السياق وتقديم المعلومات المنظمة لطلبات consult_llm_council، مما يضمن سياقًا عالي الإشارة مع تجنب الاقتطاع والتفاصيل غير ذات الصلة في استشارات مجلس الذكاء الاصطناعي متعدد الأعضاء."},"useCases":{"en":["Optimizing context allocation for complex decision-making","Structuring information for multi-model consultations","Avoiding context truncation in council requests","Providing concise summaries for LLM council deliberations"],"zh":["优化复杂决策的上下文分配","为多模型咨询构建信息结构","避免委员会请求中的上下文截断","为LLM委员会审议提供简洁摘要"],"ja":["複雑な意思決定のためのコンテキスト割り当ての最適化","マルチモデル相談のための情報構造化","評議会リクエストにおけるコンテキストの切り捨ての回避","LLM評議会審議のための簡潔な要約の提供"],"ko":["복잡한 의사 결정을 위한 컨텍스트 할당 최적화","다중 모델 협의를 위한 정보 구조화","위원회 요청에서 컨텍스트 잘림 방지","LLM 위원회 심의를 위한 간결한 요약 제공"],"es":["Optimización de la asignación de contexto para la toma de decisiones complejas","Estructuración de la información para consultas multi-modelo","Evitar el truncamiento de contexto en solicitudes de consejo","Proporcionar resúmenes concisos para deliberaciones de consejos de LLM"],"fr":["Optimisation de l''allocation du contexte pour une prise de décision complexe","Structuration de l''information pour les consultations multi-modèles","Éviter la troncation du contexte dans les demandes de conseil","Fournir des résumés concis pour les délibérations des conseils LLM"],"de":["Optimierung der Kontextzuweisung für komplexe Entscheidungsfindung","Strukturierung von Informationen für Multi-Model-Konsultationen","Vermeidung von Kontextkürzungen in Ratsanfragen","Bereitstellung prägnanter Zusammenfassungen für LLM-Ratsberatungen"],"pt":["Otimização da alocação de contexto para tomada de decisão complexa","Estruturação de informação para consultas multi-modelo","Evitar truncamento de contexto em pedidos de conselho","Fornecer resumos concisos para deliberações do conselho LLM"],"ru":["Оптимизация распределения контекста для сложного принятия решений","Структурирование информации для консультаций с несколькими моделями","Избежание усечения контекста в запросах совета","Предоставление сжатых итогов для обсуждений совета LLM"],"ar":["تحسين تخصيص السياق لصنع القرار المعقد","هيكلة المعلومات للاستشارات متعددة النماذج","تجنب اقتطاع السياق في طلبات المجلس","توفير ملخصات موجزة للمداولات في مجلس نماذج اللغة الكبيرة (LLM)"]},"limitations":{"en":["Requires consult_llm_council integration","Dependent on context budgeting strategies","Limited to structured information delivery scenarios"],"zh":["需要集成consult_llm_council","依赖于上下文预算策略","仅限于结构化信息传递场景"],"ja":["consult_llm_councilの統合が必要","コンテキスト予算編成戦略に依存","構造化された情報提供シナリオに限定"],"ko":["consult_llm_council 통합 필요","컨텍스트 예산 책정 전략에 의존","구조화된 정보 전달 시나리오로 제한됨"],"es":["Requiere integración con consult_llm_council","Depende de estrategias de presupuestación de contexto","Limitado a escenarios de entrega de información estructurada"],"fr":["Nécessite une intégration consult_llm_council","Dépend des stratégies de budgétisation du contexte","Limité aux scénarios de livraison d''information structurée"],"de":["Erfordert consult_llm_council-Integration","Abhängig von Kontext-Budgetierungsstrategien","Beschränkt auf Szenarien mit strukturierter Informationslieferung"],"pt":["Requer integração consult_llm_council","Dependente de estratégias de orçamentação de contexto","Limitado a cenários de entrega de informação estruturada"],"ru":["Требует интеграции consult_llm_council","Зависит от стратегий бюджетирования контекста","Ограничено сценариями структурированной доставки информации"],"ar":["يتطلب تكاملاً مع consult_llm_council","يعتمد على استراتيجيات ميزانية السياق","يقتصر على سيناريوهات تقديم المعلومات المنظمة"]},"version":4},"contentHash":"2efe2adf448fcd9ac47ff175e94e9f8d6d05bb434deaf41cc9828c7bd4b55e0f","qualityScore":33}');
