INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Schwartz10/llm-council-mcp/llm-council-context', 'llm-council-context', 'Schwartz10', 'llm-council-mcp', 'community', 'llm-council-context Schwartz10 llm-council-mcp community The llm-council-context skill provides high-signal context for consult_llm_council requests, focusing on context budgeting and structured information. It benefits AI developers and users by outsourcing decisions to a multi-member AI council when necessary. LLM Council Context 技术提供了结构化的信息和决策支持，帮助开发者优化 AI 工具的性能 LLM Council Context 技術は、構造化された情報と意思決定支援を提供し、開発者が AI エージェントのパフォーマンスを最適化できるようにします LLM Council Context 기술은 구조화된 정보와 의사결정 지원을 제공하여 개발자가 효율적인 AI 도구를 개발할 수 있도록 합니다 LLM Council Context es una habilidad que proporciona un resumen estructurado para solicitudes de consulta al consejo de IA, mejorando la toma de decisiones LLM Council Context est une compétence qui fournit un résumé structuré pour les demandes de consultation au conseil d''IA, améliorant la prise de décision LLM Council Context ist eine Fähigkeit, die einen strukturierten Zusammenfassung für Anfragen an den KI-Rat bereitstellt, um die Entscheidungsfindung zu verbessern O LLM Council Context é uma habilidade de IA que fornece contexto conciso e de alta qualidade para solicitações de consultoria. Ele se concentra em orçamento de contexto, estruturação de informações e evitação de truncamento. LLM Council Context - это навык ИИ, который предоставляет краткий и высококачественный контекст для запросов на консультацию. Он фокусируется на бюджете контекста, структуризации информации и избегании обрезания. سياق مجلس LLM هو مهارة ذكاء اصطناعي توفر سياقاً موجزاً وعالية الجودة لطلبات الاستشارة. انها تركز على ميزانية السياق وتنظيم المعلومات وتجنب تقطيع المعلومات. how to use llm-council-context llm-council-context setup guide what is llm-council-context llm-council-context alternative llm-council-context vs other AI skills consult_llm_council requests context budgeting for AI agents structured summaries for AI decision-making LLM Council Context AI 工具 结构化信息 决策支持 AI 技术 信息截断 模型响应预算 Provides concise, high-signal context for consult_llm_council requests Focuses on context budgeting and structuring information Avoids truncation or irrelevant details in summaries Reserves budget for model responses Leads with goal and constraints in summaries Includes only the most relevant excerpts in summaries llm-council-context is a skill that enables personal and private AI leaders to outsource decisions to a multi-member AI council, utilizing persistent memory and context budgeting.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tegnike/ai-agent-game-streamer/verify-game', 'community', 'tegnike', 'ai-agent-game-streamer', 'tegnike/ai-agent-game-streamer', 'verify-game', 0, 0, 33, '2026-03-08T01:57:15.417Z', '2026-03-08T02:07:18.554Z', '3d4d29743c0fb97a3a148ebd753de7efed369535c88ebe3f68cc7728a1f69dec', '{"id":"tegnike/ai-agent-game-streamer/verify-game","name":"verify-game","description":{"en":"The verify-game skill verifies and fixes games to ensure play-game agents can clear them without issues, benefiting AI agent developers and gamers alike.","zh":"verify-game技能是用于确保AIエージェント能够顺利完成游戏的技术","ja":"verify-gameスキルは、AIエージェントがゲームをクリアできることを保証する技術です","ko":"verify-game 스킬은 AI 툴이 게임을 클리어할 수 있도록 보장하는 기술입니다","es":"Verify-game es un skill que verifica y soluciona problemas en juegos para garantizar que los agentes de IA puedan completarlos","fr":"Verify-game est une compétence qui vérifie et résout les problèmes de jeux pour garantir que les agents d''IA puissent les compléter","de":"Verify-game ist eine Fähigkeit, die Spiele überprüft und Probleme behebt, um sicherzustellen, dass KI-Agenten sie abschließen können","pt":"O verify-game é uma ferramenta de verificação de jogos que garante que os agentes de IA possam jogar sem problemas. Ele lê o código-fonte do jogo e executa ações para garantir que o jogo seja jogável.","ru":"Verify-game - это инструмент проверки игр, который гарантирует, что ИИ агенты могут играть без проблем. Он читает исходный код игры и выполняет действия, чтобы гарантировать, что игра является играбельной.","ar":"verify-game هو أداة للتحقق من الألعاب التي تضمن أن يكون بإمكان وكلاء الذكاء الاصطناعي لعب بدون مشاكل. إنه يقرأ код مصدر اللعبة وينفذ إجراءات لضمان أن تكون اللعبة قابلة للعب."},"seo":{"title":{"en":"verify-game: Game Verification and Fix Setup Guide | AI A...","zh":"verify-game技能设置指南：确保游戏无障碍","ja":"verify-gameスキル設定ガイド：ゲームクリアの保証","ko":"verify-game 스킬 설정 가이드: 게임 클리어 보장","es":"Guía de configuración de verify-game para agentes de IA","fr":"Configurer verify-game pour les agents d''IA : Guide de mi...","de":"Einrichtung von verify-game für KI-Agenten: Leitfaden","pt":"Guia de Configuração do verify-game: Solução de Verificaç...","ru":"Настройка verify-game: Руководство по проверке игр для ИИ...","ar":"دليل إعداد verify-game: أداة التحقق من الألعاب للوكلاء ال..."},"description":{"en":"Discover how verify-game ensures play-game agents clear games without getting stuck. Learn how to setup and utilize this skill for seamless game verification...","zh":"了解verify-game技能的技术细节，确保AIエージェント的游戏体验无障碍","ja":"verify-gameスキルの技術的詳細を学び、AIエージェントのゲーム体験をスムーズに","ko":"verify-game 스킬의 기술적 세부 사항을 알아보고 AI 툴의 게임 경험을 무장애로","es":"Aprende a configurar verify-game para garantizar que los agentes de IA puedan jugar y completar juegos sin problemas","fr":"Découvrez comment configurer verify-game pour assurer que les agents d''IA puissent jouer et compléter des jeux sans encombre","de":"Erfahren Sie, wie Sie verify-game einrichten, um sicherzustellen, dass KI-Agenten Spiele spielen und abschließen können, ohne Probleme zu haben","pt":"Aprenda a configurar o verify-game para garantir que os agentes de IA possam jogar sem problemas. Descubra como essa ferramenta de verificação de jogos melho...","ru":"Узнайте, как настроить verify-game, чтобы гарантировать, что ИИ агенты могут играть без проблем. Откройте для себя, как этот инструмент проверки игр улучшает...","ar":"تعلم كيفية إعداد verify-game لضمان أن يكون بإمكان وكلاء الذكاء الاصطناعي لعب بدون مشاكل. اكتشف كيف تحسن أداة التحقق من الألعاب تجربة اللعب."},"definition":{"en":"verify-game is a skill that verifies game clearance and fixes issues to guarantee play-game agents can complete games without getting stuck.","zh":"verify-game技能是一种用于验证和修复游戏的技术，确保AIエージェント的游戏体验无障碍","ja":"verify-gameスキルは、ゲームを検証し修正する技術であり、AIエージェントのゲーム体験をスムーズにします","ko":"verify-game 스킬은 게임을 검증하고 수정하는 기술로 AI 툴의 게임 경험을 무장애로 합니다","es":"Verify-game es una habilidad que verifica la jugabilidad de los juegos y soluciona problemas para garantizar la completitud","fr":"Verify-game est une compétence qui vérifie la jouabilité des jeux et résout les problèmes pour garantir la complétude","de":"Verify-game ist eine Fähigkeit, die die Spielbarkeit von Spielen überprüft und Probleme behebt, um die Vollständigkeit zu gewährleisten","pt":"O verify-game é uma ferramenta de verificação de jogos que lê o código-fonte do jogo e executa ações para garantir que o jogo seja jogável.","ru":"Verify-game - это инструмент проверки игр, который читает исходный код игры и выполняет действия, чтобы гарантировать, что игра является играбельной.","ar":"verify-game هو أداة للتحقق من الألعاب التي تقرأ код مصدر اللعبة وتنفذ إجراءات لضمان أن تكون اللعبة قابلة للعب."},"features":{"en":["Reads and analyzes game source code via cat commands","Compares with README.md for game structure understanding","Performs Phase 1: pre-verification preparation using bash","Generates verification reports and applies fixes as needed","Supports iterative game testing and clearance verification"],"zh":["读取游戏源代码和README文件","分析游戏结构和逻辑","自动化游戏测试和验证","识别和修复游戏中的问题","生成详细的验证报告"],"ja":["ゲームのソースコードとREADMEファイルを読み取り","ゲームの構造とロジックを分析","ゲームの自動テストと検証","ゲーム内の問題を特定し修正","詳細な検証レポートを生成"],"ko":["게임 소스 코드와 README 파일 읽기","게임 구조와 논리를 분석","게임 자동 테스트와 검증","게임 내의 문제를 식별하고 수정","상세한 검증 보고서 생성"],"es":["Lectura y modificación del código fuente del juego","Análisis de la estructura del juego","Generación de informes de verificación y corrección de errores","Repetición de la verificación después de la corrección","Compatibilidad con juegos de diferentes formatos","Integración con herramientas de desarrollo de juegos"],"fr":["Lecture et modification du code source du jeu","Analyse de la structure du jeu","Génération de rapports de vérification et de correction d''erreurs","Répétition de la vérification après correction","Compatibilité avec des jeux de différents formats","Intégration avec des outils de développement de jeux"],"de":["Lesen und Modifizieren des Quellcodes des Spiels","Analyse der Spielstruktur","Erstellung von Überprüfungs- und Korrekturberichten","Wiederholung der Überprüfung nach Korrektur","Kompatibilität mit Spielen in verschiedenen Formaten","Integration mit Spielentwicklungstools"],"pt":["Leitura do código-fonte do jogo para entender a estrutura do jogo","Execução de ações para garantir que o jogo seja jogável","Geração de relatórios de verificação para identificar problemas","Suporte à edição do código-fonte do jogo para corrigir problemas","Integração com a ferramenta play-game para garantir a compatibilidade","Suporte à linha de comando (CLI) para execução automática"],"ru":["Чтение исходного кода игры для понимания структуры игры","Выполнение действий, чтобы гарантировать, что игра является играбельной","Генерация отчетов проверки для идентификации проблем","Поддержка редактирования исходного кода игры для исправления проблем","Интеграция с инструментом play-game для обеспечения совместимости","Поддержка командной строки (CLI) для автоматического выполнения"],"ar":["قراءة код مصدر اللعبة لفهم هيكل اللعبة","تنفيذ إجراءات لضمان أن تكون اللعبة قابلة للعب","توليد تقارير التحقق لتحديد المشاكل","دعم تحرير код مصدر اللعبة لإصلاح المشاكل","التكامل مع أداة play-game لضمان التوافق","دعم سطر الأوامر (CLI) للتنفيذ التلقائي"]},"keywords":{"en":["how to use verify-game","verify-game setup guide","game verification and fix","play-game agent optimization","verify-game vs play-game","verify-game install for AI agents","game clearance verification","AI game testing and fixing"],"zh":["verify-game技能","AIエージェント","游戏测试","游戏验证","游戏修复","自动化测试","游戏开发"],"ja":["verify-gameスキル","AIエージェント","ゲームテスト","ゲーム検証","ゲーム修正","自動テスト","ゲーム開発"],"ko":["verify-game 스킬","AI 툴","게임 테스트","게임 검증","게임 수정","자동 테스트","게임 개발"],"es":["verify-game","agentes de IA","juegos","desarrollo de juegos","pruebas de juegos","corrección de errores","informes de verificación","herramientas de desarrollo de juegos","IA y juegos"],"fr":["verify-game","agents d''IA","jeux","développement de jeux","tests de jeux","correction d''erreurs","rapports de vérification","outils de développement de jeux","IA et jeux"],"de":["verify-game","KI-Agenten","Spiele","Spielentwicklung","Spieltests","Fehlerkorrektur","Überprüfungsberichte","Spielentwicklungstools","KI und Spiele"],"pt":["verify-game","AI Agents","jogos","verificação de jogos","código-fonte","CLI","play-game","compatibilidade","relatórios de verificação"],"ru":["verify-game","ИИ Агенты","игры","проверка игр","исходный код","CLI","play-game","совместимость","отчеты проверки"],"ar":["verify-game","وكلاء الذكاء الاصطناعي","ألعاب","التحقق من الألعاب","كود مصدر","CLI","play-game","التوافق","تقارير التحقق"]}},"owner":"tegnike","repo":"ai-agent-game-streamer","repoPath":"tegnike/ai-agent-game-streamer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.417Z","topics":[],"category":"community","skillMd":{"name":"verify-game","description":"ゲームを実際にプレイしてクリアできるか検証し、詰まった場合は原因を特定・修正するスキル。","bodyPreview":"# Game Verification and Fix Skill\n\nゲームを実際にプレイしてクリアできるか検証し、問題があれば修正するスキルです。\n\n## 目的\n\n**play-gameスキルを使うエージェントが詰まらずにクリアできること**を保証する。\n\n## play-game との違い\n\n| 観点 | play-game | verify-game |\n|------|-----------|-------------|\n| ソースコード | 読み取り禁止（READMEのみ） | 読み取り・修正可能 |\n| 目的 | エンタメとしてプレイ | 詰まらないことを保証 |\n| 詰まった時 | 諦める or 適当に操作 | 原因特定 → 修正 → 再プレイ |\n| 出力 | 実況付きプレイ | 検証レポート + 修正 |\n\n---\n\n## 検証フロー\n\n### Phase 1: 事前準備\n\n```bash\n# 1. ソースコードを読んでゲーム構造を把握\ncat games/<game-name>/script.js\ncat games/<game-name>/README.md\n\n#","body":"# Game Verification and Fix Skill\n\nゲームを実際にプレイしてクリアできるか検証し、問題があれば修正するスキルです。\n\n## 目的\n\n**play-gameスキルを使うエージェントが詰まらずにクリアできること**を保証する。\n\n## play-game との違い\n\n| 観点 | play-game | verify-game |\n|------|-----------|-------------|\n| ソースコード | 読み取り禁止（READMEのみ） | 読み取り・修正可能 |\n| 目的 | エンタメとしてプレイ | 詰まらないことを保証 |\n| 詰まった時 | 諦める or 適当に操作 | 原因特定 → 修正 → 再プレイ |\n| 出力 | 実況付きプレイ | 検証レポート + 修正 |\n\n---\n\n## 検証フロー\n\n### Phase 1: 事前準備\n\n```bash\n# 1. ソースコードを読んでゲーム構造を把握\ncat games/<game-name>/script.js\ncat games/<game-name>/README.md\n\n# 2. HTTPサーバー起動（既存プロセスがなければ）\nlsof -i:8888 || (cd /Users/user/WorkSpace/ai-agent-game-streamer/games && python3 -m http.server 8888 &)\n\n# 3. ゲームを開く（--headed必須）\nagent-browser --headed open http://127.0.0.1:8888/<game-name>/index.html\n\n# 4. 初期状態をスクリーンショット\nmkdir -p logs\nagent-browser screenshot \"logs/$(date +%Y%m%d-%H%M%S)_initial.png\"\n```\n\n### Phase 1.5: 初期状態の整合性チェック（重要）\n\n**プレイを開始する前に、ゲームデータの整合性を確認する。**\n\n#### 倉庫番（sokoban）の場合\n\n```bash\n# 箱とゴールの数が一致しているか確認\nagent-browser eval \"\nconst boxes = game.getBoxPositions();\nconst goals = game.goals;\nJSON.stringify({boxCount: boxes.length, goalCount: goals.length, match: boxes.length === goals.length})\n\"\n```\n\n**チェック項目:**\n- `boxCount === goalCount` であること（不一致ならクリア不可能）\n- 各ステージで確認すること\n\n#### ボードゲーム（othello, gomoku）の場合\n\n```bash\n# 初期状態で有効な手があるか確認\nagent-browser eval \"JSON.stringify(game.getValidMoves(game.currentPlayer))\"\n```\n\n**チェック項目:**\n- 初期状態で有効な手が存在すること\n- ゲームオーバーでないこと\n\n**整合性エラーが見つかった場合は、Phase 4 でデータバグ（タイプD）として修正する。**\n\n### Phase 2: 実際にプレイしてクリアを目指す（1手ずつ検証）\n\n**play-gameスキルと同じ方法でゲームをプレイする。**\n\nただし、**ソースコードを読めるので、APIの正確な挙動を把握した上でプレイできる。**\n\n#### 重要: 1手ずつ期待値と実測値を比較する\n\n**検証では「意図通りに動いているか」を確認することが目的。**\n単にクリアを目指すのではなく、各操作の結果が期待通りかを検証する。\n\n```bash\n# 悪い例: ただ移動するだけ\nagent-browser eval \"game.move(''up'')\"\nagent-browser eval \"game.move(''up'')\"\n\n# 良い例: 期待値と実測値を比較しながら移動\nagent-browser eval \"\nconst before = {...game.playerPos};\nconst result = game.move(''up'');\nconst after = {...game.playerPos};\nJSON.stringify({\n  before,\n  expected: {row: before.row - 1, col: before.col},\n  after,\n  result,\n  match: after.row === before.row - 1 && after.col === before.col\n})\n\"\n```\n\n**検証すべき項目:**\n| 操作 | 期待値 | 実測値 | 一致するか |\n|------|--------|--------|-----------|\n| 移動前の位置 | - | `before` | - |\n| 移動後の位置 | `expected` | `after` | `match` |\n| 戻り値 | `true` or `false` | `result` | 期待通りか |\n\n#### ボードゲーム（othello, gomoku）\n\n```bash\n# 有効な手を確認\nagent-browser eval \"JSON.stringify(game.getValidMoves(game.currentPlayer))\"\n\n# 手を打つ（期待値と実測値を比較）\nagent-browser eval \"\nconst beforePlayer = game.currentPlayer;\nconst result = game.handleCellClick(row, col);\nconst afterPlayer = game.currentPlayer;\nJSON.stringify({beforePlayer, afterPlayer, result, turnChanged: beforePlayer !== afterPlayer})\n\"\nsleep 0.5\n\n# ゲーム終了まで繰り返す\nagent-browser eval \"game.gameOver\"\n```\n\n#### パズルゲーム（sokoban）\n\n```bash\n# 現在位置と箱の位置を確認\nagent-browser eval \"JSON.stringify({playerPos: game.playerPos, boxes: game.getBoxPositions()})\"\n\n# 移動（期待値と実測値を比較）\nagent-browser eval \"\nconst beforePlayer = {...game.playerPos};\nconst beforeBoxes = game.getBoxPositions();\nconst result = game.move(''right'');\nconst afterPlayer = {...game.playerPos};\nconst afterBoxes = game.getBoxPositions();\nJSON.stringify({\n  player: {before: beforePlayer, after: afterPlayer, moved: result},\n  boxMoved: JSON.stringify(beforeBoxes) !== JSON.stringify(afterBoxes)\n})\n\"\nsleep 0.5\n\n# クリアまで繰り返す\nagent-browser eval \"game.checkClear()\"\n```\n\n#### カードゲーム（card-battle）\n\n```bash\n# ゲーム状態を確認\nagent-browser eval \"JSON.stringify(game.getGameState())\"\n\n# カードをプレイ（期待値と実測値を比較）\nagent-browser eval \"\nconst before = game.getGameState();\ngame.playCard(0);\nconst after = game.getGameState();\nJSON.stringify({before, after})\n\"\n```\n\n### Phase 3: 詰まったら原因を特定\n\n**「詰まった」の定義**:\n- 有効な手がないのにゲーム終了していない\n- 操作しても状態が変わらない\n- APIが期待と異なる値を返す\n- エラーが発生する\n\n**原因特定の手順**:\n\n1. **症状を確認**\n   ```bash\n   # 現在の状態をダンプ\n   agent-browser eval \"JSON.stringify(game)\"\n   agent-browser screenshot \"logs/$(date +%Y%m%d-%H%M%S)_stuck.png\"\n   ```\n\n2. **ソースコードで原因を調査**\n   ```bash\n   # 該当メソッドの実装を確認\n   grep -A 30 \"getValidMoves\" games/<game-name>/script.js\n   ```\n\n3. **問題を分類**\n\n   | タイプ | 症状 | 修正対象 |\n   |--------|------|---------|\n   | A: READMEの曖昧さ | コードは正しいがドキュメントが不明確で誤操作した | README.md |\n   | B: コードのバグ | APIが期待通りに動作しない | script.js |\n   | C: API不足 | 必要な情報を取得するAPIがない | script.js + README.md |\n   | D: データバグ | ステージデータ自体が間違っている（箱とゴールの数不一致等） | script.js（STAGESデータ） |\n\n### Phase 4: 修正を適用\n\n**タイプA: READMEの曖昧さ**\n\n例: `getValidMoves(player)` の `player` が `1=黒, 2=白` だと分からなかった\n\n```markdown\n# 修正前\n| `game.getValidMoves(player)` | 有効な手の一覧を取得 |\n\n# 修正後\n| `game.getValidMoves(player)` | 有効な手の一覧を取得（player: 1=黒, 2=白）。戻り値: `[{ row: number, col: number }, ...]` |\n```\n\n**タイプB: コードのバグ**\n\n例: `handleCellClick` がプレイヤーのターンでも動作しない\n\n```javascript\n// 修正前\nhandleCellClick(row, col) {\n    if (this.gameOver || this.currentPlayer !== BLACK) return;\n    // BLACK=1 だが、初期化で currentPlayer が設定されていない\n}\n\n// 修正後\nhandleCellClick(row, col) {\n    if (this.gameOver || this.currentPlayer !== BLACK) return;\n    // init() で this.currentPlayer = BLACK を確実に設定\n}\n```\n\n**タイプC: API不足**\n\n例: 現在のステージ番号を取得するAPIがない\n\n```javascript\n// script.js に追加\nget currentStageNumber() {\n    return this.currentStage;\n}\n```\n\n```markdown\n// README.md に追加\n| `game.currentStageNumber` | 現在のステージ番号（0-9） |\n```\n\n**タイプD: データバグ**\n\n例: 倉庫番のステージ2で箱6個、ゴール5個だった（クリア不可能）\n\n```javascript\n// 修正前（箱が1つ多い）\n// ステージ 2\n[\n    \"########\",\n    \"#      #\",\n    \"# .**$ #\",\n    \"# .  $ #\",\n    \"# . $$ #\",  // ← $$ で箱が2つ\n    \"#   @  #\",\n    \"########\"\n],\n\n// 修正後（箱を1つ削除）\n// ステージ 2\n[\n    \"########\",\n    \"#      #\",\n    \"# .**$ #\",\n    \"# .  $ #\",\n    \"# . $  #\",  // ← $ 1つに修正\n    \"#   @  #\",\n    \"########\"\n],\n```\n\n**データバグの発見方法:**\n- Phase 1.5 の整合性チェックで検出\n- または、プレイ中に「全部正しく動かしてもクリアできない」場合に疑う\n\n### Phase 5: 再プレイで検証\n\n```bash\n# ページリロードして修正を反映\nagent-browser reload\n\n# 再度プレイしてクリアを目指す\n# Phase 2 に戻る\n```\n\n**クリアできたら Phase 6 へ進む。**\n\n### Phase 6: 検証後チェック（必須）\n\nクリア成功後、以下のチェックを**必ず**実施する。\n\n#### 6-1. READMEの完全性チェック\n\nplay-gameスキルはREADMEのみを参照するため、以下がすべて記載されているか確認：\n\n| チェック項目 | 確認内容 |\n|-------------|---------|\n| **操作API** | `move()`, `handleCellClick()` 等の操作メソッドが記載されているか |\n| **状態取得API** | ゲーム状態を取得するプロパティ（`playerPos`, `board`, `currentPlayer` 等）が記載されているか |\n| **戻り値の説明** | メソッドの戻り値の型と意味が明記されているか（`true`/`false` の意味など） |\n| **定数の説明** | セルタイプやプレイヤー番号などの定数値が説明されているか |\n| **クリア条件** | クリア判定APIとその使い方が記載されているか |\n\n**不足があれば README.md を修正する。**\n\n#### 6-2. ゲームロジックのレビュー\n\n検証中に使用したAPIやゲームデータに問題がないか確認：\n\n| チェック項目 | 確認内容 |\n|-------------|---------|\n| **クリア可能性** | すべてのステージ/初期状態がクリア可能か（詰み状態がないか） |\n| **API一貫性** | READMEに記載されたAPIが実際のコードと一致しているか |\n| **エッジケース** | 境界条件（盤面端、最終ステージ等）で正常動作するか |\n\n**問題があれば script.js を修正し、Phase 5 に戻って再検証する。**\n\n#### 6-3. チェックリスト\n\n```markdown\n## 検証後チェックリスト\n\n- [ ] データ: 箱とゴールの数が一致している（倉庫番）\n- [ ] データ: 初期状態で有効な手がある（ボードゲーム）\n- [ ] README: 操作APIが記載されている\n- [ ] README: 状態取得プロパティが記載されている\n- [ ] README: 戻り値の型と意味が明記されている\n- [ ] README: 定数値（セルタイプ等）が説明されている\n- [ ] ゲーム: すべてのステージがクリア可能\n- [ ] ゲーム: APIがREADMEの説明通りに動作する\n- [ ] ゲーム: 1手ずつの操作が期待通りに動作する\n```\n\n**すべてチェックが完了したら検証完了。**\n\n---\n\n## ゲーム別の「クリア」条件\n\n| ゲーム | クリア条件 | 確認方法 |\n|--------|----------|---------|\n| othello | ゲーム終了（両者パス or 盤面埋まる） | `game.gameOver === true` |\n| gomoku | 5つ並ぶ or 盤面埋まる | `game.winner !== null` |\n| sokoban | 全箱がゴール上 | `game.checkClear() === true` |\n| card-battle | 3勝する or 相手が3勝 | `game.getGameState().gameOver === true` |\n\n---\n\n## 出力フォーマット\n\n検証完了後、以下の形式でレポートを出力：\n\n```markdown\n# ゲーム検証レポート: <game-name>\n\n## 検証日時\nYYYY-MM-DD HH:MM\n\n## 結果\nクリア成功 / クリア失敗（修正後成功）\n\n## プレイログ\n1. [操作] → [結果]\n2. [操作] → [結果]\n...\n\n## 発見した問題（あれば）\n\n### 問題1: [タイプA/B/C] 問題の概要\n- **症状**: 何が起きたか\n- **原因**: なぜ起きたか\n- **修正内容**: 何を修正したか\n- **修正ファイル**: どのファイルを変更したか\n\n## 修正したファイル一覧\n- games/<game-name>/README.md\n- games/<game-name>/script.js\n\n## play-gameスキルへの影響\n影響なし / [影響内容を記載]\n\n## 検証後チェックリスト\n- [x] データ: 箱とゴールの数が一致している（倉庫番）\n- [x] データ: 初期状態で有効な手がある（ボードゲーム）\n- [x] README: 操作APIが記載されている\n- [x] README: 状態取得プロパティが記載されている\n- [x] README: 戻り値の型と意味が明記されている\n- [x] README: 定数値（セルタイプ等）が説明されている\n- [x] ゲーム: すべてのステージがクリア可能\n- [x] ゲーム: APIがREADMEの説明通りに動作する\n- [x] ゲーム: 1手ずつの操作が期待通りに動作する\n```\n\n---\n\n## 注意事項\n\n1. **--headed 必須**: ブラウザは必ず `--headed` オプションで起動\n2. **0.5秒以上の間隔**: 操作は間隔を空けて実行（状態反映のため）\n3. **破壊的変更に注意**: APIシグネチャを変更する場合、play-gameスキルへの影響を考慮\n4. **大きな修正前は git commit**: 変更を追跡できるように\n5. **スクリーンショットを残す**: `logs/` にスクリーンショットを保存\n\n---\n\n## 使用例\n\n```bash\n# オセロを検証（クリアできるまでプレイ、問題あれば修正）\n/verify-game othello\n\n# 倉庫番ステージ1を検証\n/verify-game sokoban\n\n# 五目並べを検証\n/verify-game gomoku\n```\n\n検証後、`/play-game <game>` で修正が有効か確認することを推奨。\n"},"lastSynced":"2026-03-08T02:07:18.554Z","agentAnalysis":{"suitability":{"en":"Ideal for Game Testing Agents needing to verify and fix games for seamless playability.","zh":"适合需要验证和修复游戏以实现无缝玩性的游戏测试代理。","ja":"ゲームのテストエージェントがゲームを検証して修正してスムーズなプレイ性を実現する必要がある場合に最適。","ko":"게임을 테스트하고 수정하여 완벽한 플레이 가능성을 보장해야 하는 게임 테스트 에이전트에게 적합합니다.","es":"Ideal para Agentes de Pruebas de Juegos que necesitan verificar y corregir juegos para una jugabilidad sin problemas.","fr":"Idéal pour les agents de test de jeu ayant besoin de vérifier et de corriger les jeux pour une jouabilité sans problème.","de":"Ideal für Game-Test-Agenten, die Spiele überprüfen und korrigieren müssen, um ein reibungsloses Spielen zu gewährleisten.","pt":"Ideal para Agentes de Teste de Jogos que precisam verificar e corrigir jogos para garantir uma jogabilidade sem interrupções.","ru":"Идеально подходит для агентов тестирования игр, которым необходимо проверять и исправлять игры для бесперебойной играбельности.","ar":"مثالي للوكلاء اختبار الألعاب التي تحتاج إلى التحقق من وإصلاح الألعاب لضمان لعبها بسلاسة."},"recommendation":{"en":"Empowers agents to guarantee play-game agents can clear games without issues by verifying and fixing game structures, utilizing README files and script.js analysis, and generating comprehensive verification reports.","zh":"赋予代理人验证和修复游戏结构、利用README文件和script.js分析以及生成全面验证报告的能力，以确保游戏代理人可以无误地完成游戏。","ja":"エージェントがREADMEファイルとscript.jsの分析を利用してゲーム構造を検証して修正し、包括的な検証レポートを生成することで、プレイゲームエージェントが問題なくゲームをクリアできることを保証する能力を提供します。","ko":"README 파일과 script.js 분석을 활용하여 게임 구조를 검증하고 수정하며, 포괄적인 검증 보고서를 생성하여 플레이 게임 에이전트가 문제 없이 게임을 완료할 수 있도록 보장하는 능력을 제공합니다.","es":"Habilita a los agentes a garantizar que los agentes de juego puedan completar juegos sin problemas, verificando y corrigiendo las estructuras de juego, utilizando archivos README y análisis de script.js, y generando informes de verificación completos.","fr":"Permet aux agents de garantir que les agents de jeu puissent terminer les jeux sans problème en vérifiant et en corrigeant les structures de jeu, en utilisant des fichiers README et une analyse de script.js, et en générant des rapports de vérification complets.","de":"Ermächtigt die Agenten, sicherzustellen, dass Spielagenten Spiele ohne Probleme abschließen können, indem sie Spielstrukturen überprüfen und korrigieren, README-Dateien und script.js-Analysen nutzen und umfassende Überprüfungsberichte generieren.","pt":"Habilita os agentes a garantir que os agentes de jogo possam limpar os jogos sem problemas, verificando e corrigindo estruturas de jogo, utilizando arquivos README e análise de script.js, e gerando relatórios de verificação abrangentes.","ru":"Наделяет агентов возможностью гарантировать, что агенты игры могут пройти игры без проблем, проверяя и исправляя структуры игры, используя файлы README и анализ script.js, и генерируя всесторонние отчеты о проверке.","ar":"يتمكّن الوكلاء من ضمان khảيّة وكلاء اللعبة إكمال الألعاب بدون مشاكل من خلال التحقق من وإصلاح هياكل اللعبة، واستخدام ملفات README وتحليل script.js، وتوليد تقارير تفصيلية للتحقق."},"useCases":{"en":["Verifying game clearability before play-game agent deployment","Debugging and fixing game issues to ensure smooth gameplay","Generating verification reports for game developers and testers"],"zh":["在部署游戏代理前验证游戏的可清除性","调试和修复游戏问题以确保顺畅的游戏体验","为游戏开发者和测试者生成验证报告"],"ja":["プレイゲームエージェントをデプロイする前にゲームのクリア可能性を検証する","ゲームの問題をデバッグして修正してスムーズなゲームプレイを確保する","ゲーム開発者とテスターのための検証レポートを生成する"],"ko":["플레이 게임 에이전트 배포 전 게임의 클리어 가능성을 검증하는 것","게임 문제를 디버깅하고 수정하여 부드러운 게임 플레이를 보장하는 것","게임 개발자와 테스터를 위한 검증 보고서 생성"],"es":["Verificar la capacidad de completar juegos antes de la implementación de agentes de juego","Depurar y corregir problemas de juego para garantizar un juego suave","Generar informes de verificación para desarrolladores y testers de juegos"],"fr":["Vérifier la capacité à terminer les jeux avant le déploiement des agents de jeu","Déboguer et corriger les problèmes de jeu pour assurer un jeu fluide","Générer des rapports de vérification pour les développeurs et les testeurs de jeux"],"de":["Überprüfen der Fähigkeit, Spiele zu abschließen, bevor Spielagenten bereitgestellt werden","Fehler in Spielen debuggen und korrigieren, um ein reibungsloses Spielen zu gewährleisten","Generieren von Überprüfungsberichten für Spieleentwickler und -tester"],"pt":["Verificar a capacidade de conclusão do jogo antes da implantação do agente de jogo","Depurar e corrigir problemas de jogo para garantir uma jogabilidade suave","Gerar relatórios de verificação para desenvolvedores e testadores de jogos"],"ru":["Проверка проходимости игры перед развертыванием агента игры","Отладка и исправление проблем игры для обеспечения гладкой игры","Генерация отчетов о проверке для разработчиков и тестировщиков игр"],"ar":["التحقق من khảيّة إكمال اللعبة قبل نشر وكلاء اللعبة","تصحيح الأعطال وإصلاح مشاكل اللعبة لضمان لعبها بسلاسة","توليد تقارير التحقق لفريق تطوير الألعاب والمتخصصين في اختبارها"]},"limitations":{"en":["Requires access to game source code (script.js and README.md)","Limited to games with compatible file structures"],"zh":["需要访问游戏源代码（script.js和README.md）","仅限于具有兼容文件结构的游戏"],"ja":["ゲームのソースコード（script.jsとREADME.md）へのアクセスが必要","互換性のあるファイル構造を持つゲームに限定される"],"ko":["게임 소스 코드(script.js 및 README.md) 액세스가 필요함","호환되는 파일 구조를 가진 게임으로 제한됨"],"es":["Requiere acceso al código fuente del juego (script.js y README.md)","Limitado a juegos con estructuras de archivo compatibles"],"fr":["Nécessite un accès au code source du jeu (script.js et README.md)","Limité aux jeux avec des structures de fichiers compatibles"],"de":["Benötigt Zugriff auf den Spielquellcode (script.js und README.md)","Begrenzt auf Spiele mit kompatiblen Dateistrukturen"],"pt":["Exige acesso ao código-fonte do jogo (script.js e README.md)","Limitado a jogos com estruturas de arquivo compatíveis"],"ru":["Требует доступа к исходному коду игры (script.js и README.md)","Ограничен играми с совместимыми структурами файлов"],"ar":["يتطلب الوصول إلى شفرة اللعبة المصدر (script.js و README.md)","محدود بالألعاب التي تحتوي على هياكل ملفات متوافقة"]},"version":4},"contentHash":"3d4d29743c0fb97a3a148ebd753de7efed369535c88ebe3f68cc7728a1f69dec","qualityScore":33}');
