INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tegnike/ai-agent-game-streamer/verify-game', 'verify-game', 'tegnike', 'ai-agent-game-streamer', 'community', 'verify-game tegnike ai-agent-game-streamer community The verify-game skill verifies and fixes games to ensure play-game agents can clear them without issues, benefiting AI agent developers and gamers alike. verify-game技能是用于确保AIエージェント能够顺利完成游戏的技术 verify-gameスキルは、AIエージェントがゲームをクリアできることを保証する技術です verify-game 스킬은 AI 툴이 게임을 클리어할 수 있도록 보장하는 기술입니다 Verify-game es un skill que verifica y soluciona problemas en juegos para garantizar que los agentes de IA puedan completarlos Verify-game est une compétence qui vérifie et résout les problèmes de jeux pour garantir que les agents d''IA puissent les compléter Verify-game ist eine Fähigkeit, die Spiele überprüft und Probleme behebt, um sicherzustellen, dass KI-Agenten sie abschließen können O verify-game é uma ferramenta de verificação de jogos que garante que os agentes de IA possam jogar sem problemas. Ele lê o código-fonte do jogo e executa ações para garantir que o jogo seja jogável. Verify-game - это инструмент проверки игр, который гарантирует, что ИИ агенты могут играть без проблем. Он читает исходный код игры и выполняет действия, чтобы гарантировать, что игра является играбельной. verify-game هو أداة للتحقق من الألعاب التي تضمن أن يكون بإمكان وكلاء الذكاء الاصطناعي لعب بدون مشاكل. إنه يقرأ код مصدر اللعبة وينفذ إجراءات لضمان أن تكون اللعبة قابلة للعب. how to use verify-game verify-game setup guide game verification and fix play-game agent optimization verify-game vs play-game verify-game install for AI agents game clearance verification AI game testing and fixing verify-game技能 AIエージェント 游戏测试 游戏验证 游戏修复 自动化测试 游戏开发 Reads and analyzes game source code via cat commands Compares with README.md for game structure understanding Performs Phase 1: pre-verification preparation using bash Generates verification reports and applies fixes as needed Supports iterative game testing and clearance verification verify-game is a skill that verifies game clearance and fixes issues to guarantee play-game agents can complete games without getting stuck.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Monichre/digital-mischief-group/threejs-fundamentals', 'community', 'Monichre', 'digital-mischief-group', 'Monichre/digital-mischief-group', 'threejs-fundamentals', 0, 0, 33, '2026-03-08T01:57:15.428Z', '2026-03-08T02:07:30.618Z', 'eb66d52f53f489067d602b9b62df507adb391d8220bdd1a8aae6b73e6cee578a', '{"id":"Monichre/digital-mischief-group/threejs-fundamentals","name":"threejs-fundamentals","description":{"en":"threejs-fundamentals enables developers to create immersive 3D experiences by setting up scenes, cameras, and renderers. It benefits developers working with 3D graphics and WebGL.","zh":"Three.js 基础设置，包括创建场景、相机和渲染器。使用 JavaScript 和 Three.js 库进行 3D 渲染。","ja":"Three.js の基本設定、シーン、カメラ、レンダラーの作成。JavaScript と Three.js ライブラリを使用した 3D レンダリング。","ko":"Three.js 기본 설정, 장면, 카메라, 렌더러 생성. JavaScript와 Three.js 라이브러리를 사용한 3D 렌더링.","es":"Three.js Fundamentals es una guía para crear escenas 3D con JavaScript. Aprende a configurar la escena, la cámara y el renderizador","fr":"Les fondamentaux de Three.js sont un guide pour la création de scènes 3D avec JavaScript. Apprenez à configurer la scène, la caméra et le rendu","de":"Die Grundlagen von Three.js sind ein Leitfaden für die Erstellung von 3D-Szenen mit JavaScript. Erfahren Sie, wie Sie die Szene, die Kamera und den Renderer konfigurieren","pt":"Este guia técnico cobre os fundamentos do Three.js, incluindo a criação de uma cena, câmera e renderizador. Aprenda a configurar um ambiente de renderização 3D para seus projetos de Agentes IA.","ru":"Это техническое руководство охватывает основы Three.js, включая создание сцены, камеры и рендерера. Научитесь настраивать среду 3D-рендеринга для ваших проектов ИИ Агентов.","ar":"يغطي هذا الدليل التقني أساسيات Three.js، بما في ذلك إنشاء مشهد وكاميرا وعارض. تعلم كيفية إعداد بيئة تقديم ثلاثية الأبعاد لمشاريع أدوات الذكاء الاصطناعي الخاصة بك."},"seo":{"title":{"en":"threejs-fundamentals: 3D Rendering Setup Guide | AI Agent...","zh":"Three.js 基础设置指南 - AIエージェント","ja":"Three.js Fundamentals Setup Guide - AIエージェント","ko":"Three.js 기초 설정 가이드 - AI 도구","es":"Guía de configuración de Three.js Fundamentals","fr":"Guide de démarrage rapide pour les fondamentaux de Three.js","de":"Setup-Leitfaden für Three.js-Grundlagen","pt":"Three.js Fundamentals: Setup Guide para Agentes IA","ru":"Three.js Fundamentals: Руководство по настройке для ИИ Аг...","ar":"Three.js Fundamentals: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock 3D rendering capabilities with threejs-fundamentals. Learn how to set up scenes, cameras, and WebGL renderers. Get started now and elevate your 3D vis...","zh":"了解 Three.js 基础设置，包括场景、相机和渲染器的创建 - AIエージェント","ja":"Three.js の基本設定を学ぶ、シーン、カメラ、レンダラーの作成 - AIエージェント","ko":"Three.js 기본 설정에 대해 알아보세요, 장면, 카메라, 렌더러 생성 - AI 도구","es":"Aprende a crear escenas 3D con Three.js. Descubre cómo configurar la escena, la cámara y el renderizador con nuestro ejemplo de código","fr":"Créez des scènes 3D avec Three.js. Découvrez comment configurer la scène, la caméra et le rendu avec notre exemple de code","de":"Erstellen Sie 3D-Szenen mit Three.js. Erfahren Sie, wie Sie die Szene, die Kamera und den Renderer mit unserem Codebeispiel konfigurieren","pt":"Aprenda a configurar uma cena básica do Three.js com Scene, PerspectiveCamera e WebGLRenderer. Guia de inicialização rápida para desenvolvimento de Agentes I...","ru":"Научитесь настраивать базовую сцену Three.js с Scene, PerspectiveCamera и WebGLRenderer. Руководство по быстрому запуску для разработки ИИ Агентов с 3D-ренде...","ar":"تعلم كيفية إعداد مشهد Three.js أساسي باستخدام Scene وPerspectiveCamera وWebGLRenderer. دليل بدء سريع لتطوير أدوات الذكاء الاصطناعي مع تقديم ثلاثي الأبعاد."},"definition":{"en":"threejs-fundamentals is a skill that provides the foundation for creating 3D graphics using the Three.js library, covering scene setup, camera configuration, and WebGL rendering.","zh":"Three.js 基础设置是指使用 Three.js 库创建 3D 场景、相机和渲染器的过程。","ja":"Three.js の基本設定とは、Three.js ライブラリを使用して 3D シーン、カメラ、レンダラーを作成するプロセスです。","ko":"Three.js 기본 설정은 Three.js 라이브러리를 사용하여 3D 장면, 카메라, 렌더러를 생성하는过程입니다.","es":"Three.js Fundamentals es un conjunto de técnicas y herramientas para crear escenas 3D con JavaScript","fr":"Les fondamentaux de Three.js sont un ensemble de techniques et d''outils pour créer des scènes 3D avec JavaScript","de":"Die Grundlagen von Three.js sind ein Satz von Techniken und Werkzeugen für die Erstellung von 3D-Szenen mit JavaScript","pt":"Three.js Fundamentals é um guia técnico que ensina a configurar os componentes essenciais de uma aplicação 3D no navegador. Inclui a criação de uma Scene, PerspectiveCamera e WebGLRenderer para desenvolvimento de Agentes IA com visualizações 3D.","ru":"Three.js Fundamentals — это техническое руководство по настройке основных компонентов 3D-приложения в браузере. Включает создание Scene, PerspectiveCamera и WebGLRenderer для разработки ИИ Агентов с 3D-визуализацией.","ar":"Three.js Fundamentals هو دليل تقني لتعليم إعداد المكونات الأساسية لتطبيق ثلاثي الأبعاد في المتصفح. يتضمن إنشاء Scene وPerspectiveCamera وWebGLRenderer لتطوير أدوات الذكاء الاصطناعي مع تصورات ثلاثية الأبعاد."},"features":{"en":["Creates scenes using the THREE.Scene class","Configures perspective cameras with THREE.PerspectiveCamera","Sets up WebGL renderers using THREE.WebGLRenderer","Handles window resizing and pixel ratio adjustments","Appends renderers to the DOM using document.body.appendChild"],"zh":["创建场景和相机","设置渲染器和 WebGL","使用 JavaScript 和 Three.js 库进行 3D 渲染","支持窗口内尺寸和像素比","创建 3D 对象和动画"],"ja":["シーンとカメラの作成","レンダラーと WebGL の設定","JavaScript と Three.js ライブラリを使用した 3D レンダリング","ウィンドウ内寸法とピクセル比のサポート","3D オブジェクトとアニメーションの作成"],"ko":["장면과 카메라 생성","렌더러와 WebGL 설정","JavaScript와 Three.js 라이브러리를 사용한 3D 렌더링","창 내 크기와 픽셀 비율 지원","3D 객체와 애니메이션 생성"],"es":["Creación de escenas 3D con JavaScript","Configuración de la escena, la cámara y el renderizador","Uso de la biblioteca Three.js para renderizar gráficos 3D","Compatibilidad con WebGL y otros estándares de renderizado","Personalización de la escena y la cámara para crear efectos visuales personalizados"],"fr":["Création de scènes 3D avec JavaScript","Configuration de la scène, de la caméra et du rendu","Utilisation de la bibliothèque Three.js pour rendre des graphiques 3D","Compatibilité avec WebGL et d''autres normes de rendu","Personnalisation de la scène et de la caméra pour créer des effets visuels personnalisés"],"de":["Erstellung von 3D-Szenen mit JavaScript","Konfiguration der Szene, der Kamera und des Renderers","Verwendung der Bibliothek Three.js für die Darstellung von 3D-Grafiken","Kompatibilität mit WebGL und anderen Renderstandards","Anpassung der Szene und der Kamera für die Erstellung von benutzerdefinierten visuellen Effekten"],"pt":["Configuração de Scene do Three.js","Criação de PerspectiveCamera com parâmetros de campo de visão","Inicialização do WebGLRenderer com antialias","Definição de tamanho de renderizador baseado em window.innerWidth/Height","Controle de pixel ratio com devicePixelRatio","Anexação do DOMElement do renderizador ao document.body"],"ru":["Настройка Scene Three.js","Создание PerspectiveCamera с параметрами поля зрения","Инициализация WebGLRenderer с antialias","Установка размера рендерера на основе window.innerWidth/Height","Контроль pixel ratio с devicePixelRatio","Добавление DOMElement рендерера в document.body"],"ar":["إعداد مشهد Three.js","إنشاء كاميرا PerspectiveCamera مع معلمات مجال الرؤية","تهيئة عارض WebGLRenderer مع antialias","تعيين حجم العارض بناءً على window.innerWidth/Height","التحكم في نسبة البكسل باستخدام devicePixelRatio","إضافة DOMElement الخاص بالعارض إلى document.body"]},"keywords":{"en":["threejs-fundamentals setup guide","threejs-fundamentals tutorial","how to use threejs-fundamentals","threejs-fundamentals vs Babylon.js","threejs-fundamentals install","threejs-fundamentals examples","threejs-fundamentals documentation","what is threejs-fundamentals","threejs-fundamentals alternative"],"zh":["Three.js 基础设置","Three.js 教程","JavaScript 3D 渲染","WebGL 设置","Three.js 库","3D 场景创建","相机设置","渲染器配置"],"ja":["Three.js 基本設定","Three.js チュートリアル","JavaScript 3D レンダリング","WebGL 設定","Three.js ライブラリ","3D シーン作成","カメラ設定","レンダラー構成"],"ko":["Three.js 기본 설정","Three.js 튜토리얼","JavaScript 3D 렌더링","WebGL 설정","Three.js 라이브러리","3D 장면 생성","카메라 설정","렌더러 구성"],"es":["three.js","javascript 3d","escenas 3d","renderizado 3d","webgl","creación de escenas 3d","configuración de la escena","cámara y renderizador","biblioteca three.js"],"fr":["three.js","javascript 3d","scènes 3d","rendu 3d","webgl","création de scènes 3d","configuration de la scène","caméra et rendu","bibliothèque three.js"],"de":["three.js","javascript 3d","3d-szenen","rendering 3d","webgl","erstellung von 3d-szenen","konfiguration der szene","kamera und renderer","bibliothek three.js"],"pt":["threejs setup tutorial","webglrenderer antialias","perspectivecamera threejs","scene threejs exemplo","threejs fundamentos agente ia","renderer setSize threejs","threejs quick start guide"],"ru":["threejs настройка руководство","webglrenderer antialias","perspectivecamera threejs","scene threejs пример","threejs основы ии агенты","renderer setSize threejs","threejs быстрое начало"],"ar":["threejs إعداد درس","webglrenderer antialias","perspectivecamera threejs","scene threejs مثال","threejs أساسيات أدوات الذكاء الاصطناعي","renderer setSize threejs","threejs بدء سريع"]}},"owner":"Monichre","repo":"digital-mischief-group","repoPath":"Monichre/digital-mischief-group","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.428Z","topics":[],"category":"community","skillMd":{"name":"threejs-fundamentals","description":"Three.js scene setup, cameras, renderer, Object3D hierarchy, coordinate systems. Use when setting up 3D scenes, creating cameras, configuring renderers, managing object hierarchies, or working with transforms.","bodyPreview":"# Three.js Fundamentals\n\n## Quick Start\n\n```javascript\nimport * as THREE from \"three\";\n\n// Create scene, camera, renderer\nconst scene = new THREE.Scene();\nconst camera = new THREE.PerspectiveCamera(\n  75,\n  window.innerWidth / window.innerHeight,\n  0.1,\n  1000,\n);\nconst renderer = new THREE.WebGLRenderer({ antialias: true });\n\nrenderer.setSize(window.innerWidth, window.innerHeight);\nrenderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\ndocument.body.appendChild(renderer.domElement);\n\n//","body":"# Three.js Fundamentals\n\n## Quick Start\n\n```javascript\nimport * as THREE from \"three\";\n\n// Create scene, camera, renderer\nconst scene = new THREE.Scene();\nconst camera = new THREE.PerspectiveCamera(\n  75,\n  window.innerWidth / window.innerHeight,\n  0.1,\n  1000,\n);\nconst renderer = new THREE.WebGLRenderer({ antialias: true });\n\nrenderer.setSize(window.innerWidth, window.innerHeight);\nrenderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\ndocument.body.appendChild(renderer.domElement);\n\n// Add a mesh\nconst geometry = new THREE.BoxGeometry(1, 1, 1);\nconst material = new THREE.MeshStandardMaterial({ color: 0x00ff00 });\nconst cube = new THREE.Mesh(geometry, material);\nscene.add(cube);\n\n// Add light\nscene.add(new THREE.AmbientLight(0xffffff, 0.5));\nconst dirLight = new THREE.DirectionalLight(0xffffff, 1);\ndirLight.position.set(5, 5, 5);\nscene.add(dirLight);\n\ncamera.position.z = 5;\n\n// Animation loop\nfunction animate() {\n  requestAnimationFrame(animate);\n  cube.rotation.x += 0.01;\n  cube.rotation.y += 0.01;\n  renderer.render(scene, camera);\n}\nanimate();\n\n// Handle resize\nwindow.addEventListener(\"resize\", () => {\n  camera.aspect = window.innerWidth / window.innerHeight;\n  camera.updateProjectionMatrix();\n  renderer.setSize(window.innerWidth, window.innerHeight);\n});\n```\n\n## Core Classes\n\n### Scene\n\nContainer for all 3D objects, lights, and cameras.\n\n```javascript\nconst scene = new THREE.Scene();\nscene.background = new THREE.Color(0x000000); // Solid color\nscene.background = texture; // Skybox texture\nscene.background = cubeTexture; // Cubemap\nscene.environment = envMap; // Environment map for PBR\nscene.fog = new THREE.Fog(0xffffff, 1, 100); // Linear fog\nscene.fog = new THREE.FogExp2(0xffffff, 0.02); // Exponential fog\n```\n\n### Cameras\n\n**PerspectiveCamera** - Most common, simulates human eye.\n\n```javascript\n// PerspectiveCamera(fov, aspect, near, far)\nconst camera = new THREE.PerspectiveCamera(\n  75, // Field of view (degrees)\n  window.innerWidth / window.innerHeight, // Aspect ratio\n  0.1, // Near clipping plane\n  1000, // Far clipping plane\n);\n\ncamera.position.set(0, 5, 10);\ncamera.lookAt(0, 0, 0);\ncamera.updateProjectionMatrix(); // Call after changing fov, aspect, near, far\n```\n\n**OrthographicCamera** - No perspective distortion, good for 2D/isometric.\n\n```javascript\n// OrthographicCamera(left, right, top, bottom, near, far)\nconst aspect = window.innerWidth / window.innerHeight;\nconst frustumSize = 10;\nconst camera = new THREE.OrthographicCamera(\n  (frustumSize * aspect) / -2,\n  (frustumSize * aspect) / 2,\n  frustumSize / 2,\n  frustumSize / -2,\n  0.1,\n  1000,\n);\n```\n\n**ArrayCamera** - Multiple viewports with sub-cameras.\n\n```javascript\nconst cameras = [];\nfor (let i = 0; i < 4; i++) {\n  const subcamera = new THREE.PerspectiveCamera(40, 1, 0.1, 100);\n  subcamera.viewport = new THREE.Vector4(\n    Math.floor(i % 2) * 0.5,\n    Math.floor(i / 2) * 0.5,\n    0.5,\n    0.5,\n  );\n  cameras.push(subcamera);\n}\nconst arrayCamera = new THREE.ArrayCamera(cameras);\n```\n\n**CubeCamera** - Renders environment maps for reflections.\n\n```javascript\nconst cubeRenderTarget = new THREE.WebGLCubeRenderTarget(256);\nconst cubeCamera = new THREE.CubeCamera(0.1, 1000, cubeRenderTarget);\nscene.add(cubeCamera);\n\n// Use for reflections\nmaterial.envMap = cubeRenderTarget.texture;\n\n// Update each frame (expensive!)\ncubeCamera.position.copy(reflectiveMesh.position);\ncubeCamera.update(renderer, scene);\n```\n\n### WebGLRenderer\n\n```javascript\nconst renderer = new THREE.WebGLRenderer({\n  canvas: document.querySelector(\"#canvas\"), // Optional existing canvas\n  antialias: true, // Smooth edges\n  alpha: true, // Transparent background\n  powerPreference: \"high-performance\", // GPU hint\n  preserveDrawingBuffer: true, // For screenshots\n});\n\nrenderer.setSize(width, height);\nrenderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n\n// Tone mapping\nrenderer.toneMapping = THREE.ACESFilmicToneMapping;\nrenderer.toneMappingExposure = 1.0;\n\n// Color space (Three.js r152+)\nrenderer.outputColorSpace = THREE.SRGBColorSpace;\n\n// Shadows\nrenderer.shadowMap.enabled = true;\nrenderer.shadowMap.type = THREE.PCFSoftShadowMap;\n\n// Clear color\nrenderer.setClearColor(0x000000, 1);\n\n// Render\nrenderer.render(scene, camera);\n```\n\n### Object3D\n\nBase class for all 3D objects. Mesh, Group, Light, Camera all extend Object3D.\n\n```javascript\nconst obj = new THREE.Object3D();\n\n// Transform\nobj.position.set(x, y, z);\nobj.rotation.set(x, y, z); // Euler angles (radians)\nobj.quaternion.set(x, y, z, w); // Quaternion rotation\nobj.scale.set(x, y, z);\n\n// Local vs World transforms\nobj.getWorldPosition(targetVector);\nobj.getWorldQuaternion(targetQuaternion);\nobj.getWorldDirection(targetVector);\n\n// Hierarchy\nobj.add(child);\nobj.remove(child);\nobj.parent;\nobj.children;\n\n// Visibility\nobj.visible = false;\n\n// Layers (for selective rendering/raycasting)\nobj.layers.set(1);\nobj.layers.enable(2);\nobj.layers.disable(0);\n\n// Traverse hierarchy\nobj.traverse((child) => {\n  if (child.isMesh) child.material.color.set(0xff0000);\n});\n\n// Matrix updates\nobj.matrixAutoUpdate = true; // Default: auto-update matrices\nobj.updateMatrix(); // Manual matrix update\nobj.updateMatrixWorld(true); // Update world matrix recursively\n```\n\n### Group\n\nEmpty container for organizing objects.\n\n```javascript\nconst group = new THREE.Group();\ngroup.add(mesh1);\ngroup.add(mesh2);\nscene.add(group);\n\n// Transform entire group\ngroup.position.x = 5;\ngroup.rotation.y = Math.PI / 4;\n```\n\n### Mesh\n\nCombines geometry and material.\n\n```javascript\nconst mesh = new THREE.Mesh(geometry, material);\n\n// Multiple materials (one per geometry group)\nconst mesh = new THREE.Mesh(geometry, [material1, material2]);\n\n// Useful properties\nmesh.geometry;\nmesh.material;\nmesh.castShadow = true;\nmesh.receiveShadow = true;\n\n// Frustum culling\nmesh.frustumCulled = true; // Default: skip if outside camera view\n\n// Render order\nmesh.renderOrder = 10; // Higher = rendered later\n```\n\n## Coordinate System\n\nThree.js uses a **right-handed coordinate system**:\n\n- **+X** points right\n- **+Y** points up\n- **+Z** points toward viewer (out of screen)\n\n```javascript\n// Axes helper\nconst axesHelper = new THREE.AxesHelper(5);\nscene.add(axesHelper); // Red=X, Green=Y, Blue=Z\n```\n\n## Math Utilities\n\n### Vector3\n\n```javascript\nconst v = new THREE.Vector3(x, y, z);\nv.set(x, y, z);\nv.copy(otherVector);\nv.clone();\n\n// Operations (modify in place)\nv.add(v2);\nv.sub(v2);\nv.multiply(v2);\nv.multiplyScalar(2);\nv.divideScalar(2);\nv.normalize();\nv.negate();\nv.clamp(min, max);\nv.lerp(target, alpha);\n\n// Calculations (return new value)\nv.length();\nv.lengthSq(); // Faster than length()\nv.distanceTo(v2);\nv.dot(v2);\nv.cross(v2); // Modifies v\nv.angleTo(v2);\n\n// Transform\nv.applyMatrix4(matrix);\nv.applyQuaternion(q);\nv.project(camera); // World to NDC\nv.unproject(camera); // NDC to world\n```\n\n### Matrix4\n\n```javascript\nconst m = new THREE.Matrix4();\nm.identity();\nm.copy(other);\nm.clone();\n\n// Build transforms\nm.makeTranslation(x, y, z);\nm.makeRotationX(theta);\nm.makeRotationY(theta);\nm.makeRotationZ(theta);\nm.makeRotationFromQuaternion(q);\nm.makeScale(x, y, z);\n\n// Compose/decompose\nm.compose(position, quaternion, scale);\nm.decompose(position, quaternion, scale);\n\n// Operations\nm.multiply(m2); // m = m * m2\nm.premultiply(m2); // m = m2 * m\nm.invert();\nm.transpose();\n\n// Camera matrices\nm.makePerspective(left, right, top, bottom, near, far);\nm.makeOrthographic(left, right, top, bottom, near, far);\nm.lookAt(eye, target, up);\n```\n\n### Quaternion\n\n```javascript\nconst q = new THREE.Quaternion();\nq.setFromEuler(euler);\nq.setFromAxisAngle(axis, angle);\nq.setFromRotationMatrix(matrix);\n\nq.multiply(q2);\nq.slerp(target, t); // Spherical interpolation\nq.normalize();\nq.invert();\n```\n\n### Euler\n\n```javascript\nconst euler = new THREE.Euler(x, y, z, \"XYZ\"); // Order matters!\neuler.setFromQuaternion(q);\neuler.setFromRotationMatrix(m);\n\n// Rotation orders: ''XYZ'', ''YXZ'', ''ZXY'', ''XZY'', ''YZX'', ''ZYX''\n```\n\n### Color\n\n```javascript\nconst color = new THREE.Color(0xff0000);\nconst color = new THREE.Color(\"red\");\nconst color = new THREE.Color(\"rgb(255, 0, 0)\");\nconst color = new THREE.Color(\"#ff0000\");\n\ncolor.setHex(0x00ff00);\ncolor.setRGB(r, g, b); // 0-1 range\ncolor.setHSL(h, s, l); // 0-1 range\n\ncolor.lerp(otherColor, alpha);\ncolor.multiply(otherColor);\ncolor.multiplyScalar(2);\n```\n\n### MathUtils\n\n```javascript\nTHREE.MathUtils.clamp(value, min, max);\nTHREE.MathUtils.lerp(start, end, alpha);\nTHREE.MathUtils.mapLinear(value, inMin, inMax, outMin, outMax);\nTHREE.MathUtils.degToRad(degrees);\nTHREE.MathUtils.radToDeg(radians);\nTHREE.MathUtils.randFloat(min, max);\nTHREE.MathUtils.randInt(min, max);\nTHREE.MathUtils.smoothstep(x, min, max);\nTHREE.MathUtils.smootherstep(x, min, max);\n```\n\n## Common Patterns\n\n### Proper Cleanup\n\n```javascript\nfunction dispose() {\n  // Dispose geometries\n  mesh.geometry.dispose();\n\n  // Dispose materials\n  if (Array.isArray(mesh.material)) {\n    mesh.material.forEach((m) => m.dispose());\n  } else {\n    mesh.material.dispose();\n  }\n\n  // Dispose textures\n  texture.dispose();\n\n  // Remove from scene\n  scene.remove(mesh);\n\n  // Dispose renderer\n  renderer.dispose();\n}\n```\n\n### Clock for Animation\n\n```javascript\nconst clock = new THREE.Clock();\n\nfunction animate() {\n  const delta = clock.getDelta(); // Time since last frame (seconds)\n  const elapsed = clock.getElapsedTime(); // Total time (seconds)\n\n  mesh.rotation.y += delta * 0.5; // Consistent speed regardless of framerate\n\n  requestAnimationFrame(animate);\n  renderer.render(scene, camera);\n}\n```\n\n### Responsive Canvas\n\n```javascript\nfunction onWindowResize() {\n  const width = window.innerWidth;\n  const height = window.innerHeight;\n\n  camera.aspect = width / height;\n  camera.updateProjectionMatrix();\n\n  renderer.setSize(width, height);\n  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n}\nwindow.addEventListener(\"resize\", onWindowResize);\n```\n\n### Loading Manager\n\n```javascript\nconst manager = new THREE.LoadingManager();\n\nmanager.onStart = (url, loaded, total) => console.log(\"Started loading\");\nmanager.onLoad = () => console.log(\"All loaded\");\nmanager.onProgress = (url, loaded, total) => console.log(`${loaded}/${total}`);\nmanager.onError = (url) => console.error(`Error loading ${url}`);\n\nconst textureLoader = new THREE.TextureLoader(manager);\nconst gltfLoader = new GLTFLoader(manager);\n```\n\n## Performance Tips\n\n1. **Limit draw calls**: Merge geometries, use instancing, atlas textures\n2. **Frustum culling**: Enabled by default, ensure bounding boxes are correct\n3. **LOD (Level of Detail)**: Use `THREE.LOD` for distance-based mesh switching\n4. **Object pooling**: Reuse objects instead of creating/destroying\n5. **Avoid `getWorldPosition` in loops**: Cache results\n\n```javascript\n// Merge static geometries\nimport { mergeGeometries } from \"three/examples/jsm/utils/BufferGeometryUtils.js\";\nconst merged = mergeGeometries([geo1, geo2, geo3]);\n\n// LOD\nconst lod = new THREE.LOD();\nlod.addLevel(highDetailMesh, 0);\nlod.addLevel(medDetailMesh, 50);\nlod.addLevel(lowDetailMesh, 100);\nscene.add(lod);\n```\n\n## See Also\n\n- `threejs-geometry` - Geometry creation and manipulation\n- `threejs-materials` - Material types and properties\n- `threejs-lighting` - Light types and shadows\n"},"lastSynced":"2026-03-08T02:07:30.618Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing immersive 3D visualization capabilities with WebGL and three.js","zh":"非常适合需要沉浸式 3D 可视化功能的前端代理，具有 WebGL 和 three.js 功能","ja":"フロントエンド エージェントが WebGL および three.js を使用した没入型 3D ビジュアル化機能を必要とする場合に最適","ko":"WebGL 및 three.js를 사용한 몰입형 3D 시각화 기능이 필요한 프런트엔드 에이전트에게 적합","es":"Perfecto para agentes Frontend que necesitan capacidades de visualización 3D inmersiva con WebGL y three.js","fr":"Parfait pour les agents Frontend nécessitant des capacités de visualisation 3D immersives avec WebGL et three.js","de":"Perfekt für Frontend-Agenten, die immersive 3D-Visualisierungsfähigkeiten mit WebGL und three.js benötigen","pt":"Perfeito para Agentes Frontend que necessitam de capacidades de visualização 3D imersiva com WebGL e three.js","ru":"Идеально подходит для фронтенд-агентов, которым требуются возможности иммерсивной 3D-визуализации с помощью WebGL и three.js","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى إمكانيات مرئية ثلاثية الأبعاد غامرة مع WebGL و three.js"},"recommendation":{"en":"Empowers agents to create interactive 3D scenes, leveraging WebGLRenderer and PerspectiveCamera for stunning visual effects, while utilizing three.js for seamless scene management and rendering","zh":"赋予代理创建交互式 3D 场景的能力，利用 WebGLRenderer 和 PerspectiveCamera 实现惊人的视觉效果，同时利用 three.js 实现无缝的场景管理和渲染","ja":"エージェントが WebGlRenderer および PerspectiveCamera を使用して驚異的な視覚効果を実現し、three.js を使用してシームレスなシーン管理およびレンダリングを実現することで、インタラクティブな 3D シーンを作成できるようにする","ko":"WebGLRenderer 및 PerspectiveCamera를 사용하여惊人的 시각 효과를实现하고, three.js를 사용하여無縫な シーン 관리 및 렌더링을 실현함으로써, 에이전트가 인터랙티브한 3D 씬을 생성할 수 있는 능력을 부여","es":"Habilita a los agentes a crear escenas 3D interactivas, aprovechando WebGLRenderer y PerspectiveCamera para efectos visuales impresionantes, mientras utiliza three.js para una gestión y renderización de escenas sin problemas","fr":"Permet aux agents de créer des scènes 3D interactives, en exploitant WebGLRenderer et PerspectiveCamera pour des effets visuels époustouflants, tout en utilisant three.js pour une gestion et un rendu de scènes sans problème","de":"Ermächtigt Agenten, interaktive 3D-Szenen zu erstellen, indem sie WebGLRenderer und PerspectiveCamera für atemberaubende visuelle Effekte nutzen und three.js für eine reibungslose Szenenverwaltung und -rendering verwenden","pt":"Habilita os agentes a criarem cenas 3D interativas, aproveitando WebGLRenderer e PerspectiveCamera para efeitos visuais deslumbrantes, enquanto utilizam three.js para gerenciamento de cena e renderização sem problemas","ru":"Наделяет агентов возможностью создавать интерактивные 3D-сцены, используя WebGLRenderer и PerspectiveCamera для потрясающих визуальных эффектов, а также используя three.js для бесперебойного управления сценой и рендеринга","ar":"تمكين الوكلاء من إنشاء مشاهد 3D تفاعلية، واستخدام WebGLRenderer و PerspectiveCamera لتحقيق تأثيرات بصرية مذهلة، واستخدام three.js لإدارة المشهد وتحويله بدون مشاكل"},"useCases":{"en":["Creating immersive 3D product demonstrations","Generating interactive 3D data visualizations","Building interactive WebGL-based simulations"],"zh":["创建沉浸式 3D 产品演示","生成交互式 3D 数据可视化","构建交互式 WebGL 基础模拟"],"ja":["没入型 3D プロダクト デモの作成","インタラクティブな 3D データ ビジュアライゼーションの生成","インタラクティブな WebGL ベースのシミュレーションの構築"],"ko":["몰입형 3D 제품 데모 생성","인터랙티브한 3D 데이터 시각화 생성","인터랙티브한 WebGL 기반 시뮬레이션 구축"],"es":["Creación de demostraciones de productos 3D inmersivas","Generación de visualizaciones de datos 3D interactivas","Construcción de simulaciones interactivas basadas en WebGL"],"fr":["Création de démonstrations de produits 3D immersives","Génération de visualisations de données 3D interactives","Con